typedef struct StreamConfig {
    int socket;
    sockaddr_in addr;
    int buffer_size;
    bool is_udp;
    char* config_path; // optional, may be NULL
} StreamConfig;

typedef struct SharedResource {
    pthread_mutex_t mutex;
    int num_streams;
    StreamConfig* stream_configs;
    size_t capacity;
} SharedResource;

SharedResource* initialize_shared_resource(size_t capacity) {
    SharedResource* resource = mmap(NULL, sizeof(SharedResource), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (resource == MAP_FAILED) {
        perror("mmap failed");
        exit(1);
    }

    pthread_mutex_init(&resource->mutex, NULL);
    resource->num_streams = 0;
    resource->capacity = capacity;
    resource->stream_configs = calloc(capacity, sizeof(StreamConfig));

    return resource;
}

bool add_stream_config(SharedResource* resource, StreamConfig config) {
    if (resource->num_streams >= resource->capacity) {
        fprintf(stderr, "Reached capacity limit\n");
        return false;
    }

    pthread_mutex_lock(&resource->mutex);

    resource->stream_configs[resource->num_streams] = config;
    resource->num_streams++;

    pthread_mutex_unlock(&resource->mutex);
    return true;
}

// Function to initialize and configure a network interface for handling multiple concurrent data streams.
void init_network_interface(SharedResource* resource, ...) {
    va_list args;
    int buffer_size;
    bool is_udp;
    char* config_path = NULL;

    va_start(args, resource);

    while (true) {
        int stream_index = va_arg(args, int);

        if (stream_index == -1) break; // sentinel value to signal end of arguments

        is_udp = va_arg(args, bool);
        buffer_size = va_arg(args, int);
        config_path = va_arg(args, char*);

        StreamConfig config = { .socket = -1, .addr = {.sin_family = AF_INET}, .buffer_size = buffer_size, .is_udp = is_udp, .config_path = config_path };

        if (!add_stream_config(resource, config)) {
            fprintf(stderr, "Failed to add stream configuration\n");
            continue;
        }

        // Implement initialization logic for network interface based on the provided configuration parameters.
    }

    va_end(args);
}
