#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <boost/program_options.hpp>
#include <boost/filesystem.hpp>
#include <boost/thread.hpp>
#include <sys/stat.h>
#include <cstdlib>
#include <cstring>
#include <chrono>
#include <cmath>

namespace fs = boost::filesystem;
using namespace std;
using namespace chrono;

struct FileData {
    ifstream file;
    string delimiter;
    long line_count = 0;
};

void process_file(FileData& data) {
    string line;
    while (getline(data.file, line, data.delimiter.empty() ? '\n' : data.delimiter[0])) {
        ++data.line_count;
    }
}

void progress_indicator(double total, double current) {
    cout << "Processing: " << fixed << setprecision(2) << current / total * 100 << "%" << endl;
}

int main(int argc, char* argv[]) {
    namespace po = boost::program_options;
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Print help message")
        ("log", po::value<string>()->default_value("-"), "Log file path (default: stderr)")
        ("delimiter", po::value<char>()->default('n'), "Line delimiter character");

    po::variables_map vm;
    try {
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);
    } catch (const exception& e) {
        cout << "Error: " << e.what() << endl << desc << endl;
        return 1;
    }

    if (vm.count("help")) {
        cout << desc << endl;
        return 0;
    }

    stringstream log_file(vm["log"].as<string>());
    unique_ptr<ostream> log(new ostreambuf_iterator<char>(log_file));

    vector<FileData> files;
    for (auto it = cbegin(argv), end = cend(argv); it != end; ++it) {
        if (*it == "--") break;

        fs::path path(*it);
        if (!fs::is_regular_file(path)) {
            log->setp(nullptr);
            cerr << "Error: " << path.string() << " is not a regular file." << endl;
            return 1;
        }

        ifstream test_file(path.string());
        if (!test_file) {
            log->setp(nullptr);
            cerr << "Error: Couldn't open file: " << path.string() << endl;
            return 1;
        }

        FileData data;
        data.file = move(test_file);
        data.delimiter = vm["delimiter"].as<char>();
        files.push_back(move(data));
    }

    if (files.empty()) {
        log->setp(nullptr);
        cerr << "Error: No input files provided." << endl;
        return 1;
    }

    long total_lines = 0;
    for (auto& file : files) total_lines += file.line_count;

    auto start = high_resolution_clock::now();

    vector<boost::thread> threads;
    for (size_t i = 0; i < files.size(); ++i) {
        boost::thread t(&process_file, ref(files[i]));
        threads.push_back(move(t));
    }

    progress_indicator(total_lines, 0);

    for (auto& thread : threads) thread.join();

    auto end = high_resolution_clock::now();
    auto duration = duration_cast<milliseconds>(end - start).count();

    cout << "Total lines: " << total_lines << endl;
    cout << "Processing time: " << duration / 1000.0 << " seconds" << endl;

    return 0;
}
