        fprintf(stderr, "Usage: %s input_file output_file rules buffer_size_mb log_file\n", argv[0]);
        exit(1);
    }

    const char* input = argv[1];
    const char* output = argv[2];
    const char* rules = argv[3];
    size_t buffer_size_mb = atoi(argv[4]);
    const char* logfile = argv[5];

    // Allocate memory for a chunk and map the input file into it
    chunk_t chunk;
    mmap(chunk.data, MB, PROT_READ, MAP_PRIVATE, open(input, O_RDONLY), 0);

    pthread_t threads[buffer_size_mb]; // Create a thread per megabyte of buffer size
    for (int i = 0; i < buffer_size_mb; ++i) {
        chunk.length += read_chunk(input, &chunk, buffer_size_mb);
        pthread_create(&threads[i], NULL, process_chunk, &chunk);
