    int* tmp = realloc(array->data, new_capacity * sizeof(int));
    if (!tmp) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    array->data = tmp;
    array->capacity = new_capacity;
