import java.util.ConcurrentHashMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentSkipListSet;
import java.util.concurrent.locks.ReentrantLock;

public class PokemonDetails {
    private final String apiBaseUrl;
    private final ReentrantLock lock = new ReentrantLock();
    private final Map<String, PokemonTypeData> cache = new ConcurrentHashMap<>();
    private final CacheStrategy cacheStrategy;

    public PokemonDetails(String apiBaseUrl, CacheStrategy cacheStrategy) {
        this.apiBaseUrl = apiBaseUrl;
        this.cacheStrategy = cacheStrategy;
    }

    public String getDetailedInfo(Pokemon pokemon) {
        String key = generateKey(pokemon);
        if (cache.containsKey(key)) {
            return buildDetailsString(cache.get(key));
        }

        lock.lock();
        try {
            PokemonTypeData typeData = fetchPokemonTypeData(pokemon, key);
            cache.putIfAbsent(key, typeData);
            return buildDetailsString(typeData);
        } finally {
            lock.unlock();
        }
    }

    private String generateKey(Pokemon pokemon) {
        return pokemon.getName() + "_" + pokemon.getGeneration();
    }

    private PokemonTypeData fetchPokemonTypeData(Pokemon pokemon, String key) {
        // Fetch the detailed type data from the external API using the provided base URL and adjusting for generation-specific changes
        // Handle cases where multiple Pokemon share the same name across different generations
        String url = apiBaseUrl + "/pokemon/" + pokemon.getName() + "/" + pokemon.getGeneration();
        // Use HTTP client to make API call, parse JSON response, and return PokemonTypeData instance
    }

    private String buildDetailsString(PokemonTypeData typeData) {
        StringBuilder sb = new StringBuilder();
        sb.append("Weaknesses: ");
        typeData.weaknesses.stream().forEach(w -> sb.append(w + ", "));
        if (typeData.weaknesses.isEmpty()) {
            sb.append("None");
        }
        sb.append("\nResistances: ");
        typeData.resistances.stream().forEach(r -> sb.append(r + ", "));
        if (typeData.resistances.isEmpty()) {
            sb.append("None");
        }
        sb.append("\nImmunities: ");
        typeData.immunities.stream().forEach(i -> sb.append(i + ", "));
        if (typeData.immunities.isEmpty()) {
            sb.append("None");
        }
        return sb.toString();
    }
}

interface CacheStrategy {
    void handleCacheMiss(String key, PokemonTypeData typeData);
}

class LruCacheStrategy implements CacheStrategy {
    private final int cacheSize;
    private final ConcurrentSkipListSet<String> lru = new ConcurrentSkipListSet<>();
    private final Map<String, PokemonTypeData> cache = new ConcurrentHashMap<>();

    public LruCacheStrategy(int cacheSize) {
        this.cacheSize = cacheSize;
    }

    @Override
    public void handleCacheMiss(String key, PokemonTypeData typeData) {
        if (lru.size() >= cacheSize) {
            String evictedKey = lru.pollFirst();
            cache.remove(evictedKey);
        }
        lru.add(key);
        cache.put(key, typeData);
    }
}
```

This Java code provides a `PokemonDetails` class that fetches and processes information about a given Pokemon object using an external API. The function handles edge cases like no weaknesses or unknown types by managing potential discrepancies between the external API's data and in-memory data store. The cache strategy manages frequent access to commonly requested Pokemon types with the LRU (Least Recently Used) caching mechanism. Concurrent requests are handled gracefully using a ReentrantLock. Unit tests should be added to validate the function’s behavior under various conditions, including edge cases and high-load scenarios.']

