#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char *name;
    void* (*init)(void);
    void (*destroy)(void*);
    void* (*hash)(void*, const char *);
    void* (*cipher)(void*, const char *, const char *, size_t);
} Algorithm;

Algorithm** get_crypto_algorithms() {
    static Algorithm** algo_list = NULL;
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static bool initialized = false;

    if (!initialized) {
        pthread_mutex_lock(&mutex);
        if (!initialized) {
            algo_list = malloc(sizeof(Algorithm*) * 16);
            int i;
            // Standard library algorithms initialization
            algo_list[i++] = &init_sha256;
            // Dynamically loaded library algorithms initialization
            void* handle = dlopen("path/to/libcryptolib.so", RTLD_LAZY);
            if (handle) {
                Algorithm** lib_algo_list = malloc(sizeof(Algorithm*) * 8);
                i += init_external_library(handle, lib_algo_list, &i);
                free(lib_algo_list);
            }
            initialized = true;
            pthread_mutex_unlock(&mutex);
        }
    }

    return algo_list;
}

int init_external_library(void* handle, Algorithm** lib_algo_list, int* count) {
    char name[256];
    void* function;

    while ((function = dlsym(handle, "get_next_algorithm")) != NULL) {
        strcpy(name, (char*)dlsym(handle, "get_algorithm_name"));
        if (!strcasecmp(name, "invalid_algorithm")) continue;

        Algorithm algo = {name, dlsym(handle, "init"), dlsym(handle, "destroy"), dlsym(handle, "hash"), dlsym(handle, "cipher")};
        lib_algo_list[*count] = malloc(sizeof(Algorithm));
        memcpy(lib_algo_list[*count], &algo, sizeof(algo));
        (*count)++;
    }

    return *count;
}
```

