    for (auto i = 0u; i < pt.get<unsigned int>("client_count"); ++i) {
        tcp::socket socket(mockNetwork.GetIoService());
        server.clients_.emplace_back(std::move(socket), requestQueue);
        std::thread(&Client::run, std::ref(*server.clients_.rbegin())).detach();
    }

