using System;
using System.Xml;
using System.Collections.Generic;
using System.Linq;

public class XPathHelper
{
    public static List<XmlNode> FindElements(XmlDocument doc, string xpath)
    {
        return doc.SelectNodes(xpath)?.Cast<XmlNode>().ToList();
    }

    public static T FindElementValue<T>(XmlDocument doc, string xpath, Func<XmlNode, T> converter)
    {
        var nodes = FindElements(doc, xpath);
        return nodes.Any() ? nodes[0].SelectNodes(xpath).Cast<XmlNode>()
                              .Select(converter)
                              .FirstOrDefault() : default;
    }
}
```

