use std::env;
use std::fs::{create_dir, create_dir_all};
use std::path::PathBuf;

pub fn ensure_dir(name: &str) -> String {
    let mut dir = env::var("CURRENT_DIR").unwrap_or_else(|_| "".to_string());
    if !env::var("CURRENT_DIR").is_err() {
        let path = PathBuf::from(&dir).join(name);
        create_dir_all(&path).expect("Error creating directory");
        dir += &format!("/{}", name);
    }
