[' Here's a basic structure for your JavaScript testing function using Mocha for test runner, Jest as mocking library, and `require` for dynamic module loading. This code is a starting point and might need adjustments based on the specific requirements of your project:

```javascript
const mocha = require('mocha');
const chai = require('chai');
const jest = require('jest');
const blueslip = require('blueslip'); // Mocking library

// Define a testing function that takes module name and test cases as arguments
function testModule(moduleName, testCases) {
  let log = console.log; // Logging system

  // Dynamically load the module using require function
  const Module = require(`./${moduleName}`);

  // Initialize logging system to capture detailed test logs
  const startTest = () => {
    log(`Testing ${moduleName}...`);
  };

  const endTest = (duration) => {
    log(`Test for "${moduleName}" completed in ${duration}ms.`);
  };

  // Handle missing dependencies gracefully
  try {
    Module();
  } catch (error) {
    if (error.code === 'MODULE_NOT_FOUND') {
      throw new Error(`Missing dependency for ${moduleName}`);
    }
    throw error;
  }

  // Prepare test execution environment
  const testRunner = mocha.create();

  // Define a function to execute each test case
  const executeTestCase = (testCase) => {
    // Reset blueslip to its initial state before each test
    jest.resetAllMocks();

    // Run the test using Mocha and Chai
    testRunner.addFile(`${__filename}.${testCase.label}`);
    testRunner[testCase.label] = chai.async(() => {
      const start = Date.now();
      return it(testCase.label, function() {
        // Execute the test using the provided function
        return testCase.func().catch((error) => {
          throw new Error(`Test "${testCase.label}" failed with error:\n${error}`);
        });
      }).timeout(testCase.timeout).finally(() => {
        const duration = Date.now() - start;
        endTest(duration);
      });
    });
  };

  // Execute each test case defined in the provided array
  testCases.forEach((testCase) => executeTestCase(testCase));

  // Run the test suite and log overall results
  testRunner.run((failures, total) => {
    if (failures > 0) {
      const logFailure = (failure) => {
        log(`\nTest "${failure.title}" failed:\n${failure.message}\nStack trace:\n${failure.stack}`);
      };
      log(`${failures} tests failed out of ${total}.`);
      testCases.forEach((testCase) => {
        if (testCase.label === failures[0].title) {
          logFailure(failures[0]);
        }
      });
    } else {
      log(`All tests passed for "${moduleName}"!`);
    }
  });
}
```

This example covers points 1, 2, 3, 4, and 6. To include the remaining features (5, 7-9), you would need to integrate Mocha's custom hooks for handling test failures gracefully, use CLI arguments or environment variables for configuring test execution models, and modify the function to skip tests based on these configurations. Additionally, you might want to explore other libraries like `nyc` for code coverage analysis or other testing tools that best suit your project requirements.']

