/**
 * Render Footer Scripts function
 * @param {Array<Object>} scripts - Array of script objects
 */
function renderFooterScripts(scripts) {
  // Sort scripts by dependencies (pre/post) and defer flag for optimal loading
  const sortedScripts = scripts.sort((a, b) => {
    if (a.key === 'pre' && b.key === 'pre') return 0;
    if (a.key === 'pre') return -1;
    if (b.key === 'pre') return 1;

    if (a.key === 'post' && b.key === 'post') return 0;
    if (a.key === 'post') return 1;
    if (b.key === 'post') return -1;

    // Sort by defer flag, as scripts with defer load later and can have dependencies resolved before executing
    return a.defer !== b.defer ? (b.defer ? -1 : 1) : a.id > b.id ? 1 : -1;
  });

  let html = '<ul id="footer-scripts">';

  // Process scripts and build HTML structure, handling edge cases such as missing IDs or duplicates
  const scriptMap = new Map();
  for (const script of sortedScripts) {
    if (!script.id || scriptMap.has(script.id)) continue;

    scriptMap.set(script.id, true);
    html += `<li data-key="${script.key}" data-defer="${script.defer}">`;
    html += `<script id="${script.id}" type="text/javascript" ${script.defer ? 'defer' : ''}>`;
    html += script.code ? script.code : '<!-- Missing code -->';
    html += '</script></li>';
  }

  html += '</ul>';

  return html.replace(/[\u00A0\u009D]/g, '&nbsp;').toString();
}
```

