const fs = require('fs');
const path = require('path');
const chokidar = require('chokidar');
const { createLogger, format, transports } = require('winston');

// Configuration
const baseDir = './scripts'; // Directory to watch for JS files
const logLevel = 'info';
const performanceThresholdMs = 1000;
const maxRetries = 3;

// Dependency graph management
const graph = new Map();

// File loader and executor
function loadAndExecute(filePath) {
  return new Promise((resolve, reject) => {
    let currentFile = filePath.replace(/\\/g, '/'); // Ensure cross-platform compatibility
    const extensions = ['.js', '.mjs'];

    // Attempt to load the file with all supported extensions
    for (const ext of extensions) {
      const possibleFilePath = currentFile + ext;
      fs.access(possibleFilePath, fs.constants.F_OK, (err) => {
        if (!err) {
          require(possibleFilePath);
          resolve();
          break;
        } else if (maxRetries > 0) {
          maxRetries--;
          continue;
        }
      });
    }
  }).catch((error) => {
    // Handle loading errors and log them
    console.error(`Error while loading file ${currentFile}:`, error);
  });
}

// Recursively build the dependency graph
function buildDependencyGraph(directoryPath, parentModuleName) {
  return new Promise((resolve) => {
    fs.readdir(directoryPath, (err, files) => {
      if (err) throw err;

      const modulesToProcess = files.filter((file) => {
        const isJsOrMjsFile = file.endsWith('.js') || file.endsWith('.mjs');
        return isJsOrMjsFile && !graph.has(file);
      });

      if (modulesToProcess.length === 0) {
        resolve();
        return;
      }

      const currentModuleName = parentModuleName || path.basename(directoryPath);
      for (const module of modulesToProcess) {
        const moduleFilePath = path.join(directoryPath, module);
        graph.set(module, { file: module, dependencies: [] });

        // Dynamically require the module to determine its dependencies
        loadAndExecute(moduleFilePath).then(() => {
          const moduleExports = require(moduleFilePath)[currentModuleName];

          if (Array.isArray(moduleExports)) {
            for (const dependency of moduleExports) {
              buildDependencyGraph(path.dirname(moduleFilePath), currentModuleName);
            }
          } else {
            // Handle circular dependencies
            graph.get(module).dependencies.push(currentModuleName);
          }
        });
      }
    });
  });
}

// Initialize the application
buildDependencyGraph(baseDir)
  .then(() => {
    const watcher = chokidar.watch(baseDir, { persistent: true });

    // Monitor changes in the script directory and rebuild the dependency graph as needed
    watcher.on('add', (filePath) => buildDependencyGraph(path.dirname(filePath)));
    watcher.on('change', (filePath) => buildDependencyGraph(path.dirname(filePath)));
  })
  .catch((error) => {
    console.error(`Initialization error:`, error);
  });

// Performance logging and monitoring
const logger = createLogger({
  level: logLevel,
  format: format.combine(format.timestamp(), format.json()),
  transports: [new transports.Console()],
});

function measureAndLogExecutionTime(fn) {
  return (...args) => {
    const start = Date.now();
    const result = fn.apply(this, args);
    logger.info({ execTime: Date.now() - start }, 'Execution time');
    return result;
  };
}

// Wrap loadAndExecute in a function that measures its execution time and handles performance issues
const loadAndExecuteWithTiming = measureAndLogExecutionTime(loadAndExecute);

// Set up performance monitoring
let previousLoadTime = -1;
setInterval(() => {
  const currentLoadTime = Date.now();
  if (previousLoadTime > 0 && currentLoadTime - previousLoadTime > performanceThresholdMs) {
    // Gracefully degrade performance when loading times exceed the threshold
    logger.warn('Performance warning: Loading time exceeded the specified threshold');
  }
  previousLoadTime = currentLoadTime;
}, 100);
```

