import android.content.Context
import android.graphics.BitmapFactory
import android.graphics.BitmapFactory.Options
import androidx.concurrent.futures.AbstractFutureCallback
import androidx.concurrent.futures.Future
import androidx.lifecycle.MutableLiveData
import com.squareup.okhttp3.*
import java.io.File
import java.io.IOException
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors

class ThemeCache(private val context: Context) {
    private val themeCache = ConcurrentHashMap<String, Bitmap?>()
    private val defaultThemeDirectory = MutableLiveData<String>()

    init {
        fetchDefaultThemeDirectory()
    }

    fun getBitmap(themeName: String): Bitmap? {
        return themeCache.getOrPut(themeName) { loadThemeBitmapAsync(themeName) }
    }

    private fun loadThemeBitmapAsync(themeName: String): Future<Bitmap?> {
        val callback = object : AbstractFutureCallback<Bitmap?>() {
            override fun onSuccess(result: Bitmap?) {
                themeCache[themeName] = result
            }

            override fun onFailure(t: Throwable) {
                // Handle failure and retry if necessary (e.g., with exponential backoff)
            }
        }

        val executor = Executors.newSingleThreadExecutor()
        return Future.callInBackground(executor, callback, BitmapFactory.decodeFileAsync(getThemeFilePath(themeName)))
    }

    private fun getThemeFilePath(themeName: String): String {
        return defaultThemeDirectory.value ?: "default_directory" // Fallback to default directory if not set
    }

    private fun fetchDefaultThemeDirectory() {
        val configurationServiceUrl = "https://configuration-service/default-theme-directory"

        val request = Request.Builder().url(configurationServiceUrl).build()
        OkHttpClient().newCall(request).enqueue(object : Callback() {
            override fun onFailure(call: Call, e: IOException) {
                // Handle failure and set default directory if necessary
            }

            override fun onResponse(call: Call, response: Response) {
                defaultThemeDirectory.postValue(response.body!!.string())
            }
        })
    }
}
```

