```php
<?php

// Config class with getter methods for different environments.
class Config {
    private $environments = ['development', 'testing', 'production'];
    private $currentEnvironment;
    private $configCache;

    public function __construct($env) {
        if (!in_array($env, $this->environments)) {
            throw new Exception("Invalid environment: {$env}");
        }
        $this->currentEnvironment = $env;
    }

    public function get($key) {
        // Load or refresh the config cache if not available or expired.
        if (!isset($this->configCache[$this->currentEnvironment])) {
            $this->loadConfig();
        }

        return isset($this->configCache[$this->currentEnvironment][$key])
            ? $this->configCache[$this->currentEnvironment][$key]
            : null;
    }

    private function loadConfig() {
        // Load the environment-specific configuration file.
        $envConfigPath = __DIR__ . '/config/' . $this->currentEnvironment . '.php';

        if (file_exists($envConfigPath)) {
            require_once $envConfigPath;
        } else {
            throw new Exception("Could not find environment-specific configuration file: {$envConfigPath}");
        }

        // Merge the current environment's config with the base config.
        $this->configCache[$this->currentEnvironment] = array_merge(require __DIR__ . '/config/base.php', $this->get('app'));
    }
}

// Bootstrap function to set up the application and load the autoloader.
function bootstrap($autoloadPath) {
    // Set environment-specific variables based on server metadata.
    // For example: $_SERVER['HTTP_HOST'] could be used to determine the current environment.

    $config = new Config('development'); // Initialize with default development environment.

    // Load the vendor autoloader from the specified directory path.
    require $autoloadPath;
}

// Command-line invocation entry point.
if (PHP_SAPI === 'cli') {
    bootstrap('/path/to/vendor/autoload.php'); // Replace with the actual autoloader path.

    // Handle command-line arguments and process them as needed.
} else {
    // Web-based invocation - include the necessary files for your web application.
}
