function generateReportData($charSet, $length, $password, $directory) {
    ini_set('error_reporting', E_ALL); // Enable error reporting for debugging
    ini_set('display_errors', false); // Prevent display of errors to user

    $randomString = str_repeat(
        substr($charSet, random_int(0, strlen($charSet) - 1), 1),
        $length
    );

    try {
        $fileHandle = fopen("{$directory}/report.txt", "r");
        if (!$fileHandle) {
            error_log("Could not access file: {$directory}/report.txt");
            $fileContent = "File unavailable";
        } else {
            $fileContent = fread($fileHandle, filesize("{$directory}/report.txt"));
            fclose($fileHandle);
        }
    } catch (Exception $e) {
        error_log($e->getMessage());
        $fileContent = "Error reading file: {$e->getMessage()}";
    }

    $hashedPassword = password_hash($password, PASSWORD_DEFAULT);

    return [
        'randomString' => $randomString,
        'fileContent' => $fileContent,
        'hashedPassword' => $hashedPassword
    ];
}
