const https = require('https');
const fs = require('fs');
const crypto = require('crypto');
const util = require('util');
const axios = require('axios');
const { promisify } = require('util');
const log = require('winston'); // Third-party logging service

const getRequestOptionTLS12 = (options) => {
  options.agent = new https.Agent({ minVersion: 'v1.2' });
  return options;
};

class CertificateCombiner {
  constructor(privateKeyUrl, certificateUrl) {
    this.privateKeyUrl = privateKeyUrl;
    this.certificateUrl = certificateUrl;
    this.buffer = '';
    this.paused = false;
    this.privateKeyData = null;
    this.certificateChain = [];
  }

  async fetchAndVerify(url, callback) {
    return new Promise((resolve, reject) => {
      const request = https.get(getRequestOptionTLS12({ url }));

      let certificateChain = [];
      let intermediates = [];
      let rootCert;

      request.on('data', (chunk) => {
        this.buffer += chunk;
      });

      request.on('end', async () => {
        try {
          if (!rootCert) {
            // Extract the root certificate from the fetched data
            rootCert = crypto.createCertificate();
            rootCert.parse(this.buffer);
          }

          if (intermediates.length > 0) {
            // Verify intermediates against the root certificate
            for (let intermediate of intermediates) {
              const verifyResult = crypto.verify({ key: rootCert.getPublic(), cert: intermediate }, this.buffer);
              if (!verifyResult) throw new Error('Invalid certificate chain');
            }
          } else {
            // If no intermediates, assume the fetched data is the root certificate
          }

          callback(rootCert);
          resolve();
        } catch (err) {
          reject(err);
        }
      });

      request.on('error', (err) => {
        reject(err);
      });
    });
  }

  async fetchPrivateKey() {
    if (this.privateKeyData) return Promise.resolve(this.privateKeyData);

    await this.fetchAndVerify(this.privateKeyUrl, (rootCert) => {
      this.privateKeyData = fs.readFileSync(getPrivateKeyFilePath(rootCert));
    });

    return this.privateKeyData;
  }

  async fetchCertificateChain() {
    if (this.certificateChain.length > 0) return Promise.resolve(this.certificateChain);

    await this.fetchAndVerify(this.certificateUrl, (rootCert) => {
      // Fetch intermediates recursively
      const getIntermediate = async (url, parentCert) => {
        const intermediate = await axios.get(url);
        if (!intermediate.data) return;

        // Verify the intermediate against the parent certificate
        const verifyResult = crypto.verify({ key: parentCert.getPublic(), cert: intermediate.data }, this.buffer);
        if (!verifyResult) throw new Error('Invalid certificate chain');

        this.certificateChain.unshift(intermediate.data);
        getIntermediate(url.replace(/BASIC/, 'CA'), parentCert);
      };

      const getCertificateUrl = (certUrl) => {
        return certUrl.replace(/\.crt$/, '.pem').replace(/BASIC/, 'INTERMEDIATE');
      };

      const intermediatesPromises = this.certificateUrl.split('\n').map((url) => getIntermediate(getCertificateUrl(url), rootCert));
      await Promise.all(intermediatesPromises);
    });

    return this.certificateChain;
  }

  async combineCertificates() {
    const [privateKey, ...chain] = await Promise.all([this.fetchPrivateKey(), this.fetchCertificateChain()]);
    return chain.reduce((concatenated, cert) => concatenated + cert, privateKey);
  }

  async stream(stream) {
    if (this.paused) throw new Error('Stream is paused');

    const chunks = [];
    for await (const chunk of stream) {
      this.buffer += chunk;
      chunks.push(chunk);

      // Manage memory usage by pausing the stream when buffer size exceeds a threshold
      if (this.buffer.length > 1024 * 1024) {
        this.pause();
        await new Promise((resolve) => setTimeout(resolve, 500)); // Give some time for the buffer to be processed before resuming
      }
    }

    return chunks;
  }

  pause() {
    if (!this.paused) this.paused = true;
  }

  resume() {
    if (this.paused) this.paused = false;
  }
}

// Helper function for getting the private key file path from the root certificate
function getPrivateKeyFilePath(rootCert) {
  // Implement logic to determine the private key file path based on the root certificate
  // For example, using OpenSSL's x509 extension to find the 'keyUsage' field and looking for a match with 'keyEncipherment' or 'digitalSignature'
}

module.exports = CertificateCombiner;
```
