#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

int has_class(const char* elm, const char* cls) {
    size_t len = strlen(elm);
    if (len < strlen(cls)) return 0;
    return strncmp(elm + (len - strlen(cls)), cls, strlen(cls)) == 0;
}

void append_slash(char* str, size_t size) {
    if (str[size - 1] != '/') {
        str[size] = '/';
        str[size + 1] = '\0';
    }
}

char* trimAndAppendSlash(const char* str, size_t maxSize, void(*callback)(const char*, const char*)) {
    if (strlen(str) > maxSize) return NULL;

    char* result = malloc((maxSize + 1) * sizeof(char));
    memcpy(result, str, strlen(str));
    append_slash(result, maxSize);

    for (size_t i = 0; i < strlen(result); ++i) {
        if (!isspace(result[i])) {
            char* start = result + i;
            char* end;
            if (callback(start, "id")) {
                end = strchr(start, '=');
                if (end != NULL && *(++end) == '=') {
                    char* value_start = ++end;
                    while (*++value_start && *value_start != '>') {}
                    if (*value_start == '>') {
                        i += value_start - start + 1;
                    }
                }
            } else if (callback(start, "class")) {
                end = strchr(start, '=');
                if (end != NULL && *(++end) == '=') {
                    char* value_start = ++end;
                    while (*++value_start && *value_start != ' ') {}
                    if (*value_start == ' ') {
                        i += value_start - start + 1;
                    }
                }
            }
        }
    }
    return result;
}
