// Helper function for deserializing an object from a byte array
boost::shared_ptr<MyClass> deserializeObjectFromBytes(const std::vector<char>& bytes) {
    try {
        std::istringstream iss(std::string((const char*)&bytes[0], bytes.size()));
        MyClass obj;
        boost::serialization::load_nvp(iss, obj, new boost::archive::xml_iarchiver(&obj));
        return boost::make_shared<MyClass>(obj);
    } catch (const std::exception& e) {
        std::cerr << "Warning: Failed to deserialize object from bytes. Using default instance." << std::endl;
        return boost::make_shared<MyClass>();
    }
}

// Function for converting JPEG to PDF, using exponential backoff retry logic
int convertJpegToPdf(const std::string& inputFile, const std::string& outputFile) {
    static const int MAX_ATTEMPTS = 3;
    static const unsigned int INITIAL_RETRY_INTERVAL = 1000; // in milliseconds

    for (int attempts = 0; attempts < MAX_ATTEMPTS; ++attempts) {
        try {
            // Call the third-party tool for conversion here (e.g., convert inputFile to outputFile using ImageMagick)
            std::system(("convert " + inputFile + " " + outputFile).c_str());
            return 0;
        } catch (const std::exception& e) {
            if (attempts < MAX_ATTEMPTS - 1) {
                // Wait exponential backoff interval before next attempt
                unsigned int sleepInterval = INITIAL_RETRY_INTERVAL * (unsigned int(pow(2, attempts)));
                std::this_thread::sleep_for(std::chrono::milliseconds(sleepInterval));
            } else {
                // Log error message for permanent failures and return -1
                std::cerr << "Error: Failed to convert JPEG to PDF after multiple attempts. Error: " << e.what() << std::endl;
                return -1;
            }
        }
    }

    // Return success if no errors occurred
    return 0;
}
