import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ConcurrentLinkedQueue;
import java.util.Deque;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class ScriptRunner {
    private static final Logger LOGGER = LoggerFactory.getLogger(ScriptRunner.class);

    private static final int MAX_CPU_USAGE_PERCENTAGE = 80;
    private static final long MAX_MEMORY_USAGE_BYTES = 1024L * 1024L * 512; // 512MB

    private Map<Long, ProcessHandle> runningProcesses = new HashMap<>();
    private Deque<Runnable> scriptQueue = new ConcurrentLinkedQueue<>();
    private ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void submitScript(String scriptCode, Map<String, String> env) {
        Runnable scriptTask = () -> executeScript(scriptCode, env);
        scriptQueue.add(scriptTask);
        executor.execute(scriptTask);
    }

    private void executeScript(String scriptCode, Map<String, String> env) {
        // Save the process handle for monitoring and potential termination later
        ProcessBuilder pb = new ProcessBuilder(new String[]{"sh", "-c", scriptCode});
        pb.environment().putAll(env);

        try {
            Process p = pb.start();

            runningProcesses.put(p.pid(), p.toHandle());

            // Monitor resource usage and terminate if necessary
            Thread monitorThread = new Thread(() -> {
                while (!p.destroyed()) {
                    long cpuUsage = getCpuUsage(p);
                    long memoryUsage = getMemoryUsage(p);

                    if (cpuUsage > MAX_CPU_USAGE_PERCENTAGE || memoryUsage > MAX_MEMORY_USAGE_BYTES) {
                        LOGGER.error("Process with PID {} exceeded resource thresholds: CPU={}, Memory={}", p.pid(), cpuUsage, memoryUsage);
                        p.destroy();
                    }
                }
            });
            monitorThread.start();

            int exitCode = p.waitFor();
            if (exitCode != 0) {
                LOGGER.error("Process with PID {} exited with non-zero status: {}", p.pid(), exitCode);
            } else {
                LOGGER.info("Process with PID {} finished successfully", p.pid());
            }

        } catch (IOException | InterruptedException e) {
            LOGGER.error("Error executing script:", e);
        } finally {
            // Remove the process handle from the running set and close it to free resources
            runningProcesses.remove(p.pid());
        }
    }

    private long getCpuUsage(Process p) throws IOException {
        // Implement CPU usage calculation based on /proc/<pid>/stat file or other available methods
        // This is a placeholder and should be replaced with the actual implementation
        return 0;
    }

    private long getMemoryUsage(Process p) throws IOException {
        Path processPath = Paths.get("/proc", String.valueOf(p.pid()), "status");
        Map<String, String> statusMap = new HashMap<>();
        try (BufferedReader reader = Files.newBufferedReader(processPath, StandardCharsets.UTF_8)) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("VmRSS:")) {
                    statusMap.put("VmRSS", line.split(":")[1].trim());
                }
            }
        }

        // Convert the VmRSS value to bytes and return it
        long memoryUsageBytes = Long.parseLong(statusMap.get("VmRSS")) * 4096;
        return memoryUsageBytes;
    }
}
