} ConnectionData;

static pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned char key[32];
unsigned char iv[AES_BLOCK_SIZE];

int processConnectionData(ConnectionData* data) {
    if (!data || !data->password || !data->connection || !data->callback) {
        return 1; // Invalid argument(s)
    }

    if (strcmp(data->password, "") == 0 || !data->password) {
        return 2; // Invalid password
    }

    if (!data->connection->title || strlen(data->connection->title) <= 0) {
        return 3; // Invalid connection title
    }

    pthread_mutex_lock(&key_mutex);
    if (data->connection->state != ConnectionState::PROCESSABLE) {
        pthread_mutex_unlock(&key_mutex);
        return 4; // Incompatible connection state
    }
    pthread_mutex_unlock(&key_mutex);

    const char* base64_data = data->connection->encrypted_data;
    unsigned char binary_data[base64_decoded_length(base64_data)];
    int result = base64_decode(base64_data, binary_data, sizeof(binary_data));
    if (result <= 0) {
        return 5; // Base64 decoding error
    }

    AES_KEY triple_des_key;
    AES_set_encrypt_key((const unsigned char*)key, 128, &triple_des_key);

    size_t len = sizeof(binary_data);
    unsigned char decrypted[len];
    int decryption_result = AES_cbc_decrypt(binary_data, decrypted, &len, &triple_des_key, iv, binary_data, AES_DECRYPT);
    if (decryption_result != 1) {
        return 6; // Triple DES decryption error
    }

    data->callback(decrypted);
    return 0; // Success
}
