public class DatabaseHelper
{
    private const int MaxRetries = 3;
    private readonly TcpClient _client;
    private readonly NetworkStream _stream;
    private DataTableReader _reader;

    public DatabaseHelper(string host, int port)
    {
        _client = new TcpClient(host, port);
        _stream = _client.GetStream();
    }

    public async Task<DataTableReader> SendDataToDatabase(byte[] data)
    {
        int retries = MaxRetries;
        do
        {
            try
            {
                await _stream.WriteAsync(data, 0, data.Length);
                _reader = await QueryResult();
                return _reader;
            }
            catch (SocketException)
            {
                retries--;
            }
        } while (retries > 0);

        throw new Exception("Failed to send data after maximum retries.");
    }

    private async Task<DataTableReader> QueryResult()
    {
        var query = Encoding.ASCII.GetBytes("SELECT * FROM MyTable");
        await _stream.WriteAsync(query, 0, query.Length);
        return await Task.Run(() => new DataTable().Load(new BinaryReader(_stream)));
    }
}
