```c
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MAX_CHARS 256
#define MAX_NUM_DIGITS 10

char* GenerateNewFilename(const char* filename)
{
    size_t pathLength = strlen(filename);
    size_t numDigits = 1;
    bool hasUppercase = false;
    int maxNum = -1;
    char* newFilename = malloc(MAX_CHARS + 1);

    if (pathLength >= MAX_CHARS)
        return NULL;

    for (size_t i = 0; i < pathLength; ++i)
    {
        if (isdigit(filename[i]))
            numDigits = (numDigits > i - (int)filename[i]) ? i - (int)filename[i] : numDigits;
        else if (isupper(filename[i]))
            hasUppercase = true;

        if (!isspace(filename[i]) && !iscntrl(filename[i]) && filename[i] != '.')
        {
            newFilename[i] = filename[i];
            ++i; // skip spaces and special characters
        }
    }

    if (hasUppercase)
        maxNum = atoi(&newFilename[pathLength]);
    else
        maxNum = atoi(&newFilename[pathLength]) - 2;

    snprintf(newFilename + pathLength, MAX_NUM_DIGITS, "%0*d", numDigits, (hasUppercase ? maxNum + 1 : maxNum));

    char extension[5];
    strcpy(extension, hasupper(filename) ? "TXT" : "BIN");
    snprintf(newFilename + pathLength + numDigits, MAX_CHARS - pathLength - numDigits, ".%s", extension);

    return newFilename;
}
