using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace DataLoadingUtility
{
    public class CustomBinaryFormatter : BinaryFormatter
    {
        protected override void OnTypeReceived(Type objectType)
        {
            if (objectType == typeof(List<dynamic>))
                SetSerializeMethod(serializeDynamicList);
        }

        private void serializeDynamicList(object o, Stream stream)
        {
            var list = (IEnumerable)o;
            WriteInt32(stream, list.Count());
            foreach (var item in list)
                SerializationBinder.BindTo(item).Serialize(stream);
        }
    }

    public class SerializationBinder : ISerializationBinder
    {
        private readonly Type _type;

        public SerializationBinder(Type type) => _type = type;

        public Type BindToType() => _type;

        public object BindToName(string name, Type serializedType, StreamingContext context)
        {
            if (_type == typeof(string)) return JsonConvert.DeserializeObject<string>(name);
            // Add more custom binding logic for other types here...
            throw new NotSupportedException($"Unsupported type '{_type.FullName}'");
        }
    }

    public class DataLoader
    {
        private readonly CustomBinaryFormatter _formatter;

        public DataLoader() => _formatter = new CustomBinaryFormatter();

        public async Task<T> LoadDataAsync<T>(Stream stream)
        {
            using (var reader = new BinaryReader(stream))
                return Deserialize<T>(await reader.ReadToEndAsync());
        }

        private T Deserialize<T>(string json) => JsonConvert.DeserializeObject<T>(json);

        private object Deserialize(Stream stream)
        {
            using (var reader = new MemoryStream())
            {
                _formatter.Serialize(stream, new List<dynamic>{});
                stream.Seek(0, SeekOrigin.Begin);
                _formatter.Deserialize(stream);
            }
            return _formatter.SurrogateSelector.GetSerializableCopy(_formatter.DeserializationBinder, _formatter);
        }
    }
}
```

