    void addVertex(const std::string& metadataIp, const VertexProperties& properties) {
        VertexId id = boost::add_vertex(graph_);
        property(id, vertexProperties) = properties;
        // Call external API to fetch UUID and update vertex with UUID property.
        callExternalApi(metadataIp, [this, id](const json_t* apiResponse) {
            if (apiResponse && !json_is_null(apiResponse)) {
                const char* uuidStr = json_string_value(json_object_get(apiResponse, "uuid"));
                if (!uuidStr) {
                    LOG_ERROR("Failed to extract UUID from API response");
                    return;
                }
                VertexProperties updatedProperties = properties;
                updatedProperties.uuid = uuidStr;
                property(id, vertexProperties) = updatedProperties;
            } else {
                LOG_ERROR("Empty or null API response received");
            }
        });
    }

    void addEdge(VertexId src, VertexId dest, const EdgeProperties& properties) {
        boost::add_edge(src, dest, graph_);
        property(edge(src, dest), edgeProperties) = properties;
    }

private:
    struct MockHttpClient {
        virtual ~MockHttpClient() {}
        virtual void asyncRequest(const std::string& url, const RequestCallback& callback) = 0;
    };

    class TimeoutHttpClient : public MockHttpClient {
    public:
        explicit TimeoutHttpClient(std::chrono::milliseconds timeout) : timeout_(timeout) {}

        void asyncRequest(const std::string& url, const RequestCallback& callback) override {
            auto self = shared_from_this();
            boost::asio::io_service ioService;
            boost::asio::ip::tcp::resolver resolver(ioService);
            auto endpointIter = resolver.resolve(url, "http");
            if (!endpointIter) {
                callback({ false, {}, "", {} });
                return;
            }

            boost::asio::connect(boost::asio::ip::tcp::socket(ioService), *endpointIter);

            auto readBuffer = boost::asio::streambuf();
            auto writeBuffer = boost::asio::streambuf();

            auto requestHandler = [this, callback, &readBuffer, &writeBuffer](boost::system_error error) mutable {
                if (!error) {
                    // Send the HTTP request here.
                } else {
                    callback({ false, {}, "", {} });
                }
            };

            auto readCallback = [this, callback, &readBuffer](boost::system_error error) mutable {
                if (!error && !readBuffer.size()) {
                    callback({ true, readBuffer.data(), "", {} });
                } else {
                    ioService.post(std::bind(requestHandler, std::move(error)));
                }
            };

            auto writeCallback = [this, &writeBuffer](boost::system_error error) mutable {
                if (!error) {
                    ioService.post([this, &readBuffer, readCallback]() mutable {
                        boost::asio::async_read(ioService, readBuffer, readCallback);
                    });
                } else {
                    callback({ false, {}, "", {} });
                }
            };

            boost::asio::async_write(ioService, writeBuffer, writeCallback);
            ioService.post([this, &readBuffer, readCallback]() mutable {
                boost::asio::async_read(ioService, readBuffer, readCallback);
            });

            auto timer = std::make_shared<boost::asio::deadline_timer>(ioService, timeout_);
            timer->async_wait([this](const boost::system_error& error) mutable {
                callback({ false, {}, "", {} });
                ioService.stop();
            });

            ioService.run();
        }

    private:
        std::shared_ptr<boost::asio::deadline_timer> timeout_;
    };

    struct RequestCallback {
        explicit RequestCallback(RequestHandler handler) : handler_(std::move(handler)) {}
        void operator()(const std::tuple<bool, boost::container::small_vector<char, 4096>, const char*, boost::optional<std::string>>& response) {
            if (response[0]) {
                handler_(response[1], response[2]);
            } else {
                LOG_ERROR("API call failed: {}", response[3].value_or("unknown error"));
            }
        }

    private:
        RequestHandler handler_;
    };

    template<typename... Args>
    void callExternalApi(const std::string& url, Args&&... args) {
        auto httpClient = inject<MockHttpClient>::create<TimeoutHttpClient>(std::chrono::milliseconds(5000));
        httpClient->asyncRequest(url, RequestCallback{ [this, url, args...](const char* responseData, const std::string& error) {
            if (error.empty()) {
                FindVmUuidFromMetadataIp finder = inject<FindVmUuidFromMetadataIp>::create();
                auto uuid = finder(responseData);
                if (!uuid) {
                    LOG_ERROR("Failed to extract UUID from API response data");
                    return;
                }
                // Update the vertex with the fetched UUID.
            }
        } });
    }
};

struct VertexProperties {
    std::string ip;
    boost::optional<std::string> uuid;
    // Add any other properties you want to associate with vertices.
};

struct EdgeProperties {
    // Add any properties you want to associate with edges.
};
