#include <forward_list>
#include <string>

void insertAfter(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2) {
    auto it = list.begin();
    if (it == list.end()) { // If the list is empty or if str1 doesn't exist in the list
        list.push_back(str2);
        return;
    }
    while (it != list.end() && *it != str1)
        it++;
    if (it == list.end()) { // If str1 doesn't exist in the list
        list.push_back(str2);
        return;
    }
    list.insert after(*it, str2);
}
