    size_t body_size;
} Request;

struct RequestPool {
    Request* requests;
    size_t capacity, length;
    pthread_mutex_t mutex;
};

RequestPool create_request_pool(size_t capacity) {
    RequestPool pool = {0};
    pool.capacity = capacity;
    pool.requests = calloc(capacity, sizeof(Request));
    if (!pool.requests) {
        fprintf(stderr, "Failed to allocate memory for request pool\n");
        exit(EXIT_FAILURE);
    }
    pool.mutex = PTHREAD_MUTEX_INITIALIZER;
    return pool;
}

size_t get_random_size(size_t min, size_t max) {
    return rand() % (max - min + 1) + min;
}

void init_requests(RequestPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    for (size_t i = 0; i < pool->length; ++i) {
        sprintf(pool->requests[i].method, "GET"); // Assume a GET request by default
        sprintf(pool->requests[i].url, "%.*s", sizeof(pool->requests[i].url), "example.com");
        pool->requests[i].body_size = get_random_size(10, 100);
    }
    pthread_mutex_unlock(&pool->mutex);
}

void* fetch_data(void* data) {
    // Implement asynchronous data retrieval logic here.
    return NULL;
}

RequestPool process_requests(RequestPool pool, size_t num_threads) {
    pthread_t threads[num_threads];
    void* result = NULL;

    for (size_t i = 0; i < num_threads; ++i) {
        int rc = pthread_create(&threads[i], NULL, fetch_data, &pool);
        if (rc) {
            fprintf(stderr, "Error creating thread: %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < num_threads; ++i) {
        int rc = pthread_join(threads[i], &result);
        if (rc) {
            fprintf(stderr, "Error joining thread: %d\n", rc);
            exit(EXIT_FAILURE);
        }
    }

    return pool;
}

void reset_request_pool(RequestPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    memset(pool->requests, 0, pool->capacity * sizeof(Request));
    pool->length = 0;
    pthread_mutex_unlock(&pool->mutex);
}
