#include "logging_library.h" // External logging library header

typedef struct {
    int key;
    long offset;
} Record;

typedef struct DataManager {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataManager;

DataManager create_data_manager(size_t initial_capacity) {
    DataManager dm = { NULL, initial_capacity, 0 };
    dm.records = malloc(initial_capacity * sizeof(Record));
    if (!dm.records) {
        log_error("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&dm.lock, NULL);
    return dm;
}

void destroy_data_manager(DataManager* dm) {
    free(dm->records);
    pthread_mutex_destroy(&dm->lock);
}

Record* find_largest(DataManager* dm) {
    Record *max = &dm->records[0];
    for (size_t i = 1; i < dm->size; ++i) {
        if (dm->records[i].key > max->key) {
            max = &dm->records[i];
        }
    }
    return max;
}

void resize(DataManager* dm, size_t new_capacity) {
    if (new_capacity <= dm->size) return; // No resizing needed

    Record *new_array = malloc(new_capacity * sizeof(Record));
    if (!new_array) {
        log_error("Memory allocation failure");
        return;
    }

    pthread_mutex_lock(&dm->lock);
    memcpy(new_array, dm->records, dm->size * sizeof(Record));
    free(dm->records);
    dm->records = new_array;
    dm->capacity = new_capacity;
    pthread_mutex_unlock(&dm->lock);
}

void add_record(DataManager* dm, int key, long offset) {
    if (key < INT_MIN || key > INT_MAX || offset < LONG_MIN || offset > LONG_MAX) {
        log_error("Invalid input parameter");
        return;
    }

    pthread_mutex_lock(&dm->lock);
    resize(dm, dm->size + 1);
    dm->records[dm->size].key = key;
    dm->records[dm->size].offset = offset;
    pthread_mutex_unlock(&dm->lock);
}

void reset_data_manager(DataManager* dm) {
    pthread_mutex_lock(&dm->lock);
    memset(dm->records, 0, dm->capacity * sizeof(Record));
    dm->size = 0;
    pthread_mutex_unlock(&dm->lock);
}
