        goto cleanup;
    }
    keys = malloc(keysCapacity * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for key array.\n");
        goto cleanup;
    }

    // Implement dynamic resizing strategy for keys array
    int resizeAttempts = 3;
    while (resizeAttempts > 0) {
        recordsCount = keysCapacity;
        records = malloc(recordsCount * sizeof(Record));
        if (!records) {
            free(offsets);
            free(keys);
            --resizeAttempts;
            keysCapacity *= 2;
            continue;
        }
        break;
    }

    if (resizeAttempts == 0) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        goto cleanup;
    }

    // Initialize records with unique values and log distribution for debugging
    srand(time(NULL));
    int *uniqueValues = malloc((recordsCount + 1) * sizeof(int));
    if (!uniqueValues) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Failed to allocate memory for unique values array.\n");
        goto cleanup;
    }
    int i, j;
    for (i = 0; i < recordsCount; ++i) {
        records[i].value = rand() % 100 + 1;
        pthread_mutex_lock(&mutex);
        for (j = 0; j < i; ++j) {
            if (records[i].value == uniqueValues[j]) {
                --resizeAttempts;
                recordsCount += resizeAttempts * recordsCount / 2;
                records = realloc(records, recordsCount * sizeof(Record));
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
        if (j < i) {
            uniqueValues[i] = records[i].value;
        } else {
            --resizeAttempts;
        }
    }
    free(uniqueValues);

    // Implement logging of generated values distribution for debugging
    printf("Value distribution:\n");
    int valueCount[101] = {0};
    for (i = 0; i < recordsCount; ++i) {
        valueCount[records[i].value - 1]++;
    }
    for (i = 1; i < 101; ++i) {
        printf("%d: %d\n", i, valueCount[i]);
    }

    // Return pointers to the initialized data structures and clean up resources in case of errors
cleanup:
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);

    return (void*) {offsets, keys, records};
}
