void destroy(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
        ptr = NULL;
    }
}

int initialize_system(size_t* num_tasks, size_t* max_deps, size_t* max_edges, int* error_code) {
    *error_code = 0;

    srand(time(NULL));

    Task** tasks = calloc(*num_tasks, sizeof(Task*));
    if (tasks == NULL) {
        *error_code = -1;
        return 0;
    }

    Graph graph;
    graph.num_vertices = *num_tasks;
    graph.num_edges = *max_edges;
    graph.adjacency_matrix = malloc(graph.num_vertices * graph.num_vertices * sizeof(int));
    if (graph.adjacency_matrix == NULL) {
        *error_code = -1;
        goto cleanup_tasks;
    }

    for (size_t i = 0; i < graph.num_vertices; ++i) {
        Task* task = tasks[i] = malloc(sizeof(Task));
