        task->id = i;
        task->priority = rand() % (*max_priority + 1);
        task->num_ops = rand() % (*max_ops + 1);
        task->ops = malloc(task->num_ops * sizeof(void*));
        if (task->ops == NULL) {
            *error_code = -1;
            goto cleanup_task;
        }

        for (size_t j = 0; j < task->num_ops; ++j) {
