        task->num_deps = rand() % (*max_deps + 1);
        task->deps = malloc(task->num_deps * sizeof(int));
        if (task->deps == NULL) {
            *error_code = -1;
            goto cleanup_ops;
        }

        for (size_t j = 0; j < task->num_deps; ++j) {
            task->deps[j] = rand() % graph.num_vertices;
        }

        for (size_t j = 0; j < graph.num_edges; ++j) {
            size_t src = rand() % graph.num_vertices;
            size_t dst = rand() % graph.num_vertices;
            if (src == dst || graph.adjacency_matrix[dst * graph.num_vertices + src]) continue;

            graph.adjacency_matrix[dst * graph.num_vertices + src] = 1;
        }
    }

    // Implement cyclic dependency detection and logging here...

    // Return a handle to the initialized system environment and error code if any.
    return (void*)tasks;

cleanup_ops:
    destroy(task->ops);
    destroy(task->deps);
    destroy(task);
    continue;

cleanup_task:
    destroy(tasks[i]->ops);
    destroy(tasks[i]);
    continue;

cleanup_graph:
    destroy(graph.adjacency_matrix);
    destroy(&graph);
    continue;

cleanup_tasks:
    destroy(tasks);
    return 0;
}
