typedef struct StreamConfig {
    char id[32];
    void (*filter)(void*);
    void (*transform)(void*, void*);
    void (*aggregate)(void*, void*);
} StreamConfig;

typedef struct ActiveStream {
    StreamConfig config;
    sem_t lock;
    bool active;
} ActiveStream;

sem_t stream_map_lock;
ActiveStream *stream_map;
unsigned long num_active_streams = 0;

void init_mutexes() {
    sem_init(&stream_map_lock, 0, 1);
    for (int i = 0; i < 1024; ++i) {
        sem_init(&((ActiveStream*)stream_map + i)->lock, 0, 1);
    }
}

void destroy() {
    for (int i = 0; i < 1024; ++i) {
        sem_destroy(&((ActiveStream*)stream_map + i)->lock);
    }
    sem_destroy(&stream_map_lock);
    munmap(stream_map, 1024 * sizeof(ActiveStream));
}

void add_stream(const char* id, void (*filter)(void*), void (*transform)(void*, void*), void (*aggregate)(void*, void*)) {
    sem_t temp_lock;
    sem_init(&temp_lock, 0, 1);

    sem_wait(&stream_map_lock);

    for (int i = 0; i < 1024; ++i) {
        if (!((ActiveStream*)stream_map + i)->active) {
            memcpy(&((ActiveStream*)stream_map + i)->config, &id, sizeof(char[32]));
            ((ActiveStream*)stream_map + i)->filter = filter;
            ((ActiveStream*)stream_map + i)->transform = transform;
            ((ActiveStream*)stream_map + i)->aggregate = aggregate;
            ((ActiveStream*)stream_map + i)->active = true;
            sem_post(&temp_lock);
            break;
        }
    }

    sem_post(&stream_map_lock);
    sem_destroy(&temp_lock);
}

unsigned long get_num_active_streams() {
    unsigned long count = 0;
    for (int i = 0; i < 1024; ++i) {
        if (((ActiveStream*)stream_map + i)->active) {
            ++count;
        }
    }
    return count;
}

void configureDataProcessingPipeline() {
    void* time_start = malloc(sizeof(void));
    clock_gettime(CLOCK_MONOTONIC, (struct timespec*)time_start);

    init_mutexes();
    stream_map = mmap(NULL, 1024 * sizeof(ActiveStream), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_SHARED, -1, 0);

    // Add your streaming configuration logic here.
    // Example: add_stream("example", filter_function, transform_function, aggregate_function);

    free(time_start);
}
