    size_t res_req;
    struct task* next;
};

struct thread_data {
    pthread_t thread_id;
    struct task* current_task;
    bool terminated;
};

struct worker_pool {
    struct thread_data threads[MAX_THREADS];
    struct task* task_queue;
    int num_threads;
};

struct metrics {
    uint64_t tasks_completed;
    uint64_t tasks_failed;
    double avg_task_execution_time;
    // Add more metrics as needed
};

void worker(void* arg);
bool thread_terminate(pthread_t* thread);
struct task* dequeue_task();
void enqueue_task(struct task* task);
void free_task(struct task* task);

struct worker_pool* create_worker_pool(int num_threads) {
    struct worker_pool* wp = malloc(sizeof(struct worker_pool));
    wp->num_threads = num_threads;
    wp->task_queue = NULL;
    for (int i = 0; i < num_threads; ++i) {
        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setstacksize(&attr, THREAD_STACK_SIZE);
        pthread_create(&wp->threads[i].thread_id, &attr, worker, &wp);
    }
    return wp;
}

void destroy_worker_pool(struct worker_pool* wp) {
    for (int i = 0; i < wp->num_threads; ++i) {
        if (!thread_terminate(&wp->threads[i].thread_id)) {
            pthread_join(wp->threads[i].thread_id, NULL);
        }
    }
    free(wp);
}

// Implement worker, thread_terminate, dequeue_task, enqueue_task, and free_task functions.
// Integrate with the external task queue service as needed, handle task failures gracefully, and maintain performance metrics.
