import java.io.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.concurrent.*;
import org.imgscalr.*;
import com.lowagie.text.*;
import com.lowagie.text.pdf.*;
import processing.java.javaprocessing.*;

public class ImageConverter {
    private static final int SUCCESS = 0;
    private static final int PARTIAL_SUCCESS = 1;
    private static final int FAILURE = -1;
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final ProcessBuilder pdfConverter = new ProcessBuilder("path/to/your-pdf-converter", "-f", "%s", "-o", "%s");
    private static final ProcessBuilder imgScalr = new ProcessBuilder("path/to/imgscalr", "-i", "%s", "-q", "%d", "-outfile", "%s");
    private static final Logger logger = Logger.getLogger(ImageConverter.class);

    public static int convertJpegToPdf(String jpegPath, String outputDir, int qualitySetting) {
        File inputFile = new File(jpegPath);
        if (!inputFile.exists() || !inputFile.isFile() || !inputFile.canRead()) {
            logger.severe("Unable to read input file: " + jpegPath);
            return FAILURE;
        }

        Path outputDirPath = Paths.get(outputDir);
        if (!Files.exists(outputDirPath)) {
            try {
                Files.createDirectory(outputDirPath);
            } catch (IOException e) {
                logger.severe("Unable to create output directory: " + outputDir);
                return FAILURE;
            }
        }

        String pdfName = jpegPath.substring(jpegPath.lastIndexOf(File.separator)) + "_" + Instant.now().toString().replaceAll(":", "-") + ".pdf";
        File outputFile = new File(outputDir, pdfName);

        try {
            Process imgScalrProcess = imgScaler.start();
            imgScalrProcess.inheritIO();
            imgScalrProcess.waitFor();

            if (imgScalrProcess.exitValue() != 0) {
                logger.severe("Image scaling failed.");
                return FAILURE;
            }

            File scaledJpeg = new File(jpegPath + ".scaled");
            Process pdfConverterProcess = pdfConverter.start();
            pdfConverterProcess.directory(outputDir);
            pdfConverterProcess.redirectErrorStream(true);
            pdfConverterProcess.initIOExceptionOnError();
            BufferedReader reader = new BufferedReader(new InputStreamReader(pdfConverterProcess.getInputStream()));
            writer = new PrintWriter(outputFile);

            String line;
            while ((line = reader.readLine()) != null) {
                writer.println(line);
            }
            writer.close();

            if (pdfConverterProcess.waitFor(10, TimeUnit.SECONDS)) {
                int exitValue = pdfConverterProcess.exitValue();
                if (exitValue != 0) {
                    logger.severe("PDF conversion failed.");
                    return FAILURE;
                }
            } else {
                logger.severe("Timed out during PDF conversion.");
                return PARTIAL_SUCCESS;
            }
        } catch (IOException | InterruptedException | ExecutionException e) {
            logger.log(Level.SEVERE, "Error occurred during conversion.", e);
            return FAILURE;
        }

        return SUCCESS;
    }
}
