public class ConfigLoader
{
    private readonly ILogger<ConfigLoader> _logger;
    private readonly ConfigurationBuilder _builder;
    private readonly JsonSerializerSettings _serializerSettings;
    private readonly Dictionary<string, object> _configCache = new Dictionary<string, object>();

    public ConfigLoader(ILogger<ConfigLoader> logger)
    {
        _logger = logger;
        _serializerSettings = new JsonSerializerSettings
        {
            MissingMemberHandling = MissingMemberHandling.Ignore,
            Error = (sender, args) =>
            {
                _logger.LogError("JSON deserialization error: {Message}", args.ErrorContext.Error.Message);
                args.ErrorContext.Handled = true;
            }
        };

        _builder = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", optional: true, reloadOnChange: true)
            .AddJsonFile($"appsettings.{Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT")}.json", optional: true, reloadOnChange: true)
            .AddEnvironmentVariables();
    }

    public async Task LoadAsync()
    {
        IConfigurationRoot configuration = _builder.Build();

        var config = new Config();

        foreach (var section in configuration.GetSection("Config"))
        {
            string profile = section.Key;
            try
            {
                var json = JsonConvert.DeserializeObject<Dictionary<string, object>>(section.Value, _serializerSettings);
                if (!_configCache.ContainsKey(profile))
                    _configCache[profile] = new Config();

                MergeConfigurations((Config) _configCache[profile], json);
            }
            catch (Exception ex)
            {
                _logger.LogError("Failed to load configuration profile '{Profile}': {Error}", profile, ex.Message);
            }
        }

        config = MergeConfigurations(config, _configCache.Values.ToList());

        await SaveChangesAsync(config);
    }

    private Config MergeConfigurations(Config baseConfig, List<Config> overrides)
    {
        var result = new Config();

        foreach (var property in baseConfig.GetType().GetProperties())
        {
            object value = baseConfig.GetType().GetProperty(property.Name).GetValue(baseConfig);

            if (overrides.Any(o => o.ContainsKey(property.Name)))
            {
                value = MergeValues(value, overrides.First(o => o.ContainsKey(property.Name)).GetValue(property.Name));
            }

            result.SetProperty(property.Name, value);
        }

        return result;
    }

    private object MergeValues(object a, object b)
    {
        if (a == null && b != null) return b;
        else if (a != null && b == null) return a;

        if (a is Config && b is Config)
        {
            var c = new Config();
            MergeConfigurations((Config)a, new[] { (Config)b });
            return c;
        }

        if (a is IDictionary<string, object> && b is IDictionary<string, object>)
        {
            var merged = new Dictionary<string, object>();
            foreach (var item in ((IDictionary<string, object>)a).Concat((IDictionary<string, object>)b))
            {
                merged[item.Key] = MergeValues(item.Value, merged.ContainsKey(item.Key) ? merged[item.Key] : null);
            }
            return merged;
        }

        if (a is IList<object> && b is IList<object>)
        {
            var list = new List<object>();
            foreach (var item in ((IList<object>)a).Concat((IList<object>)b))
            {
                list.Add(MergeValues(item, null));
            }
            return list;
        }

        return a ?? b;
    }

    private async Task SaveChangesAsync(Config config)
    {
