int getRandomValue(size_t limit, std::unordered_set<int>& usedValues) {
    static std::random_device rd;  // Will be used to obtain a seed for the random number engine
    static std::mt19937 gen(rd());  // Mersenne Twister pseudorandom number engine
    static std::uniform_int_distribution<> dis(0, limit - 1); // Uniform int distribution in range [0, limit)

    int value;
    do {
        value = dis(gen);
        usedValues.erase(value);
    } while (!usedValues.empty() && !usedValues.count(value + 1));

    usedValues.insert(value);
    return value;
}

