        int value = getRandomValue(100, usedValues);

        pthread_mutex_lock(&mutex);
        records[offsets[i]].key = keys[i];
        records[offsets[i]].value = value;
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
}

