['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <string.h>
#include <sys/mman.h>
#include <assert.h>

typedef struct ConfigSection {
    char* name;
    size_t capacity;
    size_t count;
    char** keys;
    void** values;
    pthread_mutex_t mutex;
} ConfigSection;

typedef struct ConfigManager {
    size_t max_entries;
    ConfigSection* sections;
    size_t num_sections;
    void(*error_func)(const char*);
    pthread_mutex_t global_mutex;
} ConfigManager;

ConfigManager* create_config_manager(const char* config_file, size_t max_entries, void(*error_func)(const char*)) {
    ConfigManager* cm = mmap(NULL, sizeof(ConfigManager), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (cm == MAP_FAILED) {
        error_func("Memory allocation failed");
        return NULL;
    }

    cm->max_entries = max_entries;
    cm->sections = NULL;
    cm->num_sections = 0;
    cm->error_func = error_func;

    pthread_mutex_init(&cm->global_mutex, NULL);

    return cm;
}

void parse_config(ConfigManager* cm, FILE* fp) {
    char line[4096];
    ConfigSection* current_section = NULL;

    while (fgets(line, sizeof(line), fp)) {
        if (strlen(line) == 1 && line[0] == '\n') continue; // Skip empty lines

        char* start = line;
        char* end = strchr(start, '=');
        if (!end) {
            cm->error_func("Invalid configuration line: Missing equals sign");
            return;
        }

        size_t section_len = end - start;
        char section[section_len + 1];
        strncpy(section, start, section_len);
        section[section_len] = '\0';

        if (!current_section) {
            current_section = add_section(cm, section);
        } else if (strcmp(section, current_section->name) != 0) {
            cm->error_func("Invalid configuration: Multiple sections with the same name");
            return;
        }

        size_t key_len = end - start;
        char key[key_len + 1];
        strncpy(key, start, key_len);
        key[key_len] = '\0';

        size_t value_len = strlen(end + 1);
        char* value = malloc(value_len + 1);
        if (!value) {
            cm->error_func("Memory allocation failed");
            return;
        }
        strcpy(value, end + 1);

        add_entry(current_section, key, value);
    }
}

ConfigSection* find_section(ConfigManager* cm, const char* section_name) {
    for (size_t i = 0; i < cm->num_sections; ++i) {
        if (strcmp(cm->sections[i].name, section_name) == 0) return &cm->sections[i];
    }
    return NULL;
}

ConfigSection* add_section(ConfigManager* cm, const char* section_name) {
    pthread_mutex_lock(&cm->global_mutex);

    ConfigSection* new_section = realloc(cm->sections, sizeof(ConfigSection) * (cm->num_sections + 1));
    if (!new_section) {
        cm->error_func("Memory allocation failed");
        pthread_mutex_unlock(&cm->global_mutex);
        return NULL;
    }
    cm->sections = new_section;

    new_section->name = strdup(section_name);
    if (!new_section->name) {
        cm->error_func("Memory allocation failed");
        pthread_mutex_unlock(&cm->global_mutex);
        free(new_section);
        return NULL;
    }

    new_section->capacity = 4;
    new_section->count = 0;
    new_section->keys = malloc(sizeof(char*) * new_section->capacity);
    if (!new_section->keys) {
        cm->error_func("Memory allocation failed");
        pthread_mutex_unlock(&cm->global_mutex);
        free(new_section->name);
        free(new_section);
        return NULL;
    }
    new_section->values = malloc(sizeof(void*) * new_section->capacity);
    if (!new_section->values) {
        cm->error_func("Memory allocation failed");
        pthread_mutex_unlock(&cm->global_mutex);
        free(new_section->name);
        free(new_section->keys);
        free(new_section);
        return NULL;
    }
    pthread_mutex_init(&new_section->mutex, NULL);

    cm->num_sections++;

    pthread_mutex_unlock(&cm->global_mutex);

    return &cm->sections[cm->num_sections - 1];
}

void add_entry(ConfigSection* section, const char* key, void* value) {
    pthread_mutex_lock(&section->mutex);

    for (size_t i = 0; i < section->count; ++i) {
        if (strcmp(section->keys[i], key) == 0) {
            free(value);
            pthread_mutex_unlock(&section->mutex);
            cm->error_func("Duplicate keys are not allowed in the same section");
            return;
        }
    }

    if (section->count >= section->capacity) {
        size_t new_capacity = section->capacity * 2;
        char** new_keys = realloc(section->keys, sizeof(char*) * new_capacity);
        void** new_values = realloc(section->values, sizeof(void*) * new_capacity);
        if (!new_keys || !new_values) {
            pthread_mutex_unlock(&section->mutex);
            cm->error_func("Memory allocation failed");
            return;
        }
        section->keys = new_keys;
        section->values = new_values;
        section->capacity = new_capacity;
    }

    section->keys[section->count] = strdup(key);
    if (!section->keys[section->count]) {
        pthread_mutex_unlock(&section->mutex);
        cm->error_func("Memory allocation failed");
        return;
    }
    section->values[section->count] = value;

    section->count++;

    pthread_mutex_unlock(&section->mutex);
}

void update_entry(ConfigSection* section, const char* key, void* new_value) {
    pthread_mutex_lock(&section->mutex);

    for (size_t i = 0; i < section->count; ++i) {
        if (strcmp(section->keys[i], key) == 0) {
            free(section->values[i]);
            section->values[i] = new_value;
            pthread_mutex_unlock(&section->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&section->mutex);
    cm->error_func("Key not found in the specified section");
}

void* get_entry(ConfigSection* section, const char* key) {
    pthread_mutex_lock(&section->mutex);

    for (size_t i = 0; i < section->count; ++i) {
        if (strcmp(section->keys[i], key) == 0) {
            void* value = section->values[i];
            pthread_mutex_unlock(&section->mutex);
            return value;
        }
    }

    pthread_mutex_unlock(&section->mutex);
    cm->error_func("Key not found in the specified section");
    return NULL;
}

void delete_entry(ConfigSection* section, const char* key) {
    pthread_mutex_lock(&section->mutex);

    for (size_t i = 0; i < section->count; ++i) {
        if (strcmp(section->keys[i], key) == 0) {
            free(section->keys[i]);
            free(section->values[i]);

            memmove(&section->keys[i], &section->keys[i + 1], sizeof(char*) * (section->count - i - 1));
            memmove(&section->values[i], &section->values[i + 1], sizeof(void*) * (section->count - i - 1));

            section->count--;

            if (section->capacity / 2 > section->count) {
                size_t new_capacity = section->capacity / 2;
                char** new_keys = realloc(section->keys, sizeof(char*) * new_capacity);
                void** new_values = realloc(section->values, sizeof(void*) * new_capacity);
                if (!new_keys || !new_values) {
                    pthread_mutex_unlock(&section->mutex);
                    cm->error_func("Memory allocation failed");
                    return;
                }
                section->keys = new_keys;
                section->values = new_values;
                section->capacity = new_capacity;
            }

            pthread_mutex_unlock(&section->mutex);
            return;
        }
    }

    pthread_mutex_unlock(&section->mutex);
    cm->error_func("Key not found in the specified section");
}

void delete_section(ConfigManager* cm, const char* section_name) {
    ConfigSection* section = find_section(cm, section_name);
    if (!section) return;

    pthread_mutex_lock(&cm->global_mutex);

    for (size_t i = 0; i < cm->num_sections; ++i) {
        if (cm->sections[i].name == section->name) {
            free(section->name);
            for (size_t j = 0; j < section->count; ++j) {
                free(section->keys[j]);
                free(section->values[j]);
            }
            free(section->keys);
            free(section->values);

            memmove(&cm->sections[i], &cm->sections[i + 1], sizeof(ConfigSection) * (cm->num_sections - i - 1));
            cm->num_sections--;

            pthread_mutex_unlock(&cm->global_mutex);
            return;
        }
    }

    pthread_mutex_unlock(&cm->global_mutex);
    cm->error_func("Section not found in the configuration manager");
}

void free_config(ConfigManager* cm) {
    for (size_t i = 0; i < cm->num_sections; ++i) {
        free(cm->sections[i].name);
        for (size_t j = 0; j < cm->sections[i].count; ++j) {
            free(cm->sections[i].keys[j]);
            free(cm->sections[i].values[j]);
        }
        free(cm->sections[i].keys);
        free(cm->sections[i].values);
    }
    free(cm->sections);
}']

