typedef struct {
    DL_FRAME_TRANSPORT_CHANNEL channel;
    DL_FRAME_TRANSPORT_FORMAT format;
} LTE_DL_FRAME_MSG;

struct network_module {
    size_t capacity;
    size_t size;
    LTE_DL_FRAME_MSG* frames;
    pthread_mutex_t lock;
};

struct network_module* create_network_module(size_t capacity) {
    struct network_module* module = malloc(sizeof(struct network_module));
    if (!module) return NULL;

    module->capacity = capacity;
    module->size = 0;
    module->frames = calloc(capacity, sizeof(LTE_DL_FRAME_MSG));
    if (!module->frames) {
        free(module);
        return NULL;
    }

    pthread_mutex_init(&module->lock, NULL);

    return module;
}

void enqueue_frame(struct network_module* module, const LTE_DL_FRAME_MSG msg) {
    pthread_mutex_lock(&module->lock);

    if (module->size == module->capacity) {
        // Handle overflow, e.g., drop the oldest frame or extend capacity
    }

    module->frames[module->size] = msg;
    module->size++;

    pthread_mutex_unlock(&module->lock);
}

LTE_DL_FRAME_MSG dequeue_frame(struct network_module* module) {
    LTE_DL_FRAME_MSG frame;
    pthread_mutex_lock(&module->lock);

    if (module->size == 0) {
        // Handle underflow, e.g., return a default or error frame
    }

    frame = module->frames[0];
    memcpy(module->frames, module->frames + 1, --module->size * sizeof(LTE_DL_FRAME_MSG));

    pthread_mutex_unlock(&module->lock);

    return frame;
}

void destroy_network_module(struct network_module* module) {
    pthread_mutex_destroy(&module->lock);
    free(module->frames);
    free(module);
}
```

