    int rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
};

class CRCArrManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> data;
    std::unordered_map<int, size_t> rntiToIndex;
    std::mutex mtx;

public:
    CRCArrManager() = default;

    void add(const NFAPI_CRC_INDICATION_PDU_T& pdus) {
        std::lock_guard<std::mutex> lock(mtx);
        if (rntiToIndex.find(pdus.rnti) == rntiToIndex.end()) {
            data.push_back(pdus);
            rntiToIndex[pdus.rnti] = data.size() - 1;
        } else {
            std::cerr << "Duplicate RNTI detected: " << pdus.rnti << std::endl;
        }
    }

    bool update(int rnti, const NFAPI_CRC_INDICATION_PDU_T& pdus) {
        auto it = rntiToIndex.find(rnti);
        if (it != rntiToIndex.end()) {
            std::lock_guard<std::mutex> lock(mtx);
            data[it->second] = pdus;
            return true;
        } else {
            return false;
        }
    }

    void delByRnti(int rnti) {
        auto it = rntiToIndex.find(rnti);
        if (it != rntiToIndex.end()) {
            std::lock_guard<std::mutex> lock(mtx);
            size_t index = it->second;
            data[index] = data.back();
            rntiToIndex[data.back().rnti] = index;
            rntiToIndex.erase(it);
            data.pop_back();
        } else {
            std::cerr << "Non-existent RNTI: " << rnti << std::endl;
        }
    }

    void delByIndex(size_t index) {
        if (index < data.size()) {
            std::lock_guard<std::mutex> lock(mtx);
            NFAPI_CRC_INDICATION_PDU_T tmp = data[index];
            rntiToIndex[tmp.rnti] = -1;
            data[index] = data.back();
            rntiToIndex[data.back().rnti] = index;
            data.pop_back();
        } else {
            std::cerr << "Non-existent index: " << index << std::endl;
        }
    }
};
```

