[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* array;
    pthread_mutex_t mutex;
    bool error_occurred;
} dynamic_array_t;

void init_dynamic_array(dynamic_array_t* da, size_t initial_capacity) {
    if (initial_capacity > 1024)
        initial_capacity = 1024;

    da->capacity = initial_capacity;
    da->size = 0;
    da->array = malloc(da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        fprintf(stderr, "Error: failed to allocate memory for dynamic array\n");
        da->error_occurred = true;
        return;
    }

    pthread_mutex_init(&da->mutex, NULL);
}

void destroy_dynamic_array(dynamic_array_t* da) {
    if (da->array) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
    }
}

static RNTI generate_rnti() {
    static int rnti = 1;
    return (RNTI)rnti++;
}

static CRC_INDICATION_REL8_TAG generate_crc_indication() {
    time_t rawtime;
    struct tm *timeinfo;
    CRC_INDICATION_REL8_TAG tag;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    tag.sequence_number = (SEQUENCE_NUMBER)(timeinfo->tm_sec | (timeinfo->tm_min << 16) | (timeinfo->tm_hour << 32));
    tag.crcflag = (CRCFLAG)(rand() & 0x1);

    return tag;
}

void push_data(dynamic_array_t* da) {
    if (!da->error_occurred && da->size >= da->capacity) {
        da->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(da->array, da->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Error: failed to resize dynamic array\n");
            da->error_occurred = true;
            return;
        }
        da->array = new_array;
    }

    pthread_mutex_lock(&da->mutex);
    RNTI rnti = generate_rnti();
    while (has_duplicate_rnti(da, rnti)) {
        rnti = generate_rnti();
    }

    NFAPI_CRC_INDICATION_PDU_T* elem = &da->array[da->size];
    elem->tag.RX_UE_INFORMATION_TAG_rnti = rnti;
    elem->rnti = rnti;
    elem->crc_indication = generate_crc_indication();

    da->size++;
    pthread_mutex_unlock(&da->mutex);
}

bool has_duplicate_rnti(const dynamic_array_t* da, RNTI rnti) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].rnti == rnti)
            return true;
    }
    return false;
}

void print_dynamic_array(const dynamic_array_t* da) {
    for (size_t i = 0; i < da->size; ++i) {
        printf("Element %zu:\n", i);
        printf("\trnti: %d\n", da->array[i].rnti.value);
        printf("\ttag.RX_UE_INFORMATION_TAG_rnti: %d\n", da->array[i].tag.RX_UE_INFORMATION_TAG_rnti.value);
        printf("\tcrc_indication:\n");
        printf("\t\tsequence_number: %lld\n", da->array[i].crc_indication.sequence_number);
        printf("\t\tcrcflag: %d\n", da->array[i].crc_indication.crcflag);
        printf("\n");
    }
}
```

