static sem_t log_mutex;
static int skipped_count = 0;

void log_skipped() {
    if (sem_trywait(&log_mutex) == 0) {
        printf("Skipped %d elements due to duplicate RNTI values\n", skipped_count);
        sem_post(&log_mutex);
        skipped_count = 0;
    }
}

void generate_and_populate_nfaapi_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t max_pdu_count) {
    static unsigned long long unique_rnti = 1;
    if (max_pdu_count <= 0) {
        printf("Error: max_pdu_count must be greater than 0\n");
        return;
    }

    sem_init(&log_mutex, 0, 1);

    pthread_t log_thread;
    pthread_create(&log_thread, NULL, &log_function, NULL);

    size_t count = 0;
    NFAPI_CRC_INDICATION_PDU_T *current_pdu = pdus;
    for (size_t i = 0; i < max_pdu_count; ++i) {
        current_pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG(i % 128);
        current_pdu->rnti = (RNTI)unique_rnti++;
        current_pdu->crc_indication_rel8_tag.crcflag = rand() % 2;

        pthread_mutex_lock(&pdus[i].rnti); // Ensure atomicity when modifying RNTIs to handle concurrent access
        if (pdus[current_pdu->rnti].rnti != current_pdu->rnti) {
            ++count;
            current_pdu++;
            continue;
        }
        pthread_mutex_unlock(&pdus[current_pdu->rnti].rnti);

        if (++count == max_pdu_count) break;
        current_pdu++;
    }

    pthread_join(log_thread, NULL);
}

void* log_function(void *arg) {
    while (true) {
        sleep(1); // Log periodically to minimize impact on performance
        log_skipped();
    }
    return NULL;
}
