                    if (read < 0) break; // End of file
                    charBuffer.clear();
                    charBuffer.put(cbuf, 0, read);
                    charBuffer.flip();
                    String line = charBuffer.toString();

                    linesRead++;
                    if (linesRead % 100_000 == 0 && logDetails) logToFile(logPath, "Processed " + linesRead + " lines");

                    // Parse Pokemon data from the line
                    String[] parts = line.split("\\s+");
                    if (parts.length < 3) continue; // Invalid line, ignore it

