                    switch (type) {
                        case FIRE: weaknesses.addAll(Arrays.asList("Water", "Rock")); break;
                        // ... Add more cases for other types
                        default: continue; // Unknown type, ignore the line
                    }

                    if (currentPokemon == null) {
                        currentPokemon = new Pokemon(name, type);
                    } else {
                        // Merge weaknesses of current and upcoming Pokemon
                        currentPokemon.setWeaknesses(currentPokemon.getWeaknesses().stream().distinct().collect(Collectors.toList()));
                        currentPokemon.getWeaknesses().addAll(weaknesses);
                    }

                    if (linesRead % bufferSize == 0 && executor != null) { // Process Pokemons incrementally if applying rules in parallel
                        List<Callable<Void>> tasks = new ArrayList<>();
                        for (String rule : ruleSet) {
                            tasks.add(() -> applyRule(currentPokemon, rule));
                        }
                        executor.invokeAll(tasks).forEach(Future::get); // Apply rules to the current Pokemon and wait for completion
                        currentPokemon = null;
                    }
                }

                // Write the final Pokemon data to the output file
                writer.println(currentPokemon == null ? "" : currentPokemon.toString());
            }
        } catch (Exception e) {
            if (logDetails) logToFile(logPath, "Error processing file: " + e.getMessage(), true);
            throw new RuntimeException("Error processing file", e);
        } finally {
            executor.shutdown();
        }
    }

    private static void applyRule(Pokemon pokemon, String rule) {
