    if (!new_fsa) return NULL;

    const int state_mem_size = sizeof(FSA_STATE) * (num_states + 1);
    new_fsa->states = malloc(state_mem_size);
    if (!new_fsa->states) {
        free(new_fsa);
        return NULL;
