    memcpy(new_fsa->states, state_list, state_mem_size - sizeof(FSA_STATE));

    new_fsa->num_states = num_states;
    new_fsa->transitions = fsa_struct->transitions;

    FSA_STATE* last_state = &new_fsa->states[num_states];
