    const size_t record_size = sizeof(record);
    size_t total_size = record_size * count + sizeof(int) * 4; // offsets, keys, flags, index

    record *records = NULL, *current_record;
    int *offsets = NULL, *keys_array = NULL, *flags = NULL, *index_array = NULL;

    records = (record*) malloc(total_size);
    if (!records) {
        perror("Memory allocation for records failed");
        exit(EXIT_FAILURE);
    }

    offsets = (int*)((char*)records + record_size * count);
    keys_array = offsets + count;
    flags = keys_array + count;
    index_array = flags + count;

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        int key = keys[i];
        int offset = offsets[i] = (key * key + key + i) % INT_MAX;
        current_record = &records[index_array[i] = i];
        sprintf(current_record->buffer, "Record_%d_Key_%d", offset, key);
        current_record->key = key;
        current_record->flag = (key % 2 == 0);
    }

    return records;
}
