This implementation utilizes std::vector from the C++ Standard Template Library (STL) to dynamically manage the linked list of states. It uses boost::mutex for synchronization in a multi-threaded environment and provides methods to traverse and modify the list efficiently.

```cpp
#include <vector>
#include <memory>
#include <utility>
#include <boost/mutex.hpp>
#include <boost/shared_ptr.hpp>

class FSA; // Forward declaration

struct StateNode {
    int state;
    boost::shared_ptr<StateNode> next;

    StateNode(int s, boost::shared_ptr<StateNode> n) : state(s), next(n) {}
};

class StateList {
private:
    std::vector<boost::shared_ptr<StateNode>> nodes;
    boost::mutex mtx;

public:
    StateList() = default;
    ~StateList() { clear(); }

    void push_back(int state) {
        boost::unique_lock<boost::mutex> lock(mtx);
        nodes.emplace_back(std::make_shared<StateNode>(state, head));
        head = nodes.back();
    }

    StateNode* getHead() const {
        boost::unique_lock<boost::mutex> lock(mtx);
        return head.get();
    }

    void setLast(int index) {
        boost::unique_lock<boost::mutex> lock(mtx);
        if (index >= 0 && index < nodes.size()) {
            nodes[index]->next = head;
        }
    }

    void clear() {
        boost::unique_lock<boost::mutex> lock(mtx);
        nodes.clear();
        head.reset();
    }
};

StateList* createLinkedList(int* states, int numStates, const FSA& fsa, int lastState) {
    StateList* list = new StateList;
    for (int i = 0; i < numStates; ++i) {
        list->push_back(states[i]);
    }
    list->setLast(lastState);
    return list;
}
