typedef struct ASTNode {
    void *data;
    size_t childrenCount;
    struct ASTNode **children;
} ASTNode;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;
static ASTNode *cache[1024]; // Cache for frequently accessed nodes (1KB max)

void astTraverse(ASTNode *node, void (*selector)(void *data), size_t depth, NFAPI_CRC_INDICATION_PDU_T *resultList, size_t resultListSize) {
    if (!node || !selector) return;

    selector(node->data); // Call the selector for this node (if it matches, add it to the result list)

    pthread_mutex_lock(&cacheLock);
    bool foundInCache = false;
    size_t i;
    for (i = 0; i < sizeof(cache)/sizeof(*cache); ++i) {
        if (cache[i] == node) {
            foundInCache = true;
            break;
        }
    }
    pthread_mutex_unlock(&cacheLock);

    if (!foundInCache) { // If not in the cache, add it
        if (depth < sizeof(cache)/sizeof(*cache)) {
            pthread_mutex_lock(&cacheLock);
            cache[depth] = node;
            pthread_mutex_unlock(&cacheLock);
        }
    }

    if (!node->children) return;

    size_t childrenCount = node->childrenCount;
    for (size_t i = 0; i < childrenCount; ++i) {
        astTraverse(node->children[i], selector, depth + 1, resultList, resultListSize);
    }
}

void *generateIndications(ASTNode *rootNode, void (*selector)(void *data), size_t resultListSize) {
    NFAPI_CRC_INDICATION_PDU_T resultList[resultListSize];
    size_t numGenerated = 0;

    astTraverse(rootNode, selector, 0, resultList, resultListSize);

    // Fill the generated structures with random CRCFLAGS and RNTIs
    for (size_t i = 0; i < numGenerated; ++i) {
        resultList[i].CRCFLAG = rand() % 256;
        resultList[i].RNTI = rand() % 65536;
        resultList[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        resultList[i].RX_UE_INFORMATION_TAG = i + 1; // Assign a unique tag for each generated structure
    }

    return malloc(numGenerated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}
```

