// Function to parse configuration file and initialize configuration manager
struct configuration_manager *initialize_config_manager(const char *config_file_path, int max_entries, void (*error_handler)(const char*, ...)) {
    // Initialize configuration manager structure
    struct configuration_manager *cm = malloc(sizeof(struct configuration_manager));
    cm->config_file_path = config_file_path;
    cm->max_entries = max_entries;
    cm->error_handler = error_handler ? error_handler : custom_error_handler;
    pthread_mutex_init(&cm->lock, NULL);

    // Parse configuration file and store settings in hash table
    int fd = open(config_file_path, O_RDONLY);
    if (fd == -1) {
        cm->error_handler("Failed to open configuration file: %s", config_file_path);
        return NULL;
    }

    char *line = mmap(NULL, 4096, PROT_READ, MAP_PRIVATE, fd, 0);
    if (line == MAP_FAILED) {
        cm->error_handler("Failed to map configuration file: %s", config_file_path);
        return NULL;
    }

    GHashTable *settings = g_hash_table_new(g_str_hash, g_str_equal);

    size_t line_len;
    ssize_t bytes_read;
    while ((bytes_read = read(fd, line, 4096)) > 0) {
        line_len = strlen(line);
        if (line[line_len - 1] == '\n')
            line[line_len - 1] = '\0'; // Remove newline character

        char *token = strtok(line, "=");
        if (!token) continue; // Skip empty lines or lines without equal sign

        char key[256];
        char value[4096];
        strncpy(key, token, 255);
        strcpy(value + strlen(key), line);

        // Handle duplicate keys within the same section gracefully
        if (g_hash_table_contains(settings, key)) {
            cm->error_handler("Duplicate configuration key found: %s", key);
        } else {
            g_hash_table_insert(settings, key, value);
        }
    }

    munmap(line, 4096);
    close(fd);

    cm->settings = settings;
    return cm;
}

