typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct generateNFAPDUListData {
    NFAPI_CRC_INDICATION_PDU_T* list;
    size_t* index;
    int numElems;
};

static void *generateNFAPDUListWorker(void *data) {
    struct generateNFAPDUListData* d = data;
    for (int i = *d->index; i < d->numElems && clock() - d->startTime < CLOCKS_PER_SEC * 2; ++(*d->index)) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &d->list[*d->index];
        pdu->RX_UE_INFORMATION_TAG = *d->index % 0xFFFF;
        pdu->RNTI = *d->index % 128 + 1; // No two consecutive structures share the same RNTI value
        pdu->CRC_INDICATION_REL8_TAG = ((pdu->RNTI ^ (*d->index)) & 0x0001) << 14 | (pdu->RNTI & 0x3FFF);
    }
    return NULL;
}

int generateNFAPDUList(NFAPI_CRC_INDICATION_PDU_T* list, size_t numElems, int* errorCode) {
    if (numElems > 1000 || numElems * sizeof(NFAPI_CRC_INDICATION_PDU_T) > availableSystemMemory / 2) {
        *errorCode = -1; // Memory allocation error
        return -1;
    }

    struct generateNFAPDUListData data = { list, &i, numElems };
    int numThreads = (numElems * 2) / 3 + 1; // Adjust the number of threads for better parallelism and load balancing
    pthread_t* threads = malloc(numThreads * sizeof(pthread_t));
    data.startTime = clock();

    for (int i = 0; i < numThreads; ++i) {
        int ret = pthread_create(&threads[i], NULL, generateNFAPDUListWorker, &data);
        if (ret != 0) {
            *errorCode = -1; // Thread creation error
            return -1;
        }
    }

    for (int i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);

    if (*errorCode == -1 || clock() - data.startTime >= CLOCKS_PER_SEC * 2) { // Check if time limit was exceeded
        *errorCode = -2; // Timeout error
    } else {
        *errorCode = 0;
    }

    return *errorCode;
}
