function authUserWithOAuth2($accessTokenURL, $token) {
    global $_SESSION; // Assuming sessions are already initialized

    if (!isset($_SESSION['oauth_access_token'])) {
        $_SESSION['oauth_access_token'] = $token;

        try {
            $ch = curl_init($accessTokenURL);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_POSTFIELDS, 'grant_type=access_token&access_token=' . $token);

            $response = json_decode(curl_exec($ch), true);
            if ($response === false) {
                throw new Exception('Curl error');
            }

            if (isset($response['error'])) {
                throw new Exception($response['error']);
            }

            $_SESSION['oauth_access_token'] = $response['access_token'];
