#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <json-c/json.h>
#include <syslog.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} cipher_params;

typedef struct cipher_node {
    cipher_params params;
    struct cipher_node *next;
    json_object *json_representation;
    pthread_key_t key; // Thread-Local Storage for logging information
} cipher_node;

cipher_node* create_cipher_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    cipher_node *new_node = (cipher_node *) malloc(sizeof(cipher_node));
    if (!new_node) {
        syslog(LOG_ERR, "Memory allocation failure");
        return NULL;
    }

    new_node->params.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->params.RNTI = RNTI;
    new_node->params.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->params.CRCFLAG = CRCFLAG;
    new_node->next = NULL;
    new_node->json_representation = json_object_new_object();
    if (!new_node->json_representation) {
        syslog(LOG_ERR, "JSON object allocation failure");
        free(new_node);
        return NULL;
    }

    pthread_key_create(&new_node->key, NULL);

    return new_node;
}

cipher_node* add_cipher_to_list(cipher_node **head, cipher_node *new_node) {
    if (!*head) {
        *head = new_node;
    } else {
        cipher_node *current = *head;
        while (current->next != NULL) current = current->next;
        current->next = new_node;
    }
    return *head;
}

void cleanup(cipher_node **head) {
    cipher_node *current = *head;
    cipher_node *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        json_object_put(temp->json_representation);
        free(temp);
    }
    *head = NULL;
}

// Implement logging function using TLS and syslog
void log_message(int priority, const char *format, ...) {
    va_list args;
    void *tls_data;
    if ((tls_data = pthread_getspecific(pthread_self()->key)) != NULL) {
        openlog("cipher_manager", LOG_PERROR | priority, LOG_DAEMON);
        vsyslog(priority, format, args);
        closelog();
    }
}

// Implement the main function to manage and process cipher configurations
int initialize_cipher_configurations(const char *logfile_path, int max_buffer_size, int loglevel) {
    int err = 0;

    openlog("cipher_manager", LOG_PERROR | loglevel, LOG_DAEMON);

    // Initialize list to store cipher configurations
    cipher_node *head = NULL;

    // Populate the list with desired number of cipher nodes
    for (int i = 0; i < MAX_NUMBER_OF_CIPHERS; ++i) {
        cipher_node *new_cipher = create_cipher_node(RX_UE_INFORMATION_TAG + i, RNTI + i, CRC_INDICATION_REL8_TAG + i, (CRCFLAG ? 1 : 0));
        if (!new_cipher) {
            syslog(LOG_ERR, "Failed to allocate cipher node");
            err = -1;
            break;
        }
        head = add_cipher_to_list(&head, new_cipher);
    }

    if (!err) {
        // Serialize the list to JSON format and save it to a file or use for further processing.
        json_object *root = json_object_new_array();
        cipher_node *current = head;
        while (current != NULL) {
            json_object *cipher_obj = json_object_get(current->json_representation, "params");
            json_array_put_object(root, cipher_obj);
            current = current->next;
        }

        // Write JSON data to a file or send it over network using provided mechanisms.
    }

    // Cleanup resources when an error occurs, or the function terminates normally
    cleanup(&head);

    closelog();
    return err;
}
