State* processAndTransmitData(int *states, int num_states, FSA *fsa, void (*action)(int state), const char *filename, int max_records) {
    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    // Deserialize data into a list of custom structures
    DataRecord **data_list = deserialize(file, max_records);
    if (!data_list) {
        fclose(file);
        return NULL;
    }

    // Allocate memory for the new state list
    State *new_state_list = malloc(sizeof(State) * num_states);
    if (!new_state_list) {
        free(data_list);
        fclose(file);
        return NULL;
    }

    // Initialize the new state list with the initial state
    for (int i = 0; i < num_states; ++i) {
        new_state_list[i].state = states[i];
        new_state_list[i].data = NULL;
        if (new_state_list[i].state == fsa->initial_state) {
            new_state_list[i].data = data_list[0];
        }
    }

    // Traverse the FSA and update state list accordingly
    int current_state = fsa->initial_state;
    for (int i = 0; i < max_records && current_state != -1; ++i) {
        State *current_state_ptr = &new_state_list[current_state];

        // Deserialize and process the current data record
        DataRecord *data_record = current_state_ptr->data;
        RX_UE_INFORMATION_TAG ue_tag = deserialize_ue_tag(data_record);
        RNTI rnti = deserialize_rnti(data_record);
        CRC_INDICATION_REL8_TAG crc_indication = { .crcflag = rand() % 2 };
        deserialize_crc_indication(&crc_indication, data_record);

        // Transition to the next state based on the transition rules
        current_state = fsa->transition_table[current_state][ue_tag][rnti];

        // Perform any state actions
        if (current_state != -1) {
            action(current_state);
        }

        // Update the data for the current state in the new state list
        current_state_ptr->data = data_list[i];
    }

    free(data_list);
    fclose(file);
    return new_state_list;
}
