#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t rnti;
    uint8_t crcflag;
    RX_UE_INFORMATION_TAG tag;
    CRC_INDICATION_REL8_TAG rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

struct external_data {
    bool is_valid;
    uint64_t data;
};

static sem_t mem_sem, ext_data_sem;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t max_structures = 1000;
static int curr_structures = 0;
static NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
static struct external_data* ext_data = NULL;

void gen_structures(void* arg) {
    while (true) {
        sem_wait(&mem_sem);

        if (curr_structures >= max_structures / 2 || getrusage().ru_maxrss > (RUSAGE_SELF >> 3))
            pthread_exit(NULL);

        int rnti = rand() % (1024 - 1); // Generate RNTI values within 1-1023 range
        NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        sem_wait(&ext_data_sem);
        structure->rnti = rnti;
        structure->crcflag = rnti ^ curr_structures++; // Generate CRCFLAG based on RNTI and index
        structure->tag.value = rand(); // Generate tag value
        structure->rel8_tag.value = rand(); // Generate rel8_tag value

        if (!ext_data || !ext_data->is_valid) {
            ext_data->is_valid = true;
            // Initialize external data here
        }

        sem_post(&ext_data_sem);
        sem_post(&mem_sem);
    }
}

void init() {
    curr_structures = 0;
    structures = calloc(max_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ext_data = malloc(sizeof(struct external_data));
    sem_init(&mem_sem, 1, max_structures - (max_structures / 2));
    sem_init(&ext_data_sem, 1, 1);
    pthread_t tid[max_structures / 4]; // Number of threads can be adjusted based on system capabilities

    for (int i = 0; i < max_structures / 4; ++i) {
        pthread_create(&tid[i], NULL, gen_structures, NULL);
    }
}

void cleanup() {
    // Wait for all threads to finish and free resources
}
