    std::int64_t timestamp;
    enum EventType { CONNECT, DISCONNECT };
    EventType eventType;
    std::string payload;

    bool operator<(const NFDataRecord& other) const {
        return timestamp < other.timestamp;
    }
};

// Define the DataRecordManager class for managing a dynamic array of NFDataRecords.
class DataRecordManager {
private:
    std::multimap<std::int64_t, std::unique_ptr<NFDataRecord>> data;
    mutable std::mutex mtx;

public:
    // Insert a new record into the dynamic array, sorted by timestamp.
    void insert(const NFDataRecord& record) {
        std::unique_lock<std::mutex> lock(mtx);
        data.insert(std::make_pair(record.timestamp, std::move(std::unique_ptr<NFDataRecord>(new NFDataRecord(record)))));
    }

    // Remove a record from the dynamic array by timestamp and free the memory.
    void erase(const std::int64_t timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = data.equal_range(timestamp);
        for (auto pos = it.first; pos != it.second; ++pos) {
            pos->second.reset();
        }
    }

    // Retrieve a record by timestamp, sorted by timestamp.
    const NFDataRecord* find(const std::int64_t timestamp) const {
        const auto it = data.find(timestamp);
        return (it != data.end()) ? it->second.get() : nullptr;
    }
};

