};

class CRC_INDICATION_REL8_TAG {
public:
    bool crcflag;

    // Constructor initializes the CRC flag with a randomly set value.
    CRC_INDICATION_REL8_TAG() : crcflag(std::random_device{}() >> 16 & 1) {}
};

class GC {
public:
    void collect() {
        std::list<boost::intrusive_ptr<CRC_INDICATION_REL8_TAG>> to_delete;
        for (auto& elem : m_gc_map) {
            if (elem.second->use_count() == 1) {
                to_delete.push_back(std::move(elem.second));
            }
        }

        for (auto ptr : to_delete) {
            m_gc_map.erase(ptr);
            delete ptr;
        }
    }

private:
    using GCMap = boost::container::concurrent_unordered_map<uint32_t, boost::intrusive_ptr<CRC_INDICATION_REL8_TAG>>;
    GCMap m_gc_map;
};

class DynamicList {
public:
    std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T> add(const RX_UE_INFORMATION_TAG& rx_ue_information_tag, uint32_t rnti) {
        auto crc_indication_rel8_tag = std::make_shared<CRC_INDICATION_REL8_TAG>();
        auto new_element = std::make_shared<NFAPI_CRC_INDICATION_PDU_T>(rx_ue_information_tag, rnti, crc_indication_rel8_tag);

        m_dynamic_list.emplace(rnti, new_element);
        ++crc_indication_rel8_tag->use_count();
        return new_element;
    }

    void update(uint32_t rnti, const std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>& element) {
        m_dynamic_list.modify(rnti, [&](auto& p) {
            if (p) {
                (*p).crc_indication_rel8_tag = element->crc_indication_rel8_tag;
            }
        });
    }

    void iterate(std::function<void(const std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>&)> callback) {
        for (auto& elem : m_dynamic_list) {
            if (elem.second) {
                callback(elem.second);
            }
        }
    }

private:
    boost::container::concurrent_unordered_map<uint32_t, std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> m_dynamic_list;
    GC gc;
};
```

