void insert_node(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *new_node) {
    pthread_mutex_lock(&list_mutex);

    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }

    pthread_mutex_unlock(&list_mutex);
}

int validate_list(NFAPI_CRC_INDICATION_PDU_T *head, unsigned int num_nodes) {
    int duplicate_found = 0;
    unsigned int RTNIs[num_nodes];

    pthread_mutex_lock(&list_mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = head;
    for (int i = 0; i < num_nodes && current != NULL; ++i) {
        if (i < num_nodes - 1 && RTNIs[current->RNTI] != 0) {
            duplicate_found = 1;
            break;
        }
        RTNIs[current->RNTI] = 1;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
    return !duplicate_found;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T **head) {
    NFAPI_CRC_INDICATION_PDU_T *temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

void populate_list(unsigned int num_nodes, unsigned int RX_UE_INFORMATION_TAG_start, unsigned int RX_UE_INFORMATION_TAG_step, unsigned int max_RNTI) {
