typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

struct array {
    std::unordered_map<RNTI, size_t> hashTable;
    NFAPI_CRUC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
};

// Custom memory allocator using malloc and free
void* customMalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Log error here for more advanced memory management integration
        fprintf(stderr, "Error: Out of memory\n");
    }
    return ptr;
}

void customFree(void* ptr) {
    free(ptr);
}

// Initialize the array with a given capacity using malloc and the custom allocator
void initArray(struct array* arr, size_t capacity) {
    arr->data = (NFAPI_CRUC_INDICATION_PDU_T*)customMalloc(capacity * sizeof(NFAPI_CRUC_INDICATION_PDU_T));
    if (!arr->data) return;

    arr->capacity = capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, nullptr);
}

// Generate a random CRCFLAG
unsigned char getRandomCrcFlag() {
    return rand() % 256;
}

// Add an element to the array if it doesn't already exist and capacity is not exceeded
void addElement(struct array* arr, const NFAPI_CRUC_INDICATION_PDU_T& element) {
    pthread_mutex_lock(&arr->mutex);

    auto it = arr->hashTable.find(element.rnti);
    if (it == arr->hashTable.end() || arr->size < arr->capacity) {
        // Add the new element and update hash table entry
        arr->data[arr->size] = element;
        arr->hashTable[element.rnti] = arr->size;
        ++arr->size;
    }

    pthread_mutex_unlock(&arr->mutex);
}

// Remove an element by RNTI if it exists, log otherwise
void removeElement(struct array* arr, RNTI rnti) {
    auto it = arr->hashTable.find(rnti);
    if (it != arr->hashTable.end()) {
        pthread_mutex_lock(&arr->mutex);

        size_t index = it->second;
        memmove(&arr->data[index], &arr->data[index + 1], (arr->size - index - 1) * sizeof(NFAPI_CRUC_INDICATION_PDU_T));
        arr->hashTable.erase(rnti);
        --arr->size;

        pthread_mutex_unlock(&arr->mutex);
    } else {
        fprintf(stderr, "Error: RNTI not found\n");
    }
}

// Find an element by RNTI and return its index if found, otherwise return -1
size_t findElementByRnti(const struct array* arr, RNTI rnti) {
    auto it = arr->hashTable.find(rnti);
    return (it != arr->hashTable.end()) ? it->second : -1;
}

// Print all elements in the array sorted by RNTI
void displayElements(const struct array* arr) {
    pthread_mutex_lock(&arr->mutex);

    bool first = true;
    for (size_t i = 0; i < arr->size; ++i) {
        if (!first) printf(", ");
        else first = false;

        const NFAPI_CRUC_INDICATION_PDU_T& element = arr->data[arr->hashTable[i]];
        printf("{%d, %d, %d}", (int)element.tag, (int)element.rnti, (int)element.crcIndicationTag.crcFlag);
    }

    pthread_mutex_unlock(&arr->mutex);
}
