struct log_ctx {
    FILE *logfile;
    size_t buffer_size;
    char buffer[LOG_MAX_BUFFER];
};

void log_message(const char *message, struct log_ctx *ctx) {
    if (ctx->buffer_size + strlen(message) > ctx->buffer_size) {
        fwrite(ctx->buffer, ctx->buffer_size, 1, ctx->logfile);
        ctx->buffer_size -= ctx->buffer_size;
        memset(ctx->buffer, 0, LOG_MAX_BUFFER);
    }
    strcat(ctx->buffer, message);
}

void log_error(const char *message, struct log_ctx *ctx) {
    if (ctx->logfile != NULL) {
        fprintf(ctx->logfile, "[ERROR] %s\n", message);
    }
    syslog(LOG_ERR, "[%d] %s", getpid(), message);
}

int create_pdus(NFAPI_CRC_INDICATION_PDU_T **pdu_list, size_t count, const char *logfile, size_t buffer_size) {
