            free(pdu_list_ptr);
            fclose(log_ctx.logfile);
            return -1;
        }
    }

    for (i = 0; i < count; ++i) {
        log_message("Creating PDU #", &log_ctx);
        log_message(i, &log_ctx);
        log_message("\n");
    }

    *pdu_list = pdu_list_ptr;
    return 0;
}

