    for (i = 0; i < MAX_DATASETS && scanf("%d", &dataSets[i]->days[0]) == 1; ++i) {
        for (j = 1; j < 7; ++j) {
            if (scanf("%d", &(dataSets[i]->days[j])) != 1 || dataSets[i]->days[j] > TOTAL_LIMIT) {
                fprintf(stderr, "Invalid number of temperature readings for dataset %d\n", i + 1);
                break;
            }
        }

        if (j == 7) {
            for (int k = 0; k < 7; ++k) {
                if (!(dataSets[i]->days[k] >= TEMPERATURE_RANGE[0] && dataSets[i]->days[k] <= TEMPERATURE_RANGE[1])) {
                    fprintf(stderr, "Temperature out of range for dataset %d at day %d\n", i + 1, k + 1);
                }
            }

            (*numDataSets)++;
        } else {
            dataSets[i] = NULL;
        }
    }

    return dataSets;
}

int maxTemperature(DataSet* dataSet) {
    int maxTemp = dataSet->days[0];

    for (int i = 1; i < 7; ++i) {
        if (dataSet->days[i] > maxTemp) {
            maxTemp = dataSet->days[i];
        }
    }

    return maxTemp;
}

void printMaxTemperatures(DataSet** dataSets, int numDataSets) {
    for (int i = 0; i < numDataSets; ++i) {
        if (dataSets[i]) {
            printf("Location %d: Highest temperature is %d\n", dataSets[i]->location, maxTemperature(dataSets[i]));
        }
    }
}
