void init_memory_pool(struct memory_pool* pool, size_t max_size) {
    pool->data = calloc(max_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        syslog(LOG_ERR, "Failed to allocate memory for the memory pool.");
        return;
    }

