NFAPI_CRC_INDICATION_PDU_T* allocateArray(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (!array) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    switch (threadSafetyOption) {
        case 0:
            break; // No mutex
        case 1:
            pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_NORMAL);
            break; // Regular mutex
        case 2:
            pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_ERRORCHECK);
            break; // Error-checking mutex
        default:
            fprintf(stderr, "Error: Invalid thread safety option\n");
            free(array);
            return NULL;
    }
    pthread_mutex_init(&dataMutex, &attr);

    for (size_t i = 0; i < size; ++i) {
        array[i].ueTag.tagValue = YOUR_EXTERNAL_DATA_SOURCE_GET_UE_TAG();
        array[i].rnti = YOUR_EXTERNAL_DATA_SOURCE_GET_RNTI();
