} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

Node* head = NULL;
int num_elements = 0;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void log(const char *message) {
