}

int check_crc(const CRC_INDICATION_REL8_TAG crc) {
    // Implement your validation logic here, returning 1 for valid and 0 for invalid.
}

void allocate_and_add_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *new_node = NULL;
    int retries = MAX_RETRIES;

    while (retries > 0) {
        new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            --retries;
            continue;
        }

        pthread_mutex_init(&new_node->lock, NULL);
        new_node->data = *data;
        new_node->next = head;
        head = new_node;
        ++num_elements;
        break;
    }

    if (retries == 0) {
        free(new_node);
        log("Failed to allocate memory after maximum retries.");
    }
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list_lock);
    if (check_crc(data->crc_indication)) {
        allocate_and_add_node(data);
    } else {
        log("Invalid CRC_INDICATION_REL8_TAG detected.");
    }
    pthread_mutex_unlock(&list_lock);
}
