#define MAX_ELEMENTS 10000

struct ring_buffer {
    NFAPI_CRC_INDICATION_PDU_T elements[MAX_ELEMENTS];
    size_t head, tail, count;
    pthread_mutex_t mutex;
    sem_t not_full, not_empty;
};

void ring_buffer_init(struct ring_buffer *rb) {
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    pthread_mutex_init(&rb->mutex, NULL);
    sem_init(&rb->not_full, 0, MAX_ELEMENTS);
    sem_init(&rb->not_empty, 0, 0);
}

int ring_buffer_push(struct ring_buffer *rb, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == MAX_ELEMENTS) {
        sem_wait(&rb->not_full);
    }
    rb->elements[rb->head] = *data;
    rb->head = (rb->head + 1) % MAX_ELEMENTS;
    rb->count++;
    if (rb->count == 1) {
        sem_post(&rb->not_empty);
    }
    pthread_mutex_unlock(&rb->mutex);
    log_debug("Added element to ring buffer");
    return 0;
}

int ring_buffer_pop(struct ring_buffer *rb, NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&rb->mutex);
    while (rb->count == 0) {
        sem_wait(&rb->not_empty);
    }
    *data = rb->elements[rb->tail];
    rb->tail = (rb->tail + 1) % MAX_ELEMENTS;
    rb->count--;
    if (rb->count == MAX_ELEMENTS - 1) {
        sem_post(&rb->not_full);
    }
    pthread_mutex_unlock(&rb->mutex);
    log_debug("Removed element from ring buffer");
    return 0;
}

// Implement periodic log flushing mechanism and error handling as required
