#include <queue>
#include <mutex>
#include <condition_variable>
#include <atomic>

class CircularBuffer {
public:
    CircularBuffer(size_t capacity) : capacity_(capacity), head_(0), tail_(0), buffer_(capacity), mutex_(), notEmpty_(), notFull_() {}

    void push(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (isFull()) {
            notFull_.wait(lock);
        }
        buffer_[head_] = data;
        head_ = (head_ + 1) % capacity_;
        lock.unlock();
        notEmpty_.notify_one();
    }

    NFAPI_CRC_INDICATION_PDU_T pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (isEmpty()) {
            notEmpty_.wait(lock);
        }
        auto result = buffer_[tail_];
        tail_ = (tail_ + 1) % capacity_;
        lock.unlock();
        notFull_.notify_one();
        return result;
    }

private:
    size_t capacity_;
    size_t head_, tail_;
    std::queue<NFAPI_CRC_INDICATION_PDU_T> buffer_;
    std::mutex mutex_;
    std::condition_variable notEmpty_, notFull_;
    std::atomic_bool isFlushing_{false};
};
