int add_entry(const NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rnti) {
    if (size >= max_size) return -1; // List is full, cannot add more entries

    AVL_NODE *new_node = malloc(sizeof(AVL_NODE));
    new_node->entry.data = *pdu;
    new_node->entry.rnti = rnti;
    new_node->balance = 0;
    new_node->left = NULL;
    new_node->right = NULL;

    AVL_NODE **insert_point, *current = root;
    insert_point = &root;
    while (current != NULL) {
        if (rnti == current->entry.rnti) {
            free(new_node); // RNTI already exists, cannot add new entry
            return -2;
        }
        if (rnti < current->entry.rnti) {
            insert_point = &current->left;
        } else {
            insert_point = &current->right;
        }
        current = *insert_point;
    }

    *insert_point = new_node;

    // Perform balancing, rotations, etc. as necessary to keep the tree balanced

    size++;
    return 0;
}

void sort() {
    // Implement a recursive in-order traversal algorithm here to sort the AVL tree
}

void clean_up() {
    destroy(root);
    root = NULL;
    size = 0;
}
