class MemPool {
public:
    MemPool(size_t capacity) : buffer_(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)), pool_(buffer_.data(), buffer_.data() + capacity, allocator_) {}

    NFAPI_CRC_INDICATION_PDU_T* Alloc() {
        if (free_list_.empty()) {
            free_list_.resize(capacity);
            std::fill(free_list_.data(), free_list_.data() + capacity, nullptr);
            current_ = free_list_.data();
        }
        auto it = std::find(free_list_.begin(), free_list_.end(), nullptr);
        if (it != free_list_.end()) {
            *it = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(current_);
            current_++;
            return it;
        }
        return static_cast<NFAPI_CRC_INDICATION_PDU_T*>(std::realloc(current_, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    }

    void Free(NFAPI_CRC_INDICATION_PDU_T* obj) {
        if (obj) {
            new (obj) NFAPI_CRC_INDICATION_PDU_T(); // Zero the memory
            std::fill(reinterpret_cast<char*>(obj), reinterpret_cast<char*>(obj) + sizeof(NFAPI_CRC_INDICATION_PDU_T), 0);
            *static_cast<std::ptrdiff_t*>(obj) = -1; // Mark as free
            free_list_.push_back(obj);
        }
    }

private:
