void init_rx_frame_context(struct init_rx_frame_context *ctx, size_t num_frames, uint32_t memory_threshold_bytes, uint8_t* memory_buffer) {
    ctx->num_frames = num_frames;
    ctx->memory_threshold_bytes = memory_threshold_bytes;
    ctx->memory_buffer = memory_buffer;
    ctx->error = INIT_SUCCESS;
    pthread_mutex_init(&ctx->lock, NULL);
}

LTE_PHY_RX_FRAME_INFO_T* init_rx_frame(struct init_rx_frame_context *ctx) {
    if (pthread_mutex_lock(&ctx->lock)) {
        fprintf(stderr, "Error: Failed to lock mutex.\n");
        ctx->error = OTHER_ERROR;
        return NULL;
    }

    uint32_t bandwidth_mhz = NUM_SUBCarriers * SUBCarrierSpacing_Hz / 1e6;
    size_t frame_size = sizeof(LTE_PHY_RX_FRAME_INFO_T) + (bandwidth_mhz * SYMBOL_DURATION_US / 1e9); // Adjust for different symbol durations and bandwidths based on the standard used.

    size_t required_memory = frame_size * ctx->num_frames;

    if (required_memory > ctx->memory_threshold_bytes || !ctx->memory_buffer) {
        fprintf(stderr, "Error: Insufficient memory.\n");
        ctx->error = MEMORY_THRESHOLD_EXCEEDED;
        pthread_mutex_unlock(&ctx->lock);
        return NULL;
    }

    LTE_PHY_RX_FRAME_INFO_T* frames = ctx->memory_buffer;
    size_t index;

    // Populate the structures with simulated data.
    for (index = 0; index < ctx->num_frames; ++index) {
        // Compute symbol duration and frequency offset based on the frame's system bandwidth and subcarrier spacing.
        frames[index].symbol.start_time = index * SYMBOL_DURATION_US;
        frames[index].symbol.frequency_offset = (index % NUM_SUBCarriers) * SUBCarrierSpacing_Hz / 1e6;
        frames[index].antenna_port = index % 8; // Adjust for the actual number of antenna ports.
    }

    pthread_mutex_unlock(&ctx->lock);
    return frames;
}

void cleanup_rx_frame(struct init_rx_frame_context *ctx) {
    if (ctx->error == INIT_SUCCESS && ctx->memory_buffer) {
        free(ctx->memory_buffer);
        ctx->memory_buffer = NULL;
    }
