struct SignalMeasurement {
    std::time_t timestamp;
    double frequency, strength;
};

class SignalManager {
private:
    using TimePoint = std::chrono::system_clock::time_point;
    using CircularBuffer = boost::circular_buffer<SignalMeasurement>;
    constexpr static size_t bufferSize = 100000; // Adjust this value based on your requirements
    CircularBuffer measurements;
    std::shared_ptr<SignalMeasurement> signalData;
    mutable boost::mutex dataMutex;
public:
    SignalManager() : signalData(std::make_shared<SignalMeasurement>()) {}

    void addMeasurement(const TimePoint& timestamp, double frequency, double strength) {
        std::lock_guard<boost::mutex> lock(dataMutex);
        signalData->timestamp = timestamp.time_since_epoch().count();
        signalData->frequency = frequency;
        signalData->strength = strength;
        measurements.push_back(*signalData);
    }

    void getMeasurements(TimePoint start, TimePoint end, std::vector<SignalMeasurement>& results) const {
        std::lock_guard<boost::mutex> lock(dataMutex);
        size_t readIndex = measurements.get_read_index();
        for (auto it = measurements.crbegin(); it != measurements.crend() || readIndex != measurements.cbegin(); ) {
            if (it == measurements.crend()) it = measurements.cbegin();
            const auto& measurement = *it++;
            if (measurement.timestamp >= start.time_since_epoch().count() && measurement.timestamp <= end.time_since_epoch().count()) {
                results.push_back(measurement);
            }
        }
    }

    double calculateAverageSignalStrength(double startFrequency, double endFrequency) const {
        std::lock_guard<boost::mutex> lock(dataMutex);
        size_t readIndex = measurements.get_read_index();
        int activeDevices = 0;
        double sumStrength = 0.0;
        for (auto it = measurements.crbegin(); it != measurements.crend() || readIndex != measurements.cbegin(); ) {
            if (it == measurements.crend()) it = measurements.cbegin();
            const auto& measurement = *it++;
            if (measurement.frequency >= startFrequency && measurement.frequency <= endFrequency) {
                sumStrength += measurement.strength;
                activeDevices++;
            }
        }
        return activeDevices > 0 ? sumStrength / activeDevices : 0.0;
    }

    void integrateExternalDataLoggingService(std::function<void(const SignalMeasurement&)> callback) {
        // Implement this function to handle integration with the external data logging service,
        // calling the provided callback function whenever new measurements are available
    }
};
