#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct PacketHeader {
    char DestinationAddress[32];
    char SourceAddress[32];
    char ProtocolType[8];
    uint64_t SequenceNumber;
    time_t InsertionTime;
} PacketHeader;

#define THRESHOLD_PERCENTAGE 75.0 // Adjust as needed

typedef struct {
    size_t capacity;
    size_t size;
    PacketHeader* data;
} PacketsArray;

void packets_array_init(PacketsArray* packets) {
    packets->capacity = 16;
    packets->size = 0;
    packets->data = malloc(sizeof(PacketHeader) * packets->capacity);
}

bool packets_array_full(const PacketsArray* packets) {
    return packets->size >= packets->capacity;
}

void packets_array_push(PacketsArray* packets, const PacketHeader* header) {
    if (packets_array_full(packets)) {
        if ((double)packets->size / packets->capacity > THRESHOLD_PERCENTAGE) {
            // Graceful degradation: prioritize newer packets over older ones by keeping a fixed number of oldest packets and removing others
            size_t min_size = packets->capacity * (1 - THRESHOLD_PERCENTAGE / 2);
            if (packets->size > min_size) {
                free(packets->data + min_size);
                packets->capacity -= min_size;
                packets->size -= min_size;
            }
        } else {
            // Resize array to double its capacity when needed
            size_t new_capacity = packets->capacity * 2;
            packets->data = realloc(packets->data, sizeof(PacketHeader) * new_capacity);
            packets->capacity = new_capacity;
        }
    }

    memcpy(&(packets->data[packets->size]), header, sizeof(PacketHeader));
    packets->size++;
    header->SequenceNumber = packets->size - 1; // Assign unique sequence number during insertion
}

void packets_array_free(PacketsArray* packets) {
    free(packets->data);
    packets->capacity = 0;
    packets->size = 0;
}
```

