class SandeshClient {
private:
    tcp::socket socket_;
    InterfaceTable* interfaceTable_;
    std::atomic<bool> running_{true};
    std::mutex queueMutex;
    std::queue<NFAPI_CRC_INDICATION_PDU_T> requestQueue;
    std::vector<std::thread> workerThreads;
    int maxConcurrency;
    int numRequests;
    int timeoutMs;
    std::chrono::system_clock::time_point lastRequestTime;

public:
    SandeshClient(tcp::endpoint endpoint, InterfaceTable* interfaceTable, int maxConcurrency, int numRequests, int timeoutMs)
        : socket_(endpoint), interfaceTable_(interfaceTable), maxConcurrency(maxConcurrency), numRequests(numRequests), timeoutMs(timeoutMs) {
    }

    void Start() {
        for (int i = 0; i < maxConcurrency && !running_.load(); ++i) {
            workerThreads.emplace_back([this]() { WorkerLoop(); });
        }
    }

    void Stop() {
        running_.store(false);
        for (auto& thread : workerThreads) {
            thread.join();
        }
    }

