    sem_t memory_sem;
    size_t capacity;
    size_t count;
    void* session_contexts;
    char allowed_ips[NUM_ALLOWED_IPS][INET_ADDRSTRLEN];
};

InterfaceContext* create_interface_context(size_t capacity) {
    InterfaceContext* context = malloc(sizeof(InterfaceContext));
    context->capacity = capacity;
    context->count = 0;
    pthread_mutex_init(&context->lock, NULL);
    sem_init(&context->memory_sem, 0, capacity);
    void* shm = shm_open("/network_interface_data", O_CREAT | O_RDWR, S_IRUSR | S_IWUSR);
    ftruncate(shm, capacity * sizeof(SessionContext));
    context->session_contexts = mmap(NULL, capacity * sizeof(SessionContext), PROT_READ | PROT_WRITE, MAP_SHARED, shm, 0);
    close(shm);
    return context;
}

bool is_allowed_ip(const char* ip) {
    for (size_t i = 0; i < NUM_ALLOWED_IPS; ++i) {
        if (!strcmp(ip, allowed_ips[i])) {
            return true;
        }
    }
    return false;
}

SessionContext* allocate_session_context(InterfaceContext* context) {
    sem_wait(&context->memory_sem);
    size_t index = context->count++;
    SessionContext* context = context->session_contexts + index;
    return context;
}

void deallocate_session_context(SessionContext* context, InterfaceContext* context) {
    sem_post(&context->memory_sem);
}

bool validate_ip(const char* ip) {
    // Validate IP address according to your requirements
}

InterfaceContext* get_interface_context() {
    static InterfaceContext* interfaces[NUM_INTERFACES];
    return interfaces[thread_id - 1];
}
```

This code provides a basic structure for managing session contexts for network interfaces. The `create_interface_context` function initializes an interface context, which includes a mutex lock for thread safety and a shared memory segment for efficient memory usage. The `allocate_session_context` and `deallocate_session_context` functions handle dynamic allocation and deallocation of session contexts, using a semaphore to prevent race conditions.

The code also includes a function to validate IP configurations against a predefined list of allowed IP ranges (`is_allowed_ip`), but you should implement the actual validation logic according to your requirements. The `validate_ip` function is left empty as an example for you to fill in.

