int create_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t min, size_t max) {
    NFAPI_CRC_INDICATION_PDU_T* temp_list = NULL;
    size_t list_size = (max - min > 0) ? min + rand() % (max - min + 1) : max;

    // Allocate memory for temporary list and structures
    if (!(temp_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size))) {
        perror("Memory allocation failure");
        return -1;
    }
    allocations++;

    // Populate the temporary list with valid structures
    for (size_t i = 0; i < list_size; ++i) {
        temp_list[i].RX_UE_INFORMATION_TAG = i;
        temp_list[i].RNTI = (i + rand() % list_size) + 1; // Ensure no two consecutive structures have the same RNTI
        temp_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        temp_list[i].CRCFLAG = (rand() % 2) == 0;
    }

    // Sort the temporary list to ensure no two consecutive structures have the same RNTI value
    qsort(temp_list, list_size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rniti);

    // Allocate memory for the final list and copy the populated structures from the temporary list
    if (!(*list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size))) {
        perror("Memory allocation failure");
        free(temp_list); // Free temporary memory in case of error
        deallocations++;
        return -1;
    }
    allocations++;

    memcpy(*list, temp_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_size);

    free(temp_list); // Free temporary memory
    deallocations++;

    return 0;
}

