LTE_PDCP_SRB_T* init_and_populate_pdcp_srb_list(uint8_t num_srb, bool enable_checksum, checksum_fn_t cs_func) {
    LTE_PDCP_SRB_T *head = NULL, *tail = NULL, *node;
    for (size_t i = 0; i < num_srb; ++i) {
        node = malloc(sizeof(LTE_PDCP_SRB_T));
        if (!node) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        node->SRB_ID = i + 1;
        node->SRB_TYPE = (i % 2 == 0) ? SRB_TYPE_FACH : SRB_TYPE_DSCH;
        node->SRB_STATUS = SRB_STATUS_IDLE;
        node->pdu_data = malloc(PDU_DATA_SIZE); // Adjust PDU_DATA_SIZE as needed
        if (!node->pdu_data) {
            free(node);
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        if (enable_checksum) {
            cs_func(node->pdu_data, PDU_DATA_SIZE);
        }
        if (!head) {
            head = node;
            tail = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }
    // Optimized in-place reversal using doubling and halving technique
    if (num_srb > 1) {
        LTE_PDCP_SRB_T *p1 = head, *p2 = tail, *tmp;
        for (size_t i = 0; (1 << i) < num_srb; ++i) {
            for (size_t j = 0; j < (1 << i); ++j, p1 = p1->next) {
                tmp = p1->prev;
                p1->prev = p2;
                p2->next = p1;
                if (p1 == tail) {
                    p2 = p1;
                } else {
                    p2 = tmp;
                }
            }
        }
    }
    return head;
}
