NODE* head = NULL;

void addMessage(uint32_t id, NFAPI_RRC_CU_MSG_TYPE type, void* payload) {
    NODE* newNode = malloc(sizeof(NODE));
    if (!newNode) return;

    newNode->msg.id = id;
    newNode->msg.type = type;
    newNode->msg.payload = payload;
    newNode->next = head;
    head = newNode;
}

NFAPI_RRC_CU_MSG* getMessage(uint32_t id) {
    NODE* current = head;
    while (current != NULL) {
        if (current->msg.id == id) return &current->msg;
        current = current->next;
    }
    return NULL;
}

void updatePayload(uint32_t id, void* newPayload) {
    NFAPI_RRC_CU_MSG* msg = getMessage(id);
    if (msg != NULL) {
        free(msg->payload);
        msg->payload = newPayload;
    }
}

void manageMemory() {
    NODE* current = head;
    while (current != NULL) {
        NODE* temp = current;
        current = current->next;
        free(temp->msg.payload);
        free(temp);
    }
    head = NULL;
}
