function getElementList(root, selector) {
    let elements = [];

    function traverseDOM(node) {
        if (node.matches && node.matchesSelector(selector)) {
            elements.push(node);
        }

        if (node.children) {
            for (let i = 0; i < node.children.length; ++i) {
                traverseDOM(node.children[i]);
            }
        }
    }

    traverseDOM(root);
    return elements;
}
