```javascript
function getElementList(root, selector) {
    let elements = [];

    function traverseDOM(node) {
        if (node instanceof HTMLElement && node.matchesSelector || node.matches) {
            if (node.matches && node.matchesSelector(selector)) {
                elements.push(node);
            }

            if (node.children) {
                for (let i = 0; i < node.children.length; ++i) {
                    traverseDOM(node.children[i]);
                }
            }
        } else if (node && node.nodeType === Node.ELEMENT_NODE) {
            // Fallback implementation for older browsers or partially loaded pages
            if (node.nodeName.toLowerCase() === selector) {
                elements.push(node);
            }

            if (node.childNodes) {
                for (let i = 0; i < node.childNodes.length; ++i) {
                    traverseDOM(node.childNodes[i]);
                }
            }
        }
    }

    traverseDOM(root);
    return elements;
}
