<?php

class UserManager {
    private $apiKey;
    private $cache;
    private $cacheExpirationTime = 600; // 10 minutes

    public function __construct($apiKey) {
        $this->apiKey = $apiKey;
        $this->cache = new \SplObjectStorage();
    }

    public function processRequest() {
        $userData = $_REQUEST;
        if (!array_key_exists('name', $userData) || !array_key_exists('email', $userData) || !array_key_exists('password', $userData)) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        $validPassword = $this->validatePassword($userData['password']);
        if (!$validPassword) {
            return json_encodde(['message' => 'error', 'data' => []]);
        }

        if (array_key_exists('id', $userData)) {
            $subAction = $userData['sub_action'];
            switch ($subAction) {
                case 'create':
                    return $this->createUser($userData);
                case 'update':
                    return $this->updateUser($userData);
                case 'delete':
                    return $this->deleteUser($userData);
                default:
                    return json_encode(['message' => 'error', 'data' => []]);
            }
        } else {
            return json_encode(['message' => 'error', 'data' => []]);
        }
    }

    private function createUser($userData) {
        if ($this->checkEmailExists($userData['email'])) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        $user = $this->externalApiCallForAuthentication($userData);
        if (!$user) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        // Store user data and cache for efficient access later
        $this->cache[$user['id']] = $user;

        return json_encode(['message' => 'success', 'data' => $user]);
    }

    private function updateUser($userData) {
        if (!$this->cacheHasKey($userData['id'])) {
            return json_encode(['message' => 'error', 'data' => []]);
        }

        // Validate and sanitize the updated data
