    // Use a pre-allocated array when n is small enough to fit in the stack.
    if (n <= sizeof(NFAPI_CRC_INDICATION_PDU_T) * 32) {
        NFAPI_CRC_INDICATION_PDU_T data[n];
        for (unsigned int i = 0; i < n; ++i) {
