                ++data[i].rnti;
            }
            data[i].crc_indication_rel8_tag.crcflag = 1; // Set CRC flag to active.
        }
        return data;
    }

    // Otherwise, use a linked list or ring buffer for better scalability and memory management.
    NFAPI_CRC_INDICATION_PDU_T* head = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!head) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* current = head;
    for (unsigned int i = 0; i < n - 1; ++i) {
        current->next = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!current->next) {
            fprintf(stderr, "Memory allocation failed.\n");
            // Free previously allocated memory and return NULL.
            while (head != NULL) {
