                    head = head->next;
                    free(temp);
                }
                return NULL;
            }
        }
        current->crc_indication_rel8_tag.crcflag = 1; // Set CRC flag to active.
    }
    // The last element does not require a next pointer and should have rnti equal to n.
    head->next = NULL;
    (current - 1)->rnti = n;
    current->crc_indication_rel8_tag.crcflag = 1;

    return head;
}

void free_dynamic_list(NFAPI_CRC_INDICATION_PDU_T* list) {
