typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node* next;
} node_t;

static node_t* head = NULL;
static size_t capacity = 0;
static size_t count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void ensureCapacity(size_t minCapacity) {
    if (minCapacity > capacity) {
        node_t** current = &head;
        size_t newCapacity = min(minCapacity * 2, CAPACITY);
        node_t* newNodes = malloc(newCapacity * sizeof(node_t));
        if (!newNodes) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }

        for (size_t i = count; i < newCapacity; ++i) {
            newNodes[i].next = current && *current ? &newNodes[i + 1] : NULL;
            *current = &newNodes[i];
        }
        capacity = newCapacity;
    }
}

void append(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rnti) {
    pthread_mutex_lock(&mutex);
    ensureCapacity(count + 1);
    node_t* current = head;
    for (size_t i = 0; i < count; ++i, current = current->next) {}

    current->data = *pdu;
    current->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    current->data.RNTI = rnti;
    current->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % MAX_CRCFLAG + 1;
    current->next = malloc(sizeof(node_t));
    if (!current->next) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    count++;
    pthread_mutex_unlock(&mutex);
}

void reset() {
    pthread_mutex_lock(&mutex);
    node_t* current = head;
    while (head) {
        node_t* next = head->next;
        free(current);
        current = next;
    }
    count = 0;
    pthread_mutex_unlock(&mutex);
}
```
