['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct {
    uint32_t id;
    NFAPI_RRC_CU_MSG_TYPE type;
    size_t payload_size;
    char *payload;
} NFAPI_RRC_CU_MSG;

typedef struct node {
    NFAPI_RRC_CU_MSG msg;
    struct node *next;
} Node;

#define MAX_NODES 10000
Node nodes[MAX_NODES];
sem_t lock;

// Function to initialize the data structure and semaphore
void init() {
    for (int i = 0; i < MAX_NODES; i++) {
        nodes[i].next = NULL;
    }
    sem_init(&lock, 0, 1);
}

// Function to add a new message
void add_message(NFAPI_RRC_CU_MSG msg) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return;
    }
    new_node->msg = msg;
    new_node->next = NULL;

    sem_wait(&lock);
    Node *head = nodes;
    for (int i = 0; i < MAX_NODES - 1 && head[i].next != NULL; i++) {
        head = &head[i + 1];
    }
    new_node->next = head[MAX_NODES - 1].next;
    head[MAX_NODES - 1].next = new_node;
    sem_post(&lock);
}

// Function to retrieve a message by its unique identifier (ID)
NFAPI_RRC_CU_MSG get_message(uint32_t id) {
    Node *current = nodes;
    for (int i = 0; i < MAX_NODES && current[i].msg.id != id; i++) {
        current = &current[i + 1];
    }
    if (i == MAX_NODES) {
        return (NFAPI_RRC_CU_MSG){0};
    }
    return current[i].msg;
}

// Function to update the payload of an existing message
void update_message(uint32_t id, size_t new_payload_size, char *new_payload) {
    NFAPI_RRC_CU_MSG msg = get_message(id);
    if (msg.payload != NULL) {
        free(msg.payload);
    }
    msg.payload_size = new_payload_size;
    msg.payload = mmap(NULL, new_payload_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (msg.payload == MAP_FAILED) {
        printf("Memory mapping failed\n");
        msg.payload = NULL;
    } else {
        memcpy(msg.payload, new_payload, new_payload_size);
    }
}

// Function to merge multiple messages into a single consolidated message
void merge_messages(uint32_t dest_id, uint32_t src_ids[], size_t num_srcs) {
    NFAPI_RRC_CU_MSG *dest = &nodes[dest_id].msg;
    for (int i = 0; i < num_srcs; i++) {
        NFAPI_RRC_CU_MSG src = get_message(src_ids[i]);
        if (src.payload != NULL) {
            size_t new_size = dest->payload_size + src.payload_size;
            char *new_payload = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            if (new_payload == MAP_FAILED) {
                printf("Memory mapping failed\n");
                return;
            }
            memcpy(new_payload, dest->payload, dest->payload_size);
            memcpy(new_payload + dest->payload_size, src.payload, src.payload_size);
            free(dest->payload);
            dest->payload = new_payload;
            dest->payload_size = new_size;
        }
    }
}
```
