// Function to dynamically allocate memory for an array of PHY_STATISTICS_PDU_T structures
PHY_STATISTICS_PDU_T* create_phy_stats_array(int N) {
    PHY_STATISTICS_PDU_T* phy_stats = (PHY_STATISTICS_PDU_T*)malloc(N * sizeof(PHY_STATISTICS_PDU_T));
    if (!phy_stats) {
        fprintf(stderr, "Memory allocation failure.\n");
        return NULL;
    }
    return phy_stats;
}

// Function to populate the PHY_STATISTICS_PDU_T structures with randomly generated values
void fill_phy_stats_array(PHY_STATISTICS_PDU_T* phy_stats, int N) {
    srand(time(NULL));

    for (int i = 0; i < N; ++i) {
        PHY_STATISTICS_PDU_T* curr = &phy_stats[i];
        parse_phy_statistics(/* some data source */, curr);

        // Handle missing RX_QUALITY_INFO values gracefully
        if (!curr->rx_quality.signal_strength)
            init_rx_quality(&curr->rx_quality);

        // Validate SINR value and adjust it if necessary
        if (!is_valid_sinr(curr->phy_channel_status.channel_type, curr->phy_channel_status.sinr)) {
            printf("Warning: Out-of-bound SINR value %f for channel type %d. Adjusting to nearest valid bound.\n", curr->phy_channel_status.sinr, curr->phy_channel_status.channel_type);
            curr->phy_channel_status.sinr = (is_valid_sinr(curr->phy_channel_status.channel_type, curr->phy_channel_status.sinr + 1.0f) ? curr->phy_channel_status.sinr + 1.0f : curr->phy_channel_status.sinr - 1.0f);
        }
    }
}

// Function to free the allocated memory for an array of PHY_STATISTICS_PDU_T structures
