typedef struct MAC_HEADER {
    unsigned short frame_control;
    unsigned short duration;
    struct sockaddr_ll address;
    unsigned short payload_length;
} MAC_HEADER;

typedef struct CONN_POOL {
    pthread_mutex_t lock;
    int max_connections;
    int num_connections;
    int *connections;
} CONN_POOL;

CONN_POOL* conn_pool_init(int max_connections) {
    CONN_POOL* pool = malloc(sizeof(CONN_POOL));
    if (!pool) return NULL;
    pthread_mutex_init(&pool->lock, NULL);
    pool->max_connections = max_connections;
    pool->num_connections = 0;
    pool->connections = malloc(max_connections * sizeof(int));
    return pool;
}

int conn_pool_acquire(CONN_POOL* pool) {
    int ret;
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->max_connections; ++i) {
        if (!pool->connections[i]) {
            pool->connections[i] = 1;
            pool->num_connections++;
            ret = i;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return ret;
}

void conn_pool_release(CONN_POOL* pool, int connection) {
    if (connection < 0 || connection >= pool->max_connections) return;
    pthread_mutex_lock(&pool->lock);
    if (pool->connections[connection]) {
        pool->connections[connection] = 0;
        pool->num_connections--;
    }
    pthread_mutex_unlock(&pool->lock);
}

void manage_data_frames(MAC_HEADER* data_frame) {
