    boost::asio::io_service ioService_;

public:
    NetworkInterface(unsigned int maxStreams, double lossRate) : maxStreams_(maxStreams), lossRate_(lossRate) {}

    void initialize() {
        for (unsigned int i = 0; i < maxStreams_; ++i) {
            streams_.emplace_back(std::make_unique<NFAPI_CRC_INDICATION_PDU_T>());
        }
    }

    void configure(const std::string& externalSource) {
        // Integrate with the specified external data source
