        if (streams_.size() >= maxStreams_) {
            return nullptr; // No more streams can be added
        }
        NFAPI_CRC_INDICATION_PDU_T* stream = streams_[streams_.size()] .get();
        // Configure the new stream with default values
        return stream;
    }

    void removeStream(NFAPI_CRC_INDICATION_PDU_T* stream) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        auto it = std::find(streams_.begin(), streams_.end(), stream);
