void create_structures(size_t n) {
    fetch_params();
    size_t thread_count = 1 + (n - 1) / CPU_COUNT; // Use #CPUs as the default number of threads.

    pthread_t* threads = malloc(thread_count * sizeof(pthread_t));

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_create(&threads[i], NULL, create_structure, (void*) i);
    }

    for (size_t i = 0; i < thread_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
