            // Handle exceptions and log errors
        }
        return hashes;
    }

    private class ConfigurationFileVisitor extends FileVisitor<Path> {
        private List<String> hashes;
        private PKCS5S2ParametersGenerator generator;

        public ConfigurationFileVisitor(List<String> hashes) {
            this.hashes = hashes;
            try {
                generator = new PKCS5S2ParametersGenerator();
                generator.init(new KeyParameter(new byte[SALT_LENGTH])); // Use a predefined salt or read from configuration
            } catch (Exception e) {
