            try (InputStream is = Files.newInputStream(file);
                 MessageDigest md = MessageDigest.getInstance("MD5")) {
                byte[] fileData = new byte[1024];
                int bytesRead;

                while ((bytesRead = is.read(fileData)) != -1) {
                    md.update(fileData, 0, bytesRead);
                }

                String hash = bytesToHex(md.digest());
                hashes.add(hash);
            } catch (Exception e) {
                // Handle exceptions and log errors
            }

            replacePlaceholders(file);
            generatePasswordAndAppend(file);

            return FileVisitResult.CONTINUE;
        }

        private void replacePlaceholders(Path file) throws IOException {
            Map<String, String> placeholders = configMgr.getPlaceholders();
            try (BufferedReader reader = new BufferedReader(new FileReader(file.toFile()));
                 BufferedWriter writer = new BufferedWriter(new FileWriter(file.toFile()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    for (Map.Entry<String, String> entry : placeholders.entrySet()) {
                        line = line.replace("{" + entry.getKey() + "}", entry.getValue());
                    }
                    writer.write(line);
                    writer.newLine();
                }
            } catch (Exception e) {
                // Handle exceptions and log warnings for missing placeholders
            }
        }

        private void generatePasswordAndAppend(Path file) throws Exception {
            byte[] password = generator.generateDerivedParameters(configMgr.getPassword().toCharArray(), null, 1000);
            try (FileWriter writer = new FileWriter(file.toFile(), true)) {
                // Append the encrypted password to the file, ensuring backward compatibility
            } catch (Exception e) {
                // Handle exceptions and log errors
            }
        }

        private boolean isConfigFile(Path file) {
            String fileName = file.getFileName().toString();
            for (String env : ENVIRONMENTS) {
                if (fileName.endsWith("_" + env + ".conf")) return true;
            }
            // Implement a strategy for fallbacks or manual updates if the configuration files are not found
            return false;
        }

        private String bytesToHex(byte[] bytes) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < bytes.length; i++) {
                sb.append(String.format("%02x", bytes[i]));
            }
            return sb.toString();
