int load_bundle(const char *path, struct bundle **bundle) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }

    struct stat file_stat;
    fstat(fd, &file_stat);
    close(fd);

    size_t file_size = file_stat.st_size;
    *bundle = malloc(sizeof(struct bundle));
    if (!*bundle) {
        perror("malloc");
        return 1;
    }

    (*bundle)->items = calloc(1, sizeof((**bundle).items[0]));
    if (!(*bundle)->items) {
        free(*bundle);
        perror("calloc");
        return 1;
    }

    fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("reopen");
        return 1;
    }

    ssize_t read_count;
    while ((read_count = read(fd, (*bundle)->items, sizeof((**bundle).items[0])) > 0)) {
        if (feof(fd)) break;
        if (ferror(fd)) {
            perror("read");
            close(fd);
            return 1;
        }

        (*bundle)->count++;
        (*bundle)->items = realloc((*bundle)->items, ((*bundle)->count + 1) * sizeof((**bundle).items[0]));
        if (!(*bundle)->items) {
            free(*bundle);
            perror("realloc");
            close(fd);
