['Here's a simple implementation of the task using `async/await` and `Map` for caching:

```javascript
const MAX_CONCURRENT_REQUESTS = 5;
let cache = new Map();
const TTL_MS = 60 * 1000; // Default TTL: 1 minute

function loadScript(url, onLoad) {
  if (cache.has(url)) {
    onLoad(cache.get(url));
    return;
  }

  const promise = fetch(url).then(response => {
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    return response.text();
  }).catch(error => {
    console.error(`Error loading script from ${url}:`, error);
  });

  promise.then(scriptText => {
    cache.set(url, scriptText);
    onLoad(scriptText);
  });

  if (cache.size >= MAX_CONCURRENT_REQUESTS) {
    promise.then(() => URL.revokeObjectURL(promise._uploadBlob));
  } else {
    const script = document.createElement("script");
    script.src = url;
    script.onload = () => {
      onLoad(cache.get(url));
      cache.delete(url);
    };
    document.head.appendChild(script);
  }
}

function loadScripts(urls, onAllLoaded) {
  const promises = urls.map((url, i) => new Promise((resolve) => {
    let loaded = false;

    function onLoad(scriptText) {
      if (!loaded) {
        loaded = true;
        resolve([i, scriptText]);
      }
    }

    loadScript(url, onLoad);
  }));

  Promise.all(promises).then((results) => {
    const sortedResults = results.sort((a, b) => a[0] - b[0]);
    onAllLoaded(sortedResults.map(([i, scriptText]) => scriptText));
  });
}

function resetCache() {
  cache.clear();
}
```

You can use the `loadScripts` function to load multiple scripts in a specific order. The number of concurrent requests is limited by the `MAX_CONCURRENT_REQUESTS` constant, and you can control the TTL using the `TTL_MS` constant. Use the `resetCache()` function to manually invalidate the cache for testing or debugging purposes.

For optimal resource usage, consider user interaction patterns (e.g., loading scripts on demand when a certain action is triggered) and adjusting the `MAX_CONCURRENT_REQUESTS` value accordingly. Monitor your application's performance and stability with varying TTL settings to evaluate trade-offs between responsiveness and resource consumption.']

