import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import java.util.concurrent.TimeUnit;

public class PageContentManager {
    private UnionFind uf;
    private long totalPairCheckTime = 0;

    public PageContentManager(int[] array) {
        uf = new UnionFind(array.length);
        for (int i = 0; i < array.length; ++i) {
            uf.unionElements(array[i], array[i] + 1);
        }
    }

    public void processDisjointPairs() {
        long startTime = System.nanoTime();
        for (int i = 0; i < uf.getSetSize(); ++i) {
            int root = uf.find(i);
            for (int j = i + 1; j < uf.getSetSize(); ++j) {
                if (uf.connected(root, uf.find(j))) continue;
                totalPairCheckTime += TimeUnit.NANOSECONDS.toMillis((System.nanoTime() - startTime));
            }
        }
    }

    public class UnionFind {
        private int[] parent;
        private long[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new long[size];
            for (int i = 0; i < size; ++i) {
                parent[i] = i;
                rank[i] = 1;
            }
        }

        public void unionElements(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP == rootQ) return;
            if (rank[rootP] < rank[rootQ]) parent[rootP] = rootQ;
            else if (rank[rootQ] < rank[rootP]) parent[rootQ] = rootP;
            else {
                parent[rootP] = rootQ;
                rank[rootQ]++;
            }
        }

        public boolean connected(int p, int q) {
            return find(p) == find(q);
        }

        public int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }

        public int getSetSize() {
            return Arrays.stream(parent).filter(i -> i == i).count();
        }
    }

    public void handleHTTPPostRequest(String pageSectionId, String elementId, String htmlContent) throws IOException {
        ContentUpdater updater = new ContentUpdater();
        if (updater.isValidDataFormat(htmlContent)) {
            updater.updateElement(pageSectionId, elementId, htmlContent);
            sendResponseToRefreshPage();
        } else {
            sendErrorResponse("Invalid data format");
        }
    }

    private void sendResponseToRefreshPage() throws IOException {
        HttpURLConnection connection = (HttpURLConnection) new URL("http://localhost:8080/refresh").openConnection();
        connection.setRequestMethod("POST");
        connection.getOutputStream().close();
        connection.disconnect();
    }

    private void sendErrorResponse(String message) throws IOException {
        HttpURLConnection connection = (HttpURLConnection) new URL("http://localhost:8080/error").openConnection();
        connection.setRequestMethod("POST");
        connection.setDoOutput(true);
        OutputStream os = connection.getOutputStream();
        os.write((message + '\n').getBytes());
        os.flush();
        os.close();
        connection.disconnect();
    }

    private class ContentUpdater {
        public boolean isValidDataFormat(String htmlContent) {
            // Implement your validation logic here
            return true;
        }

        public void updateElement(String pageSectionId, String elementId, String htmlContent) {
            // Implement your updating logic here
        }
    }
}
