        NFAPI_CRC_INDICATION_PDU_T *pdu = (*list)[i];
        pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG_INITIALIZER;
        pdu->rnti = rand() % 0xffff;
        pdu->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0;

        if (!head) {
            head = current = malloc(sizeof(struct node));
            if (!head) {
                perror("Memory allocation failed.");
                // Free previously allocated memory and return an error.
                for (unsigned int j = 0; j < i; ++j) {
                    free((*list)[j]);
                }
                free(*list);
                free(current);
                return -1;
            }
            head->data = pdu;
            head->next = NULL;
        } else {
            current->next = malloc(sizeof(struct node));
            if (!current->next) {
                perror("Memory allocation failed.");
                // Free previously allocated memory and return an error.
                for (unsigned int j = 0; j <= i; ++j) {
                    free((*list)[j]);
                }
                free(*list);
                free(head);
                return -1;
            }
            current = current->next;
            current->data = pdu;
            current->next = NULL;
        }
        allocated++;
    }

    if (allocated % 50 == 0) { // Reset CRCFLAG every 50 allocations for RNTIs.
        for (unsigned int i = 0; i < N; ++i) {
            (*list)[i]->crc_indication_rel8_tag.crcflag = (rand() % 2) ? 1 : 0;
        }
