    // Implement logging logic according to your application's requirements.

    return 0;
}

void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T** list, unsigned int N) {
    for (unsigned int i = 0; i < N; ++i) {
        free((*list)[i]);
    }
    free(*list);
}
