[" Here's a modular JavaScript function named `readAndProcessFiles` that uses Node.js's built-in `fs` (File System) module for efficient file handling:

```javascript
const fs = require('fs');
const path = require('path');

async function readAndProcessFiles(directory, extension, processFileFunction) {
    const files = await new Promise((resolve) => {
        let results = [];
        fs.readdir(directory, (err, files) => {
            if (err) return resolve([]);

            files.forEach((file) => {
                const fullPath = path.join(directory, file);
                fs.stat(fullPath, (err, stat) => {
                    if (stat && stat.isFile()) {
                        const extname = path.extname(fullPath).toLowerCase();
                        if (extname === `.${extension}`) {
                            results.push(fullPath);
                        }
                    }
                });
            });
            resolve(results);
        });
    });

    const promises = files.map((file) =>
        new Promise((resolve, reject) => {
            let chunks = [];
            const readStream = fs.createReadStream(file, { encoding: 'utf8', highWaterMark: 1024 * 16 }); // Adjust highWaterMark based on your needs and memory constraints

            readStream.on('data', (chunk) => chunks.push(chunk));
            readStream.on('error', reject);
            readStream.on('end', () => {
                try {
                    const content = Buffer.concat(chunks).toString();
                    processFileFunction(file, content);
                    resolve();
                } catch (err) {
                    reject(err);
                }
            });
        })
    );

    await Promise.all(promises);
}
```

Usage example:

```javascript
readAndProcessFiles('./my_directory', 'txt', (file, content) => {
    // Process the file here, e.g., perform some analysis or transformation
});
```"]

