#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>
#define MAX_STRUCTURES 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    FILE *file;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *data;
} RESOURCE_BUNDLE;

int load_and_process(const char *filename, size_t *num_structures) {
    RESOURCE_BUNDLE rb = {0};
    rb.file = fopen(filename, "r");
    if (!rb.file) {
        perror("Error opening file");
        return 0;
    }

    fseek(rb.file, 0, SEEK_END);
    rb.size = ftell(rb.file);
    rewind(rb.file);

    if (rb.size > RSIZE_MAX) {
        fprintf(stderr, "File size exceeds memory constraints\n");
        goto cleanup;
    }

    rb.data = malloc(rb.size);
    if (!rb.data) {
        perror("Error allocating memory for data");
        goto cleanup;
    }

    size_t read = fread(rb.data, sizeof(NFAPI_CRC_INDICATION_PDU_T), rb.size / sizeof(NFAPI_CRC_INDICATION_PDU_T), rb.file);
    if (read != rb.size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        perror("Error reading file");
        goto cleanup;
    }

    *num_structures = read;

cleanup:
    fclose(rb.file);
    free(rb.data);
    return *num_structures;
}

size_t manage_list(const char *filename, size_t *num_structures) {
    *num_structures = load_and_process(filename, num_structures);

    size_t i, success_count = 0;
    NFAPI_CRC_INDICATION_PDU_T *list = calloc(*num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Error allocating memory for list");
        return 0;
    }

    for (i = 0; i < *num_structures; ++i) {
        if ((list + i)->CRC_INDICATION_REL8_TAG != 1) {
            success_count++;
            memcpy((list + success_count - 1), (list + i), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    free(list);
    return success_count;
}
