import com.opencsv.CSVReader;
import com.google.common.cache.*;
import akka.actor.ActorSystem;
import akka.actor.Props;
import akka.stream.Materializer;

import java.io.FileReader;
import java.nio.charset.StandardCharsets;
import java.time.Duration;

public class UserRecordProcessor {
    private LoadingCache<String, User> userCache = CacheBuilder.newBuilder()
            .expireAfterAccess(Duration.HOURS)
            .maximumSize(10_000)
            .build(new CacheLoader<String, User>() {
                @Override
                public User load(String key) throws Exception {
                    return new User(key); // Instantiate User class with email, firstName, and lastName
                }
            });

    public static void main(String[] args) {
        ActorSystem system = ActorSystem.create("UserRecordProcessor");
        Materializer materializer = system.materializer();

        system.actorOf(Props.create(UserRecordActor.class), "userRecordActor"),
            IterateeSink.source(Source.fromIterator(() -> new CSVReader(new FileReader("large_file.csv", StandardCharsets.UTF_8)))
                    .flatMap(record -> Observable.fromIterable(Arrays.asList(record))
                        .map(cell -> cell.replaceAll("\\s+", ""))
                        .filter(cell -> !cell.isEmpty())
                        .map(cell -> Arrays.stream(cell.split(","))
                            .collect(Collectors.toList()))
                        .filter(list -> list.size() == 3) // Ensure record has 3 fields (email, firstName, lastName)
                        .flatMapPublisher(list -> checkEmailValidity(list.get(0))
                            .map(valid -> valid ? Just.just(list) : Next.next())
                            .onComplete(() -> materializer().shutdown()))
                        .filter(maybeList -> maybeList.isDefined())
                        .flatMapPublisher(maybeList -> {
                            List<String> list = maybeList.get();
                            User user = userCache.getIfPresent(list.get(0)); // Retrieve user from cache if exists

                            if (user == null) {
                                user = new User(list); // Instantiate User class with email, firstName, and lastName
                                userCache.put(list.get(0), user); // Store user in cache for further processing
                            }

                            return Future.successful(user);
                        })
                        .toMat(Sink.foreach(System.out::println))
                        .run(materializer));
    }

    private static Publisher<Boolean> checkEmailValidity(String email) {
        // Implement your custom email validation logic here
        // Return a Publisher that emits true for valid emails, and false otherwise
    }
}
