    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

static node_t* head = NULL;
static size_t num_elements = 0;
static size_t total_allocated_bytes = 0;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_operation(const char* operation) {
    // Implement logging using your external logging framework.
}

int add_element(const RX_UE_INFORMATION_TAG tag, const RNTI rnti) {
    pthread_mutex_lock(&list_mutex);

    if (num_elements >= MAX_PDU_COUNT) {
        log_operation("Exceeded maximum PDU count");
        pthread_mutex_unlock(&list_mutex);
        return -1; // Maximum PDU count exceeded
    }

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
        log_operation("Memory allocation failure");
        pthread_mutex_unlock(&list_mutex);
        return -2; // Memory allocation failure
    }

    new_node->data.tag = tag;
    new_node->data.rnti = rnti;
    new_node->data.crc_indication_tag.crcflag = rand() % 2;
    new_node->next = head;
    head = new_node;
    num_elements++;
    total_allocated_bytes += sizeof(node_t);

    pthread_mutex_unlock(&list_mutex);
    return 0; // Successfully added element
}

void remove_element_by_rnti(const RNTI rnti) {
    pthread_mutex_lock(&list_mutex);

    node_t* current = head;
    node_t* previous = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            num_elements--;
            total_allocated_bytes -= sizeof(node_t);
            break;
        }
        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void update_element_by_rnti(const RNTI rnti, const RX_UE_INFORMATION_TAG new_tag) {
    pthread_mutex_lock(&list_mutex);

    node_t* current = head;
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            current->data.tag = new_tag;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

