} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

void push_to_list(NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = node;
        tail = node;
    } else {
        tail->next = node;
        tail = node;
    }
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* pop_from_list() {
    NFAPI_CRC_INDICATION_PDU_T *tempNode;
    pthread_mutex_lock(&list_mutex);
    if (!head) return NULL;
    tempNode = head;
    head = head->next;
    pthread_mutex_unlock(&list_mutex);
    return tempNode;
}

bool contains_rnti(uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    bool found = false;

    pthread_mutex_lock(&list_mutex);
    while (current) {
        if (current->rnti == rnti) {
            found = true;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);

    return found;
