public class ServiceManager {
 private static final Logger LOGGER = LoggerFactory.getLogger(ServiceManager.class);
 private final ExecutorService executor;
 private final EventBus eventBus;
 private final HealthChecker healthChecker;
 private final RetryStrategy retryStrategy;
 private volatile ServiceStatus status;

 @Inject
 public ServiceManager(@Named("serviceExecutor") ExecutorService executor, EventBus eventBus, HealthChecker healthChecker, RetryStrategy retryStrategy) {
 this.executor = executor;
 this.eventBus = eventBus;
 this.healthChecker = healthChecker;
 this.retryStrategy = retryStrategy;
 this.status = ServiceStatus.STOPPED;
 }

 public void start() {
 status = ServiceStatus.STARTING;
 Completable deferredStart = Completable.defer(() -> {
 try {
 healthChecker.checkHealth();
 LOGGER.info("Service started successfully.");
 return Completable.complete();
 } catch (Exception e) {
 LOGGER.error("Failed to start service.", e);
 return Completable.error(e);
 }
 }).doOnError(throwable -> {
 status = ServiceStatus.ERROR;
 retryStrategy.retry(throwable);
 });

 deferredStart.subscribe(() -> {
 status = ServiceStatus.RUNNING;
 LOGGER.info("Service started and running.");
 Ticker startTicker = Ticker.of(1, TimeUnit.SECONDS);
 startTicker.scheduleAtFixedRate(() -> healthChecker.checkHealth(), 5, 10, TimeUnit.SECONDS);
 });

 executor.submit(() -> {
 try {
 Thread.sleep((int) (Math.random() * 3000));
 } catch (InterruptedException e) {
 LOGGER.error("Thread interrupted.", e);
 }
 deferredStart.onErrorResumeNext(throwable -> Completable.timer(1, TimeUnit.SECONDS).flatMap(__ -> deferredStart));
 });
 }

 public void stop() {
 status = ServiceStatus.STOPPING;
 Completable deferredStop = Completable.defer(() -> {
 healthChecker.checkHealth();
 eventBus.onNext("Service stopped.");
 return Completable.complete();
 }).doOnError(throwable -> {
 status = ServiceStatus.ERROR;
 retryStrategy.retry(throwable);
 });
 deferredStop.subscribe(() -> {
 status = ServiceStatus.STOPPED;
 LOGGER.info("Service stopped.");
 });
 }

 public void monitor() {
 while (true) {
 if (!healthChecker.isHealthy()) {
 LOGGER.error("Service is unhealthy.");
 }
 try {
 Thread.sleep(1000);
 } catch (InterruptedException e) {
 LOGGER.error("Thread interrupted.", e);
 }
 }
 }

 public enum ServiceStatus { STOPPED, STARTING, RUNNING, ERROR }
}

interface HealthChecker {
 boolean isHealthy();
 void checkHealth() throws Exception;
}

@FunctionalInterface
interface RetryStrategy {
 void retry(Throwable throwable);
}
