class DataHandler:
    _registry = ThreadSafeDict()

    def __init__(self, data_type=None):
        self.data = []
        if data_type:
            factory = self._registry.get(data_type)
            if factory:
                self.__class__ = factory()

    @staticmethod
    def register(data_type, factory):
        DataHandler._registry[data_type] = factory

    def read_chunk(self, chunk):
        self.data += json.loads(chunk)

    def md5(self):
        m = hashlib.md5()
        for item in self.data:
            m.update(json.dumps(item).encode())
        return m.hexdigest()

    def serialize_to_json(self):
        return json.dumps(self.data, ensure_ascii=False)

    def deserialize_from_json(self, data):
        self.data = json.loads(data)

class CustomDataHandler(DataHandler):
    # Implement custom methods or override existing ones for specialized handling of specific data types or processing requirements

