#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>
#include <time.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <unistd.h>
#include <curl/curl.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
};

typedef struct {
    const char *hostname;
    u_char ip[sizeof(struct in_addr)];
    CURL *curl;
    size_t n;
    struct NFAPI_CRC_INDICATION_PDU_T *pdu;
} context_t;

static int get_ip(const char *hostname, u_char ip[sizeof(struct in_addr)]) {
    struct hostent *he;
    int ret;

    he = gethostbyname(hostname);
    if (he == NULL) {
        return -1;
    }

    memcpy(ip, he->h_addr_list[0], sizeof(struct in_addr));

    return 0;
}

static size_t read_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    size_t realsize = size * nmemb;
    context_t *ctx = (context_t *)userdata;

    memcpy(((char *)ctx->pdu + ctx->n), ptr, realsize);
    ctx->n += realsize;

    return realsize;
}

void init_pdu(struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = 123456789;
    pdu->RNTI = 9876543210LL;
    rand_r(time(NULL)); // Set CRC_INDICATION_REL8_TAG randomly
}

void populate_list(size_t n, struct NFAPI_CRC_INDICATION_PDU_T *pdu_list) {
    for (size_t i = 0; i < n; ++i) {
        init_pdu(&pdu_list[i]);
    }
}

void* fetch_data(void *arg) {
    context_t *ctx = (context_t *)arg;
    CURLcode res;

    ctx->curl = curl_easy_init();
    if (!ctx->curl) {
        perror("curl_easy_init");
        return NULL;
    }

    curl_easy_setopt(ctx->curl, CURLOPT_URL, ctx->hostname);
    curl_easy_setopt(ctx->curl, CURLOPT_WRITEFUNCTION, read_callback);
    curl_easy_setopt(ctx->curl, CURLOPT_WRITEDATA, ctx);

    do {
        res = curl_easy_perform(ctx->curl);
    } while (res == CURLE_AGAIN && !ctx->n);

    if (res != CURLE_OK) {
        perror("curl_easy_perform");
    }

    curl_easy_cleanup(ctx->curl);
    return NULL;
}

int main(int argc, char *argv[]) {
    size_t n = 10; // Number of PDUs to create
    struct NFAPI_CRC_INDICATION_PDU_T *pdu_list;

    if (argc < 2) {
        printf("Usage: %s <hostname>\n", argv[0]);
        return 1;
    }

    pdu_list = malloc(n * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("malloc");
        return 2;
    }

    populate_list(n, pdu_list);

    context_t *ctx = malloc(sizeof(context_t));
    if (!ctx) {
        perror("malloc");
        free(pdu_list);
        return 3;
    }

    ctx->hostname = argv[1];
    ctx->n = 0;
    ctx->pdu = pdu_list;

    // Start fetching data concurrently
    pthread_t threads[n];
    for (size_t i = 0; i < n; ++i) {
        if (pthread_create(&threads[i], NULL, fetch_data, ctx)) {
            perror("pthread_create");
            free(ctx);
            free(pdu_list);
            return 4;
        }
    }

    // Wait for all threads to finish and clean up resources
    for (size_t i = 0; i < n; ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("pthread_join");
            free(ctx);
            free(pdu_list);
            return 5;
        }
    }

    free(ctx);
    free(pdu_list);

    return 0;
}
