        themeBitmap.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG_INVALID; // Set invalid values for unused bitmap
        themeBitmap.RNTI = -1;
    }

    char* themeDir = getenv("THEME_DIR") ?: DEFAULT_THEME_DIR;
    int cacheRootDirLength = strlen(themeDir) + sizeof("/cache") + 1;
    char cacheRootDir[cacheRootDirLength];
    strcpy(cacheRootDir, themeDir);
    strcat(cacheRootDir, "/cache");

    // Initialize the MD5 hash context
    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pduList) {
        perror("Memory allocation failure");
        return NULL;
    }

    // Parse the PNG file from cache root directory and place it in a theme cache
    for (int i = 0; i < N; ++i) {
        char pngFilePath[cacheRootDirLength + 16]; // Maximum PNG file name length is 15 characters plus .png extension
        snprintf(pngFilePath, sizeof(pngFilePath), "%s/theme%d.png", cacheRootDir, i);

        int fd = open(pngFilePath, O_RDONLY);
        if (fd == -1) {
            perror("Failed to open PNG file");
            continue; // Move on to the next structure if the file can't be opened
        }

        png_structp pngPtr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
        if (!pngPtr) {
            perror("Failed to create PNG read structure");
            close(fd);
            continue; // Move on to the next structure if png_create_read_struct fails
        }

        png_infop infoPtr = png_create_info_struct(pngPtr);
        if (!infoPtr) {
            perror("Failed to create PNG info structure");
            png_destroy_read_struct(&pngPtr, NULL); // Free the read structure
            close(fd);
            continue; // Move on to the next structure if png_create_info_struct fails
        }

        if (setjmp(png_jmpbuf(pngPtr))) { // Handle potential errors during PNG parsing using setjmp and longjmp
            perror("Error during PNG file reading");
            png_destroy_read_struct(&pngPtr, &infoPtr); // Free the read structure and info structure
            close(fd);
            continue; // Move on to the next structure if an error occurs during parsing
        }

        png_init_io(pngPtr, fd);
        png_read_info(pngPtr, infoPtr);

        // Update RX_UE_INFORMATION_TAG and RNTI for each structure with the parsed PNG data
        // ... (Assuming you have a function to extract RX_UE_INFORMATION_TAG and RNTI from the parsed PNG data)

        png_read_update_info(pngPtr, infoPtr); // Re-read the info after setting new values for RX_UE_INFORMATION_TAG and RNTI
        png_read_image(pngPtr, NULL); // Read the PNG image data

        png_destroy_read_struct(&pngPtr, &infoPtr); // Free the read structure and info structure
        close(fd); // Close the opened file
    }

    // Hash the provided string for each structure and store the result in CRC_INDICATION_REL8_TAG.CRC
    for (int i = 0; i < N; ++i) {
        char str[strlen(stringToHash) + 1]; // Allocate space for the null-terminated string
        strcpy(str, stringToHash);

        MD5_Update(&mdContext, str, strlen(str));
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &mdContext); // Get the final hash value

        pduList[i].CRC_INDICATION_REL8_TAG.CRC = *(uint32_t*)&digest[0];
    }

    return pduList;
}
