                    if (pdu->crc_indication.CRCFlag) {
                        // Process element based on specific conditions
                    }

                    // Update timestamp and store in primaryList
                    pdu->timestamp = steady_clock::now();
                    primaryList.push_back(move(pdu));

                    // Rebalance the list if necessary
                    if (static_cast<float>(primaryList.size()) / static_cast<float>(maxSizeLimit) > rebalanceThreshold) {
                        balance();
                    }
                }
            } catch (system_error& e) {
                // Handle errors in data source or memory allocation
            }
        }
    }

    void consumeData(io_service& ioService) {
        while (!source.stopped()) {
            try {
                lock_guard<mutex> lock(dataMutex);
                if (primaryList.empty() && secondaryList.empty()) {
                    // Fallback mechanism for data source unreliability or unavailability
                } else {
                    auto pdu = primaryList.front();
                    primaryList.pop_front();
                    ioService.post([pdu, this]() mutable {
                        // Process element and move to secondary list if necessary
                    });
                }
            } catch (system_error& e) {
                // Handle errors in data source or memory allocation
            }
        }
    }

    void balance() {
        deque<shared_ptr<NFAPI_CRC_INDICATION_PDU_T>> tempList;

        lock_guard<mutex> lock(dataMutex);
        auto primarySize = primaryList.size();
        while (!primaryList.empty()) {
