    UESRRC_CONNECTION_RECONFIGURATION message;
} NFAPI_MESSAGE_T;

static NFAPI_MESSAGE_T *messages = NULL;
static pthread_mutex_t mutex;
static size_t messages_count = 0;
static size_t messages_capacity = 0;
static bool initialized = false;
static pthread_t threads[NUM_THREADS];

void init_array() {
    if (initialized) return;
    messages = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (messages == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    messages_capacity = MAX_MESSAGES;
    messages_count = 0;
    pthread_mutex_init(&mutex, NULL);
    initialized = true;
}

void deinit_array() {
    if (!initialized) return;
    munmap(messages, BUFFER_SIZE);
    pthread_mutex_destroy(&mutex);
    initialized = false;
}

static void *consumer(void *arg) {
    while (true) {
        // Your message processing logic here
    }
    return NULL;
}

void add_message(NFAPI_MESSAGE_T message, uint32_t context_id) {
    pthread_mutex_lock(&mutex);
    if (messages_count >= messages_capacity - 10) {
        messages = realloc(messages, messages_capacity * 2 * BUFFER_SIZE);
        if (!messages) {
            perror("realloc");
            pthread_mutex_unlock(&mutex);
            return;
        }
        messages_capacity *= 2;
    }
    memcpy((void *)&messages[messages_count], &message, MESSAGE_SIZE);
    messages[messages_count].context_id = context_id;
    messages_count++;
    pthread_mutex_unlock(&mutex);
}

void run() {
    init_array();
    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, consumer, NULL);
    }
    // Add messages using add_message function

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threads[i], NULL);
    }
    deinit_array();
}
