// Create a new linked list node for a SecurityPolicy
struct SecurityPolicyNode {
    SecurityPolicy policy;
    struct SecurityPolicyNode *next;
};

// Function to create a new SecurityPolicyNode with given data
SecurityPolicyNode* create_policy_node(SecurityPolicy policy) {
    SecurityPolicyNode* new_node = (SecurityPolicyNode*)malloc(sizeof(SecurityPolicyNode));
    new_node->policy = policy;
    new_node->next = NULL;
    return new_node;
}

// Function to add a new SecurityPolicy to the list
void add_policy(NetworkInterfaceConfig* nic, SecurityPolicy policy) {
    pthread_mutex_lock(&nic->mutex);
    // Create new node and append it to the linked list
    List current = nic->policies;
    if (current == NULL) {
        nic->policies = create_policy_node(policy);
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = create_policy_node(policy);
    }
    pthread_mutex_unlock(&nic->mutex);
}

// Function to remove a SecurityPolicy by matching its rule with the given one
void remove_policy(NetworkInterfaceConfig* nic, char* rule) {
    pthread_mutex_lock(&nic->mutex);
    List current = nic->policies;
    if (current == NULL) return;

    if (strcmp(current->policy.rule, rule) == 0) {
        nic->policies = current->next;
        free(current);
    } else {
        while (current->next != NULL && strcmp((current->next)->policy.rule, rule) != 0) {
            current = current->next;
        }

        if (current->next == NULL) return;

        List temp = current->next;
        current->next = temp->next;
        free(temp);
    }

    pthread_mutex_unlock(&nic->mutex);
}

// Function to iterate over policies in the list and apply updates if needed
