        return NULL;
    }

    int i, rnti = 0;
    PJ_HASH_ITER iter;
    pj_hash_iter_init(&iter, table, sizeof(table) / sizeof(PJ_HASH_ST));

    for (i = 0; i < num_pdus && rnti < MAX_RTNI; ++i) {
        PJ_HASH_FIND_PTR(table, &rnti, &iter);
        if (!iter.found) {
            pdus[i].rx_ue_info = /* initialize rx_ue_info */;
            pdus[i].rnti = rnti++;
            pdus[i].crc_indication.crcflag = (pj_uint16_t)(crcflag++ & 0x0001); // Set CRCFLAG to 0 or 1 randomly
