char* generate_unique_filename(const char* base, size_t* new_length) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int extension_index = 0;
    char dir[4096], filename[4096];
    sscanf(base, "%s%*[./]", dir);
    strcpy(filename, dir);
    strcat(filename, "/");
    strcat(filename, basename(base));
    sprintf(&filename[strlen(filename) - 4], ".%d", extension_index++ % 5);
    pthread_mutex_lock(&mutex);
    DIR *dirp = opendir(filename);
    if (dirp != NULL) {
        closedir(dirp);
        int count = 0;
        strcpy(filename, dir);
        strcat(filename, "/");
        struct dirent *entry;
        while ((entry = readdir(opendir(filename))) != NULL) {
            if (strcmp(entry->d_name, filename + strlen(filename) - strlen(basename(base))) == 0) {
                count++;
            }
        }
        closedir(opendir(filename));
        if (count > 0) {
            sprintf(&filename[strlen(filename) - 4], ".%d", extension_index % 5);
        }
    }
    pthread_mutex_unlock(&mutex);
    *new_length = strlen(filename);
    return filename;
}

