// Initialize the NFAPI_CRC_INDICATION_PDU module
void nfapi_crc_indication_pdu_init(struct NFAPI_CRIC_INDICATION_PDU **ppInstance, size_t capacity) {
    struct NFAPI_CRIC_INDICATION_PDU *instance = malloc(sizeof(struct NFAPI_CRIC_INDICATION_PDU));
    if (!instance) {
        fprintf(stderr, "Failed to allocate memory for instance\n");
        return;
    }

    instance->capacity = capacity;
    instance->count = 0;
    instance->data = calloc(capacity, sizeof(struct NFAPI_CRIC_INDICATION_PDU_T));
    if (!instance->data) {
        fprintf(stderr, "Failed to allocate memory for data array\n");
        free(instance);
        return;
    }

    pthread_mutex_init(&(instance->lock), NULL);
    *ppInstance = instance;
}

// Populate a single NFAPI_CRIC_INDICATION_PDU structure with random values and from the REST API service
void populate_single_pdu(struct NFAPI_CRIC_INDICATION_PDU_T *pdu) {
