void populate_module(struct NFAPI_CRIC_INDICATION_PDU *instance) {
    pthread_mutex_lock(&(instance->lock));

    for (size_t i = 0; i < instance->capacity && instance->count < instance->capacity; ++i) {
        if (!instance->data[i].crc_indication_rel8_tag.crcflag) continue; // Skip populating if the CRC flag is already set

        populate_single_pdu(&(instance->data[i]));
        ++(instance->count);
    }

    pthread_mutex_unlock(&(instance->lock));
}

