std::vector<NFAPI_CRC_INDICATION_PDU_T> generateNfalistsAndSelectAttack(int N, RandomSeedGenerator* rsg, VideoGameContext* vgc) {
    std::mt19937 gen(*rsg->getNextRandom());
    std::uniform_int_distribution<> attackDist(0, 1); // 0: attack1, 1: attack2
    std::uniform_int_distribution<uint64_t> timeDist; // Time for attacks based on game state
    uint64_t now = std::chrono::steady_clock::now().time_since_epoch().count();

    std::vector<NFAPI_CRC_INDICATION_PDU_T> nfas;
    nfas.reserve(N);

    for (int i = 0; i < N; ++i) {
        uint8_t rniTag = /* generate RNI Tag */;
        uint16_t rnti = /* generate RNTI based on rniTag */;
        uint8_t cicrTag = /* generate CRC INDICATION tag */;

        vgc->lock(); // Lock the game context to avoid race conditions
        auto it = vgc->cooldownQueue.cbegin();
        if (it != vgc->cooldownQueue.cend()) {
            uint64_t cooldownEnd = (*it).second;
            if (now < cooldownEnd) {
                vgc->unlock(); // Unlock the game context and return immediately if cooldown is active
                continue;
            }
        }
        vgc->unlock(); // Update the game context with the new cooldown if necessary, then unlock it

        auto attack = attackDist(gen);
        uint64_t attackTime = timeDist(gen);

        vgc->lock(); // Lock the game context to update the cooldown for the selected attack
        vgc->cooldownQueue.emplace(attackTime + now, attack);
        vgc->unlock();

        nfas.push_back({rniTag, rnti, cicrTag});
    }

    return nfas;
}
