#include <stdio.h>
#include <stdlib.h>
#include <openssl/pem.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>
#include <getopt.h>
#define MAX_FILE_SIZE 10485760 // Default max file size is 10MB

typedef struct {
    EVP_CIPHER_CTX *cipher;
    unsigned char *data;
    size_t length;
} CipherObject;

void log_warning(const char* message) {
    openlog("my_function", LOG_PID | LOG_CONS, LOG_WARNING);
    syslog(LOG_WARNING, "%s", message);
    closelog();
}

int validate_extension(char* filename) {
    size_t len = strlen(filename);
    if (len < 4 || (len > 5 && filename[len - 3] != '.')) return 0;
    char *ext = filename + (len - 3);
    return strcasecmp(ext, "pem") == 0 || strcasecmp(ext, "key") == 0;
}

void free_cipher_object(CipherObject* obj) {
    EVP_CIPHER_CTX_free(obj->cipher);
    free(obj->data);
    free(obj);
}

CipherObject* load_file(const char *filename, int mode) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    fseeko64(fp, 0, SEEK_END);
    size_t filesize = ftello64(fp);
    if (filesize > MAX_FILE_SIZE) {
        syslog(LOG_WARNING, "File too large: %s (%zu bytes)", filename, filesize);
        fclose(fp);
        return NULL;
    }
    rewind(fp);

    unsigned char *data = malloc(filesize + AES_BLOCKSIZE);
    if (!data) {
        perror("malloc");
        fclose(fp);
        return NULL;
    }
    size_t bytesRead = fread(data, 1, filesize, fp);
    if (bytesRead != filesize) {
        perror("fread");
        free(data);
        fclose(fp);
        return NULL;
    }
    CipherObject* obj = malloc(sizeof(CipherObject));
    obj->data = data;
    obj->length = bytesRead;
    obj->cipher = NULL;

    fclose(fp);
    return obj;
}

void perform_operation(CipherObject *obj, const char* operation) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    if (strcmp(operation, "encrypt") != 0 && strcmp(operation, "decrypt") != 0) {
        log_warning("Invalid operation: %s", operation);
        return;
    }

    cipher = EVP_aes_256_cbc();
    ctx = EVP_CIPHER_CTX_new();

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL)) {
        perror("EVP_EncryptInit_ex");
        goto err;
    }

    if (strcmp(operation, "encrypt") == 0) {
        if (1 != EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_CHUNK, AES_BLOCKSIZE, NULL)) {
            perror("EVP_CTRL_CHUNK");
            goto err;
        }
    }

    size_t buf_len = obj->length + (obj->length % AES_BLOCKSIZE ? AES_BLOCKSIZE : 0);
    unsigned char *buf = malloc(buf_len);
    if (!buf) {
        perror("malloc");
        goto err;
    }

    size_t out_len = obj->length;

    while (out_len > 0) {
        size_t part = out_len < buf_len ? out_len : buf_len;
        size_t in_len = part;

        if (1 != EVP_CIPHER_CTX_update(ctx, obj->data, &in_len, buf, &part)) {
            perror("EVP_CIPHER_CTX_update");
            goto err;
        }

        out_len -= in_len;
    }

    if (1 != EVP_CIPHER_CTX_final(ctx, NULL, &out_len)) {
        perror("EVP_CIPHER_CTX_final");
        goto err;
    }

    obj->data = realloc(obj->data, out_len + AES_BLOCKSIZE);
    if (!obj->data) {
        perror("realloc");
        goto err;
    }
    memcpy(obj->data, buf, out_len);
    free(buf);

    obj->length = out_len;

err:
    EVP_CIPHER_CTX_free(ctx);
}

CipherObject* process_file(const char* filename, const char* operation) {
    if (!validate_extension(filename)) return NULL;

    CipherObject *obj = load_file(filename, 0);
    if (!obj) return NULL;

    perform_operation(obj, operation);

    return obj;
}
```
