typedef struct UeSessionInfo {
    uint64_t unique_ue_id;
    int bearer_context;
    float qos_parameters[3]; // (latency, throughput, reliability)
    struct UeSessionInfo *next;
    pthread_mutex_t mutex;
} UeSessionInfo;

UeSessionInfo* initialize_linked_list() {
    UeSessionInfo *head = NULL;

    // Function to create new node and add it to the list with locking
    void add_node(UeSessionInfo **head, UeSessionInfo *new_node) {
        pthread_mutex_lock(&new_node->mutex);
        new_node->next = *head;
        *head = new_node;
        pthread_mutex_unlock(&new_node->mutex);
    }

    // Allocate and initialize a new node with the given parameters, validation checks included
    UeSessionInfo* create_and_validate_node(uint64_t unique_ue_id, int bearer_context, const float qos_params[3]) {
        UeSessionInfo *new_node = (UeSessionInfo*) malloc(sizeof(UeSessionInfo));
        if (!new_node) return NULL;

        new_node->unique_ue_id = unique_ue_id;
        new_node->bearer_context = bearer_context;
        memcpy(new_node->qos_parameters, qos_params, sizeof(float) * 3);

        // Customize validation checks based on your requirements
        if (bearer_context < 0 || bearer_context > MAX_BEARER_CONTEXT) {
            free(new_node);
            return NULL;
        }
        for (int i = 0; i < 3; ++i) {
            if (qos_params[i] <= 0 || qos_params[i] > MAX_QOS_PARAMS) {
                free(new_node);
                return NULL;
            }
        }

        // Initialize the mutex for thread safety
        pthread_mutex_init(&new_node->mutex, NULL);

        return new_node;
    }

    // Function to iterate through the list with locking
    UeSessionInfo* traverse_list(UeSessionInfo *head, UeSessionInfo **current) {
        pthread_mutex_lock(&(*current)->mutex);
        UeSessionInfo *temp = *current;
        *current = (*current)->next;
        pthread_mutex_unlock(&temp->mutex);
        return temp;
    }

    // Allocate and initialize the linked list head node
    head = create_and_validate_node(0, 0, {0, 0, 0});
    if (!head) goto error_handler;

    add_node(&head, head);

    return head;

error_handler:
    free(head);
    return NULL;
}
```

