} LTE_MME_UE_S1AP_ID;

typedef struct MemoryBlock {
    void* memory;
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* memory_pool = NULL;
pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t allocated_memory = 0;
size_t total_memory = MEMORY_POOL_SIZE;

void* mem_alloc(size_t size) {
    if (memory_pool == NULL || memory_pool->size <= size) {
        MemoryBlock* new_block = (MemoryBlock*)malloc(total_memory);
        if (new_block == NULL) {
            fprintf(stderr, "Out of memory!\n");
            return NULL;
        }
        total_memory -= size;
        new_block->size = size;
        new_block->next = memory_pool;
        memory_pool = new_block;
    }

    void* mem = memory_pool->memory;
    memory_pool->memory += size;
    memory_pool = memory_pool->next;

    pthread_mutex_lock(&memory_lock);
    allocated_memory += size;
    pthread_mutex_unlock(&memory_lock);

    return mem;
}

void mem_free(void* mem) {
    pthread_mutex_lock(&memory_lock);
    allocated_memory -= sizeof(LTE_MME_UE_S1AP_ID);
    pthread_mutex_unlock(&memory_lock);
}

