using System;
using System.Collections.Generic;
using System.Linq;
using System.Math;
using System.Runtime.Caching;
using CryptoRandom = System.Security.Cryptography.RNGCryptoServiceProvider;

namespace FlexibleValueGenerator
{
    public class FlexibleValueGenerator
    {
        private readonly ObjectCache _cache;
        private readonly Action<object> _resetAction;
        private readonly Random _random;
        private readonly Tuple<double, double> _boundaries;
        private readonly Dictionary<Type, Func<object>> _valueGenerators;
        private readonly List<Func<object, bool>> _constraints;

        public FlexibleValueGenerator(int seed = 0, Tuple<double, double> boundaries = default)
        {
            _cache = MemoryCache.Default;
            _random = new Random(seed);
            _boundaries = boundaries;
            _valueGenerators = new Dictionary<Type, Func<object>>
            {
                [typeof(int)] = GenerateInt,
                [typeof(long)] = GenerateLong,
                [typeof(float)] = GenerateFloat,
                [typeof(double)] = GenerateDouble
            };
            _constraints = new List<Func<object, bool>>();
        }

        public void AddConstraint(Func<object, bool> constraint)
        {
            _constraints.Add(constraint);
        }

        public void Reset()
        {
            _random = new Random(_random.Next());
            _cache.Remove("generatorState");
        }

        public object Next()
        {
            var generatorStateKey = "generatorState";

            if (_cache.Get(generatorStateKey) == null)
            {
                SetGeneratorState();
                _cache.Add(generatorStateKey, this, new CacheItemPolicy { SlidingExpiration = TimeSpan.FromMinutes(10)});
            }

            var value = GenerateValue(_random);
            foreach (var constraint in _constraints)
            {
                if (!constraint(value))
                {
                    return Next();
                }
            }

            return value;
        }

        private void SetGeneratorState()
        {
            var boundaryMin = _boundaries.Item1;
            var boundaryMax = _boundaries.Item2;
            var lowerBoundary, upperBoundary;

            if (typeof(int) == _valueGenerators[typeof(int)]().GetType())
            {
                lowerBoundary = Math.Max(_random.Next(), (int)boundaryMin);
                upperBoundary = Math.Min(_random.Next((int)(1e9)), (int)boundaryMax + 1);
            }
            else if (typeof(long) == _valueGenerators[typeof(long)]().GetType())
            {
                lowerBoundary = Math.Max(_random.Next(), (long)boundaryMin);
                upperBoundary = Math.Min(_random.Next((long)(1e18)), (long)boundaryMax + 1);
            }
            else if (typeof(float) == _valueGenerators[typeof(float)]().GetType())
            {
                lowerBoundary = Math.Max(_random.NextDouble(), boundaryMin);
                upperBoundary = Math.Min(_random.NextDouble(), boundaryMax + 1e-6);
            }
            else if (typeof(double) == _valueGenerators[typeof(double)]().GetType())
            {
                lowerBoundary = Math.Max(_random.NextDouble(), boundaryMin);
                upperBoundary = Math.Min(_random.NextDouble(), boundaryMax + 1e-6);
            }
            else throw new ArgumentException("Invalid data type.");

            _resetAction = () => { lowerBoundary = Math.Max(_random.NextDouble(), boundaryMin); };

            Action<object> setIntState = (int value) =>
            {
                if (value < lowerBoundary || upperBoundary < value)
                    throw new InvalidOperationException("Value out of bounds.");
                _cache["generatorState"] = this;
            };

            Action<object> setLongState = (long value) =>
            {
                if (value < lowerBoundary || upperBoundary < value)
                    throw new InvalidOperationException("Value out of bounds.");
                _cache["generatorState"] = this;
            };

            Action<object> setFloatState = (float value) =>
            {
                if (value < lowerBoundary || upperBoundary < value)
                    throw new InvalidOperationException("Value out of bounds.");
                _cache["generatorState"] = this;
            };

            Action<object> setDoubleState = (double value) =>
            {
                if (value < lowerBoundary || upperBoundary < value)
                    throw new InvalidOperationException("Value out of bounds.");
                _cache["generatorState"] = this;
            };

            _valueGenerators[typeof(int)] = () => setIntState((int)_random.Next((int)(upperBoundary - lowerBoundary + 1)) + (int)lowerBoundary);
            _valueGenerators[typeof(long)] = () => setLongState((long)_random.Next((long)(upperBoundary - lowerBoundary + 1)) + (long)lowerBoundary);
            _valueGenerators[typeof(float)] = () => setFloatState((float)_random.NextDouble() * (upperBoundary - lowerBoundary) + lowerBoundary);
            _valueGenerators[typeof(double)] = () => setDoubleState((double)_random.NextDouble() * (upperBoundary - lowerBoundary) + lowerBoundary);
        }

        private object GenerateValue(Random random)
        {
            return _valueGenerators[typeof(object)]().DynamicInvoke(random);
        }

        public override string ToString()
        {
            var boundaryMin = _boundaries.Item1;
            var boundaryMax = _boundaries.Item2;
            var constraints = string.Join(", ", _constraints.Select((constraint, index) => $"{index + 1}: {constraint}"));
            return $"FlexibleValueGenerator: Seed={_random.Next()}, Range={boundaryMin}-{boundaryMax}, Constraints={constraints}";
        }
    }
}
