using System.Linq;
using System.Threading.Tasks;

public class RandomValueGenerator
{
    private float _minValue;
    private float _maxValue;
    private Random _random;
    private Dictionary<Type, Queue<object>> _history;

    public RandomValueGenerator()
    {
        _minValue = float.MaxValue;
        _maxValue = float.MinValue;
        _random = new Random();
        _history = new Dictionary<Type, Queue<object>>
        {
            { typeof(float), new Queue<float>() },
            { typeof(int), new Queue<int>() }
        };
    }

    public void SetMinMax(float minValue, float maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("The minimum value should be less than or equal to the maximum value.");

        _minValue = Math.Min(_minValue, minValue);
        _maxValue = Math.Max(_maxValue, maxValue);
    }

    public void SetSeed(int seed) => _random = new Random(seed);

    public float NextFloat()
    {
        lock (_history[typeof(float)])
        {
            if (_history[typeof(float)].Any())
                return _history[typeof(float)].Dequeue();
        }

        var value = _random.NextFloat(_minValue, _maxValue);
        lock (_history[typeof(float)])
            _history[typeof(float)].Enqueue(value);

        return value;
    }

    public int NextInt()
    {
        lock (_history[typeof(int)])
        {
            if (_history[typeof(int)].Any())
                return (int)_history[typeof(int)].Dequeue();
        }

        var value = _random.Next(_Math.Min((int)Math.Ceiling(_minValue), int.MaxValue), Math.Min((int)Math.Floor(_maxValue), int.MaxValue));
        lock (_history[typeof(int)])
            _history[typeof(int)].Enqueue(value);

        return value;
    }

    public async Task PeriodicallyUpdateRangeAsync(Func<Task> externalDataSource)
    {
