using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class DynamicValueGenerator
{
    private readonly Random _random;
    private readonly ILogger<DynamicValueGenerator> _logger;
    private readonly IConfiguration _configuration;
    private double _minFloat;
    private double _maxFloat;
    private int _minInt;
    private int _maxInt;
    private double _tolerance;
    private TimeSpan _cacheTime;
    private Dictionary<(double min, double max), object> _floatCache;
    private Dictionary<(int min, int max), object> _intCache;
    private SemaphoreSlim _semaphore = new SemaphoreSlim(1);

    public DynamicValueGenerator(ILogger<DynamicValueGenerator> logger, IConfiguration configuration)
    {
        _logger = logger;
        _configuration = configuration;
        _random = new Random(_configuration.GetValue<int>("RandomSeed", DateTime.Now.Millisecond));

        InitializeCache();
    }

    private void InitializeCache()
    {
        _floatCache = new Dictionary<(double min, double max), object>();
        _intCache = new Dictionary<(int min, int max), object>();
    }

    public void SetFloatRange(double min, double max)
    {
        _minFloat = min;
        _maxFloat = max;
    }

    public void SetIntRange(int min, int max)
    {
        _minInt = min;
        _maxInt = max;
    }

    public void SetTolerance(double tolerance)
    {
        _tolerance = tolerance;
    }

    public void SetCacheTime(TimeSpan cacheTime)
    {
        _cacheTime = cacheTime;
    }

    public double GenerateFloat(double target = default)
    {
        var key = (_minFloat, _maxFloat);
        if (_floatCache.TryGetValue(key, out object cachedValue))
            return (double)cachedValue;

        lock (_floatCache)
        {
            if (_floatCache.TryGetValue(key, out object cachedValue))
                return (double)cachedValue;

            var value = _random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
            _floatCache[key] = value;

            if (IsOutOfTolerance(value, target))
                _logger.LogError("Generated float {Value} is out of tolerance {Tolerance} from target {Target}", value, _tolerance, target);

            return value;
        }
    }

    public int GenerateInt(int target = default)
    {
        var key = (_minInt, _maxInt);
        if (_intCache.TryGetValue(key, out object cachedValue))
            return (int)cachedValue;

        lock (_intCache)
        {
            if (_intCache.TryGetValue(key, out object cachedValue))
                return (int)cachedValue;

            var value = _random.Next(_minInt, _maxInt + 1);
            _intCache[key] = value;

            if (IsOutOfTolerance((double)value, target))
                _logger.LogError("Generated int {Value} is out of tolerance {Tolerance} from target {Target}", value, _tolerance, target);

            return value;
        }
    }

    private bool IsOutOfTolerance(double value, double target = default) => Math.Abs(value - target) > _tolerance;
}
