    private readonly float _maxValue;
    private System.Random _random;

    public CustomRandomGenerator(float minValue, float maxValue)
    {
        ValidateRange(minValue, maxValue);
        _minValue = minValue;
        _maxValue = maxValue;
        _random = new System.Random();
    }

    private void ValidateRange(float minValue, float maxValue)
    {
        if (maxValue < minValue)
            throw new ArgumentException("Max value must be greater than or equal to the minimum value.");
    }

    public float NextFloat(bool isInclusive = true)
    {
        double range = _maxValue - _minValue;
        return (float)((_random.NextDouble() * range) + _minValue);
    }

    public int NextInt(bool isInclusive = true)
    {
        long range = (_maxValue - _minValue) + 1;
        if (range > int.MaxValue || range < int.MinValue) throw new InvalidOperationException("The specified range exceeds the bounds of an integer.");

        return (int)(_random.Next(range) + _minValue);
    }

    public bool IsInRange(float value)
    {
        if (_minValue == _maxValue) return true;
        float inclusiveRange = _maxValue - _minValue + 1;
        return (value >= _minValue && value <= _maxValue) || (value > _minValue && value < _maxValue);
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator: Min={_minValue}, Max={_maxValue}";
    }

    private object _syncLock = new Object();

    public void ResetRange()
    {
        lock (_syncLock)
        {
            _minValue = 0;
            _maxValue = 100;
        }
    }

