    if (!list->head) {
        list->head = list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }

    list->size++;
    pthread_mutex_unlock(&(list->mutex));
}

void remove_front(struct list *list) {
    pthread_mutex_lock(&(list->mutex));

    if (list->size == 0) {
        pthread_mutex_unlock(&(list->mutex));
        return;
    }

    Node* temp = list->head;
    list->head = list->head->next;

    if (list->head == NULL) {
        list->tail = NULL;
    }

    list->size--;
    pthread_mutex_unlock(&(list->mutex));

    free(temp);
}

void add_to_list(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    validate_tag(&new_node->data);
    insert_back(list, new_node);
}

void cleanup_list(struct list *list) {
    pthread_mutex_lock(&(list->mutex));

    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&(list->mutex));

    init_list(list, 0);
}
