    uint32_t source_ip;
    uint32_t dest_ip;
    uint16_t protocol;
} packet_header;

// Global variables
packet_header* headers = NULL;
size_t capacity = 0;
size_t size = 0;
pthread_mutex_t lock;

void validate_header(const packet_header* header) {
    // Implement validation logic here, ensuring all fields are properly populated
}

bool add_header(const packet_header* header) {
    if (!validate_header(header)) {
        return false;
    }

    pthread_mutex_lock(&lock);

    if (size == capacity) {
        // Resize array when it reaches its capacity
        capacity *= 2;
        packet_header* temp = realloc(headers, capacity * sizeof(packet_header));
        if (!temp) {
            perror("Realloc failed");
            pthread_mutex_unlock(&lock);
            return false;
        }
        headers = temp;
    }

    memcpy(&headers[size], header, sizeof(packet_header));
    size++;

    pthread_mutex_unlock(&lock);
    return true;
}

bool delete_header(size_t index) {
    if (index >= size) {
        return false;
    }

    pthread_mutex_lock(&lock);

    memmove(&headers[index], &headers[index + 1], (size - index - 1) * sizeof(packet_header));
    size--;

    pthread_mutex_unlock(&lock);
    return true;
}

const packet_header* get_header(size_t index) {
    if (index >= size) {
        return NULL;
    }

    return &headers[index];
}

// Initialize the data structure
void init() {
    pthread_mutex_init(&lock, NULL);
}

// Clean up the data structure
void cleanup() {
    if (headers) {
        free(headers);
        headers = NULL;
    }
    pthread_mutex_destroy(&lock);
}
