#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <zlib.h>

typedef struct {
    uint32_t length;
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t protocol;
} packet_header;

typedef struct header_node {
    packet_header header;
    struct header_node *next;
} header_node;

static header_node* head = NULL;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Lock-free linked list implementation using a cas (compare and swap) operation.
void ll_insert(header_node *new_node) {
    header_node* tail = head;
    while (tail->next != NULL) {
        tail = tail->next;
    }

    // CAS operation to insert new node at the end of the list.
    if (__sync_bool_compare_and_swap(tail->next, NULL, new_node)) {
        return;
    }

    // If CAS failed, repeat the insertion after a short delay to reduce contention.
    usleep(100);
    ll_insert(new_node);
}

void ll_remove(uint32_t ip) {
    header_node* current = head;
    header_node* previous = NULL;

    while (current != NULL) {
        if (current->header.src_ip == ip || current->header.dst_ip == ip) {
            // CAS operation to remove the node from the list.
            if (__sync_bool_compare_and_swap(current, current, current->next)) {
                if (previous != NULL) {
                    previous->next = current->next;
                } else {
                    head = current->next;
                }
                return;
            }
        }

        previous = current;
        current = current->next;
    }
}

header_node* ll_find(uint32_t ip) {
    header_node* current = head;

    while (current != NULL) {
        if (current->header.src_ip == ip || current->header.dst_ip == ip) {
            return current;
        }

        current = current->next;
    }

    return NULL;
}

// Compression algorithm that adjusts aggressiveness based on system load and available memory.
void compress_packet(packet_header* header) {
    gzFile file = gzopen("compressed.gz", "wb");
    gzwrite(file, header, sizeof(packet_header));
    gzclose(file);
}

// Integration with third-party library for compression (zlib).
void send_notification(packet_header* header) {
    if (header->length > MAX_LENGTH || header->protocol == UNUSUAL_PROTOCOL) {
        // Notify the network monitoring system about unusual packet.
        notify_monitoring_system(header);
    }
}
```

