[' Here is a C++ code using an array-based approach with linked list nodes for each packet header to balance speed of insertion/deletion and space efficiency. The dynamic resizing strategy minimizes fragmentation and ensures efficient memory utilization. The implementation also includes a robust queuing mechanism, error handling, logging, and log level mechanism.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <mutex>
#include <atomic>

struct PacketHeader {
    std::uint32_t length;
    std::string srcIP, destIP;
    std::string protocol;
};

class PacketQueue {
public:
    void enqueue(const PacketHeader& header) {
        mtx.lock();
        queue.push(header);
        mtx.unlock();
    }

    PacketHeader dequeue() {
        mtx.lock();
        if (queue.empty()) {
            condition.wait(mtx);
        }
        auto header = queue.front();
        queue.pop();
        mtx.unlock();
        return header;
    }

private:
    std::queue<PacketHeader> queue;
    std::mutex mtx, logMtx;
    std::condition_variable condition;
};

class PacketManager {
public:
    void insert(const PacketHeader& header) {
        if (!headers.empty() && headers.back().length + 1 < header.length) {
            resize();
        }
        headers.emplace_back(header);
    }

    const PacketHeader* find(const std::string& key) const {
        for (auto it = headers.cbegin(); it != headers.cend(); ++it) {
            if (it->srcIP == key || it->destIP == key) return &(*it);
        }
        return nullptr;
    }

    void remove(const PacketHeader& header) {
        auto it = std::find_if(headers.begin(), headers.end(), [&](const PacketHeader& h) {
            return (h.srcIP == header.srcIP && h.destIP == header.destIP);
        });
        if (it != headers.end()) {
            it->~PacketHeader();
            headers.erase(it);
        }
    }

private:
    void resize() {
        auto newCapacity = std::max(headers.capacity() * 2, 128);
        if (newCapacity > static_cast<std::size_t>(std::numeric_limits<std::ptrdiff_t>::max())) {
            throw std::runtime_error("Exceeded maximum capacity for packet array");
        }
        std::vector<PacketHeader> newHeaders(newCapacity);
        std::copy(headers.cbegin(), headers.cend(), newHeaders.begin());
        headers.swap(newHeaders);
    }

    std::vector<PacketHeader> headers;
    PacketQueue queue;
    std::atomic_int logLevel; // Log level, controlled externally
};
