void* custom_mem_pool_malloc(struct custom_mem_pool *mem_pool, size_t size) {
    pthread_mutex_lock(&mem_pool->lock);
    void *ptr = mem_pool->memory + mem_pool->used_size;
    if (ptr + size > mem_pool->memory + mem_pool->allocated_size) {
        pthread_mutex_unlock(&mem_pool->lock);
