class UplinkNasTransportTlvs {
private:
    std::vector<UplinkNasTransportTlv> data;
    std::unordered_map<uint64_t, size_t> ueIdToIndex;
    mutex mtx; // Mutex to handle concurrent access from multiple threads

public:
    void add(const UplinkNasTransportTlv& tlv) {
        std::unique_lock<std::mutex> lock(mtx);
        data.push_back(tlv);
        ueIdToIndex[tlv.ue_id()] = data.size() - 1;
    }

    bool updateIfExists(uint64_t ue_id, const UplinkNasTransportTlv& tlv) {
        std::unique_lock<std::mutex> lock(mtx);
        auto iter = ueIdToIndex.find(ue_id);
        if (iter == ueIdToIndex.end()) return false; // UE ID not found

        data[iter->second] = tlv;
        return true;
    }

    bool removeIfMatch(uint64_t ue_id, std::function<bool(const UplinkNasTransportTlv&)> filter) {
        std::unique_lock<std::mutex> lock(mtx);
        auto iter = ueIdToIndex.find(ue_id);
        if (iter == ueIdToIndex.end()) return false; // UE ID not found

        bool match = filter(data[iter->second]);
        if (match) {
            data.erase(iter->second);
            ueIdToIndex.erase(ue_id);
        }
        return match;
    }

    const UplinkNasTransportTlv& find(uint64_t ue_id) const {
        auto iter = ueIdToIndex.find(ue_id);
        if (iter == ueIdToIndex.end()) throw std::runtime_error("UE ID not found");
        return data[iter->second];
    }

    // Serialization/Deserialization support using Google Protobuf
    // ...
};
