['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

#define MAX_FRAMES 1000000
#define WINDOW_SIZE 10000
#define PDU_SIZE sizeof(MAC_FRAME_PDU_T)

typedef struct {
    uint32_t pdcp_sn;
    uint32_t pdu_size;
} MAC_FRAME_PDU_T;

struct mac_list_node {
    MAC_FRAME_PDU_T frame;
    struct mac_list_node *next;
};

struct mac_list {
    struct mac_list_node **nodes;
    int head, tail;
    int count;
    pthread_mutex_t lock;
    FILE *log_file;
};

void* log_frame(void *arg) {
    struct mac_list *list = arg;
    while (1) {
        pthread_mutex_lock(&list->lock);
        if (!list->log_file) break;

        MAC_FRAME_PDU_T *current = list->nodes[list->head];
        fwrite(&current->pdcp_sn, sizeof(uint32_t), 1, list->log_file);
        fwrite(&current->pdu_size, sizeof(uint32_t), 1, list->log_file);

        pthread_mutex_unlock(&list->lock);
    }
    return NULL;
}

int mac_list_init(struct mac_list **list) {
    *list = malloc(sizeof(struct mac_list));
    if (!*list) return 0;

    (*list)->nodes = calloc(MAX_FRAMES, sizeof(struct mac_list_node *));
    if (!(*list)->nodes) goto cleanup;

    (*list)->head = (*list)->tail = 0;
    (*list)->count = 0;

    pthread_mutex_init(&(*list)->lock, NULL);

    // Create a separate thread for logging to minimize impact on performance.
    pthread_t log_thread;
    if (pthread_create(&log_thread, NULL, &log_frame, *list) != 0) goto cleanup;

    return 1;

cleanup:
    if (*list) {
        mac_list_free(list);
        free(list);
    }
    return 0;
}

void mac_list_free(struct mac_list **list) {
    pthread_mutex_destroy(&(*list)->lock);

    int i;
    for (i = 0; i < MAX_FRAMES; ++i) {
        struct mac_list_node *node = (*list)->nodes[i];
        if (!node) continue;

        free(node);
    }
    free((*list)->nodes);
    free(*list);
}

void mac_list_add(struct mac_list *list, const MAC_FRAME_PDU_T *frame) {
    pthread_mutex_lock(&list->lock);

    int current = list->head;
    for (int i = 0; i < WINDOW_SIZE && current + i < MAX_FRAMES; ++i, ++current %= MAX_FRAMES) {
        if (!memcmp(&list->nodes[current]->frame.pdcp_sn, &frame->pdcp_sn, sizeof(uint32_t))) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    struct mac_list_node *new_node = mmap(NULL, PDU_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    memcpy(new_node, frame, PDU_SIZE);
    list->nodes[current] = new_node;
    ++list->count;

    pthread_mutex_unlock(&list->lock);
}

void mac_list_close_log(struct mac_list *list) {
    if (list->log_file) {
        fclose(list->log_file);
        list->log_file = NULL;
    }
}
```

