    if (!new_node) return NULL;

    new_node->connection_id = connection_id;
    new_node->source_ip = source_ip;
    new_node->destination_ip = destination_ip;
    new_node->tcp_flags = tcp_flags;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->mutex, NULL);

    return new_node;
}

void add_record(TCP_CONNECTION_RECORD *record) {
    pthread_mutex_lock(&list_mutex);

    if (!head) {
        head = record;
        tail = record;
    } else {
        tail->next = record;
        tail = record;
    }

    pthread_mutex_unlock(&list_mutex);
}

TCP_CONNECTION_RECORD* find_record(uint32_t connection_id) {
    TCP_CONNECTION_RECORD *current = head;
    while (current != NULL) {
        if (current->connection_id == connection_id) return current;
        current = current->next;
    }
    return NULL;
}

void cleanup() {
    // Implement a background cleanup or periodic garbage collection mechanism here.
}

// Assuming you have an external data source that provides connection information as arguments to this function.
void handle_external_data(uint32_t connection_id, struct in_addr source_ip, struct in_addr destination_ip, uint16_t tcp_flags) {
    TCP_CONNECTION_RECORD *existing_record = find_record(connection_id);
    if (existing_record) {
        // Update the existing record if it already exists.
        pthread_mutex_lock(&existing_record->mutex);
        existing_record->tcp_flags = tcp_flags;
        pthread_mutex_unlock(&existing_record->mutex);
    } else {
        TCP_CONNECTION_RECORD *new_record = create_record(connection_id, source_ip, destination_ip, tcp_flags);
        if (new_record) add_record(new_record);
    }

    log_connection(&find_record(connection_id)->next ? find_record(connection_id)->next : head);
}
