    CRCI_FAILURE_NEGATIVE_INPUT,
    CRCI_FAILURE_MEMORY_ALLOCATION,
    CRCI_FAILURE_DATA_RETREVAL,
} CRCI_STATUS;

CRCI_STATUS create_crc_indications(int N, FILE* log_file, uint32_t seed) {
    int i;
    NFAPI_CRC_INDICATION_PDU_T *indications;
    uint32_t ue_information, rnti;
    CRCI_STATUS status = CRCI_SUCCESS;

    if (N <= 0) {
        status = CRCI_FAILURE_NEGATIVE_INPUT;
        fprintf(log_file, "Error: Invalid input value for N. Value was %d\n", N);
        return status;
    }

    // Seed the random number generator
    srand(seed != 0 ? seed : time(NULL));

    indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        status = CRCI_FAILURE_MEMORY_ALLOCATION;
        fprintf(log_file, "Error: Failed to allocate memory for %d indications.\n", N);
        return status;
    }

    int successful_structures = 0;

    // Loop through user-provided number of structures
    for (i = 0; i < N && status == CRCI_SUCCESS; ++i) {
        if (get_ue_information(log_file, &ue_information)) {
            fprintf(log_file, "Error: Failed to retrieve UE information for structure %d.\n", i + 1);
            status = CRCI_FAILURE_DATA_RETREVAL;
            continue;
        }

        if (get_rnti(log_file, &rnti)) {
            fprintf(log_file, "Error: Failed to retrieve RNTI for structure %d.\n", i + 1);
            status = CRCI_FAILURE_DATA_RETREVAL;
            continue;
        }

        indications[i].RX_UE_INFORMATION_TAG = ue_information;
        indications[i].RNTI = rnti;
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (uint32_t)(rand() | (RAND_MAX >> 1));

        successful_structures++;
    }

    if (status == CRCI_SUCCESS) {
        fprintf(log_file, "Successfully created %d indications.\n", successful_structures);
    }

    free(indications);
    return status;
}
