    MOBILE_IDENTITY mobile_identity;
} LTE_MME_MESSAGE_T;

// Function to initialize a dynamic array of LTE_MME_MESSAGE_T structures
LTE_MME_MESSAGE_T* init_attach_requests(size_t num_requests) {
    LTE_MME_MESSAGE_T *reqs = malloc(num_requests * sizeof(LTE_MME_MESSAGE_T));
    if (!reqs) {
        log_attach_request("Failed to allocate memory for requests\n");
        return NULL;
    }

    // Allocate and initialize NAS_MESSAGE structures
    size_t alloc_size = num_requests * sizeof(NAS_MESSAGE);
    NAS_MESSAGE *nas_msgs = malloc(alloc_size);
    if (!nas_msgs) {
        free(reqs);
        log_attach_request("Failed to allocate memory for NAS messages\n");
        return NULL;
    }

    memset(nas_msgs, 0, alloc_size);

    // Allocate and initialize MOBILE_IDENTITY structures
    size_t identity_alloc_size = num_requests * sizeof(MOBILE_IDENTITY);
    MOBILE_IDENTITY *identities = malloc(identity_alloc_size);
    if (!identities) {
        free(nas_msgs);
        free(reqs);
        log_attach_request("Failed to allocate memory for identities\n");
        return NULL;
    }

    memset(identities, 0, identity_alloc_size);

    // Assign NAS_MESSAGE and MOBILE_IDENTITY structures to LTE_MME_MESSAGE_T structures
    size_t i;
    for (i = 0; i < num_requests; ++i) {
        reqs[i].nas_message = nas_msgs[i];
        reqs[i].mobile_identity = identities[i];
    }

    // Log the number of successful allocations and return the request array
    log_attach_request("Successfully allocated memory for %zu requests\n", num_requests);

    // Map a region of memory for logging (minimal impact on main processing loop)
    void *log_map = mmap(NULL, sizeof(char), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (log_map == MAP_FAILED) {
        log_attach_request("Failed to map memory for logging\n");
    } else {
        char *log = static_cast<char*>(log_map);
        // Log details about the allocation, including performance metrics and other relevant information
        sprintf(log, "Allocated %zu requests successfully\n", num_requests);
    }

    return reqs;
}
