static LIST_T head = NULL;

void list_insert(NFAPI_CRC_INDICATION_PDU_T new_data) {
    LIST_T new_node = (LIST_T) malloc(sizeof(struct list));
    if (!new_node) {
        log_event("Memory allocation failure");
        return;
