    new_node->data = new_data;
    new_node->next = head;
    head = new_node;

    if (head == head->next && M > 1) { // Resize list if necessary
        LIST_T current = head;
        while (current->next != head && M > 1) {
            LIST_T temp = current->next;
            current->next = temp->next;
            free(temp);
            --M;
        }
    }
}

