['```c
#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <stdlib.h>

typedef struct PacketHeader {
    in_addr_t src_ip;
    in_addr_t dest_ip;
    uint16_t protocol;
    uint32_t seq_num;
    bool priority;
    pthread_mutex_t lock;
} PacketHeader;

typedef struct DynArray {
    size_t capacity;
    size_t size;
    PacketHeader** data;
    pthread_mutex_t mutex;
} DynArray;

void dyn_array_init(DynArray* array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->data = malloc(initial_capacity * sizeof(PacketHeader*));
    array->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void dyn_array_push(DynArray* array, const PacketHeader* packet) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PacketHeader** tmp = realloc(array->data, new_capacity * sizeof(PacketHeader*));
        if (!tmp) {
            perror("realloc failed");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->data = tmp;
        array->capacity = new_capacity;
    }
    array->data[array->size] = malloc(sizeof(PacketHeader));
    if (!array->data[array->size]) {
        perror("malloc failed");
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    memcpy(array->data[array->size], packet, sizeof(PacketHeader));
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void dyn_array_pop(DynArray* array) {
    if (array->size > 0) {
        pthread_mutex_lock(&array->mutex);
        PacketHeader* packet = array->data[array->size - 1];
        free(packet);
        array->size--;
        pthread_mutex_unlock(&array->mutex);
    }
}

PacketHeader* dyn_array_get(const DynArray* array, size_t index) {
    if (index >= array->size) return NULL;
    pthread_mutex_lock(&array->mutex);
    PacketHeader* packet = array->data[index];
    pthread_mutex_unlock(&array->mutex);
    return packet;
}

void dyn_array_iterate(const DynArray* array, void (*func)(PacketHeader*)) {
    if (array->size > 0) {
        pthread_mutex_lock(&array->mutex);
        for (size_t i = 0; i < array->size; ++i) {
            PacketHeader* packet = array->data[i];
            (*func)(packet);
        }
        pthread_mutex_unlock(&array->mutex);
    }
}
```

