static uint32_t next_rnti = 1;

NFAPI_CRC_INDICATION_PDU_T* create_pdu(size_t N) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("malloc");
        return NULL;
    }

    pthread_mutex_lock(&rnti_mutex);

    for (size_t i = 0; i < N; ++i) {
        uint32_t rnti = next_rnti++;
        while (find_pdu_with_rnti(pdus, rnti)) {
            rnti = next_rnti++;
        }

        pdus[i].rx_ue_info.tag = RX_UE_INFORMATION_TAG_INITIALIZER;
        pdus[i].rnti = rnti;
        pdus[i].crc_indication.tag = CRC_INDICATION_REL8_TAG_INITIALIZER;
        pdus[i].crc_indication.crcflag = (rand() % 2);
    }

    pthread_mutex_unlock(&rnti_mutex);

    return pdus;
}

