['```csharp
using System;
using System.Collections.Generic;
using System.Runtime.Serialization.Formatters.Binary;
using System.IO;
using System.Threading;
using System.Diagnostics;

public class FSAState
{
    public int StateId { get; set; }
    public Dictionary<int, List<ActionDelegate>> Transitions { get; set; }
}

public delegate void ActionDelegate(FSAState currentState);

public class FSAMachine
{
    private FSAState[] _states;
    private FSAState _currentState;
    private int _numStates;
    private Dictionary<int, FSAState> _stateDict;
    private ActionDelegate _actionCallback;
    private int _lastState;

    public FSAMachine(ActionDelegate actionCallback, int[] states, int numStates, FSAState startState)
    {
        _states = states;
        _numStates = numStates;
        _stateDict = new Dictionary<int, FSAState>();
        _actionCallback = actionCallback;
        _lastState = Array.LastIndexOf(states, startState);

        InitializeFSA();
    }

    private void InitializeFSA()
    {
        for (int i = 0; i < _numStates; i++)
        {
            FSAState state = new FSAState { StateId = _states[i] };
            _stateDict.Add(_states[i], state);
        }

        LoadStateTransitions();
        SetCurrentState(_lastState);
    }

    private void LoadStateTransitions()
    {
        BinaryFormatter formatter = new BinaryFormatter();
        FileStream stream;

        try
        {
            stream = new FileStream("state_transitions.bin", FileMode.Open);

            _currentState.Transitions = (Dictionary<int, List<ActionDelegate>>)formatter.Deserialize(stream);

            foreach (var state in _states)
            {
                if (_currentState.Transitions.ContainsKey(state))
                    continue;

                stream.Position = stream.Length - GetBytesNeededForState(state);
                var stateData = formatter.Deserialize(stream) as FSAState;
                _stateDict[state] = stateData;
                _currentState.Transitions[state] = new List<ActionDelegate>();
            }
        }
        catch (Exception ex)
        {
            Debug.WriteLine($"Error loading state transitions: {ex.Message}");
        }
    }

    private int GetBytesNeededForState(int stateId) => _stateDict[stateId].Transitions.Count * sizeof(ActionDelegate);

    public void SetCurrentState(int newStateIndex)
    {
        if (newStateIndex < 0 || newStateIndex >= _numStates)
            throw new ArgumentOutOfRangeException(nameof(newStateIndex), "Invalid state index.");

        _currentState = _stateDict[newStateIndex];

        ExecuteActionsOnTransition();
    }

    private void ExecuteActionsOnTransition()
    {
        if (_currentState.Transitions[_currentState.StateId].Count > 0)
            _actionCallback(_currentState);
    }
}
```

