import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.ClassNotFoundException;
import java.util.concurrent.atomic.AtomicInteger;
import java.text.SimpleDateFormat;
import java.time.Duration;
import java.time.Instant;

public class SerializationUtils {
    private static final AtomicInteger DESERIALIZED_COUNTER = new AtomicInteger();
    private static final SimpleDateFormat DATE_FORMAT = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    private static final long SERIALIZATION_PERIOD_MS = 60000L; // 1 minute in milliseconds

    public static <T> T deserializeObjectFromByteArray(byte[] data, Class<T> clazz) throws RuntimeException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            return clazz.getDeclaredConstructor().newInstance(ois.readObject());
        } catch (InstantiationException | IllegalAccessException | ClassNotFoundException e) {
            throw new RuntimeException("Error during deserialization: " + e.getMessage(), e);
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error during deserialization: " + e.getMessage(), e);
        }
    }

    public static void trackDeserializedObject() {
        Instant currentTime = Instant.now();
        if (System.currentTimeMillis() - DESERIALIZED_COUNTER.get() > SERIALIZATION_PERIOD_MS) {
            System.out.println("Number of objects deserialized between " + DATE_FORMAT.format(DATE_FORMAT.toLocalizedPattern()) + ": " + DESERIALIZED_COUNTER.get());
            DESERIALIZED_COUNTER.set(0);
        }
        DESERIALIZED_COUNTER.incrementAndGet();
    }

    public static class ClassNotFoundException extends Exception {
        private static final long serialVersionUID = 1L;

        public ClassNotFoundException(String message) {
            super(message);
        }
    }
}
