use reqwest::{Client, Config};
use std::time::Duration;
use std::sync::Arc;

pub struct HttpClient {
    client: Arc<reqwest::Client>,
}

impl HttpClient {
    pub fn new(disable_cert_validation: bool) -> Self {
        let config = Config::new()
            .user_agent("MyApp/1.0")
            .timeout_connector(Duration::from_secs(5))
            .timeout_request(Duration::from_secs(10))
            .merge(if disable_cert_validation {
                Config::default()
                    .dangerously_disable_http2()
                    .dangerously_disable_tls_roots()
            } else {
                Config::default()
            });
        HttpClient { client: Arc::new(Client::builder().config(config).build().unwrap()) }
    }

    pub async fn request_builder(&self, url: &str) -> reqwest::Result<reqwest::client::RequestBuilder> {
        let mut rb = self.client.request(url);
        if self.client.is_dangerous_configuration() {
            eprintln!("WARNING: Certificate validation is disabled for this request!");
        }
        Ok(rb)
    }

    pub async fn rate_limited_request<T>(&self, url: &str, retry_count: u32, interval: Duration) -> reqwest::Result<T> {
        let mut count = 0;
        loop {
            match self.request_builder(url).send().await? {
                Ok(res) => {
                    if count > 0 {
                        eprintln!("Request succeeded after {} retries", count);
                    }
                    res.json::<T>().await
                },
                Err(_e) => {
                    if count < retry_count - 1 {
                        eprintln!("Request failed, retrying in {}", interval.as_secs() as u32,);
                        std::thread::sleep(interval);
                        count += 1;
                        continue;
                    } else {
                        eprintln!("Maximum number of retries reached for URL '{}'", url);
                        return Err(_e)
                    }
                }
            }
        }
    }
}
