    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

struct log_entry {
    time_t timestamp;
    enum LOG_TYPE { CREATE, ERROR } type;
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
    char message[256];
};

FILE *log_file;

void log(struct log_entry entry) {
    fwrite(&entry, sizeof(struct log_entry), 1, log_file);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(uint32_t rx_ue_information_tag, uint16_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) {
        log((struct log_entry){ .timestamp = time(NULL), .type = ERROR, .rx_ue_information_tag = rx_ue_information_tag, .rnti = rnti, .crc_indication_rel8_tag = 0, .message = "Out of memory" });
        return NULL;
    }

    node->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
    node->RNTI = rnti;

    // Generate a CRCINDICATIONREL8TAG with a randomly set CRCFLAG based on a predefined probability threshold.
    uint16_t crc_indication_rel8_tag = (rand() % 100) < PROBABILITY_THRESHOLD ? (uint16_t)(-1) : rand();
    node->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;
    node->CRCFLAG = (node->CRC_INDICATION_REL8_TAG == -1);

    node->next = NULL;

    return node;
}

void push_back(NFAPI_CRC_INDICATION_PDU_T **head, NFAPI_CRC_INDICATION_PDU_T *node) {
    node->next = *head;
    *head = node;
}

// Implement a thread-safe version of the given function.
void create_linked_list(NFAPI_CRC_INDICATION_PDU_T **head, uint32_t n, uint16_t start_rnti) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T *tail = NULL, **current = head;

    for (uint32_t i = 0; i < n; ++i) {
