            current = &tail->next;

            NFAPI_CRC_INDICATION_PDU_T *node = create_node(i, start_rnti + i);
            if (node) {
                tail->next = node;
                tail = node;
            }
        }

        pthread_mutex_unlock(&mutex);
    }
}

