    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_tag;
    bool crcflag;
    struct _node* next;
} Node;

typedef enum {
    SUCCESS,
    MEMORY_ALLOCATION_ERROR,
    MAXIMUM_SIZE_REACHED,
    RNTI_CONSECUTIVE_ERROR,
    NETWORK_TIMEOUT,
    SERIALIZATION_DESERIALIZATION_ERROR,
    UNKNOWN_ERROR
} Status;

Status create_list(Node*** head, size_t max_size) {
    *head = NULL;
    size_t count = 0;
    Node* current = NULL;

    // Allocate a new node and assign the RNTI with a random value
    // If the allocation fails or the RNTI is the same as the previous node's RNTI, free the memory and return an error code
    for (;;) {
        Node* new_node = malloc(sizeof(Node));
        if (!new_node) {
            return MEMORY_ALLOCATION_ERROR;
        }

        new_node->rnti = (RNTI)rand();
        if ((*head != NULL) && (new_node->rnti == (*head)->rnti)) {
            free(new_node);
            return RNTI_CONSECUTIVE_ERROR;
        }

        // Assign the other fields and link the new node to the head or update the current pointer if no head exists
        new_node->crc_indication_tag = (CRC_INDICATION_REL8_TAG){ .crcflag = rand() % 2 };
        new_node->next = NULL;
        if (*head == NULL) {
            *head = new_node;
            current = *head;
        } else {
            current->next = new_node;
            current = current->next;

            // Check if the maximum size limit is reached and return an error code if so
            if (++count >= max_size) {
                return MAXIMUM_SIZE_REACHED;
            }
        }
    }
}

void cleanup(Node** head) {
    Node* current = *head;
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
    *head = NULL;
}
