```java
import java.security.MessageDigest;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class MD5HashService {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final RateLimiter rateLimiter = RateLimiter.create(100);

    public String computeMD5(String input) {
        if (input == null) return "";

        Future<String> future = executor.submit(() -> {
            try {
                rateLimiter.take();
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
                StringBuilder result = new StringBuilder(2 * digest.length);
                for (byte b : digest) {
                    result.append(String.format("%02x", b & 0xff));
                }
                return result.toString();
            } catch (Exception e) {
                throw new RuntimeException("Error while computing MD5 hash", e);
            }
        });
        try {
            return future.get(1, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException("Error getting the result from the Future", e);
        }
    }
}
```

