2. Define the list structure and related functions:

```c
typedef struct _MAC_TRANSACTION_LIST {
    MAC_TRANSACTION_RECORD_T head; // Doubly linked list header
    MAC_TRANSACTION_RECORD_T tail;
    pthread_mutex_t lock; // Traditional locking mechanism (can be replaced with a lock-free approach if needed)
} MAC_TRANSACTION_LIST_T;

MAC_TRANSACTION_LIST_T mac_transaction_list;

void init_mac_transaction_list() {
    pthread_mutex_init(&mac_transaction_list.lock, NULL);
    mac_transaction_list.head.next = &mac_transaction_list.tail;
    mac_transaction_list.tail.prev = &mac_transaction_list.head;
}

MAC_TRANSACTION_RECORD_T* find_safe_position(uint32_t seq_counter) {
    MAC_TRANSACTION_RECORD_T *current = &mac_transaction_list.head;
    do {
        pthread_mutex_lock(&mac_transaction_list.lock);
        current = (current->seq_counter == seq_counter) ? current->next : current;
        pthread_mutex_unlock(&mac_transaction_list.lock);
    } while ((current != &mac_transaction_list.tail) && (current->seq_counter == current->next->seq_counter));
    return current;
}
```

3. Define the insert function, which validates the `TX_POWER_LEVEL` value and handles concurrent inserts:

```c
void insert(MAC_TRANSACTION_RECORD_T* record) {
