        // Handle the error here, e.g., log and return an error code
        return;
    }

    MAC_TRANSACTION_RECORD_T* safe_position = find_safe_position(record->seq_counter);
    if (safe_position->seq_counter == record->seq_counter) {
        // Handle the error here, e.g., log and return an error code
        return;
    }

    pthread_mutex_lock(&mac_transaction_list.lock);
    MAC_TRANSACTION_RECORD_T* new_node = malloc(sizeof(MAC_TRANSACTION_RECORD_T));
    if (!new_node) {
        // Handle the error here, e.g., log and return an error code
        pthread_mutex_unlock(&mac_transaction_list.lock);
        return;
    }

    memcpy(new_node, record, sizeof(MAC_TRANSACTION_RECORD_T));
    new_node->prev = safe_position;
    new_node->next = safe_position->next;
    safe_position->next->prev = new_node;
    safe_position->next = new_node;
    pthread_mutex_unlock(&mac_transaction_list.lock);
}
```

4. Define the delete function:

```c
void delete(MAC_TRANSACTION_RECORD_T* record) {
    MAC_TRANSACTION_RECORD_T* node = find_node(record->seq_counter);
    if (!node || !node->prev || !node->next) {
        // Handle the error here, e.g., log and return an error code
        return;
    }

    pthread_mutex_lock(&mac_transaction_list.lock);
    MAC_TRANSACTION_RECORD_T* prev = node->prev;
    MAC_TRANSACTION_RECORD_T* next = node->next;

    if (prev) {
        prev->next = next;
    } else {
        mac_transaction_list.head.next = next;
    }

    if (next) {
        next->prev = prev;
    } else {
        mac_transaction_list.tail.prev = prev;
    }

    free(node);
    pthread_mutex_unlock(&mac_transaction_list.lock);
}
