```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include <string.h>
#include <arpa/inet.h>

typedef struct LTEPHY_RXINFO_T {
    uint32_t RF_CHANNEL;
    uint64_t RX_TIMESTAMP;
    uint32_t CRC_FLAG;
    uint32_t PHY_STATS[16];
    uint32_t transaction_id;
    struct LTEPHY_RXINFO_T *prev, *next;
} LTEPHY_RXINFO;

void init_list(LTEPHY_RXINFO **head) {
    if (head == NULL) return;
    *head = NULL;
}

LTEPHY_RXINFO* create_node() {
    LTEPHY_RXINFO* node = malloc(sizeof(LTEPHY_RXINFO));
    if (!node) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memset(node, 0, sizeof(LTEPHY_RXINFO));
    return node;
}

void insert_node(LTEPHY_RXINFO **head, LTEPHY_RXINFO *new_node) {
    if (*head == NULL) {
        *head = new_node;
        return;
    }

    // Ensure the RF_CHANNEL is unique
    LTEPHY_RXINFO* current = *head;
    while (current != NULL) {
        if (current->RF_CHANNEL == new_node->RF_CHANNEL) {
            fprintf(stderr, "Warning: Duplicate RF_CHANNEL encountered\n");
            break;
        }
        current = current->next;
    }

    // Insert at the head of the list
    if (current == NULL) {
        new_node->next = *head;
        *head = new_node;
    } else {
        new_node->next = current->next;
        current->next = new_node;
        new_node->prev = current;
    }
}

void destroy_list(LTEPHY_RXINFO **head) {
    if (*head == NULL) return;

    LTEPHY_RXINFO *current = *head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current);
        current = temp;
    }
    *head = NULL;
}

uint32_t crc32(const uint8_t *buf, size_t len) {
    uint32_t crc = ~0U;
    while (len--) {
        crc = crc32_update(crc, *(buf++));
    }
    return ~crc;
}

void add_entry(LTEPHY_RXINFO **head, const uint32_t rf_channel, const uint64_t rx_timestamp) {
    LTEPHY_RXINFO* new_node = create_node();
    new_node->RF_CHANNEL = rf_channel;
    new_node->RX_TIMESTAMP = rx_timestamp;
    new_node->CRC_FLAG = crc32((const uint8_t *)&new_node, sizeof(LTEPHY_RXINFO) - sizeof(new_node->CRC_FLAG));
    insert_node(head, new_node);
}
```

