    const char *output_file = "output.bin";
    bool help = false;
    int buffer_size = MAX_BUFF_SIZE;
    int max_retries = MAX_RETRIES;
    int opt;

    while ((opt = getopt(argc, argv, "h:c:o:")) != -1) {
        switch (opt) {
            case 'h':
