                break;
            case 'c':
                buffer_size = atoi(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
            default:
                help = false;
        }
    }

    if (help) {
        printf("Usage: %s [-h] [-c buffer_size] [-o output_file]\n", argv[0]);
        return 0;
    }

    if (argc - optind != 1) {
        fprintf(stderr, "Error: An input file must be provided.\n");
        return 1;
    }

    input_file = fopen(argv[optind], "r");
    if (!input_file) {
        perror("Error opening the file.");
        return 2;
    }

    NFAPI_CRC_INDICATION_PDU_T *data = malloc(buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    uint64_t data_count = 0;

    char line[MAX_LINE_LEN];
    while (fgets(line, MAX_LINE_LEN, input_file)) {
        if (data_count + 1 >= buffer_size) {
            buffer_size += MAX_BUFF_SIZE;
            data = realloc(data, buffer_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
