        sscanf(line, "%hhu %u %llx %c", &data[data_count].rxi_information_tag, &data[data_count].rnti, &data[data_count].crc_indication_tag.rnti, &data[data_count].crc_indication_tag.crcflag);
        if (feof(input_file)) {
            break;
        } else if (sscanf(line, "%*s") == 1) {
            fprintf(stderr, "Malformed input line.\n");
            return 3;
        }

        data_count++;
    }

    fclose(input_file);

    FILE *output_stream = fopen(output_file, "wb");
    if (!output_stream) {
        perror("Error opening the output file.");
        return 4;
    }

    for (uint64_t i = 0; i < data_count; ++i) {
        fwrite(&data[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, output_stream);
    }

    free(data);
    fclose(output_stream);

    return 0;
}
