import threading
import logging
import configparser
import math
import time
from collections import deque
from typing import Callable, Tuple, Dict, Union

class Cache:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self.cache = deque(maxlen=max_size)

    def add(self, item):
        self.cache.append(item)

    def get(self) -> Union[int, float, str]:
        return self.cache[-1] if self.cache else None

class DynamicValueGenerator:
    def __init__(self, config_file: str, tolerance: float = 0.01, seed: int = None):
        self.config = configparser.ConfigParser()
        self.config.read(config_file)
        self._generate_functions = {}
        self.tolerance = tolerance
        self.seed = seed or int(time.time())
        self.cache = {k: Cache(max_size=1000) for k in self._generate_functions.keys()}
        self.lock = threading.Lock()
        self.logger = logging.getLogger(__name__)

    def load_config(self):
        sections = self.config.sections()
        for section in sections:
            items = [(k, v) for k, v in self.config.items(section)]
            if section not in self._generate_functions:
                continue
            generator_function = self._generate_functions[section]
            try:
                start, end = map(float, items[1].split("-"))
                self._configure_generator(section, start, end)
            except ValueError:
                raise ValueError(f"Invalid range configuration for section {section}")

    def _configure_generator(self, section: str, start: float, end: float, inclusive: bool = True):
        if not (start <= end):
            raise ValueError("Start value should be smaller than end value.")
        self._generate_functions[section] = lambda: self._get_value(section, start, end, inclusive)

    def _get_value(self, section: str, start: float, end: float, inclusive: bool) -> Union[int, float, str]:
        if inclusive:
            step = 1.0
        else:
            step = 2.0
        value = start + (end - start) * math.random()
        if abs(value - self.cache[section].get()) > self.tolerance:
            self.cache[section].add(value)
        return self.cache[section].get()

    def generate_value(self, section: str) -> Union[int, float, str]:
        try:
            return self._generate_functions[section]()
        except KeyError as e:
            raise ValueError(f"Invalid generator section specified: {e.args[0]}")

    def set_seed(self, seed: int):
        self.seed = seed

    def validate(self, target: Union[int, float, str], value: Union[int, float, str]) -> bool:
        tolerance = max(abs(target - value) / abs(target), self.tolerance)
        return tolerance < 1.0

    def log_value(self, level: int, value: Union[int, float, str]):
        if level > self.logger.level:
            return
        self.logger.log(level, f"Generated value: {value}")

    @staticmethod
    def _create_generator_functions():
        """
        Define the base generate functions for different types
        Replace the type annotations with the appropriate ones based on your data types
        """
        integer_generator = lambda start, end: range(int(start), int(end) + 1)
        float_generator = lambda start, end: (start + x / 100 for x in range(0, (end - start + 1) * 100))
        string_generator = lambda start, end: (f"{start + i}" for i in range(int(start), int(end) + 1))

        return {
            "integer": (integer_generator, {"start": 0, "end": 10}),
            "float": (float_generator, {"start": 0.0, "end": 10.0}),
            "string": (string_generator, {"start": "A", "end": "Z"})
        }

    @classmethod
    def create(cls, config_file: str, **kwargs) -> 'DynamicValueGenerator':
        cls._generate_functions = {k: v[0] for k, v in cls._create_generator_functions().items()}
        generator = cls(config_file, **kwargs)
        generator.load_config()
        return generator
