import java.util.Arrays;
import java.util.concurrent.*;
import java.util.Random;
import java.util.stream.IntStream;

class DisjointUnionFind {
    private final int[] parent;
    private final int[] rank;

    public DisjointUnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        Arrays.setAll(parent, i -> i);
        Arrays.fill(rank, 1);
    }

    public int find(int x) {
        while (x != parent[x]) {
            x = parent[x];
            parent[x] = root(x); // Path Compression
        }
        return x;
    }

    private int root(int x) {
        while (parent[x] != x) {
            x = parent[x];
            parent[x] = root(parent[x]); // Path Compression and Union by Rank
        }
        return x;
    }

    public void union(int x, int y) {
        int rootX = root(x);
        int rootY = root(y);
        if (rootX == rootY) return;

        // Union by Rank Optimization
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
            rank[rootY] += Math.min(rank[rootX], rank[rootY]);
        } else {
            parent[rootY] = rootX;
            rank[rootX] += Math.min(rank[rootX], rank[rootY]);
        }
    }
}

