void free_list(struct list *list) {
    if (list == NULL || list->size == 0) return;

    free(list->data);
    sem_destroy(&list->lock);
}

struct list *create_list() {
    struct list *list = mmap(NULL, sizeof(struct list), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    sem_init(&list->lock, 0, 1);
    list->size = 0;
    list->data = NULL;

    return list;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_element() {
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    memset(element, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    element->crcflag = <seed value for CRCFLAG>;

    return element;
}

void append_to_list(struct list *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    sem_wait(&list->lock);

    if (list->size == MAX_LIST_SIZE) {
        printf("Error: List size exceeded the maximum limit.\n");
        free(element);
        sem_post(&list->lock);
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T *tmp = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tmp) {
        perror("realloc");
        free_list(list);
        sem_post(&list->lock);
        exit(EXIT_FAILURE);
    }

    list->data = tmp;
    list->size++;
    list->data[list->size - 1] = *element;

    sem_post(&list->lock);
}

int main(int argc, char **argv) {
    int max_list_size = MAX_LIST_SIZE;
    struct list *list = create_list();

