    bool CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

struct list {
    Node* head;
    Node* tail;
    size_t size;
    void *mem_region;
};

void init_list(struct list *list, size_t capacity) {
    // Mmap anonymously to shared memory
    list->mem_region = mmap(NULL, sizeof(Node)*capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (list->mem_region == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    Node *nodes = list->mem_region;

    for (size_t i = 0; i < capacity; ++i) {
        nodes[i].next = &nodes[(i+1)%capacity];
        pthread_mutex_init(&nodes[i].lock, NULL);
        nodes[i].data.RNTI = i + 1;
        nodes[i].data.CRCFLAG = rand() % 2;
    }

    list->head = &nodes[0];
    list->tail = &nodes[(capacity-1)%capacity];
    list->size = capacity;
}

void insert(struct list *list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    node->data = data;
    node->next = NULL;

    pthread_mutex_lock(&list->head->lock);

    if (list->tail->next == list->head) {
        list->tail->next = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->size++;
    }

    pthread_mutex_unlock(&list->head->lock);
}

Node* remove_old(struct list *list) {
    Node *node = NULL;
    time_t current_time = time(NULL);
    pthread_mutex_lock(&list->head->lock);

    for (Node *cur = list->head; cur != list->tail; cur = cur->next) {
        if ((current_time - cur->data.timestamp) > 10) {
            node = cur;
            break;
        }
    }

    if (node == NULL) {
        pthread_mutex_unlock(&list->head->lock);
        return NULL;
    }

    Node *prev = NULL;
    for (Node *cur = list->head; cur != node; cur = cur->next) {
        prev = cur;
    }

    if (prev == NULL) { // head removal
        list->head = node->next;
    } else {
        prev->next = node->next;
    }

    if (node == list->tail) {
        list->tail = prev;
    }

    pthread_mutex_unlock(&list->head->lock);

    return node;
}

void cleanup(struct list *list) {
    while (remove_old(list) != NULL);
}

