<?php

class ClinicUpdate {
    private $transactionId;
    private $db;
    private $externalService;
    private $logger;

    public function __construct(PDO $db, ExternalServiceInterface $externalService, LoggerInterface $logger) {
        $this->db = $db;
        $this->externalService = $externalService;
        $this->logger = $logger;
    }

    public function updateClinicStatus($clinicId, $status, $ipAddress): array {
        try {
            // Validate clinic ID with external service
            if (!$this->isValidClinicId($clinicId)) {
                return ['transaction_id' => null, 'message' => 'Invalid clinic ID'];
            }

            // Generate unique transaction ID
            $this->transactionId = uniqid();

            // Start a new transaction
            $this->db->beginTransaction();

            // Query to check if the row exists and update it with the given values
            $stmt = $this->db->prepare("UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified = NOW() WHERE id = :clinicId");
            $stmt->execute([':clinicId' => $clinicId, ':status' => $status, ':ipAddress' => $ipAddress]);

            // Commit the transaction if the update was successful
            if ($stmt->rowCount() == 1) {
                $this->db->commit();
                $this->logger->log('Successfully updated clinic ID ' . $clinicId . ' with transaction ID: ' . $this->transactionId);
                return ['transaction_id' => $this->transactionId, 'message' => 'Update successful'];
            } else {
                // Rollback the transaction and log the error if the row does not exist or an error occurred during the update
                $this->db->rollBack();
                $this->logger->log('Failed to update clinic ID ' . $clinicId . '. Transaction ID: ' . $this->transactionId);
                return ['transaction_id' => $this->transactionId, 'message' => 'Update failed'];
            }
        } catch (Exception $e) {
            // Rollback the transaction and log the error if an exception occurs
            $this->db->rollBack();
            $this->logger->log('Error updating clinic ID ' . $clinicId . '. Transaction ID: ' . $this->transactionId . '. Error: ' . $e->getMessage());
            return ['transaction_id' => $this->transactionId, 'message' => 'An error occurred'];
        }
    }

    private function isValidClinicId($clinicId) {
        // Call the external service to validate the clinic ID and handle temporary unavailability of the service
        if (!$this->externalService->isAvailable()) {
            $this->logger->log('Temporary unavailability of external service. Cannot validate clinic ID.');
            return false;
        }

        // Call the external service to check the validity of the clinic ID and handle its response appropriately
        return $this->externalService->isValidClinicId($clinicId);
    }
}
