#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Custom memory pool implementation
struct MemoryPool {
    void *data_pool;
    size_t data_size;
    size_t allocated;
};

void *memory_pool_alloc(struct MemoryPool *pool, size_t size) {
    if (pool->allocated + size > pool->data_size)
        return NULL; // No memory available, return error
    void *result = (char *)pool->data_pool + pool->allocated;
    pool->allocated += size;
    return result;
}

void memory_pool_free(struct MemoryPool *pool, void *ptr) {
    if (!ptr)
        return; // Invalid pointer, ignore
    pool->allocated -= (char *)ptr - (char *)pool->data_pool;
}

// NFAPI_CRC_INDICATION_PDU_T structure definition
typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
    unsigned char crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Node structure for the linked list
typedef struct _Node {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node *next;
} Node;

// LinkedList implementation
struct LinkedList {
    struct MemoryPool mem_pool;
    struct Node *head, *tail;
};

void linkedlist_initialize(struct LinkedList *list) {
    list->mem_pool.data_pool = malloc(1024); // Allocate initial memory pool of 1KB
    list->mem_pool.data_size = 1024;
    list->head = NULL;
    list->tail = NULL;
}

void *linkedlist_allocate_node(struct LinkedList *list) {
    Node *node = memory_pool_alloc(&list->mem_pool, sizeof(Node));
    if (!node)
        return NULL; // No memory available, return error
    memset(node, 0, sizeof(Node));
    return node;
}

void linkedlist_deallocate_node(struct LinkedList *list, Node *node) {
    memory_pool_free(&list->mem_pool, node);
}

// Implement thread-safe read and write operations using pthread mutexes
```

