int parse_csv(char* filename, cellular_event** events, size_t* num_events) {
    FILE *file = fopen(filename, "r");
    char line[4096];
    size_t i = 0;
    char **tokens;
    int error = 0;

    if (!file) {
        log(LOG_ERROR, "Error opening file: %s", filename);
        return -1;
    }

    while (fgets(line, sizeof(line), file)) {
        tokens = str_split(line, ',');

        if (tokens && tokens[0] && tokens[1] && tokens[2]) {
            cellular_event* event = malloc(sizeof(cellular_event));
            if (!event) {
                log(LOG_ERROR, "Out of memory");
                error = -1;
                break;
            }

            sscanf(tokens[0], "%d", &event->event_id);
            event->timestamp = strtotime(tokens[1]);
            event->event_type = strdup(tokens[2]);

            validate_event(event);

            if (!error) {
                events[i] = event;
                i++;
            } else {
                free(event->event_type);
                free(event);
            }
        }

        token_free(tokens);
    }

    fclose(file);
    *num_events = i;
    return error ? -1 : 0;
}

char** str_split(char* a_string, char delimiter) {
    size_t tokens_count = 0;
    size_t len = strlen(a_string);
    char *tokens[len];

    for (size_t i = 0; i < len; ++i) {
        if (a_string[i] == delimiter || i == len - 1) {
            tokens_count++;
        }
    }

    tokens[tokens_count] = NULL;

    size_t current_token_index = 0;
    char* token = strtok(a_string, &delimiter);

    while (token != NULL) {
        tokens[current_token_index++] = token;
        token = strtok(NULL, &delimiter);
    }

    return tokens;
}

void token_free(char** tokens) {
    for (size_t i = 0; tokens && tokens[i]; ++i) {
        free(tokens[i]);
    }
    free(tokens);
}

