#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ELEMENTS 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* create_pdu() {
    NFAPI_CRC_INDICATION_PDU *pdu = (NFAPI_CRC_INDICATION_PDU *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!pdu) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    pdu->RX_UE_INFORMATION_TAG = rand() % UINT32_MAX;
    pdu->RNTI = rand() % 65536;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 65536;
    pdu->CRCFLAG = (unsigned char)(rand() % 2);
    pdu->next = NULL;
    return pdu;
}

void check_tag(uint32_t tag) {
    if (tag > UINT32_MAX || tag < 1) {
        fprintf(stderr, "Invalid tag value: %d\n", tag);
    }
}

void manage_list(NFAPI_CRC_INDICATION_PDU **head, NFAPI_CRC_INDICATION_PDU **tail) {
    if (*head == NULL) {
        *head = create_pdu();
        if (!*head) return;
        *tail = *head;
    } else {
        check_tag((*tail)->RX_UE_INFORMATION_TAG);
        if ((*tail)->next == NULL && (*tail)->RX_UE_INFORMATION_TAG >= MAX_ELEMENTS) {
            NFAPI_CRC_INDICATION_PDU *new_pdu = create_pdu();
            if (!new_pdu) return;

            if (*head == *tail) { // only one element in the list
                *head = new_pdu;
            } else {
                (*tail)->next = new_pdu;
            }
            *tail = new_pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU* temp = create_pdu();
            if (!temp) return;

            check_tag((*tail)->RX_UE_INFORMATION_TAG);
            check_tag(temp->RX_UE_INFORMATION_TAG);

            if ((*tail)->RX_UE_INFORMATION_TAG >= MAX_ELEMENTS) {
                *temp = *(*tail);
                *tail = temp;
                (*tail)->next = NULL;
            } else {
                (*tail)->next = temp;
                *tail = temp;
            }
        }
    }
}

void log_info(const char* msg, ...) {
    va_list args;
    FILE *logfile = fopen("nfapi.log", "a");
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", msg);
        va_start(args, msg);
        vfprintf(logfile, msg, args);
        va_end(args);
        fclose(logfile);
    } else {
        fprintf(stderr, "Unable to open log file\n");
    }
}

void init() {
    srand(time(NULL));
    FILE *logfile = fopen("nfapi.log", "w");
    if (logfile != NULL) {
        fprintf(logfile, "Initializing application...\n");
        fclose(logfile);
    } else {
        fprintf(stderr, "Unable to open log file\n");
    }
}
