}

void print_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    printf("[Tag: 0x%" PRIx64 ", RNTI: 0x%" PRIx64 ", CRC Indication: 0x%" PRIx64 ", CRC Flag: %s]\n",
           pdu->tag, pdu->rnti, pdu->crc_indication.CRCFLAG, pdu->crc_indication.CRCFLAG ? "true" : "false");
}

void iterate_and_print(const NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list && list->count > 0) {
        pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
        for (size_t i = 0; i < list->capacity; ++i) {
            pthread_mutex_lock(&lock);
            if (list->pdus[i].crc_indication.CRCFLAG || hashmap_get(&list->tags, &list->pdus[i].tag)) {
                print_pdu(&list->pdus[i]);
            }
            pthread_mutex_unlock(&lock);
        }
    }
}

