    double totalThroughput = 0.0;

    for (int i = 0; i < count; ++i) {
        if (uniqueIDs[trafficFlows[i].flowID]) {
            fprintf(stderr, "Error: Duplicate flowID %d\n", trafficFlows[i].flowID);
            exit(1);
        }
        uniqueIDs[trafficFlows[i].flowID] = true;
        totalThroughput += trafficFlows[i].throughput;
    }

    if (totalThroughput > BANDWIDTH_LIMIT) {
        fprintf(stderr, "Error: Total throughput exceeds the bandwidth limit\n");
        exit(1);
    }
}

