typedef struct {
    time_t timestamp;
    enum NetworkEventType { CONNECT, DISCONNECT, ERROR } type;
    int session_id;
} NetworkEvent;

enum NetworkEventType {
    CONNECT = 0,
    DISCONNECT,
    ERROR
};

#define MAX_EVENTS 10000
#define EVENT_QUEUE_GROWTH 10000

struct EventQueue {
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

void validate_event(const NetworkEvent *event) {
    if (event->type < CONNECT || event->type > ERROR) {
        fprintf(stderr, "Invalid network event type: %d\n", event->type);
        exit(EXIT_FAILURE);
    }
}

void push_event(struct EventQueue *queue, const NetworkEvent *event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->count == queue->capacity) {
        queue->events = realloc(queue->events, queue->capacity + EVENT_QUEUE_GROWTH);
        queue->capacity += EVENT_QUEUE_GROWTH;
    }
    validate_event(event);
    memcpy(&queue->events[queue->count], event, sizeof(NetworkEvent));
    ++queue->count;
    pthread_mutex_unlock(&queue->mutex);
}

struct EventQueue *init_event_queue() {
    struct EventQueue *queue = malloc(sizeof(struct EventQueue));
    queue->events = malloc(MAX_EVENTS * sizeof(NetworkEvent));
    queue->capacity = MAX_EVENTS;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    return queue;
}
