    node->data.crcindicationrel8tag = rand() % MAX_CRCINDICATIONREL8TAG;
    node->data.crcflag = random_crcflag();
    append_log((struct log_msg){ .timestamp=time(NULL), .type=CREATE, .u.node=node });
    return node;
}

