    for (size_t i = 0; i < n; ++i) {
        const unsigned char rnti[8] = { i / 256, i % 256, (i / 128) % 256, (i % 128) % 256,
            ((i * i) / 65536) % 256, ((i * i * i) / 16777216) % 256,
            ((i * i * i * i) / 1073741824) % 256, ((i * i * i * i * i) / 18446744073709551615) % 256 };
        struct list_node* node = create_node(i, rnti);
        if (!node) continue; // Handle memory allocation errors gracefully

        pthread_mutex_lock(&(*head)->next->data.crcindicationrel8tag); // Lock the next CRCINDICATIONREL8TAG to avoid race conditions
        node->next = *head;
        (*head) = node;
        pthread_mutex_unlock(&(*head)->next->data.crcindicationrel8tag);
    }
}

void free_list(struct list_node** head) {
    struct list_node* temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        munmap(temp, sizeof(*temp));
    }
