#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// PacketHeader structure with timestamp, sourceIP, and destinationIP
typedef struct {
    time_t timestamp;
    char sourceIP[16];
    char destinationIP[16];
} PacketHeader;

// Global variables for dynamic array and mutex to ensure thread safety
PacketHeader *headers = NULL;
size_t capacity = 0, size = 0;
pthread_mutex_t mutex;

// Function to add a packet header
void add_header(const char *srcIP, const char *destIP) {
    pthread_mutex_lock(&mutex);

    if (size == capacity) { // Resize array if necessary
        capacity *= 2;
        PacketHeader *new_headers = realloc(headers, sizeof(PacketHeader) * capacity);
        if (!new_headers) {
            fprintf(stderr, "Error allocating memory\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        headers = new_headers;
    }

    // Create a new header with the given source and destination IPs, and the current timestamp
    PacketHeader *new_header = &headers[size];
    new_header->timestamp = time(NULL);
    strncpy(new_header->sourceIP, srcIP, sizeof(new_header->sourceIP) - 1);
    strncpy(new_header->destinationIP, destIP, sizeof(new_header->destinationIP) - 1);

    size++;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing packet header by IP addresses
void update_header(const char *srcIP, const char *destIP, time_t new_timestamp) {
    PacketHeader *header;
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < size; ++i) {
        header = &headers[i];
        if (strcmp(header->sourceIP, srcIP) == 0 && strcmp(header->destinationIP, destIP) == 0) {
            header->timestamp = new_timestamp;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

// Function to iterate through packet headers and print their metadata
void iterate_headers() {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < size; ++i) {
        printf("PacketHeader:\n");
        printf("\ttimestamp: %ld\n", headers[i].timestamp);
        printf("\tsourceIP: %s\n", headers[i].sourceIP);
        printf("\tdestinationIP: %s\n", headers[i].destinationIP);
    }
    pthread_mutex_unlock(&mutex);
}

// Initialize mutex for thread safety
void init() {
    pthread_mutex_init(&mutex, NULL);
}

// Free memory used by the dynamic array when the program terminates
void cleanup() {
    free(headers);
    pthread_mutex_destroy(&mutex);
}
