}

void manage_list(NFAPI_CRC_LIST_T* list, char* file_path) {
    pthread_mutex_init(&list->mutex, NULL);

    NFAPI_CRCI_INDICATION_PDU_T* new_pdu = read_file(file_path, &new_pdu);
    if (!new_pdu) return;

    while (list->length >= list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, sizeof(NFAPI_CRCI_INDICATION_PDU_T) * list->capacity);
    }

    pthread_mutex_lock(&list->mutex);
    list->data[list->length++] = new_pdu;
    pthread_mutex_unlock(&list->mutex);
}

void free_list(NFAPI_CRCI_INDICATION_PDU_T* data, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        free(data + i);
    }
    free(data);
}
