int allocate_array(size_t* size, size_t N, size_t initial_size) {
    void** ptr = malloc(initial_size);
    if (!ptr || !N) return -1; // Handle invalid inputs

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    *size = (size_t)aligned_alloc(64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*size || !ptr) { // Handle out-of-memory conditions
        free(ptr);
        return -1;
    }

    size_t attempts = 0;
    while (*size < N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        ++attempts;
        if (attempts >= 10) return -2; // Prevent infinite reallocation loops
        size_t old_size = *size;
        *size = posix_memalign(NULL, 64, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*size) {
            free(ptr); // Free old memory and reallocate new memory
            ptr = malloc(*size / sizeof(void*));
            if (!ptr) return -2; // Handle out-of-memory conditions during reallocation
        } else {
            *size = old_size; // Revert to previous allocation size
        }
    }

    pthread_mutex_lock(&mutex);
    memset(*(NFAPI_CRC_INDICATION_PDU_T*)ptr, 0, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = *(NFAPI_CRC_INDICATION_PDU_T*)(ptr + i);
        pdu->rnti.value = custom_rand(time(NULL)); // Custom random number generator for CRCFLAG
        pdu->crcflag = pdu->crc_indication_rel8_tag.value = 0; // Initializing other fields
    }
    pthread_mutex_unlock(&mutex);

    mcheck_register(*(void**)ptr, N * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Memory monitoring for diagnosis and optimization

    return (int)ptr - (int)ptr;
}
