struct ChannelQualityIndication {
    int signalStrength;
    float channelUtilizationPercentage;
};

struct FrameStatistics {
    std::atomic<uint64_t> id;
    std::chrono::system_clock::time_point timestamp;
    std::vector<ChannelQualityIndication> cqiVector;
};

class FrameStatisticsList {
public:
    FrameStatisticsList(std::chrono::seconds retentionPolicySeconds)
        : m_retentionPolicySeconds(retentionPolicySeconds), m_mutex() {}

    FrameStatistics* append(const FrameStatistics& frameStats);

private:
    std::deque<FrameStatistics> m_frameStatisticsDeque;
    std::chrono::seconds m_retentionPolicySeconds;
    mutable std::mutex m_mutex;
};

FrameStatistics* FrameStatisticsList::append(const FrameStatistics& frameStats) {
    // Acquire lock to ensure thread safety during appending
    std::unique_lock<std::mutex> lock(m_mutex);

    auto now = std::chrono::system_clock::now();
    FrameStatistics* newFrameStat = new FrameStatistics{frameStats.id, now, frameStats.cqiVector};

    // Append to the deque and clean up old entries if needed
    m_frameStatisticsDeque.push_back(*newFrameStat);
    auto it = m_frameStatisticsDeque.begin();
    while (it != m_frameStatisticsDeque.end() && std::chrono::duration_cast<std::chrono::seconds>(now - it->timestamp).count() > m_retentionPolicySeconds.count()) {
        FrameStatistics* toErase = &*it;
        delete toErase;
        it = m_frameStatisticsDeque.erase(it);
    }

    return newFrameStat;
}
```

This code provides a thread-safe linked list of `FrameStatistics` structures, ensuring proper memory management and handling potential failures. The retention policy is defined by a `std::chrono::seconds` variable in the constructor, and entries older than this policy are periodically cleaned up during appending. The function `append()` takes a `FrameStatistics` object as input and returns a pointer to the newly created entry, providing a clear interface for integrating into other parts of the application.']

