#include <functional>
#include <iostream>
#include <memory>
#include <mutex>
#include <queue>
#include <stdexcept>
#include <sys/mman.h>
#include <thread>

struct NetworkPacket {
    std::atomic<uint64_t> id;
    time_t timestamp;
    uint32_t payloadSize;
    std::string sourceIP;
    std::string destinationIP;
};

class CircularBuffer {
public:
    CircularBuffer(std::size_t capacity, const std::string& filename)
        : buffer_(nullptr), size_(0), capacity_(capacity), file_(filename) {}

    ~CircularBuffer() { unmap(); }

    void append(const NetworkPacket& packet) {
        if (append_(packet)) {
            notifyReaders();
        }
    }

    std::optional<NetworkPacket> tryPop() {
        auto opt = pop_();
        if (opt) {
            notifyWriters();
        }
        return opt;
    }

private:
    bool append_(const NetworkPacket& packet);
    std::unique_ptr<NetworkPacket> pop_();
    void unmap();
    void notifyReaders() const;
    void notifyWriters() const;

    std::queue<std::unique_ptr<NetworkPacket>> buffer_;
    mutable std::mutex dataMutex_;
    const std::size_t size_, capacity_;
    std::string file_;
    void* mapAddr_;
    std::condition_variable readersCond_, writersCond_;
};

bool CircularBuffer::append_(const NetworkPacket& packet) {
    if (buffer_.size() >= capacity_) {
        return false; // Buffer is full, cannot append.
    }
    std::unique_ptr<NetworkPacket> newEntry(new NetworkPacket);
    *newEntry = packet;

    // Lock the data mutex to ensure atomicity when adding an item to the buffer.
    std::lock_guard<std::mutex> lock(dataMutex_);

    buffer_.push_back(std::move(newEntry));
    size_++;

    return true;
}

std::unique_ptr<NetworkPacket> CircularBuffer::pop_() {
    if (buffer_.empty()) {
        return {}; // Buffer is empty, cannot pop.
    }

    auto opt = buffer_.front();
    buffer_.pop_front();
    size_--;

    return std::move(opt);
}

void CircularBuffer::unmap() {
    if (mapAddr_) {
        munmap(mapAddr_, capacity_ * sizeof(NetworkPacket));
        mapAddr_ = nullptr;
    }
}

void CircularBuffer::notifyReaders() const {
    std::lock_guard<std::mutex> lock(writersMutex_);
    writersCond_.notify_all();
}

void CircularBuffer::notifyWriters() const {
    std::lock_guard<std::mutex> lock(readersMutex_);
    readersCond_.notify_all();
}

