#define MAX_TEMPORARY_POOL_SIZE 1024
pthread_mutex_t temporary_pool_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* temporary_pool = NULL;
size_t temporary_pool_count = 0;
size_t temporary_pool_capacity = MAX_TEMPORARY_POOL_SIZE;

pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T** primary_allocation = NULL;
size_t allocated_count = 0;
size_t allocated_capacity = 0;
size_t temporary_pool_usage = 0;

enum { NO_ERROR, MEMORY_ALLOCATION_FAILURE, INSUFFICIENT_TEMPORARY_POOL_SPACE };

void initialize_memory(size_t capacity) {
    pthread_mutex_lock(&memory_mutex);
    if (primary_allocation != NULL) free(primary_allocation);
    primary_allocation = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    allocated_count = 0;
    allocated_capacity = capacity;
    pthread_mutex_unlock(&memory_mutex);
}

void reset_temporary_pool() {
    if (temporary_pool == NULL) return;
    pthread_mutex_lock(&temporary_pool_mutex);
    for (size_t i = 0; i < temporary_pool_count; ++i) {
        memset(temporary_pool[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    temporary_pool_usage = 0;
    pthread_mutex_unlock(&temporary_pool_mutex);
}

int allocate_pdus(size_t n, NFAPI_CRC_INDICATION_PDU_T** pdus) {
    if (n > allocated_capacity) initialize_memory(allocated_capacity * 2);

    pthread_mutex_lock(&memory_mutex);
    for (size_t i = allocated_count; i < allocated_count + n; ++i) {
        if (i >= allocated_capacity) primary_allocation[i] = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdus[i] = primary_allocation[i];
    }
    allocated_count += n;
    pthread_mutex_unlock(&memory_mutex);

    return NO_ERROR;
}

NFAPI_CRC_INDICATION_PDU_T* acquire_temporary_pdu() {
    if (temporary_pool_usage >= temporary_pool_capacity) {
        reset_temporary_pool();
    }

    pthread_mutex_lock(&temporary_pool_mutex);
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;
    if (temporary_pool_count < temporary_pool_capacity) {
        pdu = temporary_pool[temporary_pool_count];
        ++temporary_pool_count;
        ++temporary_pool_usage;
    }
    pthread_mutex_unlock(&temporary_pool_mutex);

    return pdu;
}

void release_temporary_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu == NULL) return;

    pthread_mutex_lock(&temporary_pool_mutex);
    --temporary_pool_usage;
    temporary_pool[temporary_pool_count - 1] = pdu;
    --temporary_pool_count;
    pthread_mutex_unlock(&temporary_pool_mutex);
}

int setup_memory(size_t initial_capacity) {
    initialize_memory(initial_capacity);
    reset_temporary_pool();
    return NO_ERROR;
}
