#define MAX_ELEMENTS 10000
typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    time_t timestamp;
    struct _NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _CRC_INDICATION_LIST {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
    int count;
    pthread_mutex_t mutex;
} CRC_INDICATION_LIST;

void crc_indication_list_init(CRC_INDICATION_LIST* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void crc_indication_list_insert(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= MAX_ELEMENTS) {
        NFAPI_CRC_INDICATION_PDU_T *to_remove = list->head;
        if (to_remove) {
            list->head = to_remove->next;
            free(to_remove);
            list->count--;
        }
    }

    if (!list->head) {
        list->head = element;
    } else {
        list->tail->next = element;
    }
    list->tail = element;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
}

void crc_indication_list_log(CRC_INDICATION_LIST* list) {
    // Implement logging framework integration here.
}

// Cleanup function to release all allocated memory.
void crc_indication_list_cleanup(CRC_INDICATION_LIST* list) {
    pthread_mutex_lock(&list->mutex);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;

    pthread_mutex_unlock(&list->mutex);
}
