typedef struct node {
    NFAPI_CRCI_NDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

Node** list = NULL;
unsigned int capacity = 0;
unsigned int size = 0;
pthread_mutex_t list_lock;

void init() {
    if (capacity) free(list);
    capacity = 32;
    list = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i)
        list[i] = NULL;
    size = 0;
    pthread_mutex_init(&list_lock, NULL);
}

unsigned int hash(unsigned int key) {
    return key % capacity;
}

void add_pdu(NFAPI_CRCI_NDICATION_PDU_T* pdu) {
    unsigned int index = hash(pdu->rnti);
    Node** current = &list[index];
    while (*current != NULL)
        current = &((*current)->next);

    *current = malloc(sizeof(Node));
    if (!(*current)) {
        printf("Out of memory\n");
        return;
    }

    pthread_mutex_init(&(*current)->lock, NULL);

    (*current)->data = *pdu;
    (*current)->next = NULL;

    pthread_mutex_lock(&list_lock);
    ++size;
    if (size > capacity * 0.8) {
        unsigned int new_capacity = capacity * 2;
        Node** new_list = malloc(new_capacity * sizeof(Node*));
        for (int i = 0; i < new_capacity; ++i)
            new_list[i] = NULL;

        for (int i = 0; i < capacity; ++i) {
            Node* current_node = list[i];
            if (!current_node) continue;
            unsigned int index = hash(current_node->data.rnti);
            Node** new_index = &new_list[index];
            while (*new_index != NULL)
                new_index = &((*new_index)->next);

            *new_index = current_node;
        }

        free(list);
        list = new_list;
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&list_lock);
}

