    if (!pdu) return NULL;

    pdu->rnti = rand() % RNTI_MAX + 1; // Replace RNTI_MAX with the actual maximum RNTI value
    pdu->crc_indication.crcflag = rand() % 2 == 0 ? true : false;

    fetch_ue_info(pdu->rnti);

    return pdu;
}

void clean_up() {
    pthread_mutex_destroy(&list_lock);
    for (int i = 0; i < capacity; ++i) {
        Node* current_node = list[i];
        while (current_node != NULL) {
            Node* temp = current_node;
            current_node = current_node->next;
            free(temp);
        }
    }
    free(list);
}
