import $ from 'jquery';
import _ from 'lodash';
import angular from 'angular';
import 'angular-cache-for-ajax';

app.controller('DialogController', function ($scope, $httpCache, Config) {
    const fieldConfig = Config.dialogFields;
    let cache = $httpCache(angular.module('ngHttpCache'));

    function refreshFields() {
        return _.map(fieldConfig, (fieldName) => {
            const url = `services/fields/${fieldName}`;

            // Check if field is in cache and has not been updated recently
            let cachedData;
            if (cache.get(url)) {
                cachedData = cache.get(url);
                if (!cachedData.updatedAt || Date.now() - cachedData.updatedAt <= Config.cacheDuration) {
                    return Promise.resolve(cachedData[fieldName]);
                }
            }

            // Refresh field data and store in cache for future reference
            return $http.get(url).then((response) => {
                const data = response.data;
                if (cache.get(url)) {
                    cache.put(url, { updatedAt: Date.now(), [fieldName]: data[fieldName] });
                } else {
                    cache.put(url, { updatedAt: Date.now(), [fieldName]: data[fieldName] }, Config.cacheDuration);
                }
                return data[fieldName];
            }).catch((error) => {
                console.error(`Error while refreshing field '${fieldName}':`, error);
                // Handle errors gracefully, perhaps by showing an error message to the user
            });
        });
    }

    // Trigger field updates when parent window requests an update (assuming event is a custom event dispatched by the parent)
    angular.element(document).on('updateDialogFields', refreshFields);
});
