    if (!crcs) {
        log_message("Error: Failed to allocate memory for CRC indications.\n");
        exit(EXIT_FAILURE);
    }

    return crcs;
}

void handle_data_issues(NFAPI_CRC_INDICATION_PDU_T *crcs, size_t num_crcs, const uint16_t *ue_tags, const uint16_t *rntis) {
    for (size_t i = 0; i < num_crcs; ++i) {
        if (!ue_tags[i] || !rntis[i]) {
            crcs[i].rx_ue_information_tag = 0;
            crcs[i].rnti = 0;
            crcs[i].crc_indication_rel8_tag = rand() % 256;
        } else {
            crcs[i].rx_ue_information_tag = ue_tags[i];
            crcs[i].rnti = rntis[i];
            crcs[i].crc_indication_rel8_tag = rand() % 256;
        }
    }
}

void populate_crc_indications(size_t num_ue_tags, const uint16_t *ue_tags, const uint16_t *rntis) {
    size_t num_crcs = (num_ue_tags < MAX_UE_TAGS) ? num_ue_tags : MAX_UE_TAGS;

    validate_params(ue_tags, num_ue_tags, rntis);

    getrlimit(RLIMIT_STACK, &{stack_resource_t stack_limit});
