        log_message("Error: Exceeding process stack size limit.\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T *crcs = allocate_crc_indications(num_crcs);

    handle_data_issues(crcs, num_crcs, ue_tags, rntis);

    log_message("Populated %zu CRC indications.\n", num_crcs);
}
