    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct buffer_node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct buffer_node *next;
} BufferNode;

typedef struct buffer_pool {
    BufferNode *head;
    BufferNode *tail;
    unsigned int capacity;
    unsigned int size;
    pthread_mutex_t lock;
} BufferPool;

BufferPool* create_buffer_pool(unsigned int capacity) {
    BufferPool *pool = malloc(sizeof(BufferPool));
    pool->head = NULL;
    pool->tail = NULL;
    pool->capacity = capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

BufferNode* create_buffer_node() {
    BufferNode *node = malloc(sizeof(BufferNode));
    node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    node->next = NULL;
    return node;
}

void push_to_buffer(BufferPool *pool, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&pool->lock);
    if (pool->head == NULL) {
        pool->head = create_buffer_node();
        pool->tail = pool->head;
    } else {
        pool->tail->next = create_buffer_node();
        pool->tail = pool->tail->next;
    }
    memcpy(pool->tail->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
}

BufferPool* allocate_list(unsigned int N) {
    BufferPool *pool = create_buffer_pool(N);

    for (unsigned int i = 0; i < N; ++i) {
        // Fill the structure with valid data.
        NFAPI_CRC_INDICATION_PDU_T element;
        // ...
        push_to_buffer(pool, element);
    }

    return pool;
}
```

