typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node_t;

static node_t* head = NULL;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t num_elements = 0;

void append(NFAPI_CRC_INDICATION_PDU_T data) {
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return; // Handle memory exhaustion gracefully

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        node_t* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    num_elements++;
    pthread_mutex_unlock(&list_lock);
}

NFAPI_CRC_INDICATION_PDU_T* pop() {
    if (pthread_mutex_trylock(&list_lock) != 0) return NULL; // Avoid unnecessary locks when unblocked

    node_t* data = head;
    if (data == NULL) {
        pthread_mutex_unlock(&list_lock);
        return NULL;
    }

    head = head->next;
    num_elements--;
    pthread_mutex_unlock(&list_lock);

    return &data->data;
}
```

