    int state;
    std::vector<std::unique_ptr<OctreeNode>> children;
    std::vector<float> leafPrefixSum; // Sum of leaf prefixes
    std::shared_ptr<float[]> data; // Data array for this octree node and its leaves

    OctreeNode(int state, size_t capacity = NODE_CAPACITY)
        : state(state), children(capacity), leafPrefixSum(capacity + 1) {}
};

// Create the octree data structure with an FSA
std::vector<OctreeNode*> createOctree(const float* stateData, size_t numStates, const FiniteStateAutomaton& fsa,
                                      void (*callback)(int state), int lastState, size_t featureSize, size_t leafNodesCapacity) {
    // Allocate memory for the octree root node
    OctreeNode* root = new (std::nothrow) OctreeNode(INVALID_STATE);
    if (!root) return nullptr;

    // Initialize the data array with default values
    root->data.reset(new float[leafNodesCapacity]);
    std::fill(root->data.get(), root->data.get() + leafNodesCapacity, INITIAL_DATA_VALUE);

    // Perform depth-first traversal to build the octree recursively
    dfsBuildOctree(root, stateData, numStates, fsa, callback, lastState, featureSize, leafNodesCapacity);

    return std::vector<OctreeNode*>(1, root);
}

void dfsBuildOctree(OctreeNode* node, const float* stateData, size_t numStates, const FiniteStateAutomaton& fsa,
                    void (*callback)(int state), int lastState, size_t featureSize, size_t leafNodesCapacity) {
    // If this node is a leaf, set its state and data values
    if (node->children.empty()) {
        float currentFeatureSum = 0;
        for (size_t i = 0; i < featureSize; ++i)
            currentFeatureSum += stateData[node->state * featureSize + i];

        // Normalize the feature data if necessary
        if (normalizeFeatures) {
            currentFeatureSum /= sqrt(featureSize);
            for (size_t i = 0; i < featureSize; ++i)
                stateData[node->state * featureSize + i] -= currentFeatureSum;
        }

        node->state = findStateByFeatures(stateData, numStates, fsa);
        node->data.get()[node->leafPrefixSum.size() - 1] = node->state;

        if (callback) callback(node->state);

        return;
    }

    // Find the child with the given state
    int childState = findChildStateByFeatureAndTransitionRules(fsa, stateData[node->state * featureSize]);
    if (childState == INVALID_STATE) return;

    auto& childrenIter = node->children[childState];
    if (!childrenIter) {
        // Allocate a new child node and build it recursively
        childrenIter.reset(new OctreeNode(childState, leafNodesCapacity));
        dfsBuildOctree(childrenIter.get(), stateData, numStates, fsa, callback, lastState, featureSize, leafNodesCapacity);
    }

    // Update the leaf prefix sum for this node and its descendants
    node->leafPrefixSum[childState + 1] = childrenIter->leafPrefixSum[0];
    dfsUpdateLeafPrefixSum(childrenIter.get(), featureSize, leafNodesCapacity);
}

