#include <stdio.h>

typedef struct FSA {
    size_t num_states;
    void (*action)(int state);
    const int **transitions;
} FSA;

// Lazy loading of states, linked list for efficient lookup and memory management
typedef struct State {
    int id;
    struct State *next;
    int data; // Custom data field
} State;

FSA* fsa_create(int num_states, FSA* transition_table, void (*action)(int state)) {
    FSA* fsa = malloc(sizeof(FSA));
    if (!fsa) return NULL;

    fsa->num_states = num_states;
    fsa->action = action;
    fsa->transitions = transition_table;

    // Lazy loading of states using linked list
    State *last_state = NULL, *current_state;
    for (int i = 0; i < num_states; ++i) {
        current_state = malloc(sizeof(State));
        if (!current_state) {
            free_fsa(fsa);
            return NULL;
        }

        current_state->id = i;
        current_state->next = NULL;

        if (last_state) {
            last_state->next = current_state;
            last_state = current_state;
        } else {
            fsa->current_state = current_state;
        }
    }

    return fsa;
}

void free_fsa(FSA* fsa) {
    State *temp, *next;
    for (State *current = fsa->current_state; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
    free(fsa);
}

