typedef struct {
    unsigned long RNTI;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    void *config;
    sem_t sem_cfg_update;
} stream_t;

union_find_t {
    uint32_t parent;
    uint64_t size;
};

void compress(union_find_t *uf, int id) {
    if (uf[id].parent == id) {
        uf[id].parent = id - 1;
        while (uf[uf[id].parent].parent != uf[id].parent) {
            uf[id].parent = uf[uf[id].parent].parent;
            uf[id].size += uf[uf[id].parent].size;
        }
    }
}

int find(union_find_t *uf, int id) {
    if (uf[id].parent != id - 1) {
        compress(uf, id);
    }
    return uf[id].parent;
}

unsigned long get_rnti() {
    static unsigned long current = 0;
    unsigned long temp = current++;
    if (current > 0xFFFFFFFF) current = 1;
    return temp;
}

stream_t *allocate_stream(void) {
    stream_t *stream = malloc(sizeof(stream_t));
    if (!stream) return NULL;
    sem_init(&stream->sem_cfg_update, 0, 1);
    stream->RNTI = get_rnti();
    return stream;
}

void configure_stream(stream_t *stream, NFAPI_CRC_INDICATION_PDU_T pdu, void *config) {
    stream->pdu = pdu;
    stream->config = config;
}

int configureNetworkStreamsWithDynamicPDU(int max_streams, int *dynamic_config) {
    const int memory_limit = sysconf(_SC_PAGE_SIZE) * 0.6;
    sem_t *sem_pool = sem_open("stream_pool", O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IRGRP | S_IWGRP | S_IROTH | S_IWOTH, memory_limit);
    if (!sem_pool) return -1;

    union_find_t *uf = mmap(NULL, 10000, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!uf) {
        sem_close(sem_pool);
        return -1;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_REALTIME, &start);

    int total_streams = 0;
    int free_slots = max_streams;
    for (int i = 0; i < 10000 && total_streams < max_streams; ++i) {
        stream_t *stream = allocate_stream();
        if (!stream) continue;

        int disjoint = true;
        for (int j = 0, k = find(uf, (int)stream->RNTI); total_streams > k && disjoint; ++j) {
            if (find(uf, j) == k) disjoint = false;
        }
        if (disjoint) {
            configure_stream(stream, dynamic_config[total_streams], malloc(dynamic_config[total_streams + 1]));
            sem_wait(sem_pool);
            uf[(int)stream->RNTI].parent = (uint32_t)stream;
            compress(uf, (int)stream->RNTI);
            total_streams++;
            free_slots--;
        } else {
            free(stream);
        }
    }

    clock_gettime(CLOCK_REALTIME, &end);
    double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000;
    printf("Configuration completed in %.3f seconds\n", elapsed);

    munmap(uf, 10000);
    sem_close(sem_pool);
    return total_streams;
}
