import os
import hashlib
import concurrent.futures
import logging
from tqdm import tqdm

def calculate_md5(file_paths, max_chunk_size=4*1024*1024, logger=None):
    if not logger:
        logger = logging.getLogger(__name__)

    processed_files = set()
    hashes = {}

    with concurrent.futures.ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        tasks = [executor.submit(process_file, file_path, max_chunk_size, hashes) for file_path in tqdm(file_paths)]

        for future in concurrent.futures.as_completed(tasks):
            try:
                result = future.result()
                if result:
                    processed_files.add(result['filename'])
                    hashes[result['filename']] = result['hash']
                    logger.info(f"{result['filename']}: {result['hash']}")
            except Exception as e:
                logger.error(f"Error processing file: {e}", exc_info=True)

    return processed_files, hashes

def process_file(file_path, max_chunk_size, hashes):
    try:
        with open(file_path, 'rb') as f:
            md5 = hashlib.md5()
            buffer = []

            while True:
                data = f.read(max_chunk_size)
                if not data:
                    break

                buffer.append(data)
                md5.update(b''.join(buffer))
                buffer.clear()

            filename = os.path.basename(file_path)
            return {'filename': filename, 'hash': md5.hexdigest()}
    except FileNotFoundError:
        return None
    except Exception as e:
        logger.error(f"File error: {e}", exc_info=True)
        return None
