} NetConfig;

NetConfig* init_network_configs(int capacity) {
    NetConfig* configs = (NetConfig*)malloc(capacity * sizeof(NetConfig));

    for (int i = 0; i < capacity; ++i) {
        configs[i].id = i;
        configs[i].addr.sin_family = AF_INET;
        configs[i].addr.sin_port = htons(0);
        configs[i].in_use = false;
        pthread_mutex_init(&configs[i].lock, NULL);
    }

