}

bool is_range_overlapping(const sockaddr_in* addr1, const sockaddr_in* addr2) {
    unsigned int net1 = ntohl(((struct in_addr){addr1->sin_addr}).S_un.S_addr);
    unsigned int net2 = ntohl(((struct in_addr){addr2->sin_addr}).S_un.S_addr);
    unsigned int mask1 = ((addr1->sin_addr.s_addr & (~(int)0xFFFFFF00)) >> 16) & 0xFF;
    unsigned int mask2 = ((addr2->sin_addr.s_addr & (~(int)0xFFFFFF00)) >> 16) & 0xFF;

    return (mask1 == mask2 && ((net1 & ~((1 << mask1) - 1)) == (net2 & ~((1 << mask2) - 1)))) ||
           (mask1 < mask2 && (net1 >> mask2 & ((1 << (32 - mask2)) - 1)) == (net2 >> mask1 & ((1 << (32 - mask1)) - 1)));
}

bool assign_config(NetConfig* configs, int capacity, sockaddr_in* ip, unsigned int subnet_mask, unsigned int gateway) {
    for (int i = 0; i < capacity; ++i) {
        pthread_mutex_lock(&configs[i].lock);

        if (!configs[i].in_use && !is_range_overlapping(ip, &configs[i].addr)) {
            configs[i].addr.sin_addr.s_addr = htonl(((*ip).sin_addr.s_addr & 0xFFFFFF00) | (subnet_mask << 16));
            configs[i].addr.sin_port = gateway;
            configs[i].in_use = true;
            pthread_mutex_unlock(&configs[i].lock);
            return true;
        }

        pthread_mutex_unlock(&configs[i].lock);
    }

    return false;
}

// Function for dynamic reconfiguration and scaling
void resize_network_configs(NetConfig* configs, int current_capacity, int new_capacity) {
    if (new_capacity <= current_capacity)
        return;

    NetConfig* temp = (NetConfig*)realloc(configs, new_capacity * sizeof(NetConfig));
    if (!temp) {
        perror("Reallocation failed\n");
        exit(1);
    }

    for (int i = current_capacity; i < new_capacity; ++i) {
        temp[i].id = i;
        temp[i].addr.sin_family = AF_INET;
        temp[i].addr.sin_port = htons(0);
        temp[i].in_use = false;
        pthread_mutex_init(&temp[i].lock, NULL);
    }

    configs = temp;
}
```
This code provides an initial implementation for the task. It defines a `NetConfig` structure that holds an interface identifier, IP address, subnet mask, gateway, and lock to manage concurrent access. The provided functions include:
