typedef struct {
    time_t timestamp;
    char source[INET6_ADDRSTRLEN];
    char destination[INET6_ADDRSTRLEN];
    int measurements[5];
    int num_measurements;
    bool is_spike;
} LogEntry;

LogEntry* parse_line(char* line) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    sscanf(line, "%ld %[^ ] %[^ ] %d%n", &entry->timestamp, entry->source, entry->destination, &entry->num_measurements);
    int pos = strlen(line) - entry->num_measurements;
    sscanf(line + pos, "%d%n", &entry->measurements[0]);
    for (int i = 1; i < entry->num_measurements; ++i) {
        sscanf(line + pos + i * sizeof(int), "%d%n", &entry->measurements[i]);
    }
    return entry;
}

void calculate_moving_average(LogEntry* entry) {
    int sum = 0;
    for (int i = 4; i < entry->num_measurements; ++i) {
        sum += entry->measurements[i] * (5 - i);
    }
    entry->measurements[entry->num_measurements] = sum / 5;
}

void mark_spike(LogEntry* prev, LogEntry* current) {
    if (current->measurements[0] > 1.5 * prev->measurements[4]) {
        current->is_spike = true;
    }
}

int main(int argc, char** argv) {
    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening the log file.");
        return 1;
    }

    LogEntry* current_entry = NULL;
    LogEntry* previous_entry = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        if (current_entry) free(current_entry);
        current_entry = parse_line(line);
        if (current_entry->num_measurements < 4) {
            printf("Error: Line has fewer than four values.\n");
            continue;
        }
        previous_entry = current_entry;
        calculate_moving_average(current_entry);
        mark_spike(previous_entry, current_entry);
        // ... Further processing or outputting of the data can be added here.
    }

    if (previous_entry) free(previous_entry);
    fclose(file);

    return 0;
}
