#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    sequence_number_t sequence_num;
    timestamp_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

struct dynamic_array {
    pthread_mutex_t lock;
    size_t size;
    node_t **table;
};

static inline void init_dynamic_array(struct dynamic_array *da, size_t capacity) {
    da->size = 0;
    da->capacity = capacity;
    da->table = calloc((size_t)(1 + capacity), sizeof(node_t*));
    if (!da->table) {
        perror("failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&da->lock, NULL);
}

static inline void free_dynamic_array(struct dynamic_array *da) {
    for (size_t i = 0; i < da->capacity; ++i) {
        node_t *curr = da->table[i];
        while (curr != NULL) {
            node_t *temp = curr;
            curr = curr->next;
            free(temp);
        }
    }
    free(da->table);
    pthread_mutex_destroy(&da->lock);
}

static inline size_t hash(const RX_UE_INFORMATION_TAG tag) {
    // A simple hash function for demonstration purposes; use a better one in production.
    return (size_t)(tag % da->capacity);
}

void insert(struct dynamic_array *da, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&da->lock);
    size_t idx = hash(data->tag);
    node_t *new_node = malloc(sizeof(node_t));
    if (!new_node) {
        perror("failed to allocate memory for new node");
        pthread_mutex_unlock(&da->lock);
        return;
    }
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = da->table[idx];
    da->table[idx] = new_node;
    ++da->size;
    pthread_mutex_unlock(&da->lock);
}

void remove(struct dynamic_array *da, uint32_t rnti) {
    pthread_mutex_lock(&da->lock);
    size_t idx = hash((RX_UE_INFORMATION_TAG){ .rnti = rnti });
    node_t **curr = &da->table[idx];
    node_t *prev = NULL;
    while (*curr != NULL && ((*curr)->data.rnti != rnti)) {
        prev = curr;
        curr = &( (*curr)->next );
    }
    if (*curr == NULL) {
        pthread_mutex_unlock(&da->lock);
        return;
    }
    if (prev == NULL) {
        da->table[idx] = (*curr)->next;
    } else {
        prev->next = (*curr)->next;
    }
    node_t *temp = *curr;
    *curr = temp->next;
    free(temp);
    --da->size;
    pthread_mutex_unlock(&da->lock);
}

const NFAPI_CRC_INDICATION_PDU_T* find(const struct dynamic_array *da, uint32_t rnti) {
    pthread_mutex_lock(&da->lock);
    size_t idx = hash((RX_UE_INFORMATION_TAG){ .rnti = rnti });
    node_t *curr = da->table[idx];
    while (curr != NULL && curr->data.rnti != rnti) {
        curr = curr->next;
    }
    pthread_mutex_unlock(&da->lock);
    return curr ? &curr->data : NULL;
}

size_t count(const struct dynamic_array *da) {
    return da->size;
}
