    LTE_ENB_TRANSPORT_CHANNEL data;
    struct node* next;
};

struct rwlock_t {
    pthread_rwlock_t rwlock;
    int is_locked;
};

int dynamic_array_init() {
    // Initialize read-write lock
    struct rwlock_t *rw = malloc(sizeof(struct rwlock_t));
    if (!rw) return -1;
    pthread_rwlock_init(&rw->rwlock, NULL);
    rw->is_locked = 0;

    // Initialize data structure
    struct node* head = malloc(sizeof(struct node));
    if (!head) {
        free(rw);
        return -1;
    }
    head->next = NULL;

    return 0;
}

void dynamic_array_destroy() {
    struct node* current, *next;
    struct rwlock_t *rw = malloc(sizeof(struct rwlock_t));
    if (!rw) return;

    pthread_rwlock_init(&rw->rwlock, NULL);
    rw->is_locked = 0;

    current = head->next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    free(head);
    free(rw);
}

LTE_ENB_TRANSPORT_CHANNEL dynamic_array_insert(uint64_t RACH_REQUEST_ID, struct LTE_ENB_TRANSPORT_CHANNEL_T data) {
    struct rwlock_t *rw;
    struct node* current, *prev;
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;

    pthread_rwlock_rdlock(&rw->rwlock);
    current = head->next;
    prev = head;

    while (current != NULL && current->data->RACH_REQUEST_ID < RACH_REQUEST_ID) {
        prev = current;
        current = current->next;
    }

    if (!current || current->data->RACH_REQUEST_ID > RACH_REQUEST_ID) {
        prev->next = new_node;
    } else {
        new_node->next = current;
        pthread_rwlock_wrlock(&rw->rwlock);
        prev->next = new_node;
        pthread_rwlock_unlock(&rw->rwlock);
    }

    pthread_rwlock_unlock(&rw->rwlock);

    return new_node->data;
}

LTE_ENB_TRANSPORT_CHANNEL dynamic_array_delete(uint64_t RACH_REQUEST_ID) {
    struct rwlock_t *rw;
    struct node* current, *prev;

    pthread_rwlock_wrlock(&rw->rwlock);

    current = head->next;
    prev = head;

    while (current != NULL && current->data->RACH_REQUEST_ID < RACH_REQUEST_ID) {
        prev = current;
        current = current->next;
    }

    if (!current || current->data->RACH_REQUEST_ID > RACH_REQUEST_ID) {
        pthread_rwlock_unlock(&rw->rwlock);
        return NULL;
    }

    prev->next = current->next;
    LTE_ENB_TRANSPORT_CHANNEL to_free = current->data;
    free(current);

    pthread_rwlock_unlock(&rw->rwlock);

