    int key;
};

// Function to initialize and manage the hash table
std::unordered_map<int, Record> initializeHashTable(unsigned long capacity) {
    std::unordered_map<int, Record> hashTable(capacity);
    return hashTable;
}

// Function to set a random value for each record's integer field
void setRecordValues(std::unordered_map<int, Record>& hashTable, unsigned int minValue, unsigned int maxValue) {
