} NFAPI_CRC_INDICATION_PDU_T;

typedef struct unique_index {
    uint32_t value;
    pthread_mutex_t mutex;
    struct unique_index *next;
} UNIQUE_INDEX;

UNIQUE_INDEX* unique_list = NULL;

void add_unique(uint32_t rnti) {
    UNIQUE_INDEX *new, *current;

    new = (UNIQUE_INDEX*) malloc(sizeof(UNIQUE_INDEX));
    if (!new) return;

    new->value = rnti;
    new->next = NULL;

    pthread_mutex_init(&new->mutex, NULL);

    current = unique_list;
    if (!current) {
        unique_list = new;
        return;
    }

    while (current->next && current->next->value == rnti)
        current = current->next;

    pthread_mutex_lock(&new->mutex);
    pthread_mutex_lock(&current->mutex);

    if (!current->next) {
        new->next = current->next;
        current->next = new;
    } else {
        UNIQUE_INDEX *temp = (UNIQUE_INDEX*) malloc(sizeof(UNIQUE_INDEX));
        if (!temp) {
            pthread_mutex_unlock(&new->mutex);
            pthread_mutex_unlock(&current->mutex);
            free(new);
            return;
        }

        temp->value = rnti;
        temp->next = NULL;

        pthread_mutex_lock(&temp->mutex);

        while (current->next && current->next->value == rnti)
            current = current->next;

        temp->next = current->next;
        current->next = temp;
    }

    pthread_mutex_unlock(&new->mutex);
    pthread_mutex_unlock(&current->mutex);
}

void del_unique(uint32_t rnti) {
    UNIQUE_INDEX *current, **prev;

    prev = &unique_list;
    current = unique_list;

    while (current != NULL) {
        if (current->value == rnti) {
            if (*prev == current)
                *prev = current->next;
            else
                prev->next = current->next;

            pthread_mutex_destroy(&current->mutex);
            free(current);
            break;
        }

        prev = &current->next;
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_array(unsigned int N) {
    NFAPI_CRC_INDICATION_PDU_T *array, *current;

    if (N <= 0 || N > 1000)
        return NULL;

    array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!array)
        return NULL;

    current = array;
    for (size_t i = 0; i < N - 1; ++i, ++current) {
        current->rx_ue_info.value = RX_UE_INFORMATION_TAG_INVALID;
        current->rnti = rand() % 16777215 + 1; // ensure RNTI within valid range
        add_unique(current->rnti);
        current->crc_indication.value = (uint32_t)rand();
    }

    current->rx_ue_info.value = RX_UE_INFORMATION_TAG_INVALID;
    current->rnti = rand() % 16777215 + 1; // ensure last RNTI within valid range
    add_unique(current->rnti);
    current->crc_indication.value = (uint32_t)rand();

    return array;
}
```

