["```javascript
const fs = require('fs-extra');
const yaml = require('js-yaml');
const Ajv = require('ajv');
const async = require('async');
const { Queue } = require('bullmq'); // queue manager for asynchronous tasks

// Define the schema
const schema = yaml.load(require('./my-schema-version-1.2.yaml'));
const ajv = new Ajv({ allErrors: true });

function validateFileContent(fileContent) {
  const validator = ajv.compile(schema);
  return validator(fileContent);
}

async function mergeValidatedContents(validatedFiles) {
  let mergedData = {};

  for (const file of validatedFiles) {
    mergedData = { ...mergedData, ...file.data };
  }

  return mergedData;
}

function logFileOperation(operationName, filePath, result) {
  console.log(`${operationName}: ${filePath} - Result:`, result);
}

async function readAndValidateFiles(directoryPath, concurrencyLimit = 10) {
  const fileQueue = new Queue('file-processor', { connection: { redis: { host: 'localhost' } } });

  async function processFile({ filePath }) {
    try {
      const fileContent = await fs.readFile(filePath, 'utf8');
      const validationResult = validateFileContent(JSON.parse(fileContent));

      if (!validationResult.valid) {
        console.error(`Invalid content in ${filePath}:`, validationResult.errors);
        return null;
      }

      logFileOperation('Validated', filePath, validationResult);
      return { data: JSON.parse(fileContent), path: filePath };
    } catch (error) {
      console.error(`Error while processing ${filePath}:`, error);
      return null;
    }
  }

  const files = await fs.readdir(directoryPath);

  async function readAndProcessFiles() {
    const tasks = [];

    for (const file of files) {
      tasks.push({ filePath: `${directoryPath}/${file}` });
    }

    while (tasks.length > 0) {
      const chunkSize = Math.min(concurrencyLimit, tasks.length);
      tasks = tasks.slice(0, chunkSize);

      await Promise.all(
        tasks.map(task => fileQueue.add(processFile, task))
      );

      // Process the completed tasks
      for (let i = 0; i < chunkSize; i++) {
        const result = await fileQueue.processNow('file-processor');

        if (result) {
          // Add validated files to a buffer for merging later
          FileBuffer.add(result);
        }
      }
    }
  }

  try {
    await readAndProcessFiles();
  } catch (error) {
    console.error('Error while reading and processing files:', error);
  }

  return await mergeValidatedContents(FileBuffer.all());
}

// Implement the FileBuffer to store validated files for merging later
class FileBuffer {
  constructor() {
    this.files = [];
  }

  add(file) {
    if (file) {
      this.files.push(file);
    }
  }

  all() {
    return [...this.files];
  }
}
```

You can test the implementation in isolation with:

