[' Here is a simplified version of the requested C code using doubly-linked list and pthreads for concurrent access. Note that this code does not include the integration with an external data source, as it requires specific details about the API used.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T data;
    void *next, *prev;
} Node;

typedef struct {
    Node *head, *tail;
    pthread_mutex_t lock;
    size_t length;
} List;

List* list_init() {
    List *list = malloc(sizeof(List));
    if (!list) return NULL;
    list->length = 0;
    pthread_mutex_init(&list->lock, NULL);
    list->head = list->tail = NULL;
    return list;
}

void* insert_node(List *list, size_t pos, const NFAPI_CRC_INDICATION_PDU_T *data) {
    if (pos < 0 || pos > list->length) return NULL;
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = *data;
    new_node->next = new_node->prev = NULL;

    pthread_mutex_lock(&list->lock);
    if (pos == 0) {
        new_node->next = list->head;
        if (new_node->next)
            new_node->next->prev = new_node;
        list->head = new_node;
    } else if (pos == list->length) {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    } else {
        Node *current = list->head;
        for (size_t i = 0; i < pos - 1; ++i) {
            current = current->next;
        }
        new_node->next = current->next;
        if (new_node->next)
            new_node->next->prev = new_node;
        current->next = new_node;
        new_node->prev = current;
    }
    list->length++;
    pthread_mutex_unlock(&list->lock);
    return new_node;
}

Node* find_node(const List *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *current = list->head;
    while (current) {
        if (memcmp(&current->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            current = current->next;
        } else {
            break;
        }
    }
    return current;
}

void remove_node(List *list, Node *node) {
    pthread_mutex_lock(&list->lock);
    if (node->prev) node->prev->next = node->next;
    if (node->next) node->next->prev = node->prev;
    if (list->head == node) list->head = node->next;
    if (!list->head) list->tail = NULL;
    free(node);
    list->length--;
    pthread_mutex_unlock(&list->lock);
}

void update_crcflags(List *list, unsigned int seed) {
    Node *current = list->head;
    while (current) {
        current->data.CRCFLAG ^= seed++;
        current = current->next;
    }
}
