#define MAX_ELEMENTS 100000
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRUC_INDICATION_PDU_T *head = NULL, **list_ptr;
static int num_elements = 0;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;
static pthread_t worker_threads[MAX_ELEMENTS/10]; // Adjust based on your CPU cores number

void init() {
    list_ptr = &head;
}

NFAPI_CRUC_INDICATION_PDU_T* new_node(RX_UE_INFORMATION_TAG tag, int rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    NFAPI_CRUC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRUC_INDICATION_PDU_T));
    if (!new_node) {
        perror("malloc failed");
        exit(-1);
    }
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->next = NULL;
    return new_node;
}

void add_node(NFAPI_CRUC_INDICATION_PDU_T* node) {
    pthread_mutex_lock(&list_mutex);
    // Insert in sorted order based on RNTI
    NFAPI_CRUC_INDICATION_PDU_T *current = head;
    if (!head) {
        head = node;
        num_elements++;
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&list_mutex);
        return;
    }
    while (current->next && current->next->rnti < node->rnti) {
        current = current->next;
    }
    node->next = current->next;
    current->next = node;
    num_elements++;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRUC_INDICATION_PDU_T* find_node_by_rnti(int rnti) {
    NFAPI_CRUC_INDICATION_PDU_T *current = head;
    while (current) {
        if (current->rnti == rnti) {
            break;
        }
        current = current->next;
    }
    return current;
}

void remove_node(int rnti) {
    pthread_mutex_lock(&list_mutex);
    if (head && head->rnti == rnti) {
        NFAPI_CRUC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
        num_elements--;
        pthread_cond_signal(&not_empty);
    } else {
        NFAPI_CRUC_INDICATION_PDU_T *current = head, *prev = NULL;
        while (current && current->rnti != rnti) {
            prev = current;
            current = current->next;
        }
        if (!current) {
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        prev->next = current->next;
        free(current);
        num_elements--;
    }
    pthread_mutex_unlock(&list_mutex);
}

void clear_list() {
    while (head) {
        NFAPI_CRUC_INDICATION_PDU_T *temp = head;
        head = head->next;
        free(temp);
    }
    num_elements = 0;
}

void* worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&list_mutex);
        while (!head || num_elements == 0) {
            pthread_cond_wait(&not_empty, &list_mutex);
        }
        NFAPI_CRUC_INDICATION_PDU_T *temp = head;
        head = head->next;
        // Perform any operation on the node here (e.g., process it)
        free(temp);
        num_elements--;
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&list_mutex);
    }
    return NULL;
}

void run() {
    init();

    // Start worker threads
    for (int i = 0; i < sizeof(worker_threads)/sizeof(pthread_t); i++) {
        pthread_create(&worker_threads[i], NULL, &worker, NULL);
    }

    // Add elements and remove based on RNTI as needed
    NFAPI_CRUC_INDICATION_PDU_T* node1 = new_node(1, 10, CRC_INDICATION_REL8_TAG{.crc = rand()});
    add_node(node1);

    // ... (add more elements)

    NFAPI_CRUC_INDICATION_PDU_T* node2 = find_node_by_rnti(10);
    remove_node(10);

    // ... (remove more elements)

    clear_list();
}
