import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
import time
import requests

def get_md5(file_path, timeout=120):
    cache_filename = f"{file_path}.md5"
    if os.path.exists(cache_filename):
        with open(cache_filename, "r") as fd:
            return fd.read()

    try:
        if not os.path.isfile(file_path) or os.stat(file_path).st_size == 0:
            return None

        chunk_size = 65536
        hasher = hashlib.md5()
        with open(file_path, "rb") as fd:
            for chunk in iter(lambda: fd.read(chunk_size), b""):
                hasher.update(chunk)
            md5_hash = hasher.hexdigest()

        # Cache the hash for future use
        with open(cache_filename, "w") as fd:
            fd.write(md5_hash)

        # Validate against external metadata service (optional and with timeout)
        if validate_metadata:
            start_time = time.time()
            response = requests.get(f"https://metadata-service.com/checksum/{file_path}", timeout=timeout)
            if response.status_code == 200:
                if response.json().get("md5") == md5_hash:
                    return md5_hash
                else:
                    logging.warning(f"File {file_path} has mismatched checksum on metadata service.")
            elif time.time() - start_time > timeout:
                logging.warning(f"Timeout while validating file {file_path}. Skipping check.")

        return md5_hash
    except Exception as e:
        logging.error(f"Error processing file {file_path}: {e}")
        return None

def process_files(file_paths, num_workers=os.cpu_count() * 2):
    processed = {}
    with ThreadPoolExecutor(max_workers=num_workers) as executor:
        for result in executor.map(get_md5, file_paths):
            if result is not None:
                processed[result[0]] = result[1]
    return processed

logging.basicConfig(level=logging.INFO)
validate_metadata = True  # Set to False to disable external metadata service validation

file_paths = [
    "/path/to/large_file.txt",
    "/path/to/another_large_file.dat",
    ...
]
results = process_files(file_paths)
print(results)
