    uint32_t rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct cache_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct cache_node *next;
} cache_node_t;

static sem_t cache_mutex = SEM_INITIALIZER_NP;
static sem_t cache_notempty = SEM_INITIALIZER_NP;
static cache_node_t* head = NULL;
static size_t capacity = 0;
static size_t num_items = 0;

void destroy_cache() {
    if (head != NULL) {
        cache_node_t *current, *next;

        sem_wait(&cache_mutex);

        current = head;
        while (current != NULL) {
            next = current->next;
            free(current);
            current = next;
        }

        head = NULL;
        num_items = 0;
        capacity = 0;

        sem_post(&cache_mutex);
    }
}

int add_to_cache(NFAPI_CRC_INDICATION_PDU_T data) {
    if (num_items == capacity) {
        destroy_cache();
        return -1; // Return an appropriate error code indicating allocation failure.
    }

    cache_node_t *new_node = malloc(sizeof(cache_node_t));
    if (new_node == NULL) {
        return -1; // Return an appropriate error code indicating allocation failure.
    }

    new_node->data = data;
    new_node->next = head;
    head = new_node;
    ++num_items;

    if (num_items == 1) {
        sem_post(&cache_notempty);
    }

    return 0; // Return success code.
}

NFAPI_CRC_INDICATION_PDU_T* get_from_cache(uint32_t rnti) {
    if (num_items == 0) return NULL;

    cache_node_t *current = head;

    sem_wait(&cache_mutex);
    while (current != NULL) {
        if (current->data.rnti == rnti) {
            void* temp = current;
            current = current->next;
            sem_post(&cache_mutex);
            return &temp->data; // Return the found data structure's address.
        }
        current = current->next;
    }

    sem_post(&cache_mutex);
    return NULL; // Return NULL if not found.
}

int remove_from_cache(uint32_t rnti) {
    if (num_items == 0) return -1; // Return an appropriate error code indicating empty cache.

    sem_wait(&cache_mutex);
    cache_node_t *prev = NULL, *current = head;

    while (current != NULL && current->data.rnti != rnti) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        sem_post(&cache_mutex);
        return -1; // Return an appropriate error code indicating not found.
    }

    if (prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    --num_items;

    if (num_items == capacity - 1 && num_items != 0) {
        sem_post(&cache_notempty);
    } else if (num_items == 0) {
        destroy_cache();
    }

    sem_post(&cache_mutex);
    return 0; // Return success code.
}
