        int j = i;
        while (record_indices[j]) {
            j = (j + 1) % num_keys;
        }
        record_indices[j] = i;
    }

    // Initialize keys and records with unique values within specified range
    for (int i = 0; i < num_keys; ++i) {
        key_array[i] = record_indices[i] + 1;
        records[i].value = (rand() % 100) + 1;
