typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t  CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* read_file_chunk(void *arg) {
    size_t chunk_size = (size_t) arg;
    char buffer[chunk_size];
    ssize_t bytes_read;
    FILE *fp = fopen(*((const char **) arg), "rb");
    MD5_CTX md5_ctx;
    hashlib.md5(buffer, chunk_size - 1, &md5_ctx); // Skip null terminator

    while ((bytes_read = fread(buffer, sizeof(char), chunk_size - 1, fp)) > 0) {
        MD5_Update(&md5_ctx, buffer, bytes_read);
    }

    fclose(fp);
    return &md5_ctx;
}

void process_chunk(MD5_CTX *md5_ctx, NFAPI_CRC_INDICATION_PDU_T **data, size_t data_size) {
    for (size_t i = 0; i < data_size; ++i) {
        uint8_t *buf = MD5_Final(buf, md5_ctx);
        NFAPI_CRC_INDICATION_PDU_T *pdu = &data[i][0];

        pdu->RX_UE_INFORMATION_TAG = rand() % 0xFFFFFFFF;
        pdu->RNTI = rand() % 0x7FFF; // Limit to bottom 13 bits to avoid conflicts with reserved values
        pdu->CRC_INDICATION_REL8_TAG = i + 1;
        pdu->CRCFLAG = (i + 1) % 2; // Set CRC indication based on the current element index
    }
}

void log_system_metrics(const char *message) {
    rusage rusage_before, rusage_after;
    getrusage(RUSAGE_SELF, &rusage_before);
    // Implement your system metric logging here
    getrusage(RUSAGE_SELF, &rusage_after);
}

void early_error(const char *message) {
    printf("%s\n", message);
    exit(EXIT_FAILURE);
}

int processFileMD5AndHandleCRCIndications(const char *file_path, size_t max_elements, size_t chunk_size) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        early_error("Failed to open file");
    }

    fseek(fp, 0, SEEK_END);
    long filesize = ftell(fp);
    rewind(fp);

    size_t data_size = max_elements;
    NFAPI_CRC_INDICATION_PDU_T *data = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * data_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) {
        early_error("Failed to allocate memory");
    }

    pthread_t threads[chunk_size / sizeof(void *)];
    size_t chunks = chunk_size / sizeof(MD5_CTX *);
    MD5_CTX **md5_ctxs = malloc(sizeof(MD5_CTX *) * chunks);

    for (size_t i = 0; i < chunks; ++i) {
        md5_ctxs[i] = calloc(1, sizeof(MD5_CTX));
    }

    for (size_t i = 0; filesize > chunk_size * chunks && i < chunks - 1; ++i) {
        size_t thread_index = i * chunks;
        char *file_pointer = malloc(chunk_size);
        fread(file_pointer, sizeof(char), chunk_size, fp);
        pthread_create(&threads[thread_index], NULL, read_file_chunk, &file_pointer);
        process_chunk(md5_ctxs[i], (NFAPI_CRC_INDICATION_PDU_T **)&data[thread_index], 1);
    }

    if (filesize > chunks * chunk_size) {
        char *file_pointer = malloc(filesize - (chunks * chunk_size - 1));
        fread(file_pointer, sizeof(char), filesize - (chunks * chunk_size - 1), fp);
        pthread_create(&threads[chunks - 1], NULL, read_file_chunk, &file_pointer);
        process_chunk(md5_ctxs[chunks - 1], (NFAPI_CRC_INDICATION_PDU_T **)&data[chunks - 1], filesize - (chunks * chunk_size - 1) / sizeof(char));
    }

    for (size_t i = 0; i < chunks; ++i) {
        void *md5_result;
        pthread_join(threads[i], &md5_result);
        process_chunk(md5_result, (NFAPI_CRC_INDICATION_PDU_T **)&data[i * chunks], 1);
    }

    MD5_CTX final_ctx;
    MD5_Init(&final_ctx);
    for (size_t i = 0; i < data_size; ++i) {
        MD5_Update(&final_ctx, &data[i][0], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    char final_md5[33];
    sprintf(final_md5, "%s", MD5_Final(final_md5, &final_ctx));

    munmap(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * data_size);
    free(md5_ctxs);
    fclose(fp);

    log_system_metrics("System metrics after processing");

    printf("Final MD5: %s\n", final_md5);
    return 0;
}']

