import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import requests
from functools import lru_cache
import logging

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

METADATA_API_URL = "https://metadata-service.com/api"
MAX_WORKERS = 4
BATCH_SIZE = 100

def get_file_metadata(filepath):
    # Implement your service call here, using the given API URL as a placeholder
    pass

@lru_cache()
def _get_md5():
    m = hashlib.md5()
    return m

def compute_md5(filepath):
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(4096)
            if not chunk:
                break
            _get_md5().update(chunk)
    return _get_md5().hexdigest()

def process_directory(root, worker_count=MAX_WORKERS):
    file_hashes = {}
    processed_files = set()

    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        file_queue = [(filepath, compute_md5) for root, _, files in os.walk(root)]
        for i, (filepath, func) in enumerate(file_queue):
            if filepath not in processed_files:
                processed_files.add(filepath)
                try:
                    future = executor.submit(func, filepath)
                    result = future.result()
                except Exception as e:
                    logging.error(f'Error processing {filepath}: {e}')
                    continue

                metadata = get_file_metadata(filepath)
                if metadata is None:
                    logging.warning(f"Failed to retrieve metadata for file '{filepath}'.")
                else:
                    file_hashes[os.path.relpath(filepath, root)] = {
                        "md5": result,
                        "size": metadata["size"],
                        "last_modified": metadata["last_modified"]
                    }

                if (i + 1) % BATCH_SIZE == 0:
                    logging.info(f"Processed {len(file_hashes)} files.")

    return file_hashes
