int init_dynamic_array(NFAPI_CRC_INDICATION_PDU_T** arr, size_t* arr_size) {
    *arr = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!(*arr)) {
        perror("Calloc failed");
        return -1;
    }

    *arr_size = MAX_N;
    if (arr_size > MAX_N) {
        fprintf(stderr, "Requested size exceeds MAX_N\n");
        free(*arr);
        *arr = NULL;
        return -2;
    }

    for (size_t i = 0; i < *arr_size; ++i) {
        (*arr)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*arr)[i].RNTI = (i + time(NULL)) % 65535;
        (*arr)[i].CRC_INDICATION_REL8_TAG = rand() % 65535;
        (*arr)[i].CRCFLAG = rand() % 2;
    }

    return 0;
}

// Use this function to access the dynamic array, ensuring proper synchronization for concurrent threads
