    memcpy(arr, *((NFAPI_CRC_INDICATION_PDU_T**)__builtin_offsetof(*arr, arr[0])), sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_N);
    pthread_mutex_unlock(&array_mutex);

    return arr;
}
