NFAPI_CRC_INDICATION_PDU* list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static unsigned int capacity = 0, count = 0;

void nfapi_crc_indication_pdu_init(unsigned int init_capacity) {
    if (init_capacity == 0) {
        printf("Initial capacity must be greater than zero.\n");
        return;
    }
    if (capacity > 0) {
        free_list();
    }
    capacity = init_capacity;
    count = 0;
}

void *node_alloc() {
    void* ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

void free_list() {
    NFAPI_CRC_INDICATION_PDU *current, *next;
    pthread_mutex_lock(&list_mutex);
    for (current = list; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
    capacity = 0;
    count = 0;
    pthread_mutex_unlock(&list_mutex);
}

NFAPI_CRC_INDICATION_PDU* get_node() {
    if (count == capacity) {
        NFAPI_CRC_INDICATION_PDU *new_node = node_alloc();
        if (!new_node) return NULL;
        pthread_mutex_init(&new_node->mutex, NULL);
        new_node->next = NULL;
        return new_node;
    }
    NFAPI_CRC_INDICATION_PDU *node = list;
    list = node->next;
    pthread_mutex_lock(&node->mutex);
    pthread_mutex_unlock(&list_mutex);
    return node;
}

void add(RX_UE_INFORMATION_TAG tag, int rnti, CRC_INDICATION_REL8_TAG crc_indication, bool crcflag) {
    NFAPI_CRC_INDICATION_PDU *new_node = get_node();
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory\n");
        return;
    }
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication = crc_indication;
    new_node->crcflag = crcflag;
    pthread_mutex_lock(&new_node->mutex);
    new_node->next = list;
    list = new_node;
    if (++count == capacity) {
        NFAPI_CRC_INDICATION_PDU* temp = get_node();
        if (!temp) {
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&new_node->mutex);
            return;
        }
        temp->next = NULL;
    }
    pthread_mutex_unlock(&list_mutex);
}

bool update_by_rnti(int rnti, RX_UE_INFORMATION_TAG* new_tag, CRC_INDICATION_REL8_TAG* new_crc_indication) {
    bool found = false;
    NFAPI_CRC_INDICATION_PDU *current = list;
    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->rnti == rnti) {
            *new_tag = current->tag;
            *new_crc_indication = current->crc_indication;
            found = true;
            break;
        }
        current = current->next;
    }
    pthread_mutex_lock(&current->mutex);
    if (found) {
        // Update the structure here
        current->tag = *new_tag;
        current->crc_indication = *new_crc_indication;
    }
    pthread_mutex_unlock(&current->mutex);
    pthread_mutex_unlock(&list_mutex);
    return found;
}

bool remove_by_rnti(int rnti) {
    bool removed = false;
    NFAPI_CRC_INDICATION_PDU **prev, *current = list;
    pthread_mutex_lock(&list_mutex);
    while (current != NULL) {
        if (current->rnti == rnti) {
            removed = true;
            if (current == list) {
                list = current->next;
            } else {
                prev[0] = prev[1];
            }
            pthread_mutex_lock(&current->mutex);
            free(current);
            count--;
            pthread_mutex_unlock(&current->mutex);
            break;
        }
        prev[0] = prev[1] = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
    return removed;
}
