        lte_phy_mib_table_resize(table, table->capacity * TABLE_GROW_FACTOR);

    for (unsigned int i = 0; i < table->size; ++i) {
        if (table->data[i].identifier == entry->identifier) {
            // Handle duplicate identifier case, e.g., by overwriting or ignoring
            break;
        }
        if (!table->data[i].identifier) {
            table->data[i] = *entry;
            table->size++;
            break;
        }
    }

    pthread_mutex_unlock(&table->lock);
}

LTE_PHY_MIB_TABLE* lte_phy_mib_table_get(const struct table_data* table, unsigned int identifier) {
    LTE_PHY_MIB_TABLE* result = NULL;
    pthread_mutex_lock(&table->lock);

    for (unsigned int i = 0; i < table->size; ++i) {
        if (table->data[i].identifier == identifier) {
            result = &table->data[i];
            break;
        }
    }

    pthread_mutex_unlock(&table->lock);
    return result;
}

void lte_phy_mib_table_update(struct table_data* table, unsigned int identifier, void (*update_func)(LTE_PHY_MIB_TABLE*)) {
    LTE_PHY_MIB_TABLE* entry = lte_phy_mib_table_get(table, identifier);
    if (entry) update_func(entry);
}

// Periodic updates can be handled using a separate thread and an external data source
```

