typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 1000
#define MEMORY_THRESHOLD (system_memory / 2) // Adjust based on available system memory

NFAPI_CRC_INDICATION_PDU_T* structures;
pthread_mutex_t mutex;
bool is_running = true;
int error_code = 0;

void* generate_structures(void* arg) {
    srand((unsigned)time(NULL));

    for (int i = 0; i < MAX_STRUCTURES && error_code == 0; ++i) {
        int rnti = i;
        while (rnti + 1 < i && structures[rnti + 1].RNTI == structures[rnti].RNTI) {
            rnti = (rnti + 1) % MAX_STRUCTURES;
        }
        structures[rnti].RX_UE_INFORMATION_TAG = rand() % 0xFFFF;
        structures[rnti].RNTI = rnti;
        structures[rnti].CRC_INDICATION_REL8_TAG = rand() % 0xFFFF;
        structures[rnti].CRCFLAG = rand() % 2 == 0;

        pthread_mutex_lock(&mutex);
        if (i + 1 >= MAX_STRUCTURES || (long)structures - &structures[0] > MEMORY_THRESHOLD || clock() - start_time > TIMEOUT) {
            is_running = false;
            error_code = 1;
        }
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int generate_and_populate_structures(void) {
    if (posix_memalign((void**)&structures, 64, MAX_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0 ||
        pthread_mutex_init(&mutex, NULL) != 0) {
        error_code = -1;
        return error_code;
    }

    start_time = clock();
    pthread_t threads[MAX_STRUCTURES];

    for (int i = 0; i < MAX_STRUCTURES && is_running; ++i) {
        if (pthread_create(&threads[i], NULL, generate_structures, NULL) != 0) {
            error_code = -2;
            return error_code;
        }
    }

    for (int i = 0; i < MAX_STRUCTURES && is_running; ++i) {
        if (pthread_join(threads[i], NULL) != 0) {
            error_code = -3;
            return error_code;
        }
    }

    pthread_mutex_destroy(&mutex);
    free(structures);

    return error_code;
}
```

