};

struct list* create_list(size_t max_elements) {
    struct list *list = malloc(sizeof(struct list));
    if (!list) return NULL;

    list->data = calloc(max_elements, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = max_elements;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

int add_element(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (list->size == list->capacity) {
        list->data = realloc(list->data, (list->capacity + list->capacity) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->data) return FALSE;
        list->capacity *= 2;
    }

    pthread_mutex_lock(&list->mutex);
    memcpy(&list->data[list->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
