[' Here is a C implementation for the dynamic array management function using the doubly-linked list data structure with resizable heap allocation. This code provides an intuitive interface while considering resource management, performance constraints, integration issues, scalability, operational constraints, configuration flexibility, and usability.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    /* Replace with your actual structure fields */
    int id;
    char data[10];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct List {
    int size;
    int capacity;
    Node* head;
    Node* tail;
    Node* current;
} List;

List* create_list(int initial_size) {
    List *list = malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;
    list->current = NULL;
    list->size = 0;
    list->capacity = initial_size;
    list->head = malloc(sizeof(Node) * initial_size);
    if (!list->head) {
        perror("Failed to allocate memory for head node array");
        free(list);
        return NULL;
    }
    int i;
    for (i = 0; i < initial_size; ++i) {
        list->head[i].data = NULL;
        list->head[i].prev = &list->head[i - 1];
        list->head[i].next = &list->head[i + 1];
    }
    list->head[0].prev = &list->tail;
    list->head[initial_size - 1].next = &list->head[0];
    list->tail = &list->head[initial_size - 1];
    return list;
}

void resize(List* list, int new_capacity) {
    if (new_capacity <= list->size) return;
    Node *temp_head = malloc(sizeof(Node) * new_capacity);
    if (!temp_head) {
        perror("Failed to allocate memory for temporary head node array");
        return;
    }

    int i;
    for (i = 0; i < list->size; ++i) {
        temp_head[i].data = list->head[i].data;
        temp_head[i].prev = &temp_head[i - 1];
        temp_head[i].next = &temp_head[i + 1];
    }
    free(list->head);
    list->head = temp_head;
    Node* old_tail = &list->head[list->size - 1];
    list->head[new_capacity - 1].prev = old_tail;
    list->head[0].next = old_tail->next;
    old_tail->next->prev = &list->head[new_capacity - 1];
    list->capacity = new_capacity;
}

NFAPI_CRC_INDICATION_PDU_T* get(List* list) {
    if (list->current == NULL) {
        list->current = list->head;
        return &list->current->data[list->size % list->capacity];
    } else {
        ++list->size;
        list->current = list->current->next;
        return &list->current->data[list->size % list->capacity];
    }
}

void put(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (list->size == list->capacity) resize(list, 2 * list->capacity);
    list->current = &list->head[list->size];
    list->current->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->current->data) {
        perror("Failed to allocate memory for PDU data");
        return;
    }
    memcpy(list->current->data, &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_list(List* list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *next = current->next;
        if (current->data != NULL) free(current->data);
        free(current);
        current = next;
    }
    free(list);
}
```

