// Cache for frequently accessed data
#define CACHE_SIZE 1024
static struct cache_entry cache[CACHE_SIZE];
static int cache_index = 0;

void cache_put(void* data, time_t expiry) {
    if (cache_index >= CACHE_SIZE) return;
    cache[cache_index].data = data;
    cache[cache_index++].expiry = expiry;
}

void* cache_get(time_t now) {
    for (int i = 0; i < cache_index; ++i) {
        if (now >= cache[i].expiry && cache[i].data != NULL) {
            void* tmp = cache[i].data;
            cache[i].data = NULL;
            return tmp;
        }
    }
    return NULL;
}

