                if (response.getStatusCodeValue() == HttpStatus.OK.value()) {
                    break;
                } else {
                    retriesLeft--;
                }
            } catch (Exception e) {
                retriesLeft--;
            }
            if (retriesLeft > 0) {
                waitForRetry(retriesLeft);
            }
