    struct node* next;
} Node;

struct lock {
    pthread_rwlock_t rwlock;
    int size;
};

Node** init_list(int N) {
    if (N <= 0) return NULL;

    Node **array = malloc(N * sizeof(Node*));
    for (int i = 0; i < N; ++i) array[i] = NULL;
    struct lock *locks = calloc(N, sizeof(struct lock));

    return array;
}

void set_random_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->crc_indication.crcflag = rand() % 2;
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;

    node->data = data;
    set_random_crcflag(&node->data);
    node->next = NULL;

    return node;
}

void insert(Node** array, int idx, Node* new_node) {
    pthread_rwlock_wrlock(&array[idx]->lock.rwlock);

    if (!array[idx]) {
        array[idx] = new_node;
    } else {
        Node *current = array[idx];
        while (current->next) current = current->next;
        current->next = new_node;
    }

    pthread_rwlock_unlock(&array[idx]->lock.rwlock);
}

Node* lookup(Node** array, int idx, RX_UE_INFORMATION_TAG key) {
    pthread_rwlock_rdlock(&array[idx]->lock.rwlock);

    Node *current = array[idx];
    while (current && current->data.rx_ue_info != key) current = current->next;

    pthread_rwlock_unlock(&array[idx]->lock.rwlock);

    return current;
}

void destroy(Node **array, int N) {
    for (int i = 0; i < N; ++i) {
        Node *current = array[i];
        while (current) {
            Node *temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(array);
    free(array[N]);
}
