List* create_list(size_t max_elements) {
    List *list = malloc(sizeof(List));
    list->head = list->tail = NULL;
    list->size = 0;
    list->capacity = 1;
    list->max_elements = max_elements;
    sem_init(&list->mutex, 0, 1);
    return list;
}

void destroy_list(List *list) {
    Node *current, *next;

    sem_wait(&list->mutex);
    current = list->head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->size = 0;
    list->capacity = 0;
    sem_post(&list->mutex);
}

void resize_list(List *list) {
    if (list->size >= list->max_elements || list->capacity * 2 > INT_MAX / sizeof(Node))
