    new_node->data = *data;
    new_node->next = NULL;

    sem_wait(&list->mutex);
    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
    }
    sem_post(&list->mutex);
}

void* get_element(List *list, size_t index) {
