```c
#include "nfc_list.h"
#include <assert.h>
#include <time.h>

void nfc_list_init(nfc_list_t *list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&(list->mutex), NULL);
}

bool validate_crcflag(uint8_t crcflag) {
    return (crcflag >= 0 && crcflag <= 255);
}

NFAPI_CRC_INDICATION_PDU_T* generate_data() {
    static uint32_t rx_ue_information_tag = 1;
    static uint16_t rnti = 0;
    const uint8_t crcflag = (rand() % 256);

    assert(validate_crcflag(crcflag));

    rnti++;
    return (NFAPI_CRC_INDICATION_PDU_T){rx_ue_information_tag++, rnti, crcflag};
}

bool nfc_list_add_head(nfc_list_t *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    nfc_list_node_t* new_node = (nfc_list_node_t*)malloc(sizeof(nfc_list_node_t));
    new_node->data = *data;
    new_node->next = list->head;
    list->head = new_node;
    return true;
}

bool nfc_list_add_tail(nfc_list_t *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    nfc_list_node_t* new_node = (nfc_list_node_t*)malloc(sizeof(nfc_list_node_t));
    new_node->data = *data;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = new_node;
        list->tail = new_node;
    }

    return true;
}

bool nfc_list_remove_by_rnti(nfc_list_t *list, uint16_t rnti) {
    if (list->head == NULL) {
        return false;
    }

    pthread_mutex_lock(&(list->mutex));

    nfc_list_node_t* current = list->head;
    while (current != NULL) {
        if (current->data.RNTI == rnti) {
            if (current == list->head) {
                list->head = current->next;
            } else if (current->next == NULL) {
                list->tail = current->prev;
                current->prev->next = NULL;
            } else {
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }

            free(current);
            pthread_mutex_unlock(&(list->mutex));
            return true;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&(list->mutex));
    return false;
}

void nfc_list_clear(nfc_list_t *list) {
    pthread_mutex_lock(&(list->mutex));

    nfc_list_node_t* current = list->head;
    while (current != NULL) {
        nfc_list_node_t* next = current->next;
        free(current);
        current = next;
    }

    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&(list->mutex));
}

void nfc_list_destroy(nfc_list_t *list) {
    pthread_mutex_destroy(&(list->mutex));
    free(list);
}
