            metrics[i].signalStrength = data[i];
            metrics[i].snr = data[i + *count]; // Assuming SNR is at index *count and next metric at *(count+1)
            metrics[i].timingOffset = data[i + 2* *count]; // Continue the pattern for other metrics
            // ...
        } else {
            metrics[i].signalStrength = NAN; // Indicates invalid data if data is missing or inconsistent
        }
