CRCI indicationListCreate(size_t initialCapacity) {
    if (initialCapacity <= 0 || initialCapacity > 10000) {
        fprintf(stderr, "Initial capacity should be between 1 and 10000\n");
        return NULL;
    }

    CRCIndicationList* list = malloc(sizeof(CRCIndicationList));
    if (!list) {
        perror("malloc failed");
        return NULL;
    }

    list->data = malloc(initialCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        perror("malloc failed");
        free(list);
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void indicationListDestroy(CRCIndicationList* list) {
    if (!list) {
        return;
    }

    free(list->data);
    free(list);
}

int indicationListAdd(CRCIndicationList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (!list || !pdu) {
        return -1;
    }

    // Validate CRCFLAG value
    if (!(pdu->CRCFLAG)) {
        fprintf(stderr, "Invalid CRCFLAG value\n");
        return -1;
    }

    pthread_mutex_lock(&list->lock);

    // Resize if necessary
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* newData = realloc(list->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = newData;
        list->capacity = newCapacity;
    }

    // Add PDU to the list
    list->data[list->count++] = *pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
