['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
    pthread_mutex_t lock;
} Node;

static Node** array; // dynamic array pointer
static int capacity = 0, size = 0;
static pthread_mutex_t global_lock;
static unsigned long checksum = 0;

void generate_checksum(NFAPI_CRC_INDICATION_PDU_T* pdus, int len) {
    for (int i = 0; i < len; ++i) {
        checksum ^= pdus[i].RX_UE_INFORMATION_TAG;
        checksum += pdus[i].RNTI + pdus[i].CRC_INDICATION_REL8_TAG + (pdus[i].CRCFLAG ? 1 : 0);
    }
}

void init() {
    if (capacity) free(array);
    capacity = 32; // initial capacity
    size = 0;
    array = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i) array[i] = NULL;

    pthread_mutex_init(&global_lock, NULL);
}

void reset() {
    init();
    checksum = 0;
}

int index(uint16_t RNTI) {
    return (RNTI % capacity);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void add(NFAPI_CRC_INDICATION_PDU_T* pdus, int len) {
    generate_checksum(pdus, len);

    Node** current = array;
    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&current[index(pdus[i].RNTI)->lock]);
        if (!current[i]->next) {
            current[i]->next = create_node(*pdus++);
            if (current[i]->next == NULL) {
                printf("Out of memory\n");
                return;
            }
            pdus++;
            size++;
            if (size == capacity) {
                int new_capacity = capacity * 2;
                Node** tmp = realloc(array, new_capacity * sizeof(Node*));
                if (!tmp) {
                    printf("Out of memory\n");
                    return;
                }
                array = tmp;
                capacity = new_capacity;
            }
            break;
        } else {
            current = &current[i]->next;
        }
        pthread_mutex_unlock(&current[index(pdus->RNTI)->lock]);
    }

    if (!current[size]) {
        current[size] = create_node(*pdus);
        if (current[size] == NULL) {
            printf("Out of memory\n");
            return;
        }
        size++;
    }
}

void update(uint16_t RNTI, NFAPI_CRC_INDICATION_PDU_T data) {
    int index = index(RNTI);
    pthread_mutex_lock(&global_lock);
    Node** current = array + index;
    for (; *current && (*current)->data.RNTI != RNTI; current++) {}

    if (!*current) {
        printf("RNTI not found\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }

    generate_checksum(&data, 1);
    (*current)->data = data;
    pthread_mutex_unlock(&global_lock);
}

void remove(uint16_t RNTI) {
    int index = index(RNTI);
    pthread_mutex_lock(&global_lock);
    Node** current = array + index;
    for (; *current && (*current)->data.RNTI != RNTI; current++) {}

    if (!*current) {
        printf("RNTI not found\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }

    Node* tmp = *current;
    *current = tmp->next;
    free(tmp);
    size--;
    pthread_mutex_unlock(&global_lock);
}
```

