#define MAX_STRUCTURES 1000
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* structures;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    bool retransmit_needed;
    queue_t* retransmission_queue;
} CRC_INDICATOR_MANAGER_T;

CRC_INDICATOR_MANAGER_T* crc_indicator_manager_init(size_t initial_capacity, queue_t* retransmission_queue) {
    CRC_INDICATOR_MANAGER_T* manager = malloc(sizeof(CRC_INDICATOR_MANAGER_T));
    if (!manager) return NULL;

    manager->structures = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->structures) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->retransmit_needed = false;
    manager->retransmission_queue = retransmission_queue;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void crc_indicator_manager_free(CRC_INDICATOR_MANAGER_T* manager) {
    free(manager->structures);
    free(manager);
}

size_t crc_indicator_manager_resize(CRC_INDICATOR_MANAGER_T* manager, size_t new_capacity) {
    if (new_capacity <= manager->size) return 0;

    NFAPI_CRC_INDICATION_PDU_T* temp = realloc(manager->structures, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) return 0;

    manager->structures = temp;
    manager->capacity = new_capacity;
    return 1;
}

void crc_indicator_manager_add(CRC_INDICATOR_MANAGER_T* manager, const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (manager->size == manager->capacity) {
        if (!crc_indicator_manager_resize(manager, manager->capacity * 2)) {
            LOG_ERROR("Failed to resize CRCI manager array");
            return;
        }
    }

    manager->structures[manager->size] = *pdu;
    manager->structures[manager->size].crcflag = (rand() % 2) == 1; // randomly set CRCFLAG
    manager->size++;
}

void crc_indicator_manager_scan(CRC_INDICATOR_MANAGER_T* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->structures[i].crcflag) {
            LOG_INFO("CRC error detected, adding to retransmission queue");
            enqueue(manager->retransmission_queue, &manager->structures[i]);
        }
    }
    manager->retransmit_needed = false;
    pthread_mutex_unlock(&manager->lock);
}

void crc_indicator_manager_periodic_scan(CRC_INDICATOR_MANAGER_T* manager, time_t period) {
    while (true) {
        sleep(period);
        crc_indicator_manager_scan(manager);
    }
}

void crc_indicator_manager_retx_queue_process(CRC_INDICATOR_MANAGER_T* manager, retransmission_cb cb) {
    pthread_mutex_lock(&manager->lock);
    if (manager->retransmit_needed) {
        manager->retransmit_needed = false;

        NFAPI_CRC_INDICATION_PDU_T* item;
        while ((item = dequeue(manager->retransmission_queue))) {
            if (cb(item)) {
                LOG_INFO("Retransmission successful");
            } else {
                LOG_ERROR("Retransmission failed");
            }
        }
    }
    pthread_mutex_unlock(&manager->lock);
}
