typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node *next;
};

void *generate_rnti(void *arg) {
    pthread_mutex_lock((pthread_mutex_t *)arg);
    static uint32_t rnti = 1;
    uint32_t temp_rnti = rnti++;
    pthread_mutex_unlock((pthread_mutex_t *)arg);
    return temp_rnti;
}

struct node* create_list(int N, pthread_mutex_t *rnti_lock) {
    struct node *head = NULL, *temp = NULL;
    if (N <= 0 || N > 1000) {
        FILE *log_file = fopen("crc_indication_log.txt", "a");
        fprintf(log_file, "Error: Invalid input value %d, should be between 1 and 1000.\n", N);
        fclose(log_file);
        return NULL;
    }
    for (int i = 0; i < N; ++i) {
        pthread_t rnti_thread;
        void *rnti = pthread_malloc(&rnti_thread);
        pthread_create(&rnti_thread, NULL, generate_rnti, &rnti_lock);
        pthread_join(rnti_thread, &rnti);

        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        data->tag.tagValue = i + 1;
        data->rnti = *(uint32_t *)rnti;
        data->crc_indication.crcFlag = (rand() % 2) ? 1 : 0;

        if (!head) {
            head = temp = malloc(sizeof(struct node));
            head->data = data;
            head->next = NULL;
        } else {
            temp->next = malloc(sizeof(struct node));
            temp = temp->next;
            temp->data = data;
            temp->next = NULL;
        }
    }
    return head;
}

void free_list(struct node *head) {
    struct node *temp = head;
    while (head) {
        temp = head;
        head = head->next;
        free(temp);
    }
}
