// TCP header structure
typedef struct {
    in_addr_t src_ip;
    in_addr_t dest_ip;
    uint32_t sequence_number;
} PacketHeader;

// Dynamic array structure
typedef struct DynArray {
    PacketHeader *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} DynArray;

// Function to initialize the dynamic array with a given initial capacity
void dyn_array_init(DynArray *arr, size_t cap) {
    arr->data = malloc(cap * sizeof(PacketHeader));
    arr->capacity = cap;
    arr->count = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Function to check if the array is full
bool dyn_array_is_full(const DynArray *arr) {
    return arr->count == arr->capacity;
}

// Function to add a packet header to the dynamic array
void dyn_array_push(DynArray *arr, const PacketHeader *header) {
    if (dyn_array_is_full(arr)) {
        arr->capacity *= 2;
        arr->data = realloc(arr->data, arr->capacity * sizeof(PacketHeader));
    }
    pthread_mutex_lock(&arr->mutex);
    memcpy(&arr->data[arr->count], header, sizeof(PacketHeader));
    ++arr->count;
    pthread_mutex_unlock(&arr->mutex);
}

// Function to retrieve a packet header from the dynamic array
const PacketHeader *dyn_array_pop(DynArray *arr) {
    if (arr->count == 0) return NULL;

    const PacketHeader *ret = &arr->data[arr->count - 1];
    pthread_mutex_lock(&arr->mutex);
    --arr->count;
    memmove(arr->data, arr->data + 1, arr->count * sizeof(PacketHeader));
    pthread_mutex_unlock(&arr->mutex);

    return ret;
}

// Function to dynamically adjust the dynamic array based on subnet configuration changes
void dyn_array_adjust(DynArray *arr, const SubnetConfig *new_config) {
    // Implement your logic here for adjusting the array based on the new subnet configuration.
}
