#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <lrucache.h> // Includes lru_cache.h for the caching mechanism

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} node_t;

typedef struct list_t {
    int count;
    LRUCache *cache;
    pthread_mutex_t mutex;
    node_t *head, *tail;
} list_t;

list_t* create_list() {
    list_t *list = malloc(sizeof(list_t));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for the list.\n");
        return NULL;
    }

    list->count = 0;
    list->cache = lru_cache_new(10); // Initialize an LRU cache with a capacity of 10 items.
    pthread_mutex_init(&list->mutex, NULL);
    list->head = list->tail = NULL;
    return list;
}

int insert_node(list_t *list, node_t *new_node) {
    pthread_mutex_lock(&list->mutex);

    if (!list->count) { // If the list is empty
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    lru_cache_put(list->cache, new_node, NULL); // Add the newly inserted node to the cache.
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Other functions: traverse, delete, and free the list are omitted for brevity.
