    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t min_count;
    size_t max_count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *data;
} CRCI_POOL;

CRCI_POOL* crc_pool_init(size_t min_count, size_t max_count) {
    CRCI_POOL *pool = malloc(sizeof(CRCI_POOL));
    if (!pool) {
        perror("malloc");
        return NULL;
    }

    pool->min_count = min_count;
    pool->max_count = max_count;
    pthread_mutex_init(&pool->lock, NULL);

    size_t data_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_count;
    pool->data = malloc(data_size);
    if (!pool->data) {
        perror("malloc");
        free(pool);
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < min_count; ++i) {
        initialize_structure((NFAPI_CRC_INDICATION_PDU_T*)&pool->data[i]);
    }
    pthread_mutex_unlock(&pool->lock);

    return pool;
}

void* initialize_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pdu->tag.tag);
    pdu->tag = initialize_ue_information_tag(); // Implement this function to handle external data sources
    pdu->rnti = generate_rnti(); // Function to generate RNTI
    pdu->crc_indication.crcflag = rand() % 2;
    pthread_mutex_unlock(&pdu->tag.tag);
}

void crc_pool_free(CRCI_POOL *pool) {
    if (pool) {
        free(pool->data);
        pool->data = NULL;
        pthread_mutex_destroy(&pool->lock);
        free(pool);
        pool = NULL;
    }
}

NFAPI_CRC_INDICATION_PDU_T* crc_pool_acquire(CRCI_POOL *pool) {
    if (!pool || pool->data == NULL) return NULL;

    pthread_mutex_lock(&pool->lock);
    size_t current_count = pool->max_count - (pool->data + pool->max_count) % pool->max_count;
    if (current_count < pool->min_count) {
        for (size_t i = 0; i < pool->max_count - current_count; ++i) {
            initialize_structure((NFAPI_CRC_INDICATION_PDU_T*)&pool->data[i]);
        }
    }

