#include <stdio.h>
#include <stdlib.h>

typedef struct {
    TASK_TYPE task_type;
    uint32_t sequence_number;
    int tx_power_level;
} PHY_TASK_REQUEST;

struct pool {
    PHY_TASK_REQUEST* requests;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

struct pool* create_pool() {
    struct pool* pool = malloc(sizeof(struct pool));
    if (!pool) {
        perror("Error allocating pool memory");
        exit(EXIT_FAILURE);
    }
    pool->requests = NULL;
    pool->capacity = 0;
    pool->count = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void destroy_pool(struct pool* pool) {
    free(pool->requests);
    pool->requests = NULL;
    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}

bool push_request(struct pool* pool, PHY_TASK_REQUEST request) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->count >= pool->capacity && pool->capacity < 5120) {
        resize_pool(pool, pool->capacity * 2);
    }

    if (pool->count >= 5120) {
        printf("Error: Maximum number of active requests exceeded\n");
        return false;
    }

    PHY_TASK_REQUEST* next = &pool->requests[pool->count];
    *next = request;
    pool->count++;

    pthread_mutex_unlock(&pool->mutex);
    return true;
}

void resize_pool(struct pool* pool, size_t new_capacity) {
    PHY_TASK_REQUEST* new_requests = realloc(pool->requests, new_capacity * sizeof(PHY_TASK_REQUEST));
    if (!new_requests) {
        perror("Error reallocating requests array");
        exit(EXIT_FAILURE);
    }
    pool->requests = new_requests;
    pool->capacity = new_capacity;
}
```

