pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t total_allocated = 0;

void init_struct(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    struct_ptr->rx_ue_information_tag = (RX_UE_INFORMATION_TAG)(rand() % DATA_SOURCE_VARIABILITY);
    struct_ptr->rnti = (RNTI)(rand() % ((1 << 24) - 1));
