    while (N > 0) {
        if (threadCount >= MAX_THREADS) {
            usleep(1000 / MAX_THREADS); // Rate-limiting strategy
        }

        pthread_create(&threads[threadCount], NULL, worker, &N);
        threadCount++;
        N--;
    }

    for (int i = 0; i < threadCount; ++i) {
        pthread_join(threads[i], NULL);
    }

    if (!mprotect(structures, totalStructuresAllocated * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ)) { // Check for inconsistent CRCFLAG values
        NFAPI_CRC_INDICATION_PDU_T* current = structures;
        bool invalidFlagFound = false;
        for (int i = 0; i < totalStructuresAllocated; ++i) {
            if ((current->crcIndication.crcFlag != (current[i+1].crcIndication.crcFlag ^ (rand() % 2)) & 1)) {
                invalidFlagFound = true;
                break;
            }
            current++;
        }

        if (invalidFlagFound) {
            logger->error("Detected inconsistent CRCFLAG values. Freeing memory and exiting...");
            munmap(structures, totalStructuresAllocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            return -1;
        }
    }

    logger->info("Processed " << totalStructuresAllocated << " structures");
    munmap(structures, totalStructuresAllocated * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Free memory after validation and logging
    return 0;
}
```

