    #include <stdio.h>
    #include <stdlib.h>
    #include <time.h>
    #include <pthread.h>
    #include <semaphore.h>

    // Third-party logging library (potentially unreliable)
    #include "third_party_log.h"

    // Internal logging function
    void log_internal(const char *msg) {
        printf("[INTERNAL] %s\n", msg);
    }

    typedef struct LTE_Uplink_NAS_Transport_T {
        NAS_MESSAGE_T nas_message;
        LOGICAL_CHANNEL_GROUP Identity;
    } LTE_Uplink_NAS_Transport_T;

    // Rate limiter structure
    struct rate_limiter {
        sem_t semaphore;
        unsigned int attempts_per_second;
    };

    void init_rate_limiter(struct rate_limiter *limiter, unsigned int attempts_per_second) {
        sem_init(&limiter->semaphore, 0, attempts_per_second);
        limiter->attempts_per_second = attempts_per_second;
    }

    int try_acquire(struct rate_limiter *limiter) {
        if (sem_trywait(&limiter->semaphore) == 0) {
            return 1;
        }
        return 0;
    }

    LTE_Uplink_NAS_Transport_T *init_nas_transport(struct rate_limiter *limiter, size_t max_entries) {
        static LTE_Uplink_NAS_Transport_T cache[128]; // Cache for frequently accessed instances
        static unsigned int cache_size = 0;
        static unsigned int cache_index = 0;

        if (try_acquire(limiter)) {
            LTE_Uplink_NAS_Transport_T *transport = NULL;

            // Attempt to reuse cached instance
            if (cache_size > 0 && cache_index < cache_size) {
                transport = &cache[cache_index++];
                cache_size--;
            }

            // Failed to reuse cached instance, allocate a new one
            if (!transport) {
                if (max_entries <= cache_size) {
                    max_entries -= cache_size;
                    transport = &cache[cache_size--];
                } else {
                    transport = malloc(max_entries * sizeof(*transport));
                    if (!transport) {
                        log_internal("Failed to allocate memory for new instances");
                        return NULL;
                    }
                    max_entries = static_cast<size_t>(sizeof(transport) / sizeof(*transport));
                }
            }

            // Generate random data for the NAS message and logical channel group identity
            transport->nas_message.type = rand() % (1 << 24);
            transport->Identity = rand() % 256;

            // Release rate limiter semaphore
            sem_post(&limiter->semaphore);

            return transport;
        }

        return NULL;
    }

    void deinit_nas_transport(LTE_Uplink_NAS_Transport_T *transport) {
        if (transport == &cache[cache_index]) {
            cache_size++;
        } else {
            free(transport);
        }
    }

    // Main function to initialize and populate the array of structures.
    void init_array(LTE_Uplink_NAS_Transport_T **array, size_t max_entries) {
        *array = calloc(max_entries, sizeof(**array));

        if (*array == NULL) {
            log_internal("Failed to allocate memory for array");
            return;
        }

        struct rate_limiter limiter;
        init_rate_limiter(&limiter, 10); // Set an appropriate rate limit based on system behavior

        size_t num_entries = 0;
        for (size_t i = 0; i < max_entries && num_entries < max_entries; ++i) {
            LTE_Uplink_NAS_Transport_T *transport = init_nas_transport(&limiter, max_entries);

            if (transport != NULL) {
                (*array)[num_entries++] = transport;
            }
        }
    }

    // Third-party logging library (potentially unreliable)
    #include "third_party_log.h"

    void third_party_log(const char *msg) {
        if (is_network_stable()) {
            log(msg);
        } else {
            log_internal(msg);
        }
    }
```
