typedef struct {
    uint32_t rxiit;
    uint16_t rnti;
    uint16_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

struct memory_block {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
};

struct memory_manager {
    struct memory_block* memory_pool;
    size_t num_blocks;
    size_t max_entries;
};

void* memory_manager_init(size_t max_entries) {
    struct memory_manager* mm = malloc(sizeof(struct memory_manager));
    if (!mm) return NULL;
    mm->max_entries = max_entries;
    size_t block_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_entries;
    mm->num_blocks = 1 + (max_entries - 1) / (1024 * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mm->memory_pool = calloc(mm->num_blocks, sizeof(struct memory_block));
    if (!mm->memory_pool) {
        free(mm);
        return NULL;
    }

    for (size_t i = 0; i < mm->num_blocks; ++i) {
        struct memory_block* block = &mm->memory_pool[i];
        block->capacity = 1024 * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        block->size = 0;
        block->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(block->capacity);
        if (!block->data) {
            for (size_t j = 0; j < i; ++j) free(mm->memory_pool[j].data);
            free(mm->memory_pool);
            free(mm);
            return NULL;
        }
    }
    return mm;
}

void memory_manager_deinit(struct memory_manager* mm) {
    for (size_t i = 0; i < mm->num_blocks; ++i) free(mm->memory_pool[i].data);
    free(mm->memory_pool);
    free(mm);
}

NFAPI_CRC_INDICATION_PDU_T* memory_manager_alloc(struct memory_manager* mm) {
    if (mm->size + 1 >= mm->capacity) {
        size_t new_capacity = mm->capacity * 2;
        for (size_t i = 0; i < mm->num_blocks; ++i) {
            struct memory_block* block = &mm->memory_pool[i];
            if (block->capacity >= new_capacity) break;
            block->capacity *= 2;
        }
        for (size_t i = mm->num_blocks; i < mm->num_blocks + (new_capacity - mm->capacity) / sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
            struct memory_block* block = &mm->memory_pool[i];
            block->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(mm->memory_pool[i-1].data + mm->memory_pool[i-1].size, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (block->capacity - mm->memory_pool[i-1].size));
            if (!block->data) {
                memory_manager_deinit(mm);
                return NULL;
            }
            block->size = 0;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* data = mm->memory_pool[mm->size].data + mm->memory_pool[mm->size].size++;
    return data;
}

void log_error(const char* message) {
