int create_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t n, struct memory_manager* mm) {
    *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) return -1;

    int valid_entries = 0, duplicate_entries = 0;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = memory_manager_alloc(mm);
        if (!entry) {
            free(*list);
            *list = NULL;
            log_error("Failed to allocate memory for CRCI PDU list");
            return -1;
        }

        uint32_t rxiit = (uint32_t)(rand() % 0x7FFFFFFF + 1);
        entry->rxiit = rxiit;
        entry->rnti = (uint16_t)(rand() % 0x7FFFFF + 1);
        entry->crcflag = rand() % 2;

        pthread_mutex_lock(&lock);
        for (size_t j = 0; j < i; ++j) {
            if ((*list)[j].rnti == entry->rnti) {
                duplicate_entries++;
                free(entry);
                pthread_mutex_unlock(&lock);
                continue;
            }
        }
        pthread_mutex_unlock(&lock);

        if (duplicate_entries > 0) continue;
        valid_entries++;
    }

    printf("Created list with %d valid and %d duplicate entries.\n", valid_entries, duplicate_entries);
    return 0;
}
