    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU;

NFAPI_CRC_INDICATION_PDU* create_list(size_t size) {
    if (size > 1000) {
        fprintf(stderr, "Error: Size exceeds maximum limit of 1000 elements\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU *head = NULL, *current = NULL, *temp;
    for (size_t i = 0; i < size; ++i) {
        temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!temp) {
            fprintf(stderr, "Error: Memory allocation failure\n");
            return NULL;
        }
        temp->next = NULL;

        // Generate unique RNTI values and random CRCFLAG
        temp->rnti = i + 1;
        temp->crc_indication_rel8_tag.crcflag = (uint8_t)(rand() % 2);

        if (!head) {
            head = temp;
            current = head;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    return head;
}
