    pthread_mutex_lock(&mutex);
    if (count >= capacity && custom_memmanager_expand_pool(sizeof(TSN_DATA_UNIT) * 2)) {
        capacity += sizeof(TSN_DATA_UNIT) * 2;
    }

    bool is_duplicate = false;
    for (size_t i = 0; i < count; ++i) {
        if (list[i].PID == packet->PID) {
            is_duplicate = true;
            break;
        }
    }

    if (!is_duplicate && (packet->PID >= 0x1 && packet->PID <= 0xFFFF)) {
