void init_array() {
    if (arr_capacity > 0) return; // array is already initialized

    arr_capacity = INITIAL_ARRAY_CAPACITY;
    rrc_instances = mmap(NULL, arr_capacity * sizeof(LTE_ENB_RRC_INST_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (rrc_instances == MAP_FAILED) {
