LTE_ENB_RRC_INST_T* create_instance() {
    sem_wait(&buffer_sem); // wait for a free buffer

    if (arr_size == arr_capacity) {
        if (arr_capacity == 0) arr_capacity = GROWTH_FACTOR;
        rrc_instances = realloc(rrc_instances, arr_capacity * sizeof(LTE_ENB_RRC_INST_T));
