            exit(EXIT_FAILURE);
        }
    }

    LTE_ENB_RRC_INST_T* inst = &rrc_instances[arr_size];
    ++arr_size;
    sem_post(&buffer_sem); // signal that a new buffer is available

    init_instance(inst);

    return inst;
}

