        inst->sib1_buf = realloc(inst->sib1_buf, len + inst->sib1_len * GROWTH_FACTOR);
        if (!inst->sib1_buf) {
            perror("realloc");
            pthread_mutex_unlock(&array_mutex);
            exit(EXIT_FAILURE);
        }
    }

    memcpy(inst->sib1_buf + inst->sib1_len, content, len);
    inst->sib1_len += len;

    pthread_mutex_unlock(&array_mutex);
}

void free_instance(LTE_ENB_RRC_INST_T* inst) {
    pthread_mutex_lock(&array_mutex);

    free(inst->ue_context);
    munmap(inst->sib1_buf, inst->sib1_len); // release the buffer associated with SIB1
