typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTURES 5
#define RNTI_RANGE_START 0x0001
#define RNTI_RANGE_END 0x7FFF

sem_t memory_semaphore;
pthread_mutex_t log_mutex;

void log(const char *message) {
    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    printf("%s: %s\n", timestamp, message);
    pthread_mutex_unlock(&log_mutex);
}

bool next_crcflag() {
    static uint32_t crcflag = 0;
    uint32_t next = ++crcflag;

    if (next >= UINT32_MAX) {
        log("Warning: Reached maximum CRCFLAG value, resetting to 1.");
        next = 1;
    }

    return next != crcflag - 1;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_structures(size_t count, uint32_t seed) {
    srandom(seed);

    if (posix_memalign((void **)&structures, 64, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count)) {
        log("Error: Failed to allocate memory for structures.");
        return NULL;
    }

    sem_init(&memory_semaphore, 0, count);

    size_t allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T *current = structures;
    while (allocated < count) {
        current->tag = RX_UE_INFORMATION_TAG(random() % MAX_STRUCTURES + 1);
        current->rnti = (uint16_t)(RNTI_RANGE_START + random() % (RNTI_RANGE_END - RNTI_RANGE_START + 1));
        current->crc_indication.value = next_crcflag();
        allocated++;
        current++;

        sem_wait(&memory_semaphore);
    }

    return structures;
}

void deallocate_structures(NFAPI_CRC_INDICATION_PDU_T *structures, size_t count) {
    free(structures);
    sem_destroy(&memory_semaphore);
}
```
