static CACHE_NODE *cache = NULL;
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static int max_cache_entries = 100;

NFAPI_CRC_INDICATION_PDU_T* populate_crc_indications(int N) {
    if (N <= 0) {
        perror("Invalid number of entries");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!indications) {
        perror("Memory allocation failure");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        indications[i].tag.length = sizeof(RX_UE_INFORMATION_TAG);
        indications[i].tag.value[0] = '\0';

        indications[i].rnti = rand() % 65536;

        indications[i].crc_indication.length = sizeof(CRC_INDICATION_REL8_TAG);
        indications[i].crc_indication.value[0] = rand() % (1 << 24);
    }

    pthread_mutex_lock(&cache_mutex);
    CACHE_NODE *current = cache, *new_node;
    while (current && current->timestamp + max_cache_entries > time(NULL)) {
        new_node = malloc(sizeof(CACHE_NODE));
        if (!new_node) {
            perror("Memory allocation failure");
            pthread_mutex_unlock(&cache_mutex);
            return indications;
        }
        new_node->data = indications;
        new_node->timestamp = time(NULL);
        new_node->next = NULL;

        if (!cache) {
            cache = new_node;
        } else {
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
        pthread_mutex_unlock(&cache_mutex);

        break;
    }
    pthread_mutex_unlock(&cache_mutex);

    return indications;
}

void unit_test() {
    populate_crc_indications(1000); // Test large number of entries
    populate_crc_indications(-1);   // Test invalid number of entries
    // Add more test cases to cover edge cases and performance under various load scenarios.
}
