#define MAX_ARRAY_GROWTH 1024
static size_t num_elements = 0;
static size_t capacity = 0;
static NFAPI_CRUC_INDICATION_PDU_T* array = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
static pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void enqueue(NFAPI_CRC_INDICATION_PDU_T element) {
    if (num_elements >= capacity) {
        if (capacity + MAX_ARRAY_GROWTH <= num_elements * 2) {
            // Handle memory allocation failure gracefully
            perror("Memory allocation failed");
            return;
        }

        capacity += MAX_ARRAY_GROWTH;
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            perror("Memory allocation failed");
            return;
        }
        array = new_array;
    }

    pthread_mutex_lock(&mutex);
    while (num_elements == capacity) {
        pthread_cond_wait(&not_full, &mutex);
    }

    element.crcflag = (rand() % 2) ? true : false; // Set CRCFLAG based on standard IP packet filtering rules
    array[num_elements++] = element;
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&not_empty);
}

bool dequeue(NFAPI_CRC_INDICATION_PDU_T* out) {
    pthread_mutex_lock(&mutex);
    while (num_elements == 0) {
        pthread_cond_wait(&not_empty, &mutex);
    }

    *out = array[--num_elements];
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&not_full);
    return true;
}
