// Function to manage state transitions within an FSA
FSA* fsa_transition(const uint32_t* states, const uint32_t num_states, const FSA* transition_rules, void (*action)(uint32_t), uint32_t last_state) {
    // Allocate memory for the new state list and initial state
    FSA* new_fsa = (FSA*)malloc(sizeof(FSA) + num_states * sizeof(uint32_t));
    if (!new_fsa) return NULL;

    // Initialize the new state list with the initial state
    new_fsa->next = 0;
    uint32_t* states_ptr = new_fsa->states;
    *states_ptr++ = last_state;

    // Lazy load the states as needed, using a hash table for fast lookups and minimal memory usage
    uint32_t* state_hash[NUM_HASH_BUCKETS];
    uint32_t num_loaded = 0;

    for (uint32_t i = 0; i < num_states; ++i) {
        // If the current state is not already loaded, load it and update its 'next' pointer to point to the new state list
        if (!state_hash[current_state % NUM_HASH_BUCKETS][i]) {
            state_hash[current_state % NUM_HASH_BUCKETS][i] = &states[i];

            // Allocate memory for the loaded state and initialize its 'next' pointer
            uint32_t* loaded_state = (uint32_t*)malloc(sizeof(uint32_t) + num_states * sizeof(uint32_t));
            if (!loaded_state) {
                // Free all previously loaded states and return NULL if insufficient memory is available
                for (uint32_t j = 0; j < num_loaded; ++j) free(state_hash[j]);
                free(new_fsa);
                return NULL;
            }

            loaded_state[0] = i; // Initialize the loaded state with its index

            uint32_t* loaded_states_ptr = loaded_state + 1;
            *loaded_states_ptr++ = transition_rules->start_states[i];

            for (uint32_t j = 0; j < num_states; ++j) {
                if (transition_rules->transitions[i][j] != FSA_NO_TRANSITION) {
                    *loaded_states_ptr++ = transition_rules->transitions[i][j];
                }
            }

            *loaded_states_ptr = 0; // Set the 'next' pointer of the last state in the loaded state list to NULL

            num_loaded++;
        }

        // Update the current state pointer and perform any necessary actions on the loaded state
        states_ptr = state_hash[current_state % NUM_HASH_BUCKETS][*states_ptr];
    }

    action(last_state); // Perform the action associated with the initial state

    // Update the 'next' pointer of the last state in the current state list to point to the new state list
    new_fsa->states[num_states - 1] = num_loaded;

    return new_fsa;
}

