#include <boost/archive/binary_iarchive.hpp>
#include <boost/archive/binary_oarchive.hpp>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRC_INDICATION_REL8_TAG;
    std::vector<bool> CRC_FLAGS; // Flag array of size N representing received signals

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & RX_UE_INFORMATION_TAG & RNTI & CRC_INDICATION_REL8_TAG & CRC_FLAGS;
    }
};

std::shared_ptr<NFAPI_CRC_INDICATION_PDU_T[]> createAndSerializePDUs(unsigned int numUsers, unsigned int signalStrengthVariation = 3, bool useCompression = true) {
    using namespace std;
    using namespace boost;
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(0, signalStrengthVariation);

    auto pduArray = make_shared<NFAPI_CRC_INDICATION_PDU_T[]>(numUsers);

    for (auto& pdus : *pduArray) {
        pdus.RX_UE_INFORMATION_TAG = rand();
        pdus.RNTI = rand() % 0xFFFF;
        pdus.CRC_INDICATION_REL8_TAG = (rand() % 2) == 1; // 50% chance of true
        pdus.CRC_FLAGS.resize(dis(gen));
        generate(pdus.CRC_FLAGS.begin(), pdus.CRC_Flags.end(), [&](){ return rand() % 2; });
    }

    ostringstream os;
    bool_serialization::oarchive ar(os, useCompression ? BOOST_SERIALIZATION_OARCHIVE_NO_CLASS_DETAIL | boost::serialization::protocol_version<1> : BOOST_SERIALIZATION_OARCHIVE_PROTOTYPE);
    for (const auto& pdus : *pduArray) {
        ar & pdus;
    }
    ar.close();

    return pduArray;
}
