MemoryPool* create_memory_pool(size_t capacity, size_t element_size) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    pool->capacity = capacity;
    pool->used = 0;
    pool->element_size = element_size;
    pool->storage = malloc(capacity * element_size);
    return pool;
}

void* memory_pool_allocate(MemoryPool* pool) {
    if (pool->used < pool->capacity) {
        void* result = pool->storage + pool->used * pool->element_size;
        pool->used++;
        return result;
    }
    return NULL;
}

