#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct NetworkEvent {
    time_t timestamp;
    enum EventType { NETWORK_EVENT_TYPE_Unknown, NETWORK_EVENT_TYPE_Connect, NETWORK_EVENT_TYPE_Disconnect, NETWORK_EVENT_TYPE_Data } event_type;
    size_t payload_size;
    char *metadata;
} NetworkEvent;

typedef struct EventPool {
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventPool;

void init_event_pool(EventPool *pool, size_t initial_capacity) {
    pool->events = malloc(initial_capacity * sizeof(NetworkEvent));
    if (!pool->events) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    pool->capacity = initial_capacity;
    pool->count = 0;
    memset(pool->events, 0, initial_capacity * sizeof(NetworkEvent));

    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_event_pool(EventPool *pool) {
    free(pool->events);
    pthread_mutex_destroy(&pool->lock);
}

size_t get_next_index(const EventPool *pool) {
    return pool->count % pool->capacity;
}

NetworkEvent* find_event_by_timestamp(const EventPool *pool, time_t timestamp) {
    for (size_t i = 0; i < pool->count; ++i) {
        if (pool->events[i].timestamp == timestamp) {
            return &pool->events[i];
        }
    }
    return NULL;
}

void add_event(EventPool *pool, time_t timestamp, enum EventType event_type, size_t payload_size, const char *metadata) {
    NetworkEvent* new_event = &pool->events[get_next_index(pool)];
    new_event->timestamp = timestamp;
    new_event->event_type = event_type;
    new_event->payload_size = payload_size;
    if (metadata) {
        new_event->metadata = strdup(metadata);
    } else {
        new_event->metadata = NULL;
    }
    ++pool->count;
}

void update_payload(EventPool *pool, time_t timestamp, const void *new_payload, size_t payload_size) {
    NetworkEvent* event = find_event_by_timestamp(pool, timestamp);
    if (event) {
        free(event->metadata);
        event->payload_size = payload_size;
        event->metadata = malloc(payload_size);
        memcpy(event->metadata, new_payload, payload_size);
    } else {
        fprintf(stderr, "Cannot find event with timestamp %ld\n", timestamp);
    }
}

void clean_inactive_events(EventPool *pool) {
    time_t now = time(NULL);
    size_t delete_index = 0;
    for (size_t i = 0; i < pool->count; ++i) {
        if (now - pool->events[i].timestamp > 60 * 60 * 24) { // 1 day timeout
            NetworkEvent* event = &pool->events[delete_index];
            memmove(&event, &pool->events[i], sizeof(NetworkEvent));
            ++delete_index;
        } else {
            delete_index++;
        }
    }
    pool->count -= (pool->count - delete_index);
}
```

