} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} node_t;

node_t* create_new_node(NFAPI_CRUC_INDICATION_PDU_T data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void insert_node(node_t** head_ref, NFAPI_CRUC_INDICATION_PDU_T data) {
    node_t* current = *head_ref;
    node_t* new_node = create_new_node(data);

    if (current == NULL) {
        *head_ref = new_node;
        return;
    }

    pthread_mutex_lock(&new_node->lock);
    pthread_mutex_lock(&current->lock);

    while (current->next != NULL && current->next->data.rnti == data.rnti) {
        current = current->next;
    }

    if (current->next == NULL || current->next->data.rnti != data.rnti) {
        new_node->next = current->next;
        current->next = new_node;
    } else {
        new_node->data.crc_indication_tag = CRC_ERROR_TAG;
        free(new_node);
    }

    pthread_mutex_unlock(&current->lock);
    pthread_mutex_unlock(&new_node->lock);
}

