#include <netinet/in.h> // for sockaddr_in and in_port_t

typedef struct {
    time_t timestamp;
    int event_type;
    size_t payload_size;
    struct sockaddr_in source_ip;
    struct sockaddr_in destination_ip;
    pthread_mutex_t id_lock; // Lock for unique ID generation
    long id; // Unique event ID
} NetworkEvent;

struct NetworkEvents {
    NetworkEvent* events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

NetworkEvents* new_network_events(size_t initial_capacity) {
    NetworkEvents* ne = malloc(sizeof(NetworkEvents));
    if (!ne) return NULL;

    ne->events = calloc(initial_capacity, sizeof(NetworkEvent));
    if (!ne->events) {
        free(ne);
        return NULL;
    }

    ne->capacity = initial_capacity;
    ne->size = 0;
    pthread_mutex_init(&ne->lock, NULL);

    return ne;
}

void delete_network_events(NetworkEvents* ne) {
    free(ne->events);
    free(ne);
}

static void resize(NetworkEvents* ne) {
    if (ne->size >= ne->capacity) {
        size_t new_capacity = ne->capacity * 2;
        NetworkEvent* temp = realloc(ne->events, new_capacity * sizeof(NetworkEvent));
        if (!temp) return; // Failed to allocate memory, handle gracefully
        ne->events = temp;
        ne->capacity = new_capacity;
    }
}

NetworkEvent* find_event_by_timestamp(const NetworkEvents* ne, time_t timestamp) {
    for (size_t i = 0; i < ne->size; ++i) {
        if (ne->events[i].timestamp == timestamp)
            return &ne->events[i];
    }
    return NULL;
}

NetworkEvent* add_event(NetworkEvents* ne, const NetworkEvent* event) {
    pthread_mutex_lock(&ne->lock);
    resize(ne);
    *(&ne->events[ne->size]) = *event;
    ++ne->size;
    pthread_mutex_unlock(&ne->lock);

    return &ne->events[ne->size - 1]; // Return the newly added event
}

NetworkEvent* update_payload(NetworkEvents* ne, long id, size_t new_payload_size) {
    NetworkEvent* event = find_event_by_id(ne, id);
    if (!event) return NULL;

    pthread_mutex_lock(&event->id_lock);
    event->payload_size = new_payload_size;
    pthread_mutex_unlock(&event->id_lock);

    return event;
}

NetworkEvent* delete_event(NetworkEvents* ne, long id) {
    NetworkEvent* event = find_event_by_id(ne, id);
    if (!event) return NULL;

    pthread_mutex_lock(&ne->lock);
    // Remove the event from the array and decrement the size
    memmove(&event[0], &event[1], (ne->size - 1) * sizeof(NetworkEvent));
    --ne->size;
    pthread_mutex_unlock(&ne->lock);

    return event;
}

NetworkEvent* find_event_by_id(const NetworkEvents* ne, long id) {
    pthread_mutex_lock(&ne->lock);
    for (size_t i = 0; i < ne->size; ++i) {
        if (ne->events[i].id == id) {
            pthread_mutex_unlock(&ne->lock);
            return &ne->events[i];
        }
    }
    pthread_mutex_unlock(&ne->lock);
    return NULL;
}
