typedef struct {
    time_t timestamp;
    int user_id;
    int status;
} Message;

struct message_queue {
    Message* data;
    size_t capacity;
    size_t length;
    pthread_mutex_t lock;
};

struct message_queue* create_message_queue(size_t initial_capacity) {
    struct message_queue* queue = malloc(sizeof(struct message_queue));
    if (!queue) return NULL;

    queue->data = calloc(initial_capacity, sizeof(Message));
    if (!queue->data) {
        free(queue);
        return NULL;
    }

    queue->capacity = initial_capacity;
    queue->length = 0;
    pthread_mutex_init(&queue->lock, NULL);

    return queue;
}

void destroy_message_queue(struct message_queue* queue) {
    free(queue->data);
    free(queue);
}

void resize_message_queue(struct message_queue* queue) {
    Message* temp = realloc(queue->data, (queue->capacity *= 2) * sizeof(Message));
    if (!temp) return;

    queue->data = temp;
}

int add_message(struct message_queue* queue, time_t timestamp, int user_id, int status) {
    pthread_mutex_lock(&queue->lock);

    if (queue->length >= queue->capacity) resize_message_queue(queue);

    Message* msg = &queue->data[queue->length++];
    msg->timestamp = timestamp;
    msg->user_id = user_id;
    msg->status = status;

    pthread_mutex_unlock(&queue->lock);

    return 0; // Successful addition
}

void update_message(struct message_queue* queue, int user_id, time_t timestamp, int status) {
    pthread_mutex_lock(&queue->lock);

    for (size_t i = 0; i < queue->length; ++i) {
        if (queue->data[i].user_id == user_id) {
            queue->data[i].timestamp = timestamp;
            queue->data[i].status = status;
            break;
        }
    }

    pthread_mutex_unlock(&queue->lock);
}

Message* find_message(struct message_queue* queue, time_t start, time_t end) {
    Message* result = NULL;
    pthread_mutex_lock(&queue->lock);

    for (size_t i = 0; i < queue->length && queue->data[i].timestamp <= end; ++i) {
        if (queue->data[i].timestamp >= start && queue->data[i].timestamp <= end) result = &queue->data[i];
    }

    pthread_mutex_unlock(&queue->lock);

    return result;
}
