} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

struct list {
    struct node* head;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
};

void init_list(struct list* list) {
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void push(struct list* list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = malloc(sizeof(struct node));

    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->size == list->head) {
        struct node* temp = list->head;
        while (temp->next && list->size < N + M) {
            temp = temp->next;
        }

        if (list->size < N + M) {
            while (temp->next) {
                temp = temp->next;
            }
            temp->next = new_node;
            list->size++;
        } else {
            free(new_node);
            pthread_mutex_unlock(&list->mutex);
            printf("List is full\n");
        }
    } else {
        new_node->next = list->head;
        list->head = new_node;
        list->size++;
    }

    pthread_mutex_unlock(&list->mutex);
    pthread_cond_signal(&list->cond);
}

void pop(struct list* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == 0) {
        pthread_mutex_unlock(&list->mutex);
        *data = (NFAPI_CRC_INDICATION_PDU_T){0};
        return;
    }

    struct node* temp = list->head;
    list->head = temp->next;
    *data = temp->data;
    free(temp);
    list->size--;

    pthread_mutex_unlock(&list->mutex);
}

// Function to validate and convert the data for seamless integration with the existing network management system

void garbage_collect(struct list* list) {
    pthread_mutex_lock(&list->mutex);

    struct node* temp = list->head;
    while (temp != NULL) {
        if (!temp->data.CRC_INDICATION_REL8_TAG || !temp->data.RX_UE_INFORMATION_TAG || !temp->data.RNTI) {
            struct node* to_free = temp;
            temp = temp->next;
            free(to_free);
        } else {
            temp = temp->next;
        }
    }

    pthread_mutex_unlock(&list->mutex);
}
