// Function to generate a unique S-TMSI within the given range
uint32_t generateUniqueS_TMSI(RRC_MESSAGES_MANAGER_T *manager) {
    uint32_t max = manager->capacity - 1;
    for (uint32_t s_tmsi = 0; s_tmsi <= max; ++s_tmsi) {
        if (!manager->used_s_tmsis[s_tmsi]) {
            manager->used_s_tmsis[s_tmsi] = true;
            return s_tmsi;
        }
    }

    // Handle error or wait for external data
    pthread_mutex_lock(&manager->mutex);
    while (!manager->external_data_available) {
        pthread_cond_wait(&manager->cond, &manager->mutex);
    }
    uint32_t s_tmsi = manager->used_s_tmsis[manager->count];
    manager->used_s_tmsis[manager->count] = false;
    ++manager->count;
    pthread_mutex_unlock(&manager->mutex);

    return s_tmsi;
}

// Function to handle external data source and update used S-TMSIs
void updateUsedSTMSIs(RRC_MESSAGES_MANAGER_T *manager, const uint32_t *new_used_s_tmsis, size_t new_count) {
    pthread_mutex_lock(&manager->mutex);
    manager->external_data_available = true;
    for (size_t i = 0; i < new_count; ++i) {
        manager->used_s_tmsis[new_used_s_tmsis[i]] = true;
    }
    pthread_mutex_unlock(&manager->mutex);

    // Wake up waiting threads if any
    pthread_cond_broadcast(&manager->cond);
}
