#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_LIST_SIZE 10000000
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} PDU_T;

static PDU_T* head = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void randomize_crcflag(PDU_T* node) {
    node->crcflag = rand() % 2;
}

bool add_to_list(PDU_T* new_node) {
    pthread_mutex_lock(&list_mutex);
    if (!head || new_node->rnti != head->rnti) {
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&list_mutex);
        return true;
    }
    pthread_mutex_unlock(&list_mutex);
    return false;
}

void remove_from_list(PDU_T* node) {
    pthread_mutex_lock(&list_mutex);
    if (head == node)
        head = node->next;
    PDU_T *current = head;
    while (current->next != node) {
        current = current->next;
        if (!current) break;
    }
    if (current->next)
        current->next = node->next;
    pthread_mutex_unlock(&list_mutex);
}

void serialize(const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    PDU_T* current = head;
    while (current) {
        fwrite((char*)current, sizeof(PDU_T), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize(const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    PDU_T* new_node = NULL;
    while (true) {
        size_t size = sizeof(PDU_T);
        new_node = (PDU_T*)malloc(size);
        if (!new_node) break;
        fread((char*)new_node, size, 1, file);
        if (feof(file)) break;

        add_to_list(new_node);
    }
    fclose(file);
}
```

