        setenv("AST_NODE_DIR", node_dir, 1);
    }

    pthread_mutex_unlock(&node->lock);
    pthread_mutex_unlock(&ast_lock);

    // Recursively process the children of the current node
    for (size_t i = 0; i < node->num_children; ++i) {
