```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>
#include <arpa/inet.h>

typedef struct SessionData {
    int session_id;
    int ue_id;
    char ip[INET6_ADDRSTRLEN];
    int port;
    pthread_mutex_t mutex;
    bool is_active;
    bool is_suspended;
    time_t last_activity;
} SessionData;

typedef struct Node {
    SessionData data;
    struct Node *prev, *next;
} Node;

Node* create_node(SessionData data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->prev = node->next = NULL;
    return node;
}

bool check_duplicate(int session_id, Node** head) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.session_id == session_id)
            return true;
        current = current->next;
    }
    return false;
}

void initialize_and_populate(Node** head, int num_sessions, int timeout) {
    srand(time(NULL));

    for (int i = 0; i < num_sessions; ++i) {
        int session_id = -1;
        do {
            session_id = rand() % INT32_MAX;
        } while (check_duplicate(session_id, head));

        SessionData data = { .session_id = session_id, .ue_id = i + 1, .ip = "", .port = 0, .mutex = PTHREAD_MUTEX_INITIALIZER, .is_active = true, .is_suspended = false, .last_activity = time(NULL) };
        data.ip = inet_ntoa((struct in_addr){rand()}); // Generates a random IP address
        data.port = rand() % 65536;

        Node* node = create_node(data);
        if (!node) {
            perror("Failed to allocate memory for SessionData");
            return;
        }

        pthread_mutex_init(&node->data.mutex, NULL);

        if (*head == NULL) {
            *head = node;
        } else {
            node->prev = tail(*head);
            tail(*head)->next = node;
        }
    }
}

void validate_and_cleanup(Node** head, int timeout) {
    time_t current_time = time(NULL);

    Node* current = *head;
    while (current != NULL) {
        if (!current->data.is_active && current->data.last_activity + timeout < current_time) {
            // Implement network connectivity check here
            if (/* not connected */) {
                printf("Suspending session %d due to inactivity and disconnection\n", current->data.session_id);
                current->data.is_suspended = true;
            } else {
                printf("Terminating inactive session %d\n", current->data.session_id);
                remove_node(current);
            }
        }
        current = current->next;
    }
}

void suspend_resume(Node** head, int session_id, bool suspend) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data.session_id == session_id) {
            if (suspend) {
                pthread_mutex_lock(&current->data.mutex);
                current->data.is_active = false;
                current->data.is_suspended = true;
                current->data.last_activity = time(NULL);
                pthread_mutex_unlock(&current->data.mutex);
            } else {
                pthread_mutex_lock(&current->data.mutex);
                if (!current->data.is_suspended) {
                    printf("Error: Trying to resume non-suspended session %d\n", current->data.session_id);
                } else {
                    current->data.is_active = true;
                    current->data.is_suspended = false;
                    current->data.last_activity = time(NULL);
                }
                pthread_mutex_unlock(&current->data.mutex);
            }
            break;
        }
        current = current->next;
    }
}

void log_operation(const char* operation) {
    // Implement logging here
}

Node* tail(Node* head) {
    Node* current = head;
    while (current != NULL && current->next != NULL) {
        current = current->next;
    }
    return current;
}

void remove_node(Node* node) {
    if (node->prev == NULL) {
        // Head node removal
        free(node);
        *head = node->next;
    } else if (node->next == NULL) {
        // Tail node removal
        node->prev->next = NULL;
        free(node);
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        free(node);
    }
}
