    if (!packet) {
        perror("Memory allocation failure");
        return NULL;
    }

    packet->header = header;
    packet->payload_size = payload_size;
    packet->payload_buffer = malloc(payload_size);
    if (!packet->payload_buffer) {
        free(packet);
        perror("Memory allocation failure");
        return NULL;
    }

    memset(packet->payload_buffer, 0, payload_size);
    packet->calculated_checksum = 0;

    return packet;
}

int populate_packet(Packet *packet, const void *data, size_t data_size) {
