#define MAX_ELEMENTS 100000
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

bool is_rnti_unique(uint16_t* rntis, size_t num_elements, uint16_t rnti) {
    for (size_t i = 0; i < num_elements; ++i) {
        if (rntis[i] == rnti) {
            return false;
        }
    }
    return true;
}

void log(const char* message) {
    // Implement your logging mechanism here, for instance using a file or a system logger.
    printf("%s\n", message);
}

void* populate_array(void* arg) {
    size_t* array = (size_t*)arg;
    uint16_t current_rnti = 0;
    while (true) {
        pthread_mutex_lock(&mutex);
        if (is_rnti_unique(array, *array, current_rnti)) {
            array[*array] = current_rnti++;
            break;
        }
        pthread_mutex_unlock(&mutex);
    }

    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        log("Memory allocation failure");
        return NULL;
    }

    element->tag = (RX_UE_INFORMATION_TAG)time(NULL);
    element->rnti = current_rnti++;
    element->crc_indication.crcflag = rand();

    pthread_mutex_lock(&mutex);
    (*array)++;
    if (*array == MAX_ELEMENTS) {
        log("Maximum number of elements reached");
        free(element);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    (*array) = (*array) % MAX_ELEMENTS;
    pthread_mutex_unlock(&mutex);

    return element;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        if (array[i]) {
            free(array[i]);
        }
    }
}
