#include <iostream>
#include <random>
#include <chrono>
#include <unordered_map>
#include <list>
#include <mutex>
#include <thread>

using namespace std;
using clock = chrono::high_resolution_clock;

struct ENB_CONTEXT {
    int enb_id;
    int cell_id;
    S1_INTERFACE_INFO s1_info;
    time_t last_update_time;
};

class LTE_ENB_CONTEXT_MANAGER {
private:
    unordered_map<int, list<ENB_CONTEXT>> contexts;
    mutex mtx;

    int generateRandomId(int max) {
        random_device rd;
        uniform_int_distribution<> distr(1, max);
        return distr(rd);
    }

    void updateLastUpdateTime(ENB_CONTEXT& context) {
        auto now = chrono::system_clock::to_time_t(chrono::high_resolution_clock::now());
        context.last_update_time = now;
    }

    void insertWithRetry(ENB_CONTEXT& context, int enbId) {
        for (int retry = 0; retry < 5; ++retry) {
            if (contexts[enbId].emplace_hint(begin(contexts[enbId]), &context).first)
                break;
            this_thread::sleep_for(chrono::pow2(retry + 1) * chrono::milliseconds(50));
        }
    }

public:
    void initialize(int N) {
        for (int i = 0; i < N; ++i) {
            ENB_CONTEXT context{ generateRandomId(65535), generateRandomId(255), {}, chrono::system_clock::to_time_t(chrono::high_resolution_clock::now()) };
            insertWithRetry(context, context.enb_id);
        }
    }
};
