NFAPI_CRC_INDICATION_PDU* get_free_pdu() {
    if (num_free > 0) {
        NFAPI_CRC_INDICATION_PDU* pdu = free_list;
        free_list = free_list->next;
        num_free--;
        return pdu;
    } else {
        return malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
    }
}

