typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
size_t num_elements = 0;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T* new_data) {
    // Allocate a new node and initialize its data with the given structure
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;
    new_node->data = *new_data;
    new_node->next = NULL;

    // If the list is empty, set the head to the new node and increment the number of elements
    if (head == NULL) {
        head = new_node;
        num_elements++;
        return;
    }

    Node* current = head;

    // Iterate through the list to find an appropriate place for the new node, ensuring RNTI uniqueness and minimizing cache misses
    while (current->next != NULL && current->next->data.rnti == new_node->data.rnti) {
        current = current->next;
    }

    // If the new node can be inserted before the current node, update the list accordingly
    if (current == head) {
        new_node->next = head;
        head = new_node;
    } else {
        new_node->next = current->next;
        current->next = new_node;
    }
    num_elements++;

    // If the list grows beyond its initial capacity, reallocate memory and update pointers as needed
    if (num_elements > MAX_ELEMENTS) {
        Node** new_head = (Node**)realloc(head, sizeof(Node)*(2*MAX_ELEMENTS));
        if (!new_head) return;

        for (size_t i = 0; i < num_elements; ++i) {
            new_head[i] = head[i];
        }
        head = *new_head;
        MAX_ELEMENTS *= 2;
    }
}

void remove_from_list(RNTI rnti_to_remove) {
    Node* current = head;
    Node* prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti_to_remove) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            num_elements--;
            return;
        }
        prev = current;
        current = current->next;
    }
}

// Generate a random CRCFLAG value for the given RNTI to avoid duplicates in case of concurrent executions
void set_crcflag(RNTI rnti) {
    unsigned int seed = (unsigned int)rnti ^ time(NULL);
    unsigned long crcflag;
    unsigned char buffer[16];
    for (size_t i = 0; i < sizeof(buffer); ++i) {
        buffer[i] = rand_r(&seed);
