    crc32(buffer, 0, sizeof(buffer), &crcflag);
    // Assign the calculated CRCFLAG to the given RNTI structure
    NFAPI_CRC_INDICATION_PDU_T temp = { .rnti = rnti, .crc_indication = { .crcflag = crcflag } };
    add_to_list(&temp);
}
