#include <time.h>

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct thread_data {
    NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t buffer_size;
    size_t buffer_index;
    pthread_mutex_t mutex;
} ThreadData;

void log(const char* message, int threadID) {
    time_t now = time(NULL);
    struct tm* tm_now = localtime(&now);
    printf("%02d:%02d:%02d [Thread %d]: %s\n",
           tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec, threadID, message);
}

void* generator(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    srand(time(NULL));

    while (true) {
        pthread_mutex_lock(&data->mutex);
        if (data->buffer_index >= data->buffer_size) {
            log("Buffer overflow!", __sync_val_compare_and_swap(&data->threadID, -1, (int)pthread_self()));
            pthread_mutex_unlock(&data->mutex);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T* entry = &data->buffer[data->buffer_index];
        entry->RX_UE_INFORMATION_TAG = data->buffer_index + 1;
        entry->RNTI = rand();
        entry->CRC_INDICATION_REL8_TAG = rand() % 0xFFFF;
        log("Generated PDU:", __sync_val_compare_and_swap(&data->threadID, -1, (int)pthread_self()));
        data->buffer_index++;
        pthread_mutex_unlock(&data->mutex);
    }
    return NULL;
}

void manage_buffer(size_t buffer_size, size_t num_threads) {
    ThreadData* data = malloc(sizeof(ThreadData));
    data->buffer_size = buffer_size;
    data->buffer = calloc(data->buffer_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    data->buffer_index = 0;
    data->threadID = -1;
    pthread_mutex_init(&data->mutex, NULL);

    pthread_t threads[num_threads];
    for (size_t i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, generator, data)) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(data->buffer);
    free(data);
}
```

