static NFAPI_CRC_INDICATION_PDU_T *head = NULL;
static NFAPI_CRC_INDICATION_PDU_T *tail = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Helper function to calculate CRC value
uint16_t crc16(const void *data, size_t len) {
    uint16_t crc = 0xFFFF;
    const char *ptr = (const char *)data;
    while (len--) {
        crc = crc ^ (*ptr++) << 8 ^ crctab[(crc >> 8) ^ *ptr];
    }
    return ~crc;
}

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure and add it to the list
void enqueue(RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        return;
    }
    new_node->tag = tag;
    new_node->rnti = rnti;
    new_node->crc_indication.value = crc16(&new_node->tag, sizeof(new_node->tag)) ^ (crc16(&new_node->rnti, sizeof(new_node->rnti)) << 8);
    new_node->crcflag = rand() % 2;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove the first node from the list and return its CRC_INDICATION_REL8_TAG value
