    CRC_INDICATION_REL8_TAG crc_indication;
    unsigned char crcflag; // predefined algorithm for data integrity checks
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe pool structure
typedef struct Pool {
    void *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} Pool;

Pool* create_pool(size_t initial_capacity) {
    Pool *pool = (Pool*)malloc(sizeof(Pool));
    pool->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->not_full, NULL);
    pthread_cond_init(&pool->not_empty, NULL);
    return pool;
}

void push(Pool *pool, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->size == pool->capacity) {
        // Wait until the pool has space
        pthread_cond_wait(&pool->not_full, &pool->mutex);
    }
    memcpy((char*)pool->data + pool->size * sizeof(NFAPI_CRC_INDICATION_PDU_T), &data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool->size++;
    // Notify any waiting threads that data has been added
    pthread_cond_signal(&pool->not_empty);
    pthread_mutex_unlock(&pool->mutex);
}

NFAPI_CRC_INDICATION_PDU_T pop(Pool *pool) {
    pthread_mutex_lock(&pool->mutex);
    while (pool->size == 0) {
        // Wait until the pool has data
        pthread_cond_wait(&pool->not_empty, &pool->mutex);
    }
    NFAPI_CRC_INDICATION_PDU_T data = *(NFAPI_CRC_INDICATION_PDU_T*)((char*)pool->data + pool->size - 1);
    pool->size--;
    // Notify any waiting threads that data has been removed
    pthread_cond_signal(&pool->not_full);
    pthread_mutex_unlock(&pool->mutex);
    return data;
}

void destroy_pool(Pool *pool) {
    free(pool->data);
    free(pool);
}
