    if (!new_nodes) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&list->mutex);
    list->head = new_nodes;
    list->tail = &list->head[list->capacity];
    list->capacity = new_capacity;
    pthread_mutex_unlock(&list->mutex);
}

static inline void enqueue(struct _list *list, NFAPI_CRC_INDICATION_PDU_T data) {
