    new_node->next = NULL;
    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    if (list->count == list->capacity / 4 && list->capacity < 10000) {
        resize_list(list);
    }
    pthread_mutex_unlock(&list->mutex);
}

static inline NFAPI_CRC_INDICATION_PDU_T dequeue(struct _list *list) {
