typedef struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
} list_node_t;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static list_node_t* head = NULL;
static size_t current_allocated_bytes = 0;
static const size_t max_memory_kb = 1024; // Adjust as needed

void update_list(size_t start, size_t end) {
    list_node_t* current = head;
    for (size_t i = start; i < end && current != NULL; ++i) {
        pthread_mutex_lock(&list_mutex);
        if (current == head) { // Edge case: updating the first element
            list_node_t* temp = malloc(sizeof(list_node_t));
            if (!temp) {
                reclaim_memory();
                current = NULL;
            } else {
                temp->data = current->data;
                temp->next = current->next;
                current->data.crcFlag = rand() % 2; // Set CRCFLAG randomly
                head = temp;
                current = temp;
            }
        } else {
            size_t index = i - 1;
            for (list_node_t* curr = head; curr != NULL && index > 0; --index, curr = curr->next) {}
            if (curr == NULL || index != i - 1) { // Edge case: updating an invalid element or beyond current bounds
                current->data.crcFlag = rand() % 2; // Set CRCFLAG randomly for edge cases
            } else {
                list_node_t* temp = malloc(sizeof(list_node_t));
                if (!temp) {
                    reclaim_memory();
                    current = NULL;
                } else {
                    temp->data = current->data;
                    temp->next = curr->next;
                    current->data.crcFlag = rand() % 2; // Set CRCFLAG randomly
                    curr->next = temp;
                    current = temp;
                }
            }
        }
        pthread_mutex_unlock(&list_mutex);
    }
}

void reclaim_memory() {
    if (current_allocated_bytes > max_memory_kb * 1024) { // Adjust the limit as needed
        list_node_t* current = head;
        size_t freed_bytes = 0;
        while (head != NULL && current_allocated_bytes > max_memory_kb * 1024 / 2) {
            list_node_t* to_free = head;
            head = head->next;
            free(to_free);
            freed_bytes += sizeof(list_node_t);
        }
        current_allocated_bytes -= freed_bytes;
    }
}
