    list->cap = capacity;
    list->array = malloc(capacity * sizeof(Node*));
    memset(list->array, 0, capacity * sizeof(Node*));
    sem_init(&(list->lock), 0, 1);
}

void list_push_back(struct List *list, NFAPI_CRC_INDICATION_PDU_T data) {
    int index = (list->size % ARRAY_ALIGNMENT == 0) ? list->size / ARRAY_ALIGNMENT : (list->size / ARRAY_ALIGNMENT) + 1;
    sem_wait(&(list->lock));
    if (index >= list->cap) { // Resize array when necessary
        int new_capacity = list->cap * 2 > MAX_MEMORY_KB ? MAX_MEMORY_KB / PDU_SIZE * 2 : list->cap * 2;
        Node **new_array = realloc(list->array, new_capacity * sizeof(Node*));
        if (!new_array) {
            printf("Memory allocation failed\n");
            sem_post(&(list->lock));
            return;
        }
        list->array = new_array;
        list->cap = new_capacity;
    }
    list->array[index] = mmap(NULL, sizeof(Node), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    Node *node = list->array[index];
    node->data = data;
    node->next = NULL;
    sem_post(&(list->lock));
    list->size++;
}

