    default_frame_buffer_init(entity->frame_buffer);
    entity->operation_queue = queue_create();

    // Initialize the mutex for the frame buffer lock
    struct frame_buffer_lock* frame_lock = malloc(sizeof(struct frame_buffer_lock));
    if (!frame_lock) {
        perror("Failed to allocate memory for the frame buffer lock");
        free(entity->frame_buffer);
        free(entity);
        return;
    }
    pthread_mutex_init(&frame_lock->mutex, NULL);

    // Attach the frame buffer lock to the entity
    entity->frame_buffer_lock = frame_lock;

    // Enqueue the initial processing operation for the newly added MAC entity
    enqueue_operation(entity, process_frame, entity);

    (*num_entities)++;
}

void remove_mac_entity(mac_entity_t** entities, int* num_entities, int index) {
    for (int i = 0; i < *num_entities; ++i) {
        if ((*entities)[i].index == index) {
            queue_destroy((*entities)[i].operation_queue);
            free((*entities)[i].frame_buffer);
            free(*entities + i);

            memmove((*entities + i), (*entities + i + 1), ((*num_entities - 1) - i) * sizeof(mac_entity_t));
            --(*num_entities);
            break;
        }
    }
}

void update_mac_entity(mac_entity_t** entities, int* num_entities, int index, void (*update_function)(mac_entity_t* entity)) {
    for (int i = 0; i < *num_entities; ++i) {
        if ((*entities)[i].index == index) {
            update_function(&(*entities)[i]);
            break;
        }
    }
}

void manage_mac_entities(mac_entity_t** entities, int num_entities) {
    sem_init(&active_entities_semaphore, 0, num_entities);

    pthread_t frame_processing_threads[num_entities];

    for (int i = 0; i < num_entities; ++i) {
        pthread_create(&frame_processing_threads[i], NULL, process_frame, &entities[i]);
    }

    // Block until all frames are processed and the active entities semaphore reaches zero
    while (sem_wait(&active_entities_semaphore) != 0);

    for (int i = 0; i < num_entities; ++i) {
        pthread_join(frame_processing_threads[i], NULL);
    }

    // Free resources here
}
