#define MAX_UPLOAD_ATTEMPTS 3
static size_t upload_progress(void *ptr, size_t size, size_t nmemb, void *userp) {
    // Log the transferred data
    printf("Transferred %lu bytes\n", size * nmemb);
}

int create_and_upload_files(const char* filepath, const char* api_key, const char* api_url) {
    CURL* upload_handle;
    FILE* file = fopen(filepath, "rb");
    if (!file) {
        perror("Error opening the file.");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = malloc(MAX_UPLOADS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < MAX_UPLOADS; ++i) {
        data[i].rxiit = rand();
        data[i].rnti = ((uint64_t)time(NULL)) << 32 | rand();
        data[i].crcflag = rand() % 2;
    }

    json_t* root = json_object();
    json_object_set_new(root, "data", json_array());
    for (size_t i = 0; i < MAX_UPLOADS; ++i) {
        json_t* data_entry = json_object();
        json_object_set_new(data_entry, "rxiit", json_integer(data[i].rxiit));
        json_object_set_new(data_entry, "rnti", json_integer(data[i].rnti));
        json_object_set_new(data_entry, "crcflag", json_integer(data[i].crcflag));
        json_array_append_new(json_object_get_array(root, "data"), data_entry);
    }

    CURLcode res;
    curl_global_init(CURL_GLOBAL_DEFAULT);
    upload_handle = curl_easy_init();
    if (!upload_handle) {
        fprintf(stderr, "Error initializing curl handle\n");
        goto cleanup;
    }

    curl_easy_setopt(upload_handle, CURLOPT_URL, api_url);
    curl_easy_setopt(upload_handle, CURLOPT_USERPWD, api_key); // Set API key for authentication if needed
    curl_easy_setopt(upload_handle, CURLOPT_UPLOAD, 1L);
    curl_easy_setopt(upload_handle, CURLOPT_INFILESIZE, ftell(file));
    curl_easy_setopt(upload_handle, CURLOPT_READDATA, file);
    curl_easy_setopt(upload_handle, CURLOPT_WRITEFUNCTION, upload_progress);
    curl_easy_setopt(upload_handle, CURLOPT_VERBOSE, 0L);

    size_t attempts = MAX_UPLOAD_ATTEMPTS;
    int success = 0;
    do {
        res = curl_easy_perform(upload_handle);
        if (res == CURLE_OK) {
            json_t* response = json_loads(curl_easy_getinfo(upload_handle, CURLINFO_RESPONSE_DATA), 0, NULL);
            const char* url = json_string_value(json_object_get(response, "url"));
            printf("Upload successful: %s\n", url);
            success = 1;
            break;
        } else if (res != CURLE_OPERATION_TIMEDOUT && res != CURLE_ABORTED_BY_CALLBACK) {
            attempts--;
            fprintf(stderr, "Upload failed: %s\n", curl_easy_strerror(res));
        }
    } while (attempts > 0);

cleanup:
    if (!success) {
        fprintf(stderr, "Failed to upload file after all attempts.\n");
    }
    fclose(file);
    curl_easy_cleanup(upload_handle);
    curl_global_cleanup();
    free(data);
    json_decref(root);
    return !success;
}
