} net_if_config;

struct shared_data {
    int num_active_ifs;
    sem_t mem_sem; // Semaphore for memory allocation synchronization
};

void* init_packet_buffer(void* buf) {
    memset(buf, 0, BUFFER_SIZE); // Replace BUFFER_SIZE with actual buffer size
    return buf;
}

net_if_config* create_interface(int id) {
    net_if_config* ifc = malloc(sizeof(net_if_config));
    if (!ifc) {
        perror("malloc");
        return NULL;
    }

    ifc->id = id;
    ifc->packet_buffer = init_packet_buffer(calloc(BUFFER_SIZE, sizeof(char)));
    if (!ifc->packet_buffer) {
        free(ifc);
        perror("calloc");
        return NULL;
    }

    pthread_mutex_init(&ifc->buf_lock, NULL);
    pthread_cond_init(&ifc->buf_cond, NULL);
    PTHREAD_QUEUE_INIT(ifc->op_queue);

    // Map shared data and initialize semaphore
    struct shared_data* shmem = mmap(NULL, sizeof(struct shared_data), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (!shmem) {
        free(ifc->packet_buffer);
        free(ifc);
        perror("mmap");
        return NULL;
    }

    sem_init(&shmem->mem_sem, 1, NUM_MEM_SEM_AVAILABLE); // Replace NUM_MEM_SEM_AVAILABLE with the number of memory allocations allowed

    return ifc;
}

void enqueue_op(net_if_config* ifc, void* op) {
    PTHREAD_QUEUE_PUSH(ifc->op_queue, op);
    sem_post(&ifc->buf_lock.sem); // Signal that there's an operation waiting to process the buffer
