} DownlinkPduPool;

DownlinkPduPool* create_downlink_pdu_pool(int max_size) {
    DownlinkPduPool* pool = malloc(sizeof(DownlinkPduPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for DownlinkPduPool\n");
        return NULL;
    }

    pool->num_allocated = 0;
    pool->downlink_pdu = calloc(max_size, sizeof(TAI_DownlinkPdu*));
    if (!pool->downlink_pdu) {
        fprintf(stderr, "Failed to allocate memory for DownlinkPdu array\n");
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

TAI_DownlinkPdu* acquire_downlink_pdu(DownlinkPduPool* pool) {
    if (pool->num_allocated >= pool->num_elements()) {
        sleep(1); // Allow memory to be reclaimed before attempting another allocation
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);

    int index = pool->num_allocated;
    if (index < pool->num_elements()) {
        pool->downlink_pdu[index] = malloc(sizeof(TAI_DownlinkPdu));
        if (!pool->downlink_pdu[index]) {
            fprintf(stderr, "Failed to allocate memory for TAI_DownlinkPdu\n");
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }

        pool->num_allocated++;
    }

    TAI_DownlinkPdu* downlink_pdu = pool->downlink_pdu[index];

    // Configure the DownlinkPdu structure using external data source
    configure_TAI_DownlinkPdu(downlink_pdu);

