static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static struct cache_entry* cache = NULL;
static size_t cache_size = 0;
static const size_t CACHE_INITIAL_SIZE = 1024;

CRC_INDICATION_PDU_T* create_crci_pdu(char *mac_address) {
    RX_UE_INFORMATION_TAG tag = mac_address_to_tag(mac_address);
    CRC_INDICATION_PDU_T *crci_pdu = malloc(sizeof(CRC_INDICATION_PDU_T));
    if (!crci_pdu) {
        fprintf(stderr, "Failed to allocate memory for CRCI PDU\n");
        return NULL;
    }

    crci_pdu->rx_ue_information_tag = tag;
    crci_pdu->crnti = rnti_from_mac_address(mac_address);
    crci_pdu->crcflag = rand() % 2;

    return crci_pdu;
}

RX_UE_INFORMATION_TAG mac_address_to_tag(char *mac_address) {
    if (!mac_address || !cache || cache_size <= 0) {
        return hash_function(mac_address);
    }

    pthread_mutex_lock(&cache_mutex);
    size_t index = find_cached_index(mac_address);
    if (index != SIZE_MAX) {
        pthread_mutex_unlock(&cache_mutex);
        return cache[index].tag;
    }
    pthread_mutex_unlock(&cache_mutex);

    RX_UE_INFORMATION_TAG tag = hash_function(mac_address);
    if (find_cached_index(mac_address) != SIZE_MAX) {
        return tag; // Collision, return the generated tag without caching it
    }

    cache_entry_alloc(&mac_address, tag);
    return tag;
}

size_t find_cached_index(char *mac_address) {
    for (size_t i = 0; i < cache_size; ++i) {
        if (!cache[i].mac_address || strcmp(cache[i].mac_address, mac_address)) {
            continue;
        }

        return cache[i].index;
    }

    return SIZE_MAX;
}

void cache_entry_alloc(char **mac_address, RX_UE_INFORMATION_TAG tag) {
    if (cache_size >= cache_size + 1) {
        reallocate_cache();
    }

    cache[cache_size].mac_address = *mac_address;
    cache[cache_size].tag = tag;
    cache[cache_size].index = cache_size++;
}

void reallocate_cache() {
    struct cache_entry *new_cache = malloc((CACHE_INITIAL_SIZE << 1) * sizeof(struct cache_entry));
    if (!new_cache) {
        fprintf(stderr, "Failed to allocate memory for cache\n");
        return;
    }

    memcpy(new_cache, cache, cache_size * sizeof(struct cache_entry));
    free(cache);
    cache = new_cache;
    cache_size <<= 1;
}

RX_UE_INFORMATION_TAG hash_function(char *mac_address) {
    uint64_t hash = 0;
    for (size_t i = 0; i < strlen(mac_address); ++i) {
        hash = ((hash << 5) + hash) + mac_address[i];
    }

    return hash % MAX_UE_COUNT;
}

CRNC_RNTI rnti_from_mac_address(char *mac_address) {
    uint64_t rnti = hash_function(mac_address);
    // Implement different hash functions to improve uniqueness and performance based on your needs.
    return (CRNC_RNTI)((rnti & 0xFFFFFFFF) | ((uint32_t)(time(NULL) << 32)));
}
