class MemoryManager {
public:
    explicit MemoryManager(size_t budgetInKB) : budget_(budgetInKB * 1024), currentUsage_(0) {}

    void* allocate(size_t size) {
        if (currentUsage_ + size > budget_) {
            auto newCapacity = std::max(capacity_, currentUsage_ * 2);
            reallocate(newCapacity);
        }
        void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        currentUsage_ += size;
        return ptr;
    }

    void reallocate(size_t newCapacity) {
        if (capacity_ < newCapacity) {
            auto oldData = mmap(NULL, capacity_, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            void* newData = mmap(NULL, newCapacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
            memmove(newData, oldData, capacity_);
            munmap(oldData, capacity_);
            capacity_ = newCapacity;
        }
    }

    void deallocate(void* ptr, size_t size) {
        currentUsage_ -= size;
        munmap(ptr, size);
    }

private:
    size_t budget_, currentUsage_;
    size_t capacity_ = 0;
};

class StructQueue {
public:
    void enqueue(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        queue_.push_back(pdu);
        log("Enqueued structure");
    }

    NFAPI_CRC_INDICATION_PDU_T* dequeue() {
        if (queue_.empty()) return nullptr;
        auto it = queue_.begin();
        log("Dequeued structure", *it);
        return it++;
    }

    void invalidate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        auto it = std::find(queue_.begin(), queue_.end(), pdu);
        if (it != queue_.end()) {
            queue_.erase(it);
            log("Invalidated structure", *pdu);
        }
    }

private:
    std::list<NFAPI_CRC_INDICATION_PDU_T*> queue_;
};

std::mutex logMutex;
void log(const char* msg, NFAPI_CRC_INDICATION_PDU_T* pdu = nullptr) {
    static constexpr char* filename = "logs.txt";
    std::unique_lock<std::mutex> lock(logMutex);
    FILE* file = fopen(filename, "a");
    if (!file) return;
    if (pdu) {
        fprintf(file, "%s: RX_UE_INFORMATION_TAG: %d, RNTI: %u, CRCFLAG: %d\n", msg, pdu->rxtag.RX_UE_INFORMATION_TAG, pdu->rnti, pdu->crcindicationtag.CRCFLAG);
