    structQueue.enqueue(pdu);
    return pdu;
}

void updateStructure(NFAPI_CRC_INDICATION_PDU_T* pdu, uint32_t rnti) {
    if (rnti != pdu->rnti) return;
    pdu->crcindicationtag.CRCFLAG = std::atomic<bool>(!pdu->crcindicationtag.CRCFLAG);
