void invalidateStructures(uint32_t rxtag, uint32_t startIndex, uint32_t endIndex) {
    for (size_t i = startIndex; i < endIndex; ++i) {
        auto it = structQueue.begin();
        std::advance(it, i);
        if (it->rxtag.RX_UE_INFORMATION_TAG == rxtag) {
            structQueue.invalidate(*it);
        }
    }
}
