struct EventNotification {
    std::chrono::steady_clock::time_point timestamp;
    enum class EventType { kLogin, kLogout, kDataRequest };
    std::string sessionId;
    EventType type;

    EventNotification(EventType type, const std::string& sessionId) : type(type), sessionId(sessionId) {}
};

class NotificationList {
public:
    void addNotification(const EventNotification& notification);
    std::list<EventNotification> getActiveNotifications();

private:
    std::unordered_map<std::string, EventNotification> _notifications;
    const std::chrono::seconds _durationThreshold;
};

#endif // EVENT_NOTIFICATION_H
```

2. C++ Code (Source File - `EventNotification.cpp`)

```cpp
#include "EventNotification.h"

void NotificationList::addNotification(const EventNotification& notification) {
    _notifications[notification.sessionId] = notification;
}

std::list<EventNotification> NotificationList::getActiveNotifications() {
    std::list<EventNotification> activeEvents;
    auto now = std::chrono::steady_clock::now();
    for (auto& entry : _notifications) {
        auto timeDelta = now - entry.first;
        if (std::chrono::duration_cast<std::chrono::seconds>(timeDelta).count() < _durationThreshold.count()) {
            activeEvents.push_back(entry.second);
        }
    }
    return activeEvents;
}
```

