    void* (*create)(void);
    void (*destroy)(void* obj);
    // Add any necessary parameters here
} AlgorithmInfo_T;

AlgorithmInfo_T** getAvailableAlgorithms(const char *libraryPath, size_t *numAlgorithms) {
    void* handle = dlopen(libraryPath, RTLD_NOW | RTLD_LOCAL);
    if (!handle) return NULL;

    const char* symbol = "getAvailableAlgorithms";
    typedef AlgorithmInfo_T** (*getFunc)(void);
    getFunc func = (getFunc)dlsym(handle, symbol);

    AlgorithmInfo_T** availableAlgorithms = func();
    size_t numAvailableAlgorithms = 0;

    for (size_t i = 0; availableAlgorithms[i]; ++i) {
        if (!availableAlgorithms[i]->create || !availableAlgorithms[i]->destroy) {
            fprintf(stderr, "Algorithm '%s' is not properly implemented\n", availableAlgorithms[i]->name);
            continue;
        }

        void* obj = availableAlgorithms[i]->create();
        if (!obj) {
            fprintf(stderr, "Failed to create algorithm object for %s\n", availableAlgorithms[i]->name);
            continue;
        }

        availableAlgorithms[i]->destroy(obj);
        numAvailableAlgorithms++;
    }

    *numAlgorithms = numAvailableAlgorithms;
    return availableAlgorithms;
}
```

In this example, the `getAvailableAlgorithms()` function dynamically loads an external library using dlopen(), retrieves a symbol named "getAvailableAlgorithms", and calls it to get a list of available algorithms. The returned array contains pointers to AlgorithmInfo_T structures that detail each algorithm's name, create function, destroy function, and any necessary parameters.']

