// Custom hash map structure
typedef struct {
    size_t capacity; // Capacity of the hash map
    size_t count; // Current number of elements in the hash map
    void** data;  // Pointer to an array of pointers to the actual data (LTE_UARFCN_TABLE_T structures)
    void* table;  // Pointer to the hash map table itself
} CustomHashMap;

// Helper function for computing the index within the hash map based on the CELL_ID
size_t hash(size_t cell_id, size_t capacity) {
    return cell_id % capacity;
}

// Helper function for comparing two LTE_UARFCN_TABLE_T structures based on their CELL_ID
bool compare(const void* a, const void* b) {
