}

// Helper function for resizing the hash map based on the current number of elements
void resize(CustomHashMap* hashmap, size_t new_capacity) {
    if (new_capacity <= hashmap->capacity) return;

    // Allocate a new table with the new capacity
    void** new_data = malloc((size_t)(new_capacity * sizeof(void*)));
    memcpy(new_data, hashmap->data, hashmap->count * sizeof(void*));

    // Free the old table and update the hash map structure
    free(hashmap->table);
    hashmap->table = new_data;
    hashmap->capacity = new_capacity;
}

