// Function to dynamically allocate and populate an array of LTE_UARFCN_TABLE_T structures
void create_structures(CustomHashMap* hashmap, size_t max_structures) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[max_structures];
    size_t current_structures = 0;

    // Initialize the hash map with an initial capacity of max_structures * 2
    hashmap->capacity = (size_t)(max_structures * 2);
    hashmap->data = malloc(hashmap->capacity * sizeof(void*));
    hashmap->table = calloc((size_t)(hashmap->capacity / ULONG_MAX), sizeof(void*));

    for (size_t i = 0; i < max_structures; ++i) {
        pthread_create(&threads[i], NULL, (void*(*)(void*))create_func, hashmap);
    }

    // Wait for all threads to finish execution
    for (size_t i = 0; i < max_structures; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free the hash map and its associated data structures
    free(hashmap->data);
    free(hashmap->table);
}

// Function for creating a new LTE_UARFCN_TABLE_T structure in a separate thread
void* create_func(void* arg) {
    CustomHashMap* hashmap = (CustomHashMap*)arg;

    pthread_mutex_lock(&lock);

    // Check if the capacity of the hash map needs to be resized
    if (hashmap->count >= hashmap->capacity / 2) {
        resize(hashmap, hashmap->capacity * 2);
    }

    // Insert a new structure into the hash map using the helper function find()
    LTE_UARFCN_TABLE_T* struct_ptr = create_struct();
    size_t index = hash(struct_ptr->CELL_ID, hashmap->capacity);
    insert(hashmap->table[index], struct_ptr, compare);

    pthread_mutex_unlock(&lock);

