['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_FRAMES 1000
#define MIN_SIGNAL_STRENGTH 50
#define QUALITY_INDEX_RANGE 200

typedef struct {
    time_t timestamp;
    int signalStrength;
    int* channelQualityIndices;
    size_t numIndices;
} FrameMetrics;

typedef struct FrameMetricsBuffer {
    FrameMetrics** frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} FrameMetricsBuffer;

void initFrameMetricsBuffer(FrameMetricsBuffer* buffer) {
    buffer->frames = malloc(sizeof(FrameMetrics*) * MAX_FRAMES);
    buffer->capacity = MAX_FRAMES;
    buffer->count = 0;
    buffer->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void pushFrameMetrics(FrameMetricsBuffer* buffer, FrameMetrics* frame) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count < buffer->capacity) {
        buffer->frames[buffer->count++] = frame;
    } else {
        printf("Error: Frame count exceeded the maximum limit.\n");
    }
    pthread_mutex_unlock(&buffer->mutex);
}

FrameMetrics* popFrameMetrics(FrameMetricsBuffer* buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count > 0) {
        FrameMetrics* frame = buffer->frames[0];
        memmove(buffer->frames, buffer->frames + 1, --buffer->count * sizeof(FrameMetrics*));
        return frame;
    }
    return NULL;
}

void initializeFrameMetrics(FrameMetricsBuffer* buffer, size_t numFrames) {
    if (numFrames > MAX_FRAMES) {
        printf("Error: Number of frames exceeded the maximum limit.\n");
        return;
    }

    for (size_t i = 0; i < numFrames; ++i) {
        FrameMetrics* frame = malloc(sizeof(FrameMetrics));
        frame->timestamp = time(NULL);
        frame->signalStrength = rand() % (MIN_SIGNAL_STRENGTH + 1) + MIN_SIGNAL_STRENGTH;
        if (frame->signalStrength < MIN_SIGNAL_STRENGTH) {
            free(frame);
            continue;
        }
        frame->numIndices = rand() % QUALITY_INDEX_RANGE + 1;
        frame->channelQualityIndices = malloc(frame->numIndices * sizeof(int));
        for (size_t j = 0; j < frame->numIndices; ++j) {
            frame->channelQualityIndices[j] = rand() % QUALITY_INDEX_RANGE;
        }
        pushFrameMetrics(buffer, frame);
    }
}
