void init_dynamic_array(struct dynamic_array* arr) {
    arr->data = mmap(NULL, MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (arr->data == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    arr->used = 0;
    arr->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&arr->mutex, NULL);
    sem_init(&arr->semaphore, 0, arr->capacity);
}

bool add_to_array(struct dynamic_array* arr, const NFAPI_CRC_INDICATION_PDU_T* item) {
