            fprintf(stderr, "Error: Duplicate RNTI detected\n");
            return false;
        }
    }

    pthread_mutex_lock(&arr->mutex);

    if (sem_wait(&arr->semaphore) == -1) {
        perror("sem_wait failed");
        return false;
    }

    if (arr->used >= arr->capacity) {
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(arr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (arr->capacity + 1024));
        if (!new_data) {
            perror("realloc failed");
            pthread_mutex_unlock(&arr->mutex);
            sem_post(&arr->semaphore);
            return false;
        }
        arr->data = new_data;
        arr->capacity += 1024;
    }

    memcpy(&arr->data[arr->used], item, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    arr->used++;

    pthread_mutex_unlock(&arr->mutex);
    sem_post(&arr->semaphore);
    return true;
}

void clear_array(struct dynamic_array* arr) {
    if (munmap(arr->data, arr->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)) == -1) {
        perror("munmap failed");
    }
    arr->used = 0;
    arr->capacity = MAX_ELEMENTS;
    pthread_mutex_destroy(&arr->mutex);
    sem_destroy(&arr->semaphore);
}
