void add_element(NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array_lock);
    if (current_capacity == array_length()) {
        resize();
    }
    data_array[array_length()] = element;
    pthread_mutex_unlock(&array_lock);
}

void remove_element(RNTI rnti) {
