    if (index != SIZE_MAX) {
        pthread_mutex_lock(&array_lock);
        memmove(data_array + index, data_array + index + 1, --current_capacity - index);
        pthread_mutex_unlock(&array_lock);
    }
}

void update_crcflag(RNTI rnti, bool new_value) {
    size_t index = search_for_rnti(rnti);
    if (index != SIZE_MAX) {
        pthread_mutex_lock(&array_lock);
        data_array[index].crcflag = new_value;
        pthread_mutex_unlock(&array_lock);
    }
}

