class UEStatsManager {
private:
    std::unordered_map<unsigned long, UEStatsRecord> records;
    pthread_mutex_t mutex;

public:
    UEStatsManager() : records(), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    void addRecord(const UEStatsRecord& record) {
        pthread_mutex_lock(&mutex);
        auto iter = records.find(record.ID);
        if (iter == records.end()) {
            records[record.ID] = record;
        } else {
            iter->second.signalStrengths.insert(iter->second.signalStrengths.end(), record.signalStrengths.begin(), record.signalStrengths.end());
        }
        pthread_mutex_unlock(&mutex);
    }

    UEStatsRecord* getRecord(unsigned long ID) {
        pthread_mutex_lock(&mutex);
        auto iter = records.find(ID);
        if (iter != records.end()) {
            UEStatsRecord* result = new UEStatsRecord(iter->second);
            pthread_mutex_unlock(&mutex);
            return result;
        }
        pthread_mutex_unlock(&mutex);
        return nullptr;
    }

    void run() {
        // Implement your thread functions here.
    }
};

void* worker(void* arg) {
    UEStatsManager& manager = *(UEStatsManager*)arg;
    // Perform tasks on the manager object.
}

