    UEStatsRecord* retrievedRecord = manager.getRecord(record1.ID);
    if (retrievedRecord) {
        std::cout << "Retrieved record with ID: " << retrievedRecord->ID << "\n";
    } else {
        std::cout << "No record found for given ID.\n";
    }

    pthread_t threads[NUM_THREADS];
    UEStatsManager* managerCopy = new UEStatsManager();
    for (int i = 0; i < NUM_THREADS; ++i) {
