    net->capacity = initial_capacity;
    net->devices = calloc(initial_capacity, sizeof(struct device*));
}

void add_device(struct network *net, const char *device_id) {
    if (net->num_devices == net->capacity) {
        net->capacity *= 2;
        net->devices = realloc(net->devices, net->capacity * sizeof(struct device*));
    }

    struct device *dev = calloc(1, sizeof(struct device));
    dev->device_id = device_id;
    dev->config = malloc(sizeof(config_t));
    dev->is_connected = false;
    pthread_mutex_init(&dev->mutex, NULL);

    net->devices[net->num_devices++] = dev;
}

void update_config(struct device *dev) {
    // API call logic to fetch compatibility data for the device goes here
}

int main() {
    struct network net;
    init_network(&net, 10);
    add_device(&net, "device1");
    add_device(&net, "device2");

    pthread_create(&net.api_thread, NULL, fetch_configs, &net);

    // Your main program logic here
}

void* fetch_configs(void *arg) {
    struct network *net = arg;
    CURLcode res;
    char *response;
    size_t len = 0;
    struct device *devices[net->num_devices];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    net->api_handle = curl_easy_init();

    while (true) {
        res = curl_easy_setopt(net->api_handle, CURLOPT_URL, "https://api.example.com/devices");
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to set API URL: %s\n", curl_easy_strerror(res));
            break;
        }

        res = curl_easy_perform(net->api_handle);
        if (res != CURLE_OK) {
            fprintf(stderr, "API request failed: %s\n", curl_easy_strerror(res));
            continue;
        }

        response = malloc(curl_easy_getinfo(net->api_handle, CURLINFO_SIZE_DOWNLOAD) + 1);
        snprintf(response, len + 1, "%s", curl_easy_getinfo(net->api_handle, CURLINFO_DATA));

        json_object *root = json_tokener_parse(response);
        if (!json_object_get_ex(root, "devices")) {
            fprintf(stderr, "Invalid API response\n");
            free(response);
            continue;
        }

        json_object *device_obj;
        struct device *dev;
        json_array *device_arr = json_object_get_array(json_object_get_ex(root, "devices"));
        for (size_t i = 0; i < json_array_length(device_arr); ++i) {
            device_obj = json_array_get_idx(device_arr, i);
            const char *device_id = json_object_get_string(json_object_get_ex(device_obj, "id"));

            for (size_t j = 0; j < net->num_devices; ++j) {
                dev = net->devices[j];
                if (!strcmp(dev->device_id, device_id)) {
                    update_config(dev);
                    devices[j] = dev;
                    break;
                }
            }
        }

        curl_easy_cleanup(net->api_handle);
        free(response);
        usleep(100000); // Sleep for a short period to reduce API call overhead
    }

    curl_global_cleanup();
}
