void pushBack(NFAPI_CRC_INDICATION_PDU_T data) {
    if (curSize >= maxSize && maxSize < INT_MAX / sizeof(Node)) {
        logError("Memory allocation failed, reducing list size.");
        shrinkList();
    }

    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        logError("Memory allocation failed during insertion.");
        return;
    }

    newNode->data = data;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    curSize++;
    LOGGING_MECHANISM_INFO("Successfully added element to the list.");
}

void shrinkList() {
    int newMaxSize = maxSize / 2;
    if (newMaxSize <= 0) return; // Prevent underflow

    Node* current = head;
    Node* tempNode;

    while (current != NULL && curSize > newMaxSize) {
        tempNode = current->next;
        free(current);
        current = tempNode;
        curSize--;
    }

    maxSize = newMaxSize;
}

