        updateUEInfoFromSource(&ueInfoSource, &current->data.tag);
        current = current->next;
    }
}

void cleanup() {
    Node* current = head;
    while (current != NULL) {
        Node* tempNode = current;
        current = current->next;
        free(tempNode);
    }
    head = NULL;
    curSize = 0;
