typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    bool crcflag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

struct cache_node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct cache_node* next;
};

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
struct cache_node* head = NULL;

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

NFAPI_CRC_INDICATION_PDU_T* alloc_structure() {
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) {
        log_error("Memory allocation failed");
        return NULL;
    }
    time(&structure->timestamp);
    structure->rnti = rand();
    structure->crcflag = (rand() % 2 == 0) ? true : false;
    memset(structure->rx_ue_info.data, 0, sizeof(structure->rx_ue_info.data));
    memset(structure->crc_indication.data, 0, sizeof(structure->crc_indication.data));
    return structure;
}

void free_structure(NFAPI_CRC_INDICATION_PDU_T* structure) {
    if (!structure) return;
    free(structure);
}

struct cache_node* find_cache_node(int N) {
    struct cache_node* current = head;
    for (int i = 0; i < N && current != NULL; ++i, current = current->next) {}
    return current;
}

void insert_to_cache(int N, NFAPI_CRC_INDICATION_PDU_T* structure) {
    struct cache_node* current = find_cache_node(N);
    if (!current) {
        current = (struct cache_node*)malloc(sizeof(struct cache_node));
        if (!current) {
            log_error("Memory allocation failed");
            free_structure(structure);
            return;
        }
        current->data = structure;
        current->next = head;
        pthread_mutex_lock(&queue_mutex);
        head = current;
        pthread_mutex_unlock(&queue_mutex);
    } else {
        current->next = (struct cache_node*)malloc(sizeof(struct cache_node));
        if (!current->next) {
            log_error("Memory allocation failed");
            free_structure(structure);
            return;
        }
        current->next->data = structure;
        current->next->next = head;
        pthread_mutex_lock(&queue_mutex);
        head = current->next;
        pthread_mutex_unlock(&queue_mutex);
    }
}

NFAPI_CRC_INDICATION_PDU_T* get_from_cache(int N) {
    struct cache_node* current = find_cache_node(N);
    if (!current || !current->next) return NULL;
    struct cache_node* temp = current->next;
    pthread_mutex_lock(&queue_mutex);
    current->next = temp->next;
    pthread_mutex_unlock(&queue_mutex);
    return temp->data;
}

NFAPI_CRC_INDICATION_PDU_T* allocate(int N) {
    if (N <= 0) return NULL;
    if (N > MAX_STRUCTS) {
        log_error("Requested number of structures exceeds the maximum allowed value");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = get_from_cache(N);
    if (structure) return structure;

    pthread_mutex_lock(&queue_mutex);
    while (head && head->next && head->next->data[0].data_length + head->data[0].data_length >= N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        struct cache_node* temp = head;
        head = head->next;
        free(temp);
    }
    pthread_mutex_unlock(&queue_mutex);

    structure = alloc_structure();
    if (!structure) return NULL;

    insert_to_cache(N, structure);
    return structure;
}
