[" Here's a solution using a circular linked list (doubly-linked list with the end pointing back to the start) as it provides efficient insertion, deletion, and lookup operations. This data structure also allows for easy concurrent access by multiple threads without causing data corruption using locks or atomic operations. The solution uses `pthread_mutex_t` for locking, ensuring thread safety.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct _NFAPI_MESSAGE_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    SNR_INDICATION_TAG snr_indication_tag;
    struct _NFAPI_MESSAGE_T *next;
} NFAPI_MESSAGE_T;

typedef struct _DYNAMIC_ARRAY {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    NFAPI_MESSAGE_T *head;
    NFAPI_MESSAGE_T *tail;
} DYNAMIC_ARRAY;

DYNAMIC_ARRAY* dynamic_array_init() {
    DYNAMIC_ARRAY *arr = malloc(sizeof(DYNAMIC_ARRAY));
    if (!arr) return NULL;

    pthread_mutex_init(&arr->lock, NULL);
    arr->size = 0;
    arr->capacity = 16;
    arr->head = calloc(arr->capacity, sizeof(NFAPI_MESSAGE_T));
    if (!arr->head) {
        free(arr);
        return NULL;
    }
    arr->tail = arr->head + arr->capacity - 1;
    return arr;
}

void dynamic_array_push(DYNAMIC_ARRAY *arr, const NFAPI_MESSAGE_T *msg) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        size_t new_capacity = arr->capacity * 2;
        NFAPI_MESSAGE_T *new_head = realloc(arr->head, new_capacity * sizeof(NFAPI_MESSAGE_T));
        if (!new_head) {
            pthread_mutex_unlock(&arr->lock);
            return;
        }
        arr->head = new_head;
        arr->tail = arr->head + new_capacity - 1;
    }

    // Link the new message to the list
    msg->next = arr->head;
    arr->head->prev = msg;
    arr->head = msg;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
}

NFAPI_MESSAGE_T* dynamic_array_get(DYNAMIC_ARRAY *arr, size_t index) {
    if (index >= arr->size) return NULL;
    pthread_mutex_lock(&arr->lock);
    NFAPI_MESSAGE_T *current = arr->head;
    for (size_t i = 0; i < index; ++i) current = current->next;
    NFAPI_MESSAGE_T *result = current;
    pthread_mutex_unlock(&arr->lock);
    return result;
}

bool dynamic_array_remove(DYNAMIC_ARRAY *arr, RNTI rnti) {
    pthread_mutex_lock(&arr->lock);
    NFAPI_MESSAGE_T *current = arr->head;
    while (current != NULL && current->rnti != rnti) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&arr->lock);
        return false;
    }

    // Remove the current node from the list
    if (current == arr->head) {
        arr->head = current->next;
        if (arr->head != NULL) arr->head->prev = NULL;
    } else {
        current->prev->next = current->next;
        if (current->next != NULL) current->next->prev = current->prev;
    }
    free(current);
    arr->size--;
    pthread_mutex_unlock(&arr->lock);
    return true;
}
```

