void create_linked_list(struct linkedList* list, size_t size) {
    if (size > MAX_STRUCTURES || size == 0) {
        fprintf(stderr, "Invalid size: %zu\n", size);
        return;
    }

    list->head = NULL;
    list->count = 0;
    list->maxSize = size;
