import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5Hash {
    private static final ExecutorService POOL = Executors.newFixedThreadPool(10);
    private static final ConcurrentLinkedQueue<String> QUEUE = new ConcurrentLinkedQueue<>();

    public static void main(String[] args) throws InterruptedException {
        // Start the pool of workers
        POOL.shutdown();
        POOL.execute(() -> {
            while (!QUEUE.isEmpty()) {
                String input = QUEUE.poll();
                if (input != null && !input.isBlank()) {
                    computeHash(input);
                }
            }
        });

        // Process incoming requests and add them to the queue
        while (true) {
            String input = // Get user input or read from a data source
            if (input != null && !input.isBlank()) {
                QUEUE.add(input);
            }
            TimeUnit.SECONDS.sleep(1);
        }
    }

    private static void computeHash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(input.getBytes());
            BigInteger bigInt = new BigInteger(1, digest);
            String hashedInput = bigInt.toString(16);
            while (hashedInput.length() < 32) {
                hashedInput = "0" + hashedInput;
            }
            System.out.println("Hash of \"" + input + "\": " + hashedInput);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
