#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _list_node *next;
} list_node_t;

struct _dynamic_list {
    uint32_t capacity;
    uint32_t size;
    list_node_t **nodes;
    pthread_mutex_t mutex;
};

void init_dynamic_list(struct _dynamic_list *list, uint32_t capacity) {
    if (capacity == 0) return;
    list->capacity = capacity;
    list->size = 0;
    list->nodes = malloc(sizeof(list_node_t*) * capacity);
    memset(list->nodes, 0, sizeof(list_node_t*) * capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

bool is_valid_index(uint32_t index, uint32_t size) {
    return (index >= 0 && index < size);
}

NFAPI_CRC_INDICATION_PDU_T* get_node(struct _dynamic_list *list, uint32_t index) {
    if (!is_valid_index(index, list->size)) return NULL;
    pthread_mutex_lock(&list->mutex);
    list_node_t *current = list->nodes[index];
    pthread_mutex_unlock(&list->mutex);
    return &current->data;
}

void resize_dynamic_list(struct _dynamic_list *list, uint32_t new_capacity) {
    if (new_capacity <= list->capacity) return;
    list_node_t **new_nodes = malloc(sizeof(list_node_t*) * new_capacity);
    memcpy(new_nodes, list->nodes, sizeof(list_node_t*) * list->capacity);
    memset(&new_nodes[list->capacity], 0, sizeof(list_node_t*) * (new_capacity - list->capacity));
    free(list->nodes);
    list->nodes = new_nodes;
    list->capacity = new_capacity;
}

void insert_sorted(struct _dynamic_list *list, const NFAPI_CRC_INDICATION_PDU_T *new_element) {
    uint32_t i;
    for (i = 0; i < list->size && new_element->rnti > get_node(list, i)->rnti; ++i);
    resize_dynamic_list(list, list->size + 1);
    pthread_mutex_lock(&list->mutex);
    for (; i < list->size; ++i) {
        list->nodes[i] = list->nodes[i+1];
    }
    list->nodes[i]->next = malloc(sizeof(list_node_t));
    list->nodes[i+1] = list->nodes[i]->next;
    list->nodes[i+1]->data = *new_element;
    list->nodes[i+1]->next = NULL;
    pthread_mutex_unlock(&list->mutex);
}

void delete_by_index(struct _dynamic_list *list, uint32_t index) {
    if (!is_valid_index(index, list->size)) return;
    pthread_mutex_lock(&list->mutex);
    list_node_t *current = list->nodes[index];
    list_node_t **prev = &list->nodes[index];
    while (current != NULL) {
        *prev = current->next;
        current = (*prev)->next;
        free(*prev);
        if (prev == &list->nodes[index]) break;
        prev = &((*prev)->next);
    }
    --list->size;
    pthread_mutex_unlock(&list->mutex);
}

void compute_crcflag(const NFAPI_CRC_INDICATION_PDU_T *element, double normalized_weight) {
    double weighted_rnti = element->rnti * normalized_weight;
    uint32_t index = (uint32_t)(weighted_rnti % list->capacity);
    element->crcflag = (index + element->rnti) & 1;
}

void handle_signal(struct _dynamic_list *list, const RX_UE_INFORMATION_TAG rx_ue_information_tag, uint32_t rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T new_element = {rx_ue_information_tag, rnti, crc_indication_rel8_tag, false};
    double normalized_weight = (double)(time(NULL)) / 60.0 / CLOCKS_PER_SEC; // Normalize the current system time to a value between 0 and 1
    compute_crcflag(&new_element, normalized_weight);
    insert_sorted(list, &new_element);
}
