#define MAX_N 10000 // Maximum number of structures allowed

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    unsigned int rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU;

typedef struct PDU_MANAGER_T {
    NFAPI_CRC_INDICATION_PDU** pdu_array;
    size_t array_size;
    size_t num_allocated;
    pthread_mutex_t mutex;
} PDU_MANAGER;

PFDM_init(PDU_MANAGER* manager, size_t init_size) {
    if (init_size > MAX_N || init_size == 0)
        return -1;

    manager->pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU*) * init_size);
    if (!manager->pdu_array) {
        fprintf(stderr, "Failed to allocate memory for PDU manager\n");
        return -1;
    }

    manager->array_size = init_size;
    manager->num_allocated = 0;
    manager->mutex = PTHREAD_MUTEX_INITIALIZER;

    return 0;
}

PDU_MANAGER* create_pdu_manager(size_t init_size) {
    PDU_MANAGER* manager = malloc(sizeof(PDU_MANAGER));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for PDU manager object\n");
        return NULL;
    }

    int res = PFDM_init(manager, init_size);
    if (res != 0) {
        free(manager);
        return NULL;
    }

    return manager;
}

PFDM_allocate(PDU_MANAGER* manager, size_t n) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->num_allocated + n > manager->array_size) {
        void* temp = realloc(manager->pdu_array, sizeof(NFAPI_CRC_INDICATION_PDU*) * (manager->array_size * 2));
        if (!temp) {
            pthread_mutex_unlock(&manager->mutex);
            fprintf(stderr, "Failed to resize PDU manager array\n");
            return -1;
        }

        manager->pdu_array = temp;
        manager->array_size *= 2;
    }

    for (size_t i = manager->num_allocated; i < manager->num_allocated + n; ++i) {
        manager->pdu_array[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
        if (!manager->pdu_array[i]) {
            pthread_mutex_unlock(&manager->mutex);
            fprintf(stderr, "Failed to allocate memory for PDU structure\n");
            return -1;
        }

        // Initialize the structure with random values and log the creation
        memset(manager->pdu_array[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU));
        manager->pdu_array[i]->rx_ue_information_tag = rand();
        manager->pdu_array[i]->rnti = rand();
        manager->pdu_array[i]->crc_indication_rel8_tag.crcflag = rand() % 2;

        // Logging can be implemented using a logging library or a custom mechanism
        printf("PDU structure created with tags: rx_ue_information_tag=%u, rnti=%u, crc_indication_rel8_tag.crcflag=%d\n",
               manager->pdu_array[i]->rx_ue_information_tag,
               manager->pdu_array[i]->rnti,
               manager->pdu_array[i]->crc_indication_rel8_tag.crcflag);
    }

    manager->num_allocated += n;
    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU* pdu) {
    free(pdu);
}

void destroy_pdu_manager(PDU_MANAGER* manager) {
    if (!manager)
        return;

    pthread_mutex_destroy(&manager->mutex);

    for (size_t i = 0; i < manager->num_allocated; ++i)
        destroy_pdu(manager->pdu_array[i]);

    free(manager->pdu_array);
    free(manager);
}
