#include <time.h>

typedef struct {
    int UE_ID;
    int BWP[10];
    int CG_resources[10];
} UEContext;

typedef struct Node {
    UEContext* context;
    struct Node* next;
} Node;

int MAX_UE_CONTEXTS = 1000;
Node* head = NULL;
ResourceManager* resource_manager;

void log(char* message, int context_id) {
    if (!logging_enabled) return;
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s: [UE%d] %s\n", timestamp, context_id, message);
}

int create_ue_context(int* error_code) {
    if (head == NULL || resource_manager->available_memory < sizeof(UEContext)) {
        *error_code = RESOURCE_EXHAUSTION;
        return 0;
    }

    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        *error_code = MEMORY_ALLOCATION_FAILURE;
        return 0;
    }
    new_node->context = (UEContext*) malloc(sizeof(UEContext));
    if (!new_node->context) {
        *error_code = MEMORY_ALLOCATION_FAILURE;
        free(new_node);
        return 0;
    }

    log("Created UE context", -1); // -1 means generic context ID for logging purposes

    new_node->context->UE_ID = generate_unique_UE_ID();
    // Initialize other fields as needed

    new_node->next = head;
    head = new_node;
    resource_manager->used_memory += sizeof(UEContext);

    *error_code = SUCCESS;
    return 1;
}

void cleanup() {
    Node* current = head;
    Node* next_node;

    while (current != NULL) {
        next_node = current->next;

        if (!current->context->is_active) { // Check if the UE context is active before releasing it
            log("Released unused UE context", current->context->UE_ID);
            free(current->context);
            free(current);

            resource_manager->used_memory -= sizeof(UEContext);
        }

        current = next_node;
    }
}

void enable_logging(int enabled) {
    logging_enabled = enabled;
}
