    if (!ptr) {
        perror("malloc");
        exit(1);
    }
    return ptr;
}

static uint32_t compute_checksum(const void *data, size_t size) {
    const unsigned char *data_u8 = (const unsigned char *)data;
    uint32_t checksum = 0;
    for (size_t i = 0; i < size; ++i) {
        checksum += data_u8[i];
    }
    return checksum;
}

// Function to initialize and populate a dynamic array of LTE_DL_FRAME_MESSAGE structures
