    memcpy(payload->data, data, data_size);
    payload->data_size = data_size;
    payload->checksum = compute_checksum(data, data_size);

    if (seq_len > 0 && rand() % 2 == 0) { // Randomly decide to add child frames or not
        size_t num_child_frames = seq_len + rand() % 15; // Up to 15 additional child frames

        if (num_child_frames > frame->child_frame_capacity) {
            frame->child_frame_capacity *= 2;
            realloc(frame->child_frames, sizeof(struct LTE_DL_FRAME_MESSAGE *) * frame->child_frame_capacity);
        }

        for (size_t i = frame->child_frame_index; i < num_child_frames + frame->child_frame_index; ++i) {
            populate_frame(frame->child_frames[i], modulation_scheme, seq_len - 1, generate_random_data(modulation_scheme), data_size * rand() % 5);
        }

        frame->num_child_frames = num_child_frames + 1;
        frame->child_frame_index += num_child_frames;
    }
}

// Helper function to generate random data based on the given modulation scheme
