            break;
        case 3:
            // Assume custom struct definition as given by the user
            // ...
            break;
    }
}

// Main function to create a frame structure with nested frames and random data
int main() {
    LTE_DL_FRAME_MESSAGE *frames;
    init_frames(&frames, 1, 0);
    populate_frame(frames[0], rand() % 4, 3, generate_random_data(rand() % 4), sizeof(uint32_t));
    return 0;
}

