// Thread-safe list structure
typedef struct list {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
} List;

List* create_list(size_t capacity) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;
    list->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = capacity;
    list->length = 0;
    for (size_t i = 0; i < capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[i];
        pthread_mutex_init(&pdu->mutex, NULL);
    }
    return list;
}

void destroy_list(List* list) {
    if (!list) return;
    for (size_t i = 0; i < list->capacity; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list->data[i];
        pthread_mutex_destroy(&pdu->mutex);
    }
    free(list->data);
    free(list);
}

// Add a new PDU to the list, returning an error code
