    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (fd != -1) {
        dprintf(fd, "[%s] RNTI: 0x%lX, CRCFLAG: %s\n", timestamp, pdu->rnti, pdu->crc_indication.crcflag ? "TRUE" : "FALSE");
