    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu();
        if (!pdu) continue; // Retry on failure

        sem_wait(&semaphore);
        // Add pdu to the managed list here, ensuring thread-safety
        sem_post(&semaphore);
    }
}

int manage_pdus(struct config *cfg) {
    sem_init(&semaphore, 0, cfg->max_limit);
    fd = open(cfg->log_file, O_WRONLY | O_APPEND | O_CREAT | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) return -1; // Handle invalid file paths here

    pthread_t threads[cfg->max_limit];
    for (int i = 0; i < cfg->max_limit; ++i) {
        int rc = pthread_create(&threads[i], NULL, thread_function, cfg);
        if (rc) return rc; // Handle memory allocation failures here
    }

    for (int i = 0; i < cfg->max_limit; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&semaphore);
    close(fd);

    return 0;
}
