    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* data = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
size_t size = 0;

void clear() {
    if (data) {
        munmap(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
        data = NULL;
        size = 0;
    }
}

void* allocate_memory(size_t new_size) {
    void* mem = mmap(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    return mem;
}

void expand_array() {
    size_t new_size = size + 1024;
    void* new_data = allocate_memory(new_size);
    if (data) {
        memcpy(new_data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    }
    pthread_mutex_destroy(&mutex);
    munmap(data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    data = new_data;
    size = new_size;
    pthread_mutex_init(&mutex, NULL);
}

void push(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&mutex);
    if (size == MAX_ELEMENTS) {
        expand_array();
    }
    data[size] = *pdu;
    size++;
    pthread_mutex_unlock(&mutex);
}

// Function to handle periodic updates from external data source
