typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef void (*callback)(NFAPI_CRC_INDICATION_PDU_T*);

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t capacity = 0;
static size_t count = 0;
static callback add_element;
static FILE* log_file = stderr;

enum error_codes { NO_ERROR, MEMORY_ALLOCATION_FAILURE, INVALID_INPUT };

void init_list(size_t initial_capacity) {
    if (initial_capacity == 0) return;

    list = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(log_file, "Memory allocation failure\n");
        return NO_ERROR;
    }

    capacity = initial_capacity;
}

enum error_codes add_element_to_list(RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    if (!tag || !rnti) return INVALID_INPUT;

    pthread_mutex_lock(&list_mutex);

    if (count >= capacity) {
        size_t new_capacity = capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list_mutex);
            fprintf(log_file, "Memory allocation failure\n");
            return MEMORY_ALLOCATION_FAILURE;
        }

        list = new_list;
        capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &list[count];
    pdu->tag = tag;
    pdu->rnti = rnti;
    pdu->crc_indication.crcflag = rand() % 2;

    add_element(pdu);
    count++;

    pthread_mutex_unlock(&list_mutex);

    return NO_ERROR;
}

void log_error(enum error_codes error) {
    switch (error) {
        case INVALID_INPUT:
            fprintf(log_file, "Invalid input\n");
            break;
        case MEMORY_ALLOCATION_FAILURE:
            fprintf(log_file, "Memory allocation failure\n");
            break;
        default:
            break;
    }
}
