typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_CAPACITY 1024
static NFAPI_CRC_INDICATION_PDU_T *array = NULL;
static size_t current_size = 0, max_allocated = 0;
static const char *resource_pool_name = "NFAPI CR-IND PDU pool";

// Hash function for RNTI
uint32_t rnti_hash(RNTI rnti) {
    uint32_t hash = 5381;
    for (int i = 0; i < sizeof(RNTI); i++)
        hash = (hash * 33) ^ rnti[i];
    return hash % MAX_CAPACITY;
}

// Linear probing function
size_t linear_probe(size_t index, size_t table_size) {
    for (int i = 1; ; i++) {
        index = (index + i) % table_size;
        if (array[index].rnti == 0)
            return index;
    }
}

void initialize() {
    // Allocate initial capacity and track resource usage
    array = calloc(MAX_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Error allocating memory for %s\n", resource_pool_name);
        exit(1);
    }
    max_allocated = MAX_CAPACITY;
}

void add(const NFAPI_CRC_INDICATION_PDU_T *pdus, size_t num_pdu) {
    if (num_pdu == 0 || current_size + num_pdu > max_allocated)
        return;

    // Handle memory fragmentation and cache performance
    size_t table_index, probe_index = linear_probe(0, MAX_CAPACITY);

    for (size_t i = 0; i < num_pdu; ++i) {
        if (array[probe_index].rnti != 0)
            probe_index = linear_probe(probe_index + 1, MAX_CAPACITY);

        array[probe_index] = *pdus++;
        array[probe_index].crc_indication.crcflag = rand() % 2;
        current_size++;
    }
}

void remove(RNTI rnti) {
    uint32_t index = rnti_hash(rnti);
    size_t probe_index = linear_probe(index, MAX_CAPACITY);

    if (array[probe_index].rnti == rnti) {
        array[probe_index] = (NFAPI_CRC_INDICATION_PDU_T){0};
        current_size--;
    } else {
        size_t i = probe_index + 1;
        for (; i < MAX_CAPACITY; ++i) {
            if (array[i].rnti == rnti) {
                array[probe_index] = array[i];
                array[i] = (NFAPI_CRC_INDICATION_PDU_T){0};
                current_size--;
                break;
            }
        }
    }
}

int search(RNTI rnti) {
    uint32_t index = rnti_hash(rnti);
    size_t probe_index = linear_probe(index, MAX_CAPACITY);

    for (; ; ++probe_index) {
        if (array[probe_index].rnti == rnti)
            return probe_index;

        if (probe_index >= MAX_CAPACITY)
            return -1;

        if (array[probe_index].rnti == 0)
            probe_index = linear_probe(probe_index, MAX_CAPACITY);
    }
}

void display() {
    // Implement a logging filter to control verbosity
    if (!current_size)
        return;

    printf("\nNFAPI CR-IND PDU pool (capacity: %zu, current size: %zu):\n", max_allocated, current_size);
    for (size_t i = 0; i < current_size; ++i) {
        printf("%2zu: RNTI=%d CRC_INDICATION.CRCFLAG=%d\n", i, array[i].rnti, array[i].crc_indication.crcflag);
    }
}
