    pthread_mutex_init(&ue_contexts_mutex, NULL);
}

// Add a new UE context
void add_ue_context(UEContext *new_context) {
    if (context_count >= max_ue_contexts) {
        fprintf(stderr, "The maximum number of UE contexts has been reached\n");
        return;
    }

    pthread_mutex_lock(&ue_contexts_mutex);
    ue_contexts[context_count] = new_context;
    configure_callback(new_context); // Apply configuration to newly created context
    context_count++;
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Update an existing UE context by id
void update_ue_context(int id, UEContext *updated_context) {
    size_t index = find_ue_context_index(id);
    if (index == UNSPECIFIED_UE_CONTEXT_INDEX) {
        fprintf(stderr, "Could not find UE context with the given identifier\n");
        return;
    }

    pthread_mutex_lock(&ue_contexts_mutex);
    UEContext *current_context = ue_contexts[index];
    memcpy(current_context, updated_context, sizeof(UEContext)); // Update context data
    persist_callback(current_context, NULL); // Save the updated context data to the database
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Retrieve a UE context by id
UEContext* get_ue_context(int id) {
    size_t index = find_ue_context_index(id);
    if (index == UNSPECIFIED_UE_CONTEXT_INDEX) {
        fprintf(stderr, "Could not find UE context with the given identifier\n");
        return NULL;
    }

    pthread_mutex_lock(&ue_contexts_mutex);
    UEContext *context = ue_contexts[index];
    pthread_mutex_unlock(&ue_contexts_mutex);

    return context;
}

// Clean up resources when the array is no longer needed
void destroy_ue_contexts() {
    for (size_t i = 0; i < context_count; ++i)
        cleanup_callback(ue_contexts[i]);

    free(ue_contexts);
}
```

This implementation handles thread safety using a mutex, dynamically allocates memory for the UE context array, and provides functions for adding, updating, and retrieving contexts. The code also includes mechanisms to clean up resources when the array is no longer needed, as well as support for error handling and configuration flexibility.']

