#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    uint32_t crcflag;
};

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

static struct list_node* head = NULL;
static size_t count = 0;
static const size_t max_size = 1000;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t total_crcflag = 0;

void init_list() {
    if (head) return; // already initialized
    head = malloc(sizeof(struct list_node));
    if (!head) {
        printf("Error: Unable to allocate memory for list\n");
        exit(EXIT_FAILURE);
    }
    head->next = NULL;
}

void destroy_list() {
    struct list_node *current, *temp;
    pthread_mutex_lock(&mutex);
    current = head->next;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    head->next = NULL;
    count = 0;
    pthread_mutex_unlock(&mutex);
}

void add_to_list() {
    struct list_node* new_node;

    pthread_mutex_lock(&mutex);
    if (count >= max_size) {
        printf("Error: List is full\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    new_node = malloc(sizeof(struct list_node));
    if (!new_node) {
        printf("Error: Unable to allocate memory for new node\n");
        pthread_mutex_unlock(&mutex);
        destroy_list(); // free other nodes and reset count on failure
        return;
    }

    memset(new_node, 0, sizeof(struct list_node));
    total_crcflag += rand(); // update the running checksum
    new_node->data.crc_indication.crcflag = total_crcflag;
    new_node->next = head->next;
    head->next = new_node;
    count++;
    pthread_mutex_unlock(&mutex);
}

void log_checksum() {
    printf("Total CRCFLAG checksum: 0x%" PRIx32 "\n", total_crcflag);
}
```
