#define MAX_STRUCTS 10000
struct cache {
    size_t used;
    NFAPI_CRC_INDICATION_PDU_T* data[MAX_STRUCTS];
};

static struct cache cache;
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

struct thread_data {
    size_t index;
};

void init_struct(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    struct_ptr->tag = generate_ue_information_tag(); // Function for generating UE information tag.
    struct_ptr->rnti = generate_rnti(); // Function for generating RNTI.
    struct_ptr->crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    struct_ptr->timestamp = time(NULL);
}

void* allocate_struct(void* arg) {
    size_t* index = arg;
    if (index >= cache.used || cache.data[*index] == NULL) {
        while (cache.used >= MAX_STRUCTS) {
            pthread_mutex_lock(&cache_mutex);
            if (cache.used >= MAX_STRUCTS) {
                pthread_mutex_unlock(&cache_mutex);
                usleep(100); // Sleep to reduce contention.
                continue;
            }
            pthread_mutex_unlock(&cache_mutex);
        }
        NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_struct == NULL) {
            // Log error and return NULL.
            return NULL;
        }
        init_struct(new_struct);
        cache.data[cache.used++] = new_struct;
    }
    size_t* temp_index = &cache.data[*index][0];
    *temp_index = *index;
    return cache.data[*index];
}

NFAPI_CRC_INDICATION_PDU_T* allocate_structs(size_t N) {
    if (N <= 0) return NULL;
    size_t allocated = 0;
    struct thread_data threads[N];
    for (size_t i = 0; i < N; ++i) {
        threads[i].index = allocated++;
        pthread_t thread;
        if (pthread_create(&thread, NULL, allocate_struct, &threads[i].index) != 0) {
            // Log error and return NULL.
            return NULL;
        }
    }
    for (size_t i = 0; i < N; ++i) {
        pthread_join(threads[i].index, NULL);
    }
    if (allocated != N) {
        // Log error and return remaining allocated structures.
        return cache.data;
    }
    return cache.data;
}
```
