// TrafficEvent structure
struct TrafficEvent {
    time_t timestamp;
    enum EventType { NONE, EVENT1, EVENT2, EVENT3 } event;
    char* metadata; // dynamically allocated memory
};

// Custom dynamic array with garbage collection
class DynamicArray {
private:
    std::map<time_t, TrafficEvent*> data;  // data stored as a map for efficient lookups
    int capacity;
    int size;
    pthread_mutex_t lock;
    GarbageCollector gc; // Garbage collector object

public:
    DynamicArray(int initialCapacity) : capacity(initialCapacity), size(0) {
        data.reserve(capacity);
        gc = GarbageCollector();
        pthread_mutex_init(&lock, nullptr);
    }

    ~DynamicArray() {
        pthread_mutex_destroy(&lock);
    }

    // Add event to the array with garbage collection
    void addEvent(TrafficEvent* event) {
        // Lock the mutex before modifying data to ensure thread safety
        pthread_mutex_lock(&lock);

        // Add event to the dynamic array and call garbage collector if necessary
        data[event->timestamp] = event;
        gc.collect();

        // Unlock the mutex after modifying data to ensure thread safety
        pthread_mutex_unlock(&lock);
    }

    // Update event in the array with garbage collection
    void updateEvent(TrafficEvent* event) {
        // Lock the mutex before modifying data to ensure thread safety
        pthread_mutex_lock(&lock);

        // Update event in the dynamic array and call garbage collector if necessary
        data[event->timestamp] = event;
        gc.collect();

        // Unlock the mutex after modifying data to ensure thread safety
        pthread_mutex_unlock(&lock);
    }

    // Query event from the array with garbage collection
    TrafficEvent* queryEvent(time_t timestamp) {
        // Lock the mutex before modifying data to ensure thread safety
        pthread_mutex_lock(&lock);

        // Return event if it exists, otherwise return null
        auto it = data.find(timestamp);
        TrafficEvent* event = (it != data.end()) ? it->second : nullptr;

        // Unlock the mutex after querying data to ensure thread safety
        pthread_mutex_unlock(&lock);

        return event;
    }
};

// Garbage collector class
class GarbageCollector {
public:
