    if (mmaped_file == MAP_FAILED) {
        if (error_func) error_func("Error mapping file for concurrent access");
        free(cfg->data);
        json_decref(cfg->config);
        free(cfg);
        return NULL;
    }

    cfg->num_entries = populate_data(cfg, mmaped_file, st.st_size);
    munmap(mmaped_file, st.st_size);

    return cfg;
}

