UeContextInfo* initUeContexts() {
    UeContextInfo* ueContexts = malloc(MAX_UE_CONTEXTS * sizeof(UeContextInfo));
    if (!ueContexts) {
        perror("Memory allocation error");
        return NULL;
    }

    pthread_t nmsThread;
    NMSConfig nmsConfig;
    getNMSConfig(&nmsConfig); // Retrieve network configurations from NMS

    int usedContexts = 0;
    for (int i = 0; i < MAX_UE_CONTEXTS; ++i) {
        UeContextInfo* ueContext = &ueContexts[i];
        ueContext->ueId = i + 1;
        ueContext->rrcConnReqList = malloc(nmsConfig.numRntis * sizeof(RrcConnectionRequest));
        if (!ueContext->rrcConnReqList) {
            perror("Memory allocation error");
            return NULL;
        }

        int numUniqueRntis = 0;
        for (int j = 0; j < nmsConfig.numRntis && numUniqueRntis < nmsConfig.numRntis; ++j) {
            int foundDuplicate = 0;
            for (int k = 0; k < i && !foundDuplicate; ++k) {
                if (ueContexts[k].rrcConnReqList[numUniqueRntis].rnti == ueContext->rrcConnReqList[j].rnti) {
                    foundDuplicate = 1;
                }
            }

            if (!foundDuplicate) {
                ueContext->rrcConnReqList[numUniqueRntis] = ueContext->rrcConnReqList[j];
                ++numUniqueRntis;
            }
        }

        for (int j = numUniqueRntis; j < nmsConfig.numRntis; ++j) {
            free(ueContext->rrcConnReqList[j].timestamp);
        }
        ueContext->rrcConnReqList[nmsConfig.numRntis] = NULL; // Mark the end of the list

        if (numUniqueRntis > 0) {
            genSecKey(ueContext->securityKey, numUniqueRntis);
            ++usedContexts;
        }
    }

    cacheNMSConfig(nmsConfig); // Cache network configurations for future use

    return &ueContexts[0];
}

void getNMSConfig(NMSConfig* nmsConfig) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Socket creation error");
        return;
    }

    struct sockaddr_in serv_addr;
    memset((char*)&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(nmsConfigPort);
    inet_pton(AF_INET, nmsConfigIp, &serv_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection error");
        close(sockfd);
        return;
    }

    recv(sockfd, nmsConfig, sizeof(NMSConfig), 0);

    for (int i = 0; i < RETRY_INTERVAL && !nmsConfig->isReady; ++i) {
        sleep(1);
        if (connect(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
            perror("Connection error");
            close(sockfd);
            return;
        }
        recv(sockfd, nmsConfig, sizeof(NMSConfig), 0);
    }

    if (!nmsConfig->isReady) {
        fprintf(stderr, "Error: NMS is not ready\n");
    }
}

void cacheNMSConfig(NMSConfig nmsConfig) {
    int cacheFile = open(CONFIG_FILE, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (cacheFile < 0) {
        perror("Error opening cache file");
        return;
    }

    write(cacheFile, &nmsConfig, sizeof(NMSConfig));
    close(cacheFile);

    // Implement an LRU eviction policy based on the given EVICTION_RATE
}
