    for (int i = 0; i < 100; ++i) {
        ueContexts[i].ueId = i + 1;
        ueContexts[i].mutex = PTHREAD_MUTEX_INITIALIZER;

        for (int j = 0; j < 10; ++j) {
            ueContexts[i].connections[j] = malloc(sizeof(RrcConnectionRequest));
            if (!ueContexts[i].connections[j]) {
                perror("Memory allocation error");
                exit(EXIT_FAILURE);
            }
        }

        // Generate unique rntis and store them in the first connection for each UE context
        ueContexts[i].connections[0]->rnti = rand() % (UINT16_MAX + 1);
        for (int j = 1; j < i; ++j) {
            while (ueContexts[j].connections[0]->rnti == ueContexts[i].connections[0]->rnti) {
                ueContexts[i].connections[0]->rnti = rand() % (UINT16_MAX + 1);
            }
        }

        // Generate securityKey for each UE context using a secure random number generator
        // ...

        ++ueCount;
    }
}

void handleRrcConnectionRequest(UeContextInfo* ueContext, RrcConnectionRequest request) {
    pthread_mutex_lock(&ueContext->mutex);

    bool activeConnectionsFull = false;
    for (int i = 0; i < 10 && !activeConnectionsFull; ++i) {
        if (!ueContext->connections[i]) {
            ueContext->connections[i] = request;
        } else if (ueContext->connections[i]->timestamp > request.timestamp) {
            // Overwrite an older connection
            for (int j = i + 1; j < 10; ++j) {
                if (!ueContext->connections[j]) {
                    ueContext->connections[j] = request;
                    activeConnectionsFull = false;
                    break;
                }
            }
        } else {
            activeConnectionsFull = true;
        }
    }

    if (activeConnectionsFull) {
        LOG(INFO, "UE %d reached maximum number of active connections.", ueContext->ueId);
    }

    pthread_mutex_unlock(&ueContext->mutex);
}

void cleanupInactiveConnections() {
    struct timeval now;
    gettimeofday(&now, NULL);
    time_t currentTime = now.tv_sec;

    for (int i = 0; i < 100; ++i) {
        pthread_mutex_lock(&ueContexts[i].mutex);

        bool anyActiveConnectionsRemoved = false;
        for (int j = 0; j < 10; ++j) {
            if (ueContexts[i].connections[j]) {
                if (ueContexts[i].connections[j]->timestamp + 3600 < currentTime) {
                    free(ueContexts[i].connections[j]);
                    ueContexts[i].connections[j] = NULL;
                    anyActiveConnectionsRemoved = true;
                }
            }
        }

        if (anyActiveConnectionsRemoved) {
            // Notify that some connections have been cleaned up, adjust threshold dynamically based on current network load and performance metrics
            LOG(INFO, "UE %d had inactive connections removed.", ueContexts[i].ueId);
        }

        pthread_mutex_unlock(&ueContexts[i].mutex);
    }
}
