CRC_INDICATION_POOL_T* crc_indication_pool_create(size_t capacity) {
    CRC_INDICATION_POOL_T* pool = (CRC_INDICATION_POOL_T*)malloc(sizeof(CRC_INDICATION_POOL_T));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->count = 0;
    pool->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < capacity; ++i) {
        pool->data[i].RX_UE_INFORMATION_TAG = 12345678; // Placeholder value
        pool->data[i].RNTI = i + 1;
        pool->data[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pthread_mutex_init(&pool->data[i].mutex, NULL);
    }

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* crc_indication_pool_get(CRC_INDICATION_POOL_T* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->capacity) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &pool->data[pool->count];
    ++pool->count;
    pthread_mutex_unlock(&pool->lock);

    return entry;
}

bool crc_indication_pool_set(CRC_INDICATION_POOL_T* pool, NFAPI_CRC_INDICATION_PDU_T* entry, uint16_t rnti) {
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (&pool->data[i] == entry && pool->data[i].RNTI == rnti) {
            pthread_mutex_lock(&entry->mutex);
            pool->data[i].RX_UE_INFORMATION_TAG = rand(); // Update placeholder value
            pool->data[i].CRC_INDICATION_REL8_TAG = rand() % 256; // Randomly update CRCFLAG
            pthread_mutex_unlock(&entry->mutex);
            return true;
        }
    }

    return false;
}

void crc_indication_pool_destroy(CRC_INDICATION_POOL_T* pool) {
    if (!pool) return;

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->count; ++i) {
        pthread_mutex_destroy(&pool->data[i].mutex);
    }
    free(pool->data);
    pthread_mutex_unlock(&pool->lock);
    free(pool);
}
