    struct Node* next;
} Node;

void validate_list(Node** head) {
    bool circular = false, mismatch = false;
    Node* current = *head, *check = NULL;

    if (!current) return;
    check = current;

    while (current->next != NULL) {
        current = current->next;
        if (current == check) circular = true;
        if (!mismatch && current_crc32(&current->data.crc) != current->data.crc) mismatch = true;
    }

    if (circular) {
        fprintf(stderr, "Circular linked list detected!\n");
        free_list(head); // Cleanup and reallocate memory for a new list
    }
    else if (mismatch) {
        fprintf(stderr, "Inconsistent CRCFLAG values found in the list.\n");
        // Handle inconsistencies as per your system's requirements (e.g., log, discard elements, or correct them)
    }
}

void free_list(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = *data;
    newNode->next = NULL;

    return newNode;
}

void insert_node(Node** head, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (head == NULL || *head == NULL) {
        *head = create_node(data);
        if (*head == NULL) return; // Handle out-of-memory errors gracefully
    }
    else {
        Node* current = *head, *newNode = create_node(data);

        while (current->next != NULL && current->next->data.batch_id == newNode->data.batch_id) { // Batch processing
            if (current->next->next == NULL) {
                current->next = newNode;
                break;
            }
            current = current->next;
        }

        if (current->next == NULL && current->data.batch_id != newNode->data.batch_id) { // Handle exceeding batch size or different batches
            free(newNode);
        }
        else {
            newNode->next = current->next;
            current->next = newNode;
        }
    }
}

void manage_list(const NFAPI_CRC_INDICATION_PDU_T* data, size_t max_batch_size) {
    static Node* head = NULL; // Assuming persistent storage of the list between function calls
    insert_node(&head, data);
    validate_list(&head);
}
