void list_manager_push(struct list_manager *mgr, CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&mgr->mutex);
    if (mgr->count >= mgr->capacity && !mgr->callback(node)) { // Discard node if callback fails or list is full
        free(node);
        pthread_mutex_unlock(&mgr->mutex);
        return;
    }

    size_t index = mgr->count % mgr->capacity;
    CRC_INDICATION_PDU_T **current = &mgr->head[index];

    // Detect and handle circular linked list formation during insertion
    while (*current && (*current)->next == *current) {
        if (mgr->callback(node)) { // Callback for handling circular linked list detection
            free(node);
        }
        current = &((*current)->next);
