} NFAPI_CRC_INDICATION_PDU_T;

struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
};

static struct node* head = NULL;
static struct node* tail = NULL;
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_elements = 0;
static int eviction_policy = 1; // 1: LRU, 2: LFU...
static time_t last_access[M];

void list_init() {
    head = (struct node*)malloc(sizeof(struct node));
    head->next = NULL;
    tail = head;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T data) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&list_mutex);
    tail->next = new_node;
    tail = new_node;
    num_elements++;

    if (num_elements > M) {
        struct node* to_evict = head->next;
        memmove(last_access, last_access + 1, sizeof(time_t) * (M - 1));
        last_access[M-1] = time(NULL);

        while (to_evict && eviction_policy == 1) { // LRU policy
            if (last_access[0] < last_access[to_evict->next ? to_evict->next->data.timestamp : 0]) {
                to_evict = to_evict->next;
            } else {
                break;
            }
        }

        if (to_evict) {
            struct node* temp = to_evict;
            head->next = to_evict->next;
            free(temp);
            num_elements--;
        }

        pthread_mutex_unlock(&list_mutex);
    } else {
        pthread_mutex_unlock(&list_mutex);
    }
}

bool dequeue(NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);
    if (head->next == NULL) {
        pthread_mutex_unlock(&list_mutex);
        return false;
    }

    struct node* temp = head->next;
    *data = temp->data;
    head->next = temp->next;
    free(temp);

    if (num_elements == 1) {
        head = NULL;
        tail = NULL;
    }

    num_elements--;
    pthread_mutex_unlock(&list_mutex);

    return true;
}

void validate() {
    bool inconsistency_found = false;
    struct node* curr = head->next;

    while (curr) {
        if (curr->data.CRCFLAG != curr->next ? curr->next->data.CRCFLAG : 0) {
            inconsistency_found = true;
            break;
        }
        curr = curr->next;
    }

    if (inconsistency_found) {
        printf("Inconsistency found in CRCFLAG values!\n");
    }
}
```
