} entry_t;

// Custom RNTI set for fast lookup and uniqueness check
typedef struct {
    uint32_t* data;
    size_t len;
} RNTISet;

void initRNTISet(RNTISet* rntiSet) {
    rntiSet->data = malloc(RNTI_SET_SIZE * sizeof(uint32_t));
    memset(rntiSet->data, 0, RNTI_SET_SIZE * sizeof(uint32_t));
    rntiSet->len = 0;
}

void addRNTIToSet(RNTISet* rntiSet, uint32_t rnti) {
    if (rntiSet->data[rnti] == 1) {
        fprintf(stderr, "Warning: Duplicate RNTI encountered.\n");
    } else {
        rntiSet->data[rnti] = 1;
        rntiSet->len++;
    }
}

void removeRNTISet(RNTISet* rntiSet, uint32_t rnti) {
    if (rntiSet->data[rnti]) {
        rntiSet->data[rnti] = 0;
        rntiSet->len--;
    }
}

int findRNTISet(const RNTISet* rntiSet, uint32_t rnti) {
    return rntiSet->data[rnti];
}

void createDynamicList(entry_t** list, size_t* len) {
    *list = malloc(MAX_LIST_SIZE * sizeof(entry_t));
    *len = 0;
}

void addEntryToList(entry_t** list, size_t* len, RNTISet rntiSet, time_t timestamp) {
    uint32_t rnti = rand() % MAX_LIST_SIZE;

    while (findRNTISet(&rntiSet, rnti)) {
        rnti = (rnti + 1) % MAX_LIST_SIZE;
    }

    addRNTIToSet(&rntiSet, rnti);

    list[*len]->timestamp = timestamp;
    list[*len]->pdu.RX_UE_INFORMATION_TAG = (NFAPI_RX_UE_INFORMATION_TAG_T)rand();
    list[*len]->pdu.RNTI = rnti;
    list[*len]->pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

    (*len)++;
}

void freeDynamicList(entry_t** list, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        free(list[i]);
    }
    free(*list);
}
