static size_t g_total_allocated = 0; // Total number of successfully allocated structures

void set_seed(uint64_t seed) {
    pthread_mutex_lock(&g_mutex);
    g_seed = seed;
    pthread_mutex_unlock(&g_mutex);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu_array(size_t n) {
    if (n > MAX_N || n == 0) {
        fprintf(stderr, "Invalid array size: %zu\n", n);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        perror("malloc failed");
        return NULL;
    }

    pthread_mutex_lock(&g_mutex);
    g_total_allocated += n;
    pthread_mutex_unlock(&g_mutex);

    // Align data for network communication and endianness handling
    void* aligned_pdus = posix_memalign(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!aligned_pdus) {
        free(pdus);
        perror("posix_memalign failed");
        return NULL;
    }

    // Populate the structures with random data
    for (size_t i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = aligned_pdus + i;

