static size_t total_allocated = 0;
static unsigned int seed = time(NULL);

void *random_number_generator(void *arg) {
    (void) arg;
    while (1) {
        pthread_mutex_lock(&mutex);
        seed = (seed * 3 + 1) % UINT_MAX;
        pthread_mutex_unlock(&mutex);
    }
