#include <pthread.h>

typedef struct _node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct _node *prev, *next;
} Node;

Node* create_node(const RX_UE_INFORMATION_TAG*, const RNTI);
void init_list(Node** head);
int append_node(Node**, Node*);
Node* get_node_by_rnti(const Node*, const RNTI);
void destroy_node(Node**);
void garbage_collect(Node**);

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

Node* create_node(const RX_UE_INFORMATION_TAG *ue, const RNTI rnti) {
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return nullptr;

    new_node->data.ueInfoTag = *ue;
    new_node->data.rnti = rnti;
    new_node->data.crcIndicationRel8Tag.crcFlag = rand() % 2;
    time_t timestamp = time(NULL);
    new_node->data.crcIndicationRel8Tag.timestamp = timestamp;

    new_node->prev = nullptr;
    new_node->next = nullptr;

    return new_node;
}

void init_list(Node** head) {
    *head = nullptr;
}

int append_node(Node **head, Node *new_node) {
    if (!head || !new_node) return -1;

    pthread_mutex_lock(&list_mutex);
    Node *temp = *head;

    if (*head) {
        while (temp->next != nullptr) temp = temp->next;
        temp->next = new_node;
        new_node->prev = temp;
    } else {
        *head = new_node;
    }

    pthread_mutex_unlock(&list_mutex);

    return 0;
}

Node* get_node_by_rnti(const Node *head, const RNTI rnti) {
    if (!head) return nullptr;

    Node *temp = head;

    while (temp != nullptr) {
        if (temp->data.rnti == rnti) break;
        temp = temp->next;
    }

    return temp;
}

void destroy_node(Node **node) {
    if (!node || !*node) return;

    pthread_mutex_lock(&list_mutex);

    if ((*node)->prev != nullptr) (*(*node)->prev).next = (*node)->next;
    if ((*node)->next != nullptr) (*(*node)->next)->prev = (*node)->prev;

    free(*node);
    *node = nullptr;

    pthread_mutex_unlock(&list_mutex);
}

void garbage_collect(Node **head) {
    if (!head || !*head) return;

    Node *current, *next;
    pthread_mutex_lock(&list_mutex);

    current = *head;
    while (current != nullptr) {
        next = current->next;
        if (!next || !next->prev) {
            destroy_node(current);
            current = next;
        } else {
            current = next;
        }
    }

    pthread_mutex_unlock(&list_mutex);
}
```

