#include <time.h>

typedef struct {
    uint8_t preamble_code;
    time_t timestamp;
    int sequence_number;
    // Add your MAC_PAYLOAD structure here
} MAC_HEADER;

typedef struct MAC_PDU {
    MAC_HEADER header;
    // Add your MAC_PAYLOAD data structure here
} MAC_PDU;

typedef struct MAC_DYNAMIC_LIST {
    size_t length;
    MAC_PDU** array;
} MAC_DYNAMIC_LIST;

void mac_dynamic_list_init(MAC_DYNAMIC_LIST* list, size_t initial_capacity) {
    if (initial_capacity == 0)
        initial_capacity = 4; // Set a minimum capacity

    list->length = 0;
    list->array = malloc(initial_capacity * sizeof(MAC_PDU*));
}

void mac_dynamic_list_add(MAC_DYNAMIC_LIST* list, MAC_PDU* pdu) {
    for (size_t i = 0; i < list->length; ++i) {
        if (list->array[i]->header.preamble_code == pdu->header.preamble_code) {
            printf("Warning: Duplicate preamble code encountered.\n");
            break;
        }
    }

    list->array[list->length] = pdu;
    list->length++;
}

MAC_PDU* mac_dynamic_list_get(const MAC_DYNAMIC_LIST* list, size_t index) {
    if (index >= list->length) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return NULL;
    }

    return list->array[index];
}
```

