    struct rte_eth_dev *dev;
    pthread_mutex_t lock;
    struct rte_mbuf **rx_queues;
    unsigned int num_rx_queues;
    unsigned int cur_rx_queue;
    unsigned long *rx_queue_refs; // Dynamic queue reference counter
} Nic;

// Allocate memory for a new NIC with a specified number of transmit and receive queues
Nic* create_nic(int id, struct rte_eth_dev *dev, unsigned int num_tx_queues, unsigned int num_rx_queues) {
    Nic *nic = malloc(sizeof(Nic));
    nic->id = id;
    nic->dev = dev;
    pthread_mutex_init(&nic->lock, NULL);

    // Allocate memory for transmit queues
    nic->rx_queues = calloc(num_rx_queues, sizeof(struct rte_mbuf*));
    if (!nic->rx_queues) {
        perror("Error allocating receive queue memory");
        free(nic);
        return NULL;
    }

    // Allocate dynamic reference counter for each receive queue
    nic->rx_queue_refs = calloc(num_rx_queues, sizeof(unsigned long));
    if (!nic->rx_queue_refs) {
        perror("Error allocating receive queue reference counter memory");
        free(nic->rx_queues);
        free(nic);
        return NULL;
    }

    nic->num_rx_queues = num_rx_queues;
    nic->cur_rx_queue = 0;

    // Initialize transmit and receive queues here (e.g., rte_eth_tx_queue_init(), rte_eth_rx_queue_init())

    return nic;
}

// Adjust the number of dynamic receive queues based on current system load
void adjust_rx_queues(Nic *nic, unsigned int new_num_rx_queues) {
    // Implement a mechanism to determine the optimal number of dynamic receive queues based on the current system load
    if (new_num_rx_queues > nic->num_rx_queues) {
        unsigned int i;
        struct rte_mbuf **new_rx_queues = realloc(nic->rx_queues, new_num_rx_queues * sizeof(struct rte_mbuf*));
        if (!new_rx_queues) {
            perror("Error resizing receive queue memory");
            return;
        }
        nic->rx_queues = new_rx_queues;

        unsigned long *new_rx_queue_refs = realloc(nic->rx_queue_refs, new_num_rx_queues * sizeof(unsigned long));
        if (!new_rx_queue_refs) {
            perror("Error resizing receive queue reference counter memory");
            free(nic->rx_queues);
            return;
        }
        nic->rx_queue_refs = new_rx_queue_refs;

        memset(&nic->rx_queues[nic->num_rx_queues], 0, (new_num_rx_queues - nic->num_rx_queues) * sizeof(struct rte_mbuf*));
        memmove(&nic->rx_queue_refs[nic->num_rx_queues], &nic->rx_queue_refs[0], nic->num_rx_queues * sizeof(unsigned long));
        nic->num_rx_queues = new_num_rx_queues;
    } else if (new_num_rx_queues < nic->num_rx_queues) {
        unsigned int i;
        struct rte_mbuf *temp_rx_queue;
        unsigned long temp_rx_queue_ref;

        for (i = new_num_rx_queues; i < nic->num_rx_queues; ++i) {
            temp_rx_queue = nic->rx_queues[i];
            temp_rx_queue_ref = nic->rx_queue_refs[i];
            if (temp_rx_queue && temp_rx_queue_ref > 0) {
                // Free the unused receive queue and its reference counter entry
                free(temp_rx_queue);
                nic->rx_queues[i] = NULL;
                nic->rx_queue_refs[i] = 0;
            }
        }
        nic->num_rx_queues = new_num_rx_queues;
    }
}

