['```python
import os
import sys
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging
from queue import Queue
import signal
import pickle

class HashWorker:
    def __init__(self, file_path):
        self.file_path = file_path
        self.hexdigest = None
        self.error = None

    def calculate_hash(self):
        hasher = hashlib.md5()
        with open(self.file_path, 'rb') as f:
            while True:
                chunk = f.read(64*1024)
                if not chunk:
                    break
                hasher.update(chunk)
            self.hexdigest = hasher.hexdigest()

class FileHasher:
    def __init__(self, directory, log_file, num_workers=os.cpu_count()):
        self.directory = directory
        self.log_file = log_file
        self.num_workers = num_workers
        self.status_updates = Queue()
        self.errors = Queue()
        self.worker_results = {}
        self.threadpool = ThreadPoolExecutor(max_workers=self.num_workers)
        self.signal.signal(signal.SIGINT, self.handle_interrupt)

    def handle_interrupt(self, signum, frame):
        self.threadpool.shutdown()
        self.save_state()

    def save_state(self):
        with open(self.log_file + '.pickle', 'wb') as f:
            pickle.dump((self.worker_results, self.status_updates, self.errors), f)

    def load_state(self):
        if os.path.exists(self.log_file + '.pickle'):
            with open(self.log_file + '.pickle', 'rb') as f:
                (self.worker_results, self.status_updates, self.errors) = pickle.load(f)
        else:
            self.worker_results = {}

    def process_files(self):
        logging.basicConfig(filename=self.log_file, level=logging.INFO)
        self.load_state()
        for root, _, files in sorted(os.walk(self.directory)):
            for file in files:
                worker = HashWorker(os.path.join(root, file))
                future = self.threadpool.submit(worker.calculate_hash)
                self.worker_results[future] = worker
        for future in as_completed(self.threadpool):
            worker = self.worker_results[future]
            try:
                worker.calculate_hash()
                self.status_updates.put((worker.file_path, 'Completed'))
            except Exception as e:
                logging.error(f"Error processing file {worker.file_path}: {str(e)}")
                self.errors.put((worker.file_path, str(e)))
        self.save_state()

    def run(self):
        self.process_files()
        if not self.errors.empty():
            raise CustomHashError("Failed to compute hashes for the following files: {}".format(", ".join([str(e) for e in self.errors.queue])))
        return {k.result().file_path: k.result().hexdigest for k in self.threadpool.map((lambda w: w.result()), self.worker_results)}
```

This code defines a `HashWorker` class responsible for calculating file hashes in parallel using multithreading and a `FileHasher` class handling directory traversal, error logging, and status updates. The function `run()` initializes the object, processes files, handles potential interruptions gracefully, and returns a dictionary containing the calculated hash values for each successfully processed file. If any file fails to compute its hash, a custom exception is raised indicating the failure.']

