#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <tbb/concurrent_unordered_map.h>
#include <tbb/mutex.h>
#include <tbb/tbb_thread.h>
#include "UEContext.h" // Definitions for UEContext, NAS_Message, RadioResourceManager
#include "MessageBroker.h" // Interface for message broker

class UEContextPool {
private:
    tbb::concurrent_unordered_map<uint32_t, UEContext*, tbb::mutex> contextMap;
    MessageBroker* messageBroker;

public:
    UEContextPool(MessageBroker* mb) : messageBroker(mb) {}

    UEContext* allocateUEContext(uint32_t rnti) {
        tbb::mutex::scoped_lock lock(contextMap.mutex());
        auto it = contextMap.find(rnti);
        if (it != contextMap.end()) {
            it->second->refCount++;
            return it->second;
        }

        UEContext* ctx = new UEContext(rnti, messageBroker);
        contextMap[rnti] = ctx;
        return ctx;
    }

    void releaseUEContext(UEContext* ctx) {
        tbb::mutex::scoped_lock lock(contextMap.mutex());
        if (--ctx->refCount == 0) {
            contextMap.erase(ctx->rnti);
            delete ctx;
        }
    }
};
```
In this implementation, we use a concurrent hash map for efficient allocation and retrieval of `UEContext` instances based on their RNTI values. The reference-counted pointer pattern is used to manage memory efficiently, minimizing unnecessary memory allocations and deallocations during high concurrency scenarios. The `MessageBroker` instance is passed as a constructor argument, ensuring seamless interaction with the external message broker for reliable message delivery.

The implementation uses the TBB library (Thread Building Blocks) for concurrent data structures, which provides scalable performance under varying load conditions and low overhead synchronization primitives that help minimize latency. The design allows easy integration into an existing network architecture since it follows a common pattern of using reference-counted pointers and external libraries for asynchronous communication.']

