char* trimAndAppendSlash(const char* str, size_t maxLength, void (*callback)(const char*, bool)) {
    if (!str || strlen(str) >= maxLength) return NULL;

    char* modifiedStr = malloc((strlen(str) + 1 + (maxLength - strlen(str)) + 1) * sizeof(char));
    if (!modifiedStr) return NULL;

    strncpy(modifiedStr, str, maxLength);
    modifiedStr[maxLength] = '\0';

    if (*(strlen(str) + modifiedStr)) {
