```c
char* trimAndAppendSlash(char *str, int sizeLimit, void (*callback)(char*, int)) {
    if (!str || sizeLimit <= 0) return NULL;
    char* tempStr = malloc(strlen(str) + 1);
    strcpy(tempStr, str);
    int len = strlen(tempStr);
    if (len > sizeLimit) {
        free(tempStr);
        return NULL;
    }
    if (callback) callback(tempStr, len);
    tempStr[len] = '/';
    tempStr[len + 1] = '\0';
    return tempStr;
}
