        if (head == NULL) return -1; // Memory allocation error
        head->data = data;
        head->next = NULL;
        return 0;
    }

    list_node *temp = head, *new_node;
    for (int i = 0; i < MAX_ENTRIES && temp->next != NULL; ++i) {
        temp = temp->next;
    }

    if (temp->next == NULL) { // Reached the end of the list, create a new node
        new_node = malloc(sizeof(list_node));
        if (new_node == NULL) return -1; // Memory allocation error
        new_node->data = data;
        new_node->next = NULL;
        temp->next = new_node;
    } else {
        return -2; // List is full, cannot enqueue more elements
