    size_t index;
    NFAPI_CRC_INDICATION_PDU_T *current_pdu;
    static NFAPI_CRC_INDICATION_PDU_T *memory_pool = NULL;

    if (reuse_memory && memory_pool != NULL) {
        current_pdu = memory_pool;
        memory_pool = NULL;
    } else {
