        if (current_pdu == NULL) {
            error_code = 1;
            log_event("Memory allocation failure. Exiting.", log_file);
            return error_code;
        }
    }

    *pdu_array = current_pdu;

    if (reuse_memory && current_pdu + N < memory_pool) {
        size_t remaining_memory = memory_pool - current_pdu - N;
        log_event(fsprintf(stdout, "Reusing %zu bytes of previously allocated memory.\n", remaining_memory * sizeof(NFAPI_CRC_INDICATION_PDU_T)), log_file);
