using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Threading;
using System.Web;
using System.Xml;

public class NAS_MESSAGE
{
    public int ConnectionId { get; set; }
    public byte[] Data { get; set; }
}

public class Website
{
    public string SiteName { get; private set; }
    public string DirectoryPath { get; private set; }
    private readonly HttpListener _listener;
    private readonly Queue<NAS_MESSAGE> _messageQueue = new Queue<NAS_MESSAGE>();
    private SemaphoreSlim _semaphore = new SemaphoreSlim(1);

    public Website(string siteName, string directoryPath)
    {
        SiteName = siteName;
        DirectoryPath = directoryPath;
        _listener = new HttpListener();

        if (!File.Exists($"{directoryPath}/web.config")) return null;

        _listener.Prefixes.Add($"http://localhost:80/{siteName}/", "HttpNegotiate");
        _listener.Start();
    }

    public void StartProcessingMessages()
    {
        var threadPool = new ThreadPoolExecutor(MaxThreads => 5);

        while (true)
        {
            if (_messageQueue.TryDequeue(out var message))
            {
                threadPool.Execute(() => ProcessMessage(message));
            }
        }
    }

    private void ProcessMessage(NAS_MESSAGE message)
    {
        _semaphore.Wait();

        try
        {
            // Perform processing on the message here

            _semaphore.Release();
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error processing message: {ex}");
        }
    }
}

public class ThreadPoolExecutor
{
    private readonly SemaphoreSlim _semaphore;
    private readonly List<Thread> _threads = new List<Thread>();

    public ThreadPoolExecutor(int maxConcurrentTasks)
    {
        _semaphore = new SemaphoreSlim(maxConcurrentTasks);

        for (int i = 0; i < maxConcurrentTasks; i++)
        {
            var thread = new Thread(() => WorkerLoop());
            thread.IsBackground = true;
            _threads.Add(thread);
            thread.Start();
        }
    }

    public void Execute(Action action)
    {
        _semaphore.Wait();

        try
        {
            action();
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error executing action: {ex}");
        }
        finally
        {
            _semaphore.Release();
        }
    }

    private void WorkerLoop()
    {
        while (true)
        {
            _semaphore.Wait();

            try
            {
                // Perform the worker's tasks here

                _semaphore.Release();
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"Error executing worker loop: {ex}");
            }
        }
    }
}

public void InitializeAndStartWebsite(string directoryPath, string siteName)
{
    var website = new Website(siteName, directoryPath);

    if (website != null)
    {
        Console.WriteLine($"Initializing and starting website: {siteName}");

        try
        {
            website.StartProcessingMessages();
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Error initializing and starting website: {ex}");
        }
    }
    else
    {
        Console.WriteLine($"Website initialization failed for {siteName}: web.config not found.");
    }
}
```

