        data->tag = get_ue_info_tag(); // replace with external source
        data->rnti = ++unique_rnstis; // ensure uniqueness
        data->crc_indication.crcflag = rand() % 2;

        list[data->rnti - 1] = current = malloc(sizeof(Node));
        current->data = *data;
        current->next = NULL;

        if (head == NULL) {
            head = current;
        }
    }

