class CRCFLAGValidator {
public:
    void validateCRCFlag(const uint16_t& value, const size_t index) {
        if (_validFlags.find(value) == _validFlags.end()) {
            LOG(ERROR, "Invalid CRCFLAG value detected at index " << index);
            throw std::runtime_error("Invalid CRCFLAG value");
        }
    }

    void addValidFlag(uint16_t flag) {
