class Allocator {
public:
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> allocate(size_t n) {
        if (n <= 0 || rateLimiter.count() > MAX_N / RATE_LIMIT_INTERVAL.count())
            throw std::runtime_error("Invalid request size or too many requests per second");

