int allocate_phy_frames(int M) {
    PHY_RX_FRAME_INFO *frames = NULL;
    int i, processed = 0, inconsistencies = 0;

    if (M <= 0) {
        log_error("Invalid input. Requested allocation of %d structures is not valid.", M);
        return -1;
