            return -3;
        }
        processed++;
    }

    sem_post(&sem_allocator); // Release the rate limit semaphore

    log_info("Processed %d structures, encountered %d inconsistencies.", processed, inconsistencies);
    return processed;
}

// Initialize and clean up functions for semaphore and logging service
