#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct TCP_CONNECTION_RECORD {
    int connection_id;
    char source_ip[32];
    char destination_ip[32];
    unsigned short source_port, destination_port;
    time_t last_activity;
} TCP_CONNECTION_RECORD;

struct memory_pool {
    TCP_CONNECTION_RECORD *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

struct memory_pool* create_memory_pool(size_t capacity) {
    struct memory_pool *pool = malloc(sizeof(struct memory_pool));
    pool->records = calloc(capacity, sizeof(TCP_CONNECTION_RECORD));
    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

TCP_CONNECTION_RECORD* acquire_record(struct memory_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        TCP_CONNECTION_RECORD *record = &pool->records[pool->count];
        pool->count++;
        pthread_mutex_unlock(&pool->lock);
        return record;
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void release_record(struct memory_pool *pool, TCP_CONNECTION_RECORD *record) {
    memset(record, 0, sizeof(TCP_CONNECTION_RECORD));
    pthread_mutex_lock(&pool->lock);
    pool->records[--pool->count] = *record;
    pthread_mutex_unlock(&pool->lock);
}

int add_connection(struct memory_pool *pool, TCP_CONNECTION_RECORD *record) {
    if (pool->count >= 5000) return -1; // Max active connections limit exceeded

    TCP_CONNECTION_RECORD *tmp = acquire_record(pool);
    if (!tmp) return -2; // Memory pool full

    memcpy(tmp, record, sizeof(TCP_CONNECTION_RECORD));
    return 0;
}
```

