    dl_grant_t* data;
    struct list_node* next;
} list_node_t;

// Global variables for thread-safe operations
pthread_mutex_t contexts_lock = PTHREAD_MUTEX_INITIALIZER;
list_node_t* head = NULL; // Head of the dynamic list

void lte_ue_context_init(lte_ue_context_t* ctx) {
    ctx->ue_identity = 0;
    ctx->rnti = 0;
    pthread_mutex_init(&ctx->context_lock, NULL);
    ctx->grants = NULL;
}

void dl_grant_init(dl_grant_t* grant) {
    grant->scheduling_instance = 0;
    grant->power_control_command = 0;
}

list_node_t* create_context(uint32_t ue_identity, uint32_t rnti) {
    lte_ue_context_t* ctx = malloc(sizeof(lte_ue_context_t));
    lte_ue_context_init(ctx);
    ctx->ue_identity = ue_identity;
    ctx->rnti = rnti;
    return &(ctx->grants);
}

void add_grant(list_node_t* context, dl_grant_t grant) {
    pthread_mutex_lock(&context->context->context_lock);

    list_node_t* new_node = malloc(sizeof(list_node_t));
    dl_grant_init(new_node->data = &grant);
    new_node->next = context->next;
    context->next = new_node;

    pthread_mutex_unlock(&context->context->context_lock);
}

bool remove_grant(list_node_t* context, dl_grant_t* grant) {
    pthread_mutex_lock(&context->context->context_lock);

    list_node_t* current = context;
    while (current != NULL && current->next != NULL) {
        if (current->next->data->scheduling_instance == grant->scheduling_instance) {
            list_node_t* temp = current->next;
            current->next = current->next->next;
            free(temp);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&context->context->context_lock);
    return (current != NULL && current->next != NULL);
}

void iterate_contexts(void(*func)(lte_ue_context_t*)) {
    pthread_mutex_lock(&contexts_lock);

    list_node_t* current = head;
    while (current != NULL) {
        func(current->data->context);
        current = current->next;
    }

    pthread_mutex_unlock(&contexts_lock);
}

lte_ue_context_t* find_context(uint32_t ue_identity) {
    pthread_mutex_lock(&contexts_lock);

    list_node_t* current = head;
    while (current != NULL) {
        if (current->data->ue_identity == ue_identity) {
            pthread_mutex_unlock(&contexts_lock);
            return current->data->context;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&contexts_lock);
    return NULL;
}
