```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <atomic>
#include <algorithm>

class Context {
public:
    int ueIdentity;
    int rnti;
    std::vector<Grant> grants;

    // Constructor, getters, and setters for UE Identity, RNTI, and individual Grant elements
};

class Grant {
public:
    std::chrono::steady_clock::time_point timestamp;
    int powerControlCommandValue;
    bool isActive;

    // Constructor and getters for timestamp, power control command value, and active flag
};

std::unordered_map<int, std::shared_ptr<Context>> contextMap;
std::mutex contextMapMutex;
std::condition_variable cv;
std::atomic<bool> running{true};

void cleanUpGrants() {
    while (running) {
        std::unique_lock<std::mutex> lock(contextMapMutex);
        auto now = std::chrono::steady_clock::now();

        // Find all contexts with inactive grants older than 5 minutes
        auto it = contextMap.begin();
        auto end = contextMap.end();
        for (; it != end; ) {
            if (it->second->grants.empty()) {
                ++it;
                continue;
            }

            bool foundInactiveGrant = false;
            for (const auto& grant : it->second->grants) {
                if (!grant.isActive && now - grant.timestamp > std::chrono::minutes(5)) {
                    it->second->grants.erase(std::remove_if(it->second->grants.begin(), it->second->grants.end(),
                                                            [&](const Grant& g) { return !g.isActive && now - g.timestamp > std::chrono::minutes(5); }),
                                              it->second->grants.end());
                    foundInactiveGrant = true;
                    break;
                }
            }

            if (!foundInactiveGrant) {
                ++it;
            }
        }

        lock.unlock();
        std::this_thread::sleep_for(std::chrono::seconds(1)); // Adjust sleep time according to system requirements
    }
}

void addContext(int ueIdentity, int rnti) {
    auto newContext = std::make_shared<Context>(ueIdentity, rnti);
    // Add the new context to contextMap and wake up any waiting threads that may be blocked on the condition variable
    {
        std::unique_lock<std::mutex> lock(contextMapMutex);
        contextMap[ueIdentity] = newContext;
        cv.notify_all();
    }
}

void updateContext(int ueIdentity, int rnti, const Grant& grant) {
    // Lock the contextMapMutex to access the shared_ptr and modify its grants vector
    std::unique_lock<std::mutex> lock(contextMapMutex);

    auto it = contextMap.find(ueIdentity);
    if (it == contextMap.end()) {
        // If the context doesn't exist, add it to the map and wake up any waiting threads that may be blocked on the condition variable
        std::unique_ptr<Context> newContext = std::make_unique<Context>(ueIdentity, rnti);
        newContext->grants.push_back(grant);
        contextMap[ueIdentity] = std::move(newContext);
        cv.notify_all();
    } else {
        it->second->grants.push_back(grant);
    }
}

void markGrantInactive(int ueIdentity, int rnti) {
    // Lock the contextMapMutex to access the shared_ptr and modify its grants vector
    std::unique_lock<std::mutex> lock(contextMapMutex);

    auto it = contextMap.find(ueIdentity);
    if (it == contextMap.end()) {
        return; // Context not found, no action needed
    }

    for (auto& grant : it->second->grants) {
        if (grant.rnti == rnti) {
            grant.isActive = false;
            break;
        }
    }
}

void iterateAndReportContextDetails() {
    std::unique_lock<std::mutex> lock(contextMapMutex);
    for (const auto& context : contextMap) {
        // Print details of the current context
        std::cout << "UE Identity: " << context.first << ", RNTI: " << context.second->rnti << "\n";
        for (const auto& grant : context.second->grants) {
            std::cout << "- Grant Timestamp: " << std::chrono::duration_cast<std::chrono::seconds>(grant.timestamp.time_since_epoch().count()).count()
                      << ", Power Control Command Value: " << grant.powerControlCommandValue << ", Active: " << grant.isActive << "\n";
        }
    }
}

void startCleanUpThread(std::thread& cleanUpThread) {
    cleanUpThread.detach();
}

int main() {
    std::thread cleanUpThread(cleanUpGrants);

    // Add some sample contexts and grants
    addContext(1, 200);
    updateContext(1, 200, Grant{std::chrono::steady_clock::now(), 5, true});
    updateContext(1, 200, Grant{std::chrono::steady_clock::now() + std::chrono::seconds(10), 10, false});

    // Mark a grant as inactive for context with UE Identity 1 and RNTI 200
    markGrantInactive(1, 200);

    // Iterate over all contexts to report their details
    iterateAndReportContextDetails();

    // Gracefully shutdown the clean up thread
    running = false;
    startCleanUpThread(cleanUpThread);
}
```

This code provides a starting point for implementing the given programming task. It includes a thread that continually cleans up inactive grants, functions to add contexts and grants, update context details, mark grants as inactive, and iterate over all contexts to report their details. The main function adds some sample contexts and grants, marks a grant as inactive for a specific context, and iterates over all contexts to report their details before gracefully shutting down the clean up thread.']

