#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <atomic.h>
#include <list.h> // Custom dynamic list implementation

typedef struct {
    uint32_t UE_Identity;
    uint32_t RNTI;
    uint32_t RX_UE_INFORMATION_TAG;
    List* grants; // Dynamic list of grant structures
} UE_Context;

typedef struct {
    uint32_t flowID;
    uint32_t schedulingInstance;
    int32_t powerControlCommandValue;
    uint64_t throughput;
} TrafficFlow;

static sem_t lock; // Global lock for thread safety
static uint64_t bandwidthLimit; // Predefined bandwidth limit
static List* contexts = NULL; // Dynamic list of UE contexts

void init() {
    sem_init(&lock, 0, 1);
    bandwidthLimit = <desired bandwidth limit>;
    contexts = newList();
}

UE_Context* createUEContext(uint32_t UE_Identity, uint32_t RNTI, uint32_t RX_UE_INFORMATION_TAG) {
    UE_Context* newContext = malloc(sizeof(UE_Context));
    newContext->UE_Identity = UE_Identity;
    newContext->RNTI = RNTI;
    newContext->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newContext->grants = newList();
    listAppend(contexts, newContext);
    return newContext;
}

TrafficFlow* createTrafficFlow(uint32_t flowID, uint32_t schedulingInstance, int32_t powerControlCommandValue, uint64_t throughput) {
    TrafficFlow* newTrafficFlow = malloc(sizeof(TrafficFlow));
    newTrafficFlow->flowID = flowID;
    newTrafficFlow->schedulingInstance = schedulingInstance;
    newTrafficFlow->powerControlCommandValue = powerControlCommandValue;
    newTrafficFlow->throughput = throughput;
    return newTrafficFlow;
}

void addGrantToContext(UE_Context* context, TrafficFlow* grant) {
    sem_wait(&lock);
    listAppend(context->grants, grant);
    sem_post(&lock);
}

UE_Context* getUEContextByUEIdentity(uint32_t UE_Identity) {
    for (ListNode* node = contexts->head; node != NULL; node = node->next) {
        UE_Context* context = (UE_Context*)node->data;
        if (context->UE_Identity == UE_Identity) {
            sem_wait(&lock);
            return context;
        }
    }
    return NULL;
}

void updateUEContext(UE_Context* context, TrafficFlow* updatedGrant) {
    sem_wait(&lock);
    for (ListNode* node = context->grants->head; node != NULL; node = node->next) {
        TrafficFlow* grant = (TrafficFlow*)node->data;
        if (grant == updatedGrant) {
            *grant = *updatedGrant;
            break;
        }
    }
    sem_post(&lock);
}

void iterateUEContexts(void (*func)(UE_Context* context)) {
    sem_wait(&lock);
    for (ListNode* node = contexts->head; node != NULL; node = node->next) {
        UE_Context* context = (UE_Context*)node->data;
        func(context);
    }
    sem_post(&lock);
}

void cleanUp() {
    sem_destroy(&lock);
    for (ListNode* node = contexts->head; node != NULL;) {
        UE_Context* context = (UE_Context*)node->data;
        ListRemoveNode(node);
        free(context);
    }
    freeList(contexts);
}
