struct allocated_data {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t data_size;
    size_t used;
};
struct allocated_data* queue = NULL;
size_t current_allocated = 0;
size_t current_used = 0;

void enqueue(struct allocated_data* data) {
    pthread_mutex_lock(&queue_lock);
    if (current_allocated + data->data_size > MAX_STRUCTS) {
        // Queue full, wait for allocation to be freed
        pthread_cond_wait(&queue_not_full, &queue_lock);
    }
    if (current_allocated + data->data_size <= MAX_STRUCTS) {
        // Append the new data to the queue
        size_t index = current_allocated;
        while (index < current_allocated + data->data_size) {
            queue[index] = data->data[index - current_used];
            ++index;
        }
        // Update the current state of the queue
        current_allocated += data->data_size;
        current_used += data->used;
        pthread_cond_signal(&queue_not_empty);
    }
    pthread_mutex_unlock(&queue_lock);
}

NFAPI_CRC_INDICATION_PDU_T* dequeue() {
    pthread_mutex_lock(&queue_lock);
    if (current_used == 0) {
        // Queue empty, wait for new data to be enqueued
        pthread_cond_wait(&queue_not_empty, &queue_lock);
    }
    NFAPI_CRC_INDICATION_PDU_T* result = queue + current_used - 1;
    --current_used;
    if (current_used == (current_allocated - 1)) {
        // No more structures allocated, free the unused part of the queue
        size_t index = 0;
        while (index < current_allocated - current_used) {
            free(queue[index].data);
            ++index;
        }
        current_allocated -= current_used;
    }
    pthread_cond_signal(&queue_not_full);
    pthread_mutex_unlock(&queue_lock);
    return result;
}

