#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <jansson.h>
#include <tcmalloc/tcmalloc.h>

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    uint16_t port;
    bool status;
} connection_statistics;

typedef struct hash_map_node {
    connection_statistics stats;
    struct hash_map_node *next;
} hash_map_node;

typedef struct hash_map {
    size_t capacity;
    size_t size;
    hash_map_node **nodes;
    pthread_mutex_t mutex;
} hash_map;

hash_map* create_hash_map(size_t capacity) {
    hash_map *hm = GC_MALLOC(sizeof(hash_map), malloc);
    hm->capacity = capacity;
    hm->size = 0;
    hm->nodes = GC_MALLOC(capacity * sizeof(hash_map_node*), malloc);
    memset(hm->nodes, 0, capacity * sizeof(hash_map_node*));
    pthread_mutex_init(&hm->mutex, NULL);
    return hm;
}

size_t hash(const char *key, size_t length) {
    uint32_t hash = 5381;
    for (size_t i = 0; i < length; ++i)
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    return hash % hm->capacity;
}

void put(hash_map *hm, const char *key, size_t length, void *value) {
    pthread_mutex_lock(&hm->mutex);
    size_t index = hash(key, length);
    hash_map_node *node = hm->nodes[index];
    if (!node) {
        node = GC_MALLOC(sizeof(hash_map_node), malloc);
        memcpy(&node->stats, value, sizeof(connection_statistics));
        node->next = hm->nodes[index];
        hm->nodes[index] = node;
        ++hm->size;
    } else {
        while (node->next) node = node->next;
        node->next = GC_MALLOC(sizeof(hash_map_node), malloc);
        memcpy(&node->next->stats, value, sizeof(connection_statistics));
        ++hm->size;
    }
    pthread_mutex_unlock(&hm->mutex);
}

void* get(const hash_map *hm, const char *key, size_t length) {
    pthread_mutex_lock(&hm->mutex);
    size_t index = hash(key, length);
    hash_map_node *node = hm->nodes[index];
    connection_statistics stats;
    while (node) {
        memcpy(&stats, &node->stats, sizeof(connection_statistics));
        if (!memcmp(key, node->stats.ip, length) && node->stats.port == htons((uint16_t)length))
            break;
        node = node->next;
    }
    pthread_mutex_unlock(&hm->mutex);
    return &stats;
}

void manage_connections(hash_map *connections, int num_connections) {
    for (int i = 0; i < num_connections; ++i) {
        char ip[INET6_ADDRSTRLEN];
        uint16_t port;
        if (getrandom(&port, sizeof(port), RAND_CHAR_DEVICE)) {
            getrandom(ip, INET6_ADDRSTRLEN - 1, "/dev/urandom");
            ip[INET6_ADDRSTRLEN - 1] = '\0';
        }
        put(connections, ip, strlen(ip), &{(connection_statistics) { .port = port, .status = rand() % 2 }});
    }
}

void* connection_status_thread(void *arg) {
    // Integrate real-time data source here
    json_t *data = get_realtime_connection_status();
    json_object_foreach(data, key, value) {
        void *stats = get(connections, key->string, strlen(key->string));
        memcpy(stats, value->valuename, sizeof(connection_statistics));
    }
    return NULL;
}
