['```python
import gzip
import hashlib
import threading
import logging
from tqdm import tqdm

def rolling_hash(file_path, window_size, chunk_size=65536, logger=None):
    buffer = b""
    hash_obj = hashlib.md5()

    def process_chunk(chunk):
        nonlocal buffer, hash_obj
        if chunk:
            if chunk[-4:] == b'\x1f\x8b\x08\x00':  # gzip header
                with gzip.GzipFile(mode='r', fileobj=BytesIO(chunk)) as f:
                    buffer += f.read(chunk_size)
            else:
                buffer += chunk
        else:
            return False

        start = len(buffer) - window_size
        if start > 0:
            end = min(len(buffer), start + window_size)
            hash_obj.update(buffer[start:end])

        while len(buffer) >= window_size:
            yield hash_obj.hexdigest()
            buffer = buffer[window_size:]
            if not process_chunk(buffer):
                break

    with open(file_path, "rb") as f:
        tqdm_func = (tqdm if logger else lambda x: x)
        for chunk in tqdm_func(f, total=f.seek(0, 2), ncols=80, leave=True):
            process_chunk(chunk)

    while len(buffer) >= window_size:
        yield hash_obj.hexdigest()
        buffer = buffer[window_size:]

class RollingHashThreaded:
    def __init__(self, file_path, window_size, chunk_size=65536):
        self.file_path = file_path
        self.window_size = window_size
        self.chunk_size = chunk_size
        self.buffer = None
        self.hash_obj = hashlib.md5()

    def _process_chunk(self, chunk):
        if chunk:
            if chunk[-4:] == b'\x1f\x8b\x08\x00':  # gzip header
                with gzip.GzipFile(mode='r', fileobj=BytesIO(chunk)) as f:
                    self.buffer += f.read(self.chunk_size)
            else:
                self.buffer += chunk
        else:
            return False

        start = len(self.buffer) - self.window_size
        if start > 0:
            end = min(len(self.buffer), start + self.window_size)
            self.hash_obj.update(self.buffer[start:end])

        while len(self.buffer) >= self.window_size:
            hash = self.hash_obj.hexdigest()
            if self._should_yield(hash):
                yield hash
                self.buffer = self.buffer[self.window_size:]
                if not self._process_chunk(self.buffer):
                    break

    def _should_yield(self, hash):
        if self.logger and len(self.logger.handlers) > 0:
            self.logger.info(hash)
        return True

    def run(self, logger=None):
        with open(self.file_path, "rb") as f:
            for chunk in iter(lambda: f.read(self.chunk_size), b''):
                self._process_chunk(chunk)
```

In this code, the `rolling_hash` function handles a single pass over the file with a dynamically-sized buffer and rolling hash object. The multi-threaded approach is implemented in the `RollingHashThreaded` class, which processes chunks concurrently using multiple threads while ensuring thread safety and synchronization with a lock around critical sections like updating the hash object or yielding hashes. Additionally, the code includes optional progress tracking and error reporting through a logger instance. Adjust memory usage by tuning chunk_size, window_size, and buffer size as needed for your specific application environment and resource constraints.']

