#define LIST_GROWTH_FACTOR 1.5

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

typedef struct list_node *LIST_NODE;
typedef LIST_NODE* LIST;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static LIST head = NULL;
static unsigned int capacity = 0, size = 0;

void list_init() {
    capacity = 16;
    head = malloc(capacity * sizeof(LIST_NODE));
    if (!head) {
        // Handle memory allocation failure gracefully
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (unsigned int i = 0; i < capacity - 1; ++i) {
        head[i].next = &head[i + 1];
    }
    head[capacity - 1].next = NULL;
}

LIST list_push(const NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&list_mutex);

    if (size == capacity) {
        // Resize the list when it reaches its capacity
        unsigned int new_capacity = (unsigned int)(capacity * LIST_GROWTH_FACTOR);
        LIST new_head = realloc(head, new_capacity * sizeof(LIST_NODE));

        if (!new_head) {
            // Handle memory allocation failure gracefully
            perror("Memory allocation failed");
            pthread_mutex_unlock(&list_mutex);
            exit(EXIT_FAILURE);
        }

        for (unsigned int i = size; i < new_capacity - 1; ++i) {
            new_head[i].next = &new_head[i + 1];
        }
        new_head[new_capacity - 1].next = NULL;
        head = new_head;
        capacity = new_capacity;
    }

    LIST current = head;
    for (unsigned int i = 0; i < size; ++i, current = current->next) {
        if (current->data.rnti == data->rnti && i != size - 1) {
            // Ensure no two consecutive structures have the same RNTI value
            pthread_mutex_unlock(&list_mutex);
            return NULL;
        }
    }

    LIST_NODE new_node = malloc(sizeof(LIST_NODE));
    if (!new_node) {
        // Handle memory allocation failure gracefully
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list_mutex);
        exit(EXIT_FAILURE);
    }

    new_node->data = *data;
    new_node->next = current->next;
    current->next = new_node;
    ++size;

    pthread_mutex_unlock(&list_mutex);
    return new_node;
}

LIST list_pop() {
    pthread_mutex_lock(&list_mutex);

    if (size == 0) {
        pthread_mutex_unlock(&list_mutex);
        return NULL;
    }

    LIST current = head;
    --size;

    while (current->next != NULL && size > 0) {
        current = current->next;
        --size;
    }

    LIST result = current->next;
    current->next = NULL;
    free(result);

    pthread_mutex_unlock(&list_mutex);
    return result;
}
