typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

#define THRESHOLD 50 // Signal strength threshold for setting CRCFLAG to false

pthread_rwlock_t lock;
NFAPI_CRC_INDICATION_PDU_T* list;
size_t size;

void initList(size_t n) {
    pthread_rwlock_init(&lock, NULL);
    size = n;
    list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);

    for (size_t i = 0; i < size; ++i) {
        list[i].tag.RNTI = i + 1;
        list[i].rnti = i + 1;
        list[i].crcIndicationTag.CRCFLAG = rand() % 2 == 0 ? true : false;
    }
}

void updateCRCFLAGS(int signalStrength) {
    for (size_t i = 0; i < size; ++i) {
        if (signalStrength < THRESHOLD) {
            list[i].crcIndicationTag.CRCFLAG = false;
        }
    }
}

void setSignalStrength(int index, int strength) {
    pthread_rwlock_wrlock(&lock);
    list[index].signalStrength = strength;
    pthread_rwlock_unlock(&lock);
}

int getSignalStrength(int index) {
    pthread_rwlock_rdlock(&lock);
    int signalStrength = list[index].signalStrength;
    pthread_rwlock_unlock(&lock);
    return signalStrength;
}

