import hashlib
import os
import sys
import time
import threading
import queue
from concurrent.futures import ThreadPoolExecutor
from tempfile import TemporaryDirectory

class MD5Hasher:
    CHUNK_SIZE = 65536

    def __init__(self, log_func=print, verbose=False):
        self.log_func = log_func
        self.verbose = verbose

    def _md5(self, file_path):
        with open(file_path, 'rb') as f:
            hasher = hashlib.md5()
            while True:
                data = f.read(self.CHUNK_SIZE)
                if not data:
                    break
                hasher.update(data)
            return hasher.hexdigest()

    def _hash_file(self, file_path):
        try:
            return self._md5(file_path)
        except Exception as e:
            if self.verbose:
                self.log_func(f"Error computing hash for {file_path}: {e}")
            return None

    def _hash_chunk(self, queue, temp_dir, hashed_files):
        while True:
            file_path = queue.get()
            if not file_path:
                break

            try:
                hash_value = self._hash_file(file_path)
                if hash_value:
                    temp_file = os.path.join(temp_dir, f"{os.path.basename(file_path)}_chunk")
                    with open(temp_file, 'wb') as tmp:
                        tmp.write(hash_value.encode('utf-8'))
                    hashed_files[file_path] = temp_file
            except Exception as e:
                if self.verbose:
                    self.log_func(f"Error processing chunk for {file_path}: {e}")

        for file in hashed_files.values():
            os.remove(file)

    def _hash_directory(self, root_dir, temp_dir):
        hashed_files = {}
        queue = queue.Queue()

        def _recursive_walk(path):
            if not os.path.isdir(path):
                queue.put(path)
                return

            for item in os.listdir(path):
                item_path = os.path.join(path, item)
                _recursive_walk(item_path)
                if not os.path.isfile(item_path):
                    queue.put(item_path)

        _recursive_walk(root_dir)

        with ThreadPoolExecutor(max_workers=os.cpu_count() - 1) as executor:
            executor.submit(self._hash_chunk, queue, temp_dir, hashed_files)

        return hashed_files

    def compute_directory_hash(self, root_dir, temp_dir=None):
        if not temp_dir:
            temp_dir = TemporaryDirectory()
        self._hash_directory(root_dir, temp_dir.name)
        return {k: v for k, v in os.listdir(temp_dir.name) if v.endswith("_chunk")}

    def verify_reference_hash(self, root_dir, reference_hashes):
        computed_hashes = self.compute_directory_hash(root_dir)

        missing = set()
        mismatched = set()

        for file, hash_path in computed_hashes.items():
            if not os.path.exists(hash_path):
                missing.add(file)
            else:
                with open(hash_path, 'rb') as f:
                    reference = reference_hashes[os.path.basename(hash_path)]
                    if hash_path != reference:
                        mismatched.add(file)

        self.log_func(f"Missing hashes: {missing}")
        self.log_func(f"Mismatched hashes: {mismatched}")
