    list->data = calloc(n, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = n;

    sem_init(&list->lock, 0, 1);

    // Initialize configuration service interaction (optional compression)
    list->fd = open("config", O_RDONLY);

    return list;
}

void populate(list_t* list) {
    pthread_t threads[list->capacity];
    size_t i;

    for (i = 0; i < list->capacity; ++i) {
        // Fetch RNTI and CRCFLAG values from configuration service (optional compression)
        struct RNTI* rnti = &list->data[i].rnti;
        struct CRC_INDICATION_REL8_TAG* crc_indication = &list->data[i].crc_indication;

