    struct CRC_INDICATION_REL8_TAG* crc_indication = &list->data[idx].crc_indication;

    // Read RNTI and CRCFLAG values from file descriptor (configuration service)
    read(list->fd, rnti, sizeof(*rnti));
    read(list->fd, crc_indication, sizeof(*crc_indication));

    return NULL;
}
