// FSA structure definition
typedef struct FSATransition {
    int state;
    char input;
    void (*action)(int, int); // State action callback function
} FSATransition_t;

typedef struct FSANode {
    int id;
    int properties[]; // Customizable properties for each node
    pthread_mutex_t mutex;
    struct FSANode* next;
} FSANode_t;

// Function prototypes
FSANode_t* create_node(int properties_len, ...);
void add_edge(FSANode_t*, FSANode_t*, FSATransition_t* transitions[], int num_transitions);
void handle_state_action(int state, int action_param);

// Main function to create the graph
FSANode_t* create_graph(int* states, int num_states, FSATransition_t** transitions, int num_transitions, void (*last_state_action)(int)) {
    // Allocate memory for the first node and mutex
    FSANode_t* head = (FSANode_t*)malloc(sizeof(FSANode_t));
    if (!head) return NULL;

    // Initialize mutex
    pthread_mutex_init(&head->mutex, NULL);

    // Create remaining nodes and edges dynamically
    FSANode_t* current = head;
    int state_index = 0;
    for (int i = 0; i < num_states; ++i) {
        if ((current->next = create_node(sizeof(int) * (states[i] + 1), states[state_index])) == NULL) return NULL;

        // Set state properties
        current->next->id = i;
        memcpy((current->next)->properties, states[i], sizeof(int) * (states[i] + 1));

        // Add edges and transitions
        add_edge(current, current->next, transitions[state_index], num_transitions);

        // Increment state index
        state_index = (i + 1) % num_states;
        current = current->next;
    }

    // Set last state action
    head->next->properties[states[state_index]] = (void*)last_state_action;

    return head;
}
