    node_t* current = head;
    for (size_t i = 0; i < index; i++) {
        if (current == NULL) {
            pthread_mutex_unlock(&list_lock);
            return NULL;
        }
        current = current->next;
    }
    my_struct_t* data = current ? current->data : NULL;
    pthread_mutex_unlock(&list_lock);
    return data;
}

void list_remove(size_t index) {
    pthread_mutex_lock(&list_lock);
    node_t* current = head;
    size_t i = 0;
    if (current != NULL && index == 0) {
        head = current->next;
        free(current);
        size--;
    } else {
