    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Initializing timestamps at: %s\n", time_string);
}

void cache_init() {
    if (head == NULL) {
        head = malloc(MAX_STRUCTS * sizeof(cache_node_t));
        for (unsigned int i = 0; i < MAX_STRUCTS; ++i) {
            head[i].data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!head[i].data) {
                printf("Failed to allocate memory for cache\n");
                exit(EXIT_FAILURE);
            }
            head[i].next = &head[(i + 1) % MAX_STRUCTS];
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* alloc_struct() {
    if (allocated_structs >= MAX_STRUCTS) return NULL;

    pthread_mutex_lock(&cache_lock);
    cache_node_t* node = head;
    for (unsigned int i = 0; i < allocated_structs; ++i) {
        if (!node->next->data) {
            node->next->data = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!node->next->data) {
                pthread_mutex_unlock(&cache_lock);
                return NULL;
            }
            allocated_structs++;
            node = node->next;
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&cache_lock);

    return node->data;
}

void free_struct(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    if (!struct_ptr) return;

    cache_node_t* current = head, * previous = NULL;
    while (current != NULL) {
        if (current->data == struct_ptr) {
            if (previous == NULL) {
                current->data = current->next->data;
                free(current);
                allocated_structs--;
            } else {
                previous->next->data = current->next->data;
                free(current);
                allocated_structs--;
                current = head;
            }
            break;
        }
        previous = current;
        current = current->next;
    }
}

void* alloc_array(unsigned int N) {
