    uint32_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRCI_T;

typedef struct _NFAPI_CRCI_LIST {
    NFAPI_CRCI_T *elements;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t notFull;
    pthread_cond_t notEmpty;
} NFAPI_CRCI_LIST;

NFAPI_CRCI_LIST *nfapi_crc_list_create(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    NFAPI_CRCI_LIST *list = malloc(sizeof(NFAPI_CRCI_LIST));
    if (!list) return NULL;

    list->elements = calloc(initial_capacity, sizeof(NFAPI_CRCI_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->notFull, NULL);
    pthread_cond_init(&list->notEmpty, NULL);

    return list;
}

void nfapi_crc_list_destroy(NFAPI_CRCI_LIST **list) {
    if (!list || !*list) return;

    free((*list)->elements);
    free(*list);
    *list = NULL;
}

bool nfapi_crc_list_full(const NFAPI_CRCI_LIST *list) {
    return list->size == list->capacity;
}

bool nfapi_crc_list_empty(const NFAPI_CRCI_LIST *list) {
    return list->size == 0;
}

void nfapi_crc_list_push(NFAPI_CRCI_LIST *list, const NFAPI_CRCI_T *element) {
    pthread_mutex_lock(&list->lock);

    while (nfapi_crc_list_full(list)) {
        pthread_cond_wait(&list->notFull, &list->lock);
    }

    memcpy(&list->elements[list->size], element, sizeof(NFAPI_CRCI_T));
    list->size++;

    if (list->size < list->capacity / 2) {
        pthread_cond_signal(&list->notEmpty);
    }

    pthread_mutex_unlock(&list->lock);
}

const NFAPI_CRCI_T *nfapi_crc_list_pop(NFAPI_CRCI_LIST *list) {
    pthread_mutex_lock(&list->lock);

    while (nfapi_crc_list_empty(list)) {
        pthread_cond_wait(&list->notEmpty, &list->lock);
    }

    const NFAPI_CRCI_T *element = &list->elements[list->size - 1];
    list->size--;

    if (list->size > list->capacity / 4 && list->size < list->capacity) {
        pthread_cond_signal(&list->notFull);
    }

    pthread_mutex_unlock(&list->lock);

    return element;
}

