    struct cache_node* head;
    pthread_mutex_t lock;
};

static struct cache g_cache = {.head = NULL, .lock = PTHREAD_MUTEX_INITIALIZER};

PHY_FRAME_RX_PARAMS* get_params(size_t n) {
    struct cache_node *node = g_cache.head;
    pthread_mutex_lock(&g_cache.lock);
    if (node && node->count >= n) {
        void* next = node->next;
        PHY_FRAME_RX_PARAMS* params = &node[n];
        g_cache.head = node->next;
        node->next = NULL;
        node->count -= n;
        pthread_mutex_unlock(&g_cache.lock);
        return params;
    }
    pthread_mutex_unlock(&g_cache.lock);

    PHY_FRAME_RX_PARAMS* params = (PHY_FRAME_RX_PARAMS*)calloc(n, sizeof(PHY_FRAME_RX_PARAMS));
    if (!params) {
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        params[i].header.field1 = rand();
        // Fill in the rest of the structure as needed
    }

    if (!g_cache.head || g_cache.head->count <= n) {
        struct cache_node* new_node = (struct cache_node*)calloc(1, sizeof(struct cache_node));
        new_node->params = params;
        new_node->count = n;
        new_node->next = g_cache.head;
        g_cache.head = new_node;
    }

    return params;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(PHY_FRAME_RX_PARAMS* params) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
