PHY_FRAME_RX_PARAMS** allocate_memory(size_t N) {
    if (N <= 0) {
        return NULL;
    }

    PHY_FRAME_RX_PARAMS** array = (PHY_FRAME_RX_PARAMS**)calloc(N, sizeof(PHY_FRAME_RX_PARAMS*));
    if (!array) {
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        array[i] = get_params(1);
        if (!array[i]) {
            free(array);
            return NULL;
        }
    }

    for (size_t i = 0; i < N - 1; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(array[i]);
        if (!pdu) {
            for (size_t j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
        array[i+1] = pdu;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(array[N-1]);
    if (!pdu) {
        for (size_t i = 0; i < N; ++i) {
            free(array[i]);
        }
        free(array);
        return NULL;
    }
    array[N-1] = pdu;

    return array;
}
