using namespace std;

struct ConnectionStat {
    string ip;
    unsigned int port;
    bool status; // connection status flags
};

class TCPConnectionManager {
private:
    static constexpr uint32_t MAX_CONNS = 1000;
    static constexpr float LOAD_FACTOR = 0.75f;

    class HashFunc {
    public:
        size_t operator()(const ConnectionStat& s) const {
            return hash<tuple<string, unsigned int>>({s.ip, s.port}) % MAX_CONNS;
        }
    };

    map<size_t, list<ConnectionStat>, HashFunc> data;
    mutex mtx;

public:
    TCPConnectionManager() {
        for (uint32_t i = 0; i < MAX_CONNS; ++i)
            data[i] = list<ConnectionStat>();
    }

    ConnectionStat& get(const string& ip, unsigned int port) {
        lock_guard<mutex> lck(mtx);
        auto it = data.at(hashFunc(make_tuple(ip, port)))
            .begin();
        for (; it != data[hashFunc(make_tuple(ip, port))].end(); ++it) {
            if (it->ip == ip && it->port == port)
                return *it;
        }
        // Insert a new connection stat if not found
        ConnectionStat stat{ip, port, false};
        data[hashFunc(make_tuple(ip, port))].push_back(stat);
        return stat;
    }

    void add(const string& ip, unsigned int port, bool status) {
        lock_guard<mutex> lck(mtx);
        get(ip, port).status = status;
    }

    void remove(const string& ip, unsigned int port) {
        lock_guard<mutex> lck(mtx);
        auto it = data.at(hashFunc(make_tuple(ip, port)))
            .begin();
        for (; it != data[hashFunc(make_tuple(ip, port))].end(); ++it) {
            if (it->ip == ip && it->port == port) {
                data[hashFunc(make_tuple(ip, port))].erase(it);
                break;
            }
        }
    }
};
