// Thread-safe list structure
typedef struct list {
    struct node* head;
    struct node* tail;
    pthread_mutex_t list_lock;
} list_t;

list_t* create_list() {
    list_t* list = (list_t*)malloc(sizeof(list_t));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
