node_t* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) return NULL;
    pthread_mutex_init(&new_node->node_lock, NULL);
    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = NULL;
    return new_node;
}

void add_to_list(list_t* list, node_t* node) {
    pthread_mutex_lock(&list->list_lock);
    if (!list->head) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->list_lock);
