    node_t* popped_node = NULL;
    pthread_mutex_lock(&list->list_lock);
    if (list->head) {
        popped_node = list->head;
        list->head = list->head->next;
        if (!list->head) list->tail = NULL;
    }
    pthread_mutex_unlock(&list->list_lock);
    return popped_node;
}

