typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* prev;
    struct node* next;
} Node;

struct dlist {
    Node* head;
    Node* tail;
    size_t size;
    pthread_mutex_t mutex;
};

void init_dlist(struct dlist* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

Node* create_node(const NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->data = *data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

void insert_node(struct dlist* list, Node* node) {
    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        node->prev = NULL;
        list->head->prev = node;
        list->head = node;
    }

    ++(list->size);
    pthread_mutex_unlock(&list->mutex);
}

void remove_node(struct dlist* list, Node* node) {
    pthread_mutex_lock(&list->mutex);

    if (node == list->head) {
        list->head = node->next;
        if (list->head) list->head->prev = NULL;
        else list->tail = NULL;
    } else if (node == list->tail) {
        list->tail = node->prev;
        if (list->tail) list->tail->next = NULL;
        else list->head = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    --(list->size);
    pthread_mutex_unlock(&list->mutex);

    free(node);
}

void clear_dlist(struct dlist* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
}

Node* get_nth_node(struct dlist* list, size_t n) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    for (size_t i = 0; i < n && current != NULL; ++i) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return current;
}

void iterate_batch(struct dlist* list, size_t batch_size, void(*function)(const NFAPI_CRC_INDICATION_PDU_T*)) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    size_t processed = 0;
    while (current != NULL && processed < list->size) {
        if (processed + batch_size <= list->size) {
            for (size_t i = processed; i < processed + batch_size && current != NULL; ++i) {
                function(&current->data);
                current = current->next;
            }
            processed += batch_size;
        } else {
            for (size_t i = processed; i < list->size && current != NULL; ++i) {
                function(&current->data);
                current = current->next;
            }
            processed = list->size;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

bool probabilistic_crcflag(void) {
    static bool random_state[128] = { 0 }; // A seed based on the current time, assuming reasonable distribution of system calls
    static size_t index = 0;

    if (random_state[index] < 128) return true;

    index = (index + 1) % sizeof(random_state);
    return false;
}
