void* get_buffer() {
    BufferNode *node;
    if (buffer_pool == NULL || pool_capacity <= 0) {
        node = malloc(sizeof(BufferNode));
        node->next = buffer_pool;
        node->buffer = malloc(MAX_SIZE);
        buffer_pool = node;
        pool_capacity++;
    }
    void* buffer = buffer_pool->buffer;
    BufferNode* temp = buffer_pool;
    buffer_pool = buffer_pool->next;
    free(temp);
    return buffer;
}

