    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* process_file(const char *path, int *status) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        openlog("File Processor", LOG_PERROR | LOG_ERR, LOG_DAEMON);
        syslog(LOG_ERR, "Failed to open file: %s", path);
        *status = 1;
        return NULL;
    }

    off_t length;
    struct stat st;
    if (fstat(fd, &st) == -1) {
        close(fd);
        openlog("File Processor", LOG_PERROR | LOG_ERR, LOG_DAEMON);
        syslog(LOG_ERR, "Failed to get file size: %s", path);
        *status = 2;
        return NULL;
    }
    length = st.st_size;

    NFAPI_CRC_INDICATION_PDU_T* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (length / BUFFER_SIZE + 1));
    if (!result) {
        close(fd);
        openlog("File Processor", LOG_PERROR | LOG_ERR, LOG_DAEMON);
        syslog(LOG_ERR, "Out of memory");
        *status = 3;
        return NULL;
    }
    char buffer[BUFFER_SIZE];
    int offset = 0;
    uint8_t* bufptr = (uint8_t*)buffer;
    size_t read_bytes = BUFFER_SIZE;
    while ((read_bytes = read(fd, buffer, sizeof(buffer))) > 0) {
        for (size_t i = 0; i < read_bytes; ++i) {
            memcpy(&result[offset].RX_UE_INFORMATION_TAG + (offset * BUFFER_SIZE + i) / 4, &bufptr[i], sizeof(uint32_t));
            memcpy(&result[offset].RNTI + (offset * BUFFER_SIZE + i) / 2, &bufptr[i], sizeof(uint16_t));
            memcpy(&result[offset].CRC_INDICATION_REL8_TAG + (offset * BUFFER_SIZE + i), &bufptr[i], sizeof(uint32_t));
        }
        offset++;
    }

    close(fd);
    openlog("File Processor", LOG_INFO, LOG_DAEMON);
    syslog(LOG_INFO, "Processed file: %s", path);
    *status = 0;
    return result;
}
