#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>

typedef struct UESession {
    char ip[32];
    int session_id;
    sem_t sessions_mutex;
    struct list_head active_sessions;
    unsigned int max_sessions;
    struct UESession *cache; // Cache pointer
    size_t cache_size; // Cache size
    sem_t cache_mutex; // Cache mutex
} UESession;

// List structure for UE sessions
struct list_head {
    struct list_head *next, *prev;
};

UESession* ue_session_create(const char *ip, int session_id, unsigned int max_sessions) {
    UESession *ues = (UESession*) malloc(sizeof(UESession));
    if (!ues) return NULL;

    memcpy(ues->ip, ip, 32);
    ues->session_id = session_id;
    INIT_LIST_HEAD(&ues->active_sessions);
    ues->max_sessions = max_sessions;
    sem_init(&ues->sessions_mutex, 0, 1);
    sem_init(&ues->cache_mutex, 0, 1);
    ues->cache = NULL;
    ues->cache_size = 0;

    return ues;
}

UESession* ue_session_find(UESession *ues, const char *ip) {
    UESession *cached = ues->cache;
    while (cached && memcmp(cached->ip, ip, 32)) cached = cached->cache;

    if (cached) {
        sem_wait(&ues->cache_mutex);
        ues->cache = cached;
        sem_post(&ues->cache_mutex);
        return cached;
    }

    return NULL;
}

void ue_session_insert(UESession *ues, UESession *new_ses) {
    sem_wait(&ues->sessions_mutex);

    // If the number of active sessions is less than max_sessions or if the new session belongs to a different UE, insert the new session.
    if (list_empty(&ues->active_sessions) || memcmp(ues->ip, new_ses->ip, 32)) {
        list_add(&new_ses->active_sessions, &ues->active_sessions);
    }

    sem_post(&ues->sessions_mutex);
}

void ue_session_delete(UESession *ues, UESession *del_ses) {
    sem_wait(&ues->sessions_mutex);

    list_del(&del_ses->active_sessions);
    free(del_ses);

    sem_post(&ues->sessions_mutex);
}

void ue_session_update_cache(UESession *ues, UESession *update_ses) {
    sem_wait(&ues->cache_mutex);

    if (ues->cache) {
        // If the cached session needs an update, remove it from the cache and re-cache the updated session.
        ues->cache->active_sessions.next->prev = &ues->cache->cache;
        ues->cache->cache = update_ses;
    } else {
        // Cache the updated session if the cache is empty or if the session to be cached doesn't already exist in the cache.
        update_ses->cache = update_ses;
        update_ses->cache->next = &ues->cache;
        ues->cache = update_ses;
    }

    sem_post(&ues->cache_mutex);
}

void dynamic_resize(UESession *ues, unsigned int new_size) {
    if (new_size > ues->cache_size) {
        while (new_size > ues->cache_size) {
            UESession *new_cache = (UESession*) realloc(ues->cache, sizeof(UESession)*(new_size));
            if (!new_cache) break;
            ues->cache_size = new_size;
            ues->cache = new_cache;
        }
    } else {
        while (ues->cache_size > new_size) {
            ues->cache[new_size]->next->prev = &ues->cache[new_size + 1];
            ues->cache[new_size + 1]->prev = ues->cache[new_size].prev;
            memmove(ues->cache, ues->cache + new_size, sizeof(UESession)*(ues->cache_size - new_size));
            --ues->cache_size;
        }
    }
