    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

struct pdu_list {
    NFAPI_CRFC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t count;
    semaphore_t lock;
};

void validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu || !pdu->rx_ue.present || !pdu->rnti.present || !pdu->crc_ind.present) {
        fprintf(stderr, "Invalid PDU: null pointers detected\n");
        exit(1);
