}

void pdu_list_init(struct pdu_list *list, size_t initial_size) {
    list->data = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        fprintf(stderr, "Failed to allocate memory for PDU list\n");
        exit(1);
    }
    list->capacity = initial_size;
    list->count = 0;
    sem_init(&list->lock, 0, 1);
}

void pdu_list_resize(struct pdu_list *list, size_t new_capacity) {
    if (new_capacity <= list->capacity || !list->data) return;

    NFAPI_CRC_INDICATION_PDU_T *temp = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        fprintf(stderr, "Failed to resize PDU list\n");
        exit(1);
    }
    list->data = temp;
    list->capacity = new_capacity;
}

void pdu_list_add(struct pdu_list *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    sem_wait(&list->lock);

    validate_pdu(pdu);

    if (list->count == list->capacity) {
        pdu_list_resize(list, list->capacity * 2);
    }

    memcpy(&list->data[list->count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ++list->count;

    sem_post(&list->lock);
}

