    void* handle;
    UserFunction user_function;
};

struct LibraryLock {
    pthread_mutex_t lock;
};

static struct LibraryLock library_lock = { .lock = PTHREAD_MUTEX_INITIALIZER };
static int num_threads = 0;

NFAPI_CRC_INDICATION_PDU_T* generate_pdus(int N, const char* lib_path) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("malloc failed");
        return NULL;
    }

    void* handle = dlopen(lib_path, RTLD_LAZY);
    struct LibraryHandle *library = NULL;

    pthread_mutex_lock(&library_lock.lock);
    if (num_threads++ == 1) {
        library = malloc(sizeof(struct LibraryHandle));
        if (!library) {
            dlclose(handle);
            free(pdus);
            perror("malloc failed");
            return NULL;
        }
        library->handle = handle;
    } else {
        library = reinterpret_cast<struct LibraryHandle*>(library_lock.handle);
    }
    pthread_mutex_unlock(&library_lock.lock);

    UserFunction user_function = dlsym(handle, "user_function");
    if (!user_function) {
        perror("dlsym failed");
        goto cleanup;
    }

    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i * 123456789;
        pdus[i].RNTI = rand() % 65536;
        pdus[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdus[i].CRCFLAG = (rand() % 10) > 4 ? 1 : 0;
    }

cleanup:
    if (library) {
        library->user_function = NULL;
        dlclose(handle);
        free(library);
    }
    return pdus;
}

void* load_and_execute(void *arg) {
    struct LibraryHandle *library = reinterpret_cast<struct LibraryHandle*>(arg);

    if (!library->user_function) {
        pthread_mutex_lock(&library_lock.lock);
        while (!library->user_function && num_threads > 1) {
            pthread_mutex_unlock(&library_lock.lock);
            pthread_cond_wait(&library_lock.condition, &library_lock.lock);
            pthread_mutex_lock(&library_lock.lock);
        }
        if (num_threads > 1) {
            library->handle = dlopen(library->handle, RTLD_LAZY);
            library->user_function = dlsym(library->handle, "user_function");
        }
        pthread_mutex_unlock(&library_lock.lock);
    }

    if (library->user_function) {
        library->user_function();
    }

    return NULL;
}
