typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG cid_tag;
    bool crcflag;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node *next;
} Node;

static pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
static Node* head = NULL;
static size_t num_structs = 0;
const size_t MAX_STRUCTS = 10000;

Node* dequeue() {
    Node* temp = head;
    if (head != NULL)
        head = head->next;
    return temp;
}

void enqueue(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&queue_mutex);
    if (head == NULL)
        head = newNode;
    else
        tail->next = newNode;
    tail = newNode;
    pthread_mutex_unlock(&queue_mutex);
}

void* allocate(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* struct_data = (NFAPI_CRC_INDICATION_PDU_T*)data;

    if (num_structs >= MAX_STRUCTS) {
        free(struct_data);
        return NULL;
    }

    struct_data->crcflag = rand() % 2;
    struct_data->timestamp = time(NULL);

    enqueue(struct_data);
    num_structs++;
    return struct_data;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_request(size_t N) {
    if (N <= 0)
        return NULL;

    Node* temp;
    for (size_t i = 0; i < N; i++) {
        temp = dequeue();
        if (!temp)
            return allocate((NFAPI_CRC_INDICATION_PDU_T*)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    }

    pthread_t t;
    for (size_t i = 0; i < N && num_structs < MAX_STRUCTS; i++) {
        pthread_create(&t, NULL, allocate, temp->data);
        temp = dequeue();
    }

    return temp->data;
}
