struct javascript_env {
    char *path;
    void (*func)(void);
};

void execute_js(void *arg) {
    struct javascript_env *env = arg;

    if (!env->path || !access(env->path, R_OK))
        return;

    int fd = open(env->path, O_RDONLY);
    char buffer[4096];
    size_t nread;

    if (fd < 0)
        fprintf(stderr, "Error: Unable to open JavaScript file %s\n", env->path);
    else {
        while ((nread = read(fd, buffer, sizeof(buffer))) > 0) {
            void (*js_func)(void) = dlsym(RLD_DATA, "functionName");
            js_func();
        }

        close(fd);
    }
}

element_t *create_and_populate_array() {
    const int size = 10000;
    element_t *arr = malloc(size * sizeof(element_t));
    if (!arr) {
        perror("Error: Failed to allocate memory for the array");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        element_t *e = arr + i;
        e->data.RX_UE_INFORMATION_TAG = i % 256;
        e->data.RNTI = (uint32_t)(i * 0x10001);
        e->data.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() & 1;

        if (pthread_mutex_init(&e->mutex, NULL)) {
            perror("Error: Failed to initialize mutex");
            free(arr);
            return NULL;
        }
    }

    return arr;
}

void monitor_cpu() {
    struct rusage ru;
    double cpu_usage = 0.0, previous_cpu_usage = 0.0;
    clock_t prev_clock = clock();

    while (1) {
        clock_t curr_clock = clock();
        getrusage(RUSAGE_SELF, &ru);
        cpu_usage = ru.ru_utime.tv_sec + (ru.ru_utime.tv_usec / 1000000.0);

        if ((cpu_usage - previous_cpu_usage) > cpu_usage * 0.9 && curr_clock - prev_clock > CLOCKS_PER_SEC * 5) {
            fprintf(stderr, "Error: CPU usage exceeded 90% for more than 5 seconds\n");
            break;
        }

        previous_cpu_usage = cpu_usage;
        prev_clock = curr_clock;
    }
}

void load_and_execute_js(const char *path) {
    struct javascript_env env = { path, NULL };
    pthread_t thread;

    if (pthread_create(&thread, NULL, &execute_js, &env)) {
        perror("Error: Failed to create JavaScript execution thread");
        return;
    }
}

int main() {
    element_t *array = create_and_populate_array();

    if (!array)
        return 1;

    DIR *dir = opendir("/path/to/javascripts");

    if (!dir) {
        perror("Error: Unable to open JavaScript directory");
        free(array);
        return 1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir))) {
        char ext[4];
        strcpy(ext, entry->d_name + strlen(entry->d_name) - 3);
        if (strcmp(ext, ".js") == 0)
            load_and_execute_js(entry->d_name);
    }

    closedir(dir);
    monitor_cpu();

    free(array);
    return 0;
}
