// Network statistic record structure
typedef struct {
    time_t timestamp;
    int UID;
    double metric;
} StatRecord;

// Dynamic list structure
typedef struct ListNode {
    StatRecord data;
    struct ListNode* next;
} ListNode;

// Custom error codes for easier debugging
enum ErrCodes { NO_ERROR = 0, MEMORY_FAILURE = -1 };

// Error handling function
void handle_error(const char *msg) {
    fprintf(stderr, "[Error] %s\n", msg);
    exit(MEMORY_FAILURE);
}

// Allocate a new StatRecord
StatRecord* new_stat_record() {
    StatRecord* stat = malloc(sizeof(StatRecord));
    if (!stat) handle_error("Memory allocation failure for StatRecord");
    return stat;
}

// Validate the metric value (optional validation mechanism)
bool validate_metric(double metric) {
    // Implement custom validation logic here
    // For example, ensure that the metric is non-negative and not NaN or Infinity
    if (!isfinite(metric) || metric < 0.0) return false;
    return true;
}

// Add a record to the list (assumes head pointer is provided)
void add_record(ListNode** head, StatRecord* data) {
    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) handle_error("Memory allocation failure for ListNode");

    new_node->data = *data;
    new_node->next = *head;
    *head = new_node;
}

// Retrieve a record by UID (assumes head pointer and UID are provided)
StatRecord* get_record(ListNode** head, int UID) {
    ListNode* current = *head;
    while (current != NULL) {
        if (current->data.UID == UID) return &current->data;
        current = current->next;
    }
    // Return null if not found
    return NULL;
}

// List management functions (optional depending on external dependencies and system requirements)
void free_list(ListNode** head) {
    ListNode* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

// Main function for adding records with validation and error handling
int add_record_with_validation(ListNode** head, int UID, double metric) {
    if (!validate_metric(metric)) return MEMORY_FAILURE;

    StatRecord* data = new_stat_record();
    data->timestamp = time(NULL);
    data->UID = UID;
    data->metric = metric;

    add_record(head, data);
    return NO_ERROR;
}
