#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    time_t timestamp;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_STRUCTS 1000
pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_queue_t cache_queue;

NFAPI_CRC_INDICATION_PDU_T* allocate_structs(size_t N) {
    if (N <= 0) return NULL;

    // Create and initialize thread-safe queue for caching structures
    pthread_queue_init(&cache_queue, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    size_t num_structs = N < MAX_STRUCTS ? N : MAX_STRUCTS;
    NFAPI_CRC_INDICATION_PDU_T* structs = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_structs, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!structs) {
        perror("Calloc failed");
        return NULL;
    }

    // Initialize each structure with valid tags and random crcflag
    for (size_t i = 0; i < num_structs; ++i) {
        structs[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_VALID;
        structs[i].rnti = (RNTI)i + 1;
        structs[i].crc_indication_rel8_tag.value = rand() % 256;
        structs[i].timestamp = time(NULL);
        structs[i].crcflag = rand() % 2;
    }

    // Cache unused structures and return allocated ones
    pthread_mutex_lock(&cache_mutex);
    while (N > num_structs) {
        NFAPI_CRC_INDICATION_PDU_T* cached_struct = pthread_queue_pop(&cache_queue);
        if (cached_struct) {
            --N;
            structs[num_structs + N] = *cached_struct;
        }
    }
    pthread_mutex_unlock(&cache_mutex);

    return structs;
}

void deallocate_structs(NFAPI_CRC_INDICATION_PDU_T* structs, size_t num_structs) {
    if (!structs || !num_structs) return;

    pthread_mutex_lock(&cache_mutex);
    for (size_t i = 0; i < num_structs; ++i) {
        pthread_queue_push(&cache_queue, &structs[i]);
    }
    pthread_mutex_unlock(&cache_mutex);

    free(structs);
}
