} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate random CRCFLAG value
uint16_t generate_random_crcflag() {
    return rand() % (1 << 15);
}

// Lock-free memory pool for efficient allocation under high concurrency
struct mem_pool {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t used;
    pthread_spinlock_t lock;
};

void init_mem_pool(struct mem_pool *pool, size_t initial_capacity) {
    pool->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for the memory pool.\n");
        exit(1);
    }
    pool->capacity = initial_capacity;
    pool->used = 0;
    pthread_spin_init(&pool->lock, PTHREAD_SPIN_TRYLOCK);
}

NFAPI_CRC_INDICATION_PDU_T *mem_pool_pop(struct mem_pool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;

    // Try to acquire the lock without blocking other threads
    if (pthread_spin_trylock(&pool->lock)) {
        // Lock acquired, allocate a PDU and return it
        pdu = &pool->data[pool->used];
        pool->used++;
        pthread_spin_unlock(&pool->lock);

        pdu->rx_ue_information_tag.tag = rx_ue_information_tag;
        pdu->rnti = generate_external_rnti(); // replace this with your API call or database function for RNTI value
        pdu->crc_indication_rel8_tag.crcflag = generate_random_crcflag();
    } else {
        // Unable to acquire the lock, retry later
        pthread_spin_unlock(&pool->lock);
    }

    return pdu;
}

void* create_pdu_array(size_t N, struct mem_pool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t i;

    pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Failed to allocate memory for the PDUs array.\n");
        return NULL;
    }

    // Fill the array using the lock-free memory pool
    for (i = 0; i < N; ++i) {
        pdus[i] = mem_pool_pop(pool);
        if (!pdus[i]) {
            fprintf(stderr, "Failed to allocate memory for PDU %zu.\n", i);
            free(pdus);
            return NULL;
        }
    }

    // Validate all PDUs have been properly initialized
    for (i = 0; i < N; ++i) {
        if (!pdus[i].rx_ue_information_tag.tag || !pdus[i].rnti || !pdus[i].crc_indication_rel8_tag.crcflag) {
            fprintf(stderr, "PDU %zu is not properly initialized.\n", i);
            for (size_t j = 0; j < i; ++j) free(pdus[j]);
            free(pdus);
            return NULL;
        }
    }

    return pdus;
}
