import mmap
from concurrent.futures import ThreadPoolExecutor
import logging

class FileHashWorker:
    def __init__(self, log):
        self.log = log

    def calculate_md5(self, filepath):
        if not os.path.exists(filepath) or not os.access(filepath, os.R_OK):
            self.log.warning(f'File {filepath} is unavailable or inaccessible')
            return None

        try:
            with open(filepath, 'rb') as f:
                if hasattr(f, 'memmap'):
                    mm = mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ)
                    hash_obj = hashlib.md5()
                    while len(mm):
                        hash_obj.update(mm[:4096])
                        mm.seek(len(mm)-4096, os.SEEK_SET)
                    hexdigest = hash_obj.hexdigest()
                else:
                    hash_obj = hashlib.md5()
                    for chunk in iter(lambda: f.read(4096), b''):
                        hash_obj.update(chunk)
                    hexdigest = hash_obj.hexdigest()
                return hexdigest
        except Exception as e:
            self.log.error(f'Error processing file {filepath}: {e}')
            return None

def process_files(filepaths, num_workers=4, log):
    result = {}
    executor = ThreadPoolExecutor(num_workers)
    for filepath in filepaths:
        future = executor.submit(FileHashWorker(log), filepath)
        result[filepath] = future.result()
    executor.shutdown(wait=True)
    return result, log.getvalue()

logging.basicConfig(level=logging.INFO)
filepaths = ['/path/to/file1', '/path/to/file2', '/path/to/corrupted_file']
results, log = process_files(filepaths)
print(results)
print(log)
