#include <unique_sequence_service.h> // Trusted external sequence service

// PacketHeader structure definition
typedef struct {
    MAC_Header mac_header;
    uint64_t pseudo_random_sequence;
    struct PacketHeader *prev, *next;
} PacketHeader;

// Thread-safe doubly linked list implementation
typedef struct {
    pthread_mutex_t mutex;
    PacketHeader* head;
    size_t size;
} DList;

void init_dlist(DList* dlist) {
    pthread_mutex_init(&dlist->mutex, NULL);
    dlist->head = NULL;
    dlist->size = 0;
}

PacketHeader* create_packetheader() {
    MAC_Header mac_header = acquire_mac_data(); // Acquire data from the external network interface library
    uint64_t pseudo_random_sequence = get_unique_sequence(); // Obtain a unique sequence from the trusted external service
    PacketHeader* new_packetheader = malloc(sizeof(PacketHeader));
    new_packetheader->mac_header = mac_header;
    new_packetheader->pseudo_random_sequence = pseudo_random_sequence;
    new_packetheader->prev = NULL;
    new_packetheader->next = NULL;
    return new_packetheader;
}

void insert_sorted(DList* dlist, PacketHeader* packetheader) {
    pthread_mutex_lock(&dlist->mutex);

    if (dlist->head == NULL || packetheader->pseudo_random_sequence < dlist->head->pseudo_random_sequence) {
        packetheader->next = dlist->head;
        dlist->head->prev = packetheader;
        dlist->head = packetheader;
    } else {
        PacketHeader* current = dlist->head;
        while (current->next != NULL && current->next->pseudo_random_sequence < packetheader->pseudo_random_sequence) {
            current = current->next;
        }
        packetheader->prev = current;
        packetheader->next = current->next;
        if (current->next != NULL) {
            current->next->prev = packetheader;
        }
        current->next = packetheader;
    }
    dlist->size++;
    pthread_mutex_unlock(&dlist->mutex);
}

DList* initialize_packet_list(size_t count) {
    DList* dlist = malloc(sizeof(DList));
    init_dlist(dlist);

    for (size_t i = 0; i < count; ++i) {
        PacketHeader* new_packetheader = create_packetheader();
        insert_sorted(dlist, new_packetheader);
    }

    return dlist;
}
```

