struct list {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count, threshold_warning;
    pthread_mutex_t lock;
};

static void init_list(struct list* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->threshold_warning = THRESHOLD;
    pthread_mutex_init(&list->lock, NULL);
}

static NFAPI_CRC_INDICATION_PDU_T* create_node() {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;

    node->prev = node->next = NULL;
    // Set the values of RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG here.
    node->crc_ind.crcflag = rand() % 2;
    return node;
}

static void insert(struct list* list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0) {
        list->head = list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }

    ++(list->count);

    if (list->count > list->threshold_warning) {
        printf("Warning: List size exceeded threshold.\n");
        list->threshold_warning *= 2;
    }

    pthread_mutex_unlock(&list->lock);
}

static void remove(struct list* list, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&list->lock);

    if (list->count == 0) return;

    node->prev->next = node->next;
    node->next->prev = node->prev;

    free(node);

    --(list->count);

    pthread_mutex_unlock(&list->lock);
}

static struct list* create_list() {
    struct list *list = malloc(sizeof(struct list));
    if (!list) return NULL;

    init_list(list);

    return list;
}
