#define MAX_ENTRIES 1024
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} node_t;

node_t* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void validate(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->tag < 1 || pdu->tag > MAX_ENTRIES || pdu->rnti < 1 || pdu->rnti > 0xFFFF || pdu->crc_indication.crcflag != RANDOM_CRCFLAG) {
        fprintf(stderr, "Invalid NFAPI_CRC_INDICATION_PDU_T structure\n");
        exit(1);
    }
}

void add_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    validate(pdu);
    node_t *new_node = (node_t*)malloc(sizeof(node_t));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(1);
    }
    new_node->data = *pdu;
    new_node->next = head;
    head = new_node;
}

void remove_pdu_by_tag(unsigned int tag) {
    pthread_mutex_lock(&list_lock);
    node_t* current = head;
    node_t* previous = NULL;

    while (current != NULL && current->data.tag != tag) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // Not found

    if (previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list_lock);
}

node_t* find_pdu_by_tag(unsigned int tag) {
    pthread_mutex_lock(&list_lock);
    node_t* current = head;

    while (current != NULL && current->data.tag != tag) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&list_lock);
        return NULL;
    }

    pthread_mutex_unlock(&list_lock);
    return current;
}
```

